/* Memory management and a simple stop-the-world mark & sweep collector. */
#include "lj.h"
#include "lj_api.h"

#define MARKED 1
#define FINALIZED_FLAG 2

static GCobj **gray_stack = NULL;
static size_t gray_n = 0, gray_cap = 0;

LJ_NORET static void mem_error(lua_State *L)
{
  lj_err_throw(L, LUA_ERRMEM);
}

void *lj_mem_alloc(lua_State *L, size_t sz)
{
  void *p = malloc(sz ? sz : 1);
  if (!p) mem_error(L);
  G(L)->totalbytes += sz;
  return p;
}

void *lj_mem_realloc(lua_State *L, void *p, size_t osz, size_t nsz)
{
  void *np = realloc(p, nsz ? nsz : 1);
  if (!np) mem_error(L);
  G(L)->totalbytes = G(L)->totalbytes - osz + nsz;
  return np;
}

void lj_mem_free(global_State *g, void *p, size_t sz)
{
  if (p) {
    free(p);
    g->totalbytes -= sz;
  }
}

GCobj *lj_gc_newobj(lua_State *L, size_t sz, int gct)
{
  global_State *g = G(L);
  GCobj *o = (GCobj *)lj_mem_alloc(L, sz);
  o->gch.gct = (uint8_t)gct;
  o->gch.marked = 0;
  o->gch.gcnext = g->rootgc;
  g->rootgc = o;
  return o;
}

/* -- Marking ------------------------------------------------------------ */

static void gray_push(GCobj *o)
{
  if (gray_n == gray_cap) {
    gray_cap = gray_cap ? gray_cap * 2 : 1024;
    gray_stack = (GCobj **)realloc(gray_stack, gray_cap * sizeof(GCobj *));
    if (!gray_stack) abort();
  }
  gray_stack[gray_n++] = o;
}

static void mark_obj(GCobj *o)
{
  if (o == NULL) return;
  if (o->gch.marked & MARKED) return;
  o->gch.marked |= MARKED;
  if (o->gch.gct != LJ_TSTR) gray_push(o);
}

#define mark_tv(tv) do { cTValue *_tv = (tv); if (tvisgcv(_tv)) mark_obj(_tv->u.gc); } while (0)

static int tab_weakmode(global_State *g, GCtab *t)
{
  GCtab *mt = t->metatable;
  cTValue *mode;
  int w = 0;
  if (!mt) return 0;
  mode = lj_tab_getstr(mt, g->mmname[MM_mode]);
  if (mode && tvisstr(mode)) {
    const char *s = strdata(strV(mode));
    if (strchr(s, 'k')) w |= 1;
    if (strchr(s, 'v')) w |= 2;
  }
  return w;
}

static GCtab **weak_list = NULL;
static size_t weak_n = 0, weak_cap = 0;

static void weak_push(GCtab *t)
{
  if (weak_n == weak_cap) {
    weak_cap = weak_cap ? weak_cap * 2 : 64;
    weak_list = (GCtab **)realloc(weak_list, weak_cap * sizeof(GCtab *));
    if (!weak_list) abort();
  }
  weak_list[weak_n++] = t;
}

static void traverse_tab(global_State *g, GCtab *t)
{
  int weak;
  uint32_t i;
  if (t->metatable) mark_obj((GCobj *)t->metatable);
  weak = tab_weakmode(g, t);
  t->weak = (uint8_t)weak;
  if (weak) weak_push(t);
  if (weak == 3) return;
  if (!(weak & 2)) {
    for (i = 0; i < t->asize; i++) mark_tv(&t->array[i]);
  }
  if (t->hmask > 0 || t->node != &g->nilnode) {
    Node *node = t->node;
    for (i = 0; i <= t->hmask; i++) {
      Node *n = &node[i];
      if (!tvisnil(&n->val)) {
        if (!(weak & 1)) mark_tv(&n->key);
        else if (tvisstr(&n->key)) mark_obj(n->key.u.gc);
        if (!(weak & 2)) mark_tv(&n->val);
        else if (tvisstr(&n->val)) mark_obj(n->val.u.gc);
      }
    }
  }
  if (weak & 2) {
    for (i = 0; i < t->asize; i++)
      if (tvisstr(&t->array[i])) mark_obj(t->array[i].u.gc);
  }
}

static void traverse_func(GCfunc *fn)
{
  int i;
  if (fn->env) mark_obj((GCobj *)fn->env);
  if (fn->isC) {
    for (i = 0; i < fn->nupvalues; i++) mark_tv(&fn->u.c.upvalue[i]);
  } else {
    mark_obj((GCobj *)fn->u.l.pt);
    for (i = 0; i < fn->nupvalues; i++)
      if (fn->u.l.uv[i]) mark_obj((GCobj *)fn->u.l.uv[i]);
  }
}

static void traverse_proto(GCproto *pt)
{
  int i;
  if (pt->source) mark_obj((GCobj *)pt->source);
  for (i = 0; i < pt->sizek; i++) mark_tv(&pt->k[i]);
  for (i = 0; i < pt->sizep; i++) if (pt->p[i]) mark_obj((GCobj *)pt->p[i]);
  for (i = 0; i < pt->sizevars; i++) if (pt->vars[i].name) mark_obj((GCobj *)pt->vars[i].name);
  for (i = 0; i < pt->nups; i++) if (pt->uvnames && pt->uvnames[i]) mark_obj((GCobj *)pt->uvnames[i]);
}

static void traverse_thread(lua_State *th)
{
  TValue *o, *lim;
  CallInfo *ci;
  if (th->stack == NULL) return;
  lim = th->top;
  for (ci = th->base_ci; ci <= th->ci; ci++) {
    if (lim < ci->top) lim = ci->top;
  }
  if (lim > th->stack_last) lim = th->stack_last;
  for (o = th->stack; o < lim; o++) mark_tv(o);
  for (; o <= th->stack_last + LJ_STACK_EXTRA - 1; o++) setnilV(o);
  if (th->env) mark_obj((GCobj *)th->env);
  mark_tv(&th->hookf);
  {
    GCupval *uv;
    for (uv = th->openupval; uv; uv = uv->nextopen) uv->gch_marked_dummy_unused_guard: ;
  }
}
EOF
