  mark_obj((GCobj *)g->mainthread);
  mark_tv(&g->registry);
  for (i = 0; i < 16; i++) if (g->basemt[i]) mark_obj((GCobj *)g->basemt[i]);
  for (i = 0; i < MM__MAX; i++) if (g->mmname[i]) mark_obj((GCobj *)g->mmname[i]);
  if (g->cdata_fin) mark_obj((GCobj *)g->cdata_fin);
  for (th = g->curthread; th; th = th->resumer) mark_obj((GCobj *)th);
  lj_ffi_markstate(g, mark_obj);
}

static int is_cleared(cTValue *o)
{
  if (!tvisgcv(o)) return 0;
  if (tvisstr(o)) { o->u.gc->gch.marked |= MARKED; return 0; }
  return !(o->u.gc->gch.marked & MARKED);
}

static int is_cleared_key(cTValue *o)
{
  if (!tvisgcv(o)) return 0;
  if (tvisstr(o)) { o->u.gc->gch.marked |= MARKED; return 0; }
  /* Userdata being finalized are still considered live keys (5.1 semantics are
  ** to clear them; we follow that for values only). */
  return !(o->u.gc->gch.marked & MARKED);
}

static void clear_weak(global_State *g)
{
  size_t k;
  for (k = 0; k < weak_n; k++) {
    GCtab *t = weak_list[k];
    uint32_t i;
    if (t->weak & 2) {
      for (i = 0; i < t->asize; i++)
        if (is_cleared(&t->array[i])) setnilV(&t->array[i]);
    }
    if (t->node != &g->nilnode) {
      for (i = 0; i <= t->hmask; i++) {
        Node *n = &t->node[i];
        if (!tvisnil(&n->val)) {
          if (((t->weak & 1) && is_cleared_key(&n->key)) ||
              ((t->weak & 2) && is_cleared(&n->val)))
            setnilV(&n->val);
        }
      }
    }
  }
  weak_n = 0;
}

/* -- Finalizers ---------------------------------------------------------- */

static GCobj **fin_list = NULL;
static size_t fin_n = 0, fin_cap = 0;

static void fin_push(GCobj *o)
{
  if (fin_n == fin_cap) {
    fin_cap = fin_cap ? fin_cap * 2 : 64;
    fin_list = (GCobj **)realloc(fin_list, fin_cap * sizeof(GCobj *));
    if (!fin_list) abort();
  }
  fin_list[fin_n++] = o;
}

/* Pending finalizers (objects resurrected for finalization). */
static GCobj **pend_list = NULL;
static size_t pend_n = 0, pend_cap = 0, pend_pos = 0;
static TValue *pend_fn = NULL;  /* parallel array of finalizer functions for cdata */

static void pend_push(GCobj *o, cTValue *fn)
{
  if (pend_n == pend_cap) {
    pend_cap = pend_cap ? pend_cap * 2 : 64;
    pend_list = (GCobj **)realloc(pend_list, pend_cap * sizeof(GCobj *));
    pend_fn = (TValue *)realloc(pend_fn, pend_cap * sizeof(TValue));
    if (!pend_list || !pend_fn) abort();
  }
  pend_list[pend_n] = o;
  if (fn) pend_fn[pend_n] = *fn; else setnilV(&pend_fn[pend_n]);
  pend_n++;
}

static void separate_udata(global_State *g, int all)
{
  GCobj *o;
  fin_n = 0;
  for (o = g->rootgc; o; o = o->gch.gcnext) {
    if (o->gch.gct == LJ_TUDATA && (all || !(o->gch.marked & MARKED)) &&
        !(o->ud.finalized)) {
      GCtab *mt = o->ud.metatable;
      if (mt) {
        cTValue *gcf = lj_tab_getstr(mt, g->mmname[MM_gc]);
        if (gcf && !tvisnil(gcf)) {
          fin_push(o);
        }
      }
      o->ud.finalized = 1;
    }
  }
}

static void separate_cdata(global_State *g, int all)
{
  GCtab *t = g->cdata_fin;
  uint32_t i;
  if (!t || t->node == &g->nilnode) return;
  for (i = 0; i <= t->hmask; i++) {
    Node *n = &t->node[i];
    if (!tvisnil(&n->val) && tviscdata(&n->key)) {
      GCobj *o = n->key.u.gc;
      if (all || !(o->gch.marked & MARKED)) {
        pend_push(o, &n->val);
        setnilV(&n->val);
        mark_obj(o);
      }
    }
  }
}

/* -- Sweep --------------------------------------------------------------- */

extern void lj_udata_free(global_State *g, GCudata *ud);
extern void lj_cdata_free(global_State *g, GCcdata *cd);

static void free_obj(global_State *g, GCobj *o)
{
  switch (o->gch.gct) {
  case LJ_TTAB: lj_tab_free(g, &o->tab); break;
  case LJ_TFUNC: lj_mem_free(g, o, lj_func_size(&o->fn)); break;
  case LJ_TPROTO: lj_func_freeproto(g, &o->pt); break;
  case LJ_TUPVAL: lj_func_freeuv(g, &o->uv); break;
  case LJ_TTHREAD: lj_state_free(g, &o->th); break;
  case LJ_TUDATA: lj_udata_free(g, &o->ud); break;
  case LJ_TCDATA: lj_cdata_free(g, &o->cd); break;
  default: abort();
  }
}

static void close_dead_threads(global_State *g)
{
  GCobj *o;
  for (o = g->rootgc; o; o = o->gch.gcnext) {
    if (o->gch.gct == LJ_TTHREAD && !(o->gch.marked & MARKED)) {
      lua_State *th = &o->th;
      if (th->stack) lj_func_closeuv(th, th->stack);
    }
  }
}

static void sweep(global_State *g)
{
  GCobj **p = &g->rootgc;
  GCobj *o;
  uint32_t i;
  while ((o = *p) != NULL) {
    if (o->gch.marked & MARKED) {
      o->gch.marked &= ~MARKED;
      p = &o->gch.gcnext;
    } else {
      *p = o->gch.gcnext;
      free_obj(g, o);
    }
  }
  /* Sweep strings. */
  for (i = 0; i <= g->strt.mask; i++) {
    GCstr **sp = &g->strt.hash[i];
    GCstr *s;
    while ((s = *sp) != NULL) {
      if (s->marked & MARKED) {
        s->marked &= ~MARKED;
        sp = &s->hnext;
      } else {
        *sp = s->hnext;
        g->strt.count--;
        lj_mem_free(g, s, sizeof(GCstr) + s->len);
      }
    }
  }
}

static void set_threshold(global_State *g)
{
  size_t est = g->totalbytes;
  size_t th = (est / 100) * (size_t)g->gcpause;
  if (th < est + 256 * 1024) th = est + 256 * 1024;
  g->estimate = est;
  g->threshold = th;
}

/* Run a complete collection cycle. Finalizers are queued, not called. */
static void gc_cycle(lua_State *L)
{
  global_State *g = G(L);
  size_t i;
  if (g->gcinprogress) return;
  g->gcinprogress = 1;
  gray_n = 0;
  weak_n = 0;
  mark_roots(g);
  /* Pending finalizer objects must stay alive. */
  for (i = pend_pos; i < pend_n; i++) { mark_obj(pend_list[i]); mark_tv(&pend_fn[i]); }
  propagate(g);
  separate_udata(g, 0);
  for (i = 0; i < fin_n; i++) { mark_obj(fin_list[i]); pend_push(fin_list[i], NULL); }
  propagate(g);
  separate_cdata(g, 0);
  propagate(g);
  clear_weak(g);
  close_dead_threads(g);
  sweep(g);
  set_threshold(g);
  g->gcinprogress = 0;
}

/* Call one pending finalizer. Returns 0 if none pending. */
static int call_one_finalizer(lua_State *L)
{
  global_State *g = G(L);
  GCobj *o;
  TValue fn;
  TValue *top;
  if (pend_pos >= pend_n) { pend_pos = pend_n = 0; return 0; }
  o = pend_list[pend_pos];
  fn = pend_fn[pend_pos];
  pend_pos++;
  if (o->gch.gct == LJ_TUDATA) {
    GCtab *mt = o->ud.metatable;
    cTValue *gcf = mt ? lj_tab_getstr(mt, g->mmname[MM_gc]) : NULL;
    if (!gcf || tvisnil(gcf)) return 1;
    fn = *gcf;
  }
  if (tvisnil(&fn)) return 1;
  lj_checkstack(L, 3);
  top = L->top;
  copyTV(top, &fn);
  if (o->gch.gct == LJ_TUDATA) setudataV(top + 1, o); else setcdataV(top + 1, o);
  L->top = top + 2;
  {
    int oldhook = L->allowhook;
    int status;
    g->gcdisabled++;
    L->allowhook = 0;
    status = lua_pcall(L, 1, 0, 0);
    L->allowhook = (uint8_t)oldhook;
    g->gcdisabled--;
    if (status) {
      /* Propagate error from finalizer, like the reference implementation. */
      lj_err_throw(L, status);
    }
  }
  return 1;
}

void lj_gc_callfinalizers(lua_State *L)
{
  global_State *g = G(L);
  if (g->gcdisabled) return;
  while (call_one_finalizer(L)) ;
}

void lj_gc_fullgc(lua_State *L)
{
  gc_cycle(L);
  lj_gc_callfinalizers(L);
}

void lj_gc_step_check(lua_State *L)
{
  global_State *g = G(L);
  if (!g->gcrunning || g->gcdisabled || g->gcinprogress) {
    if (g->totalbytes >= g->threshold) g->threshold = g->totalbytes + 1024 * 1024;
    return;
  }
  gc_cycle(L);
  lj_gc_callfinalizers(L);
}

int lj_gc_step(lua_State *L)
{
  lj_gc_fullgc(L);
  return 1;
}

/* Called at state close: finalize everything. */
void lj_gc_freeall(lua_State *L)
{
  global_State *g = G(L);
  size_t i;
  /* Run cdata finalizers then udata finalizers for all objects. */
  gray_n = 0;
  separate_cdata(g, 1);
  gray_n = 0;
  for (;;) {
    int any;
    lj_gc_callfinalizers(L);
    separate_udata(g, 1);
    any = (int)fin_n;
    /* Reference implementation finalizes in reverse order of creation for
    ** userdata objects since the list is LIFO. */
    for (i = 0; i < fin_n; i++) pend_push(fin_list[i], NULL);
    fin_n = 0;
    lj_gc_callfinalizers(L);
    if (!any) break;
  }
}
