static uint32_t str_hash(const char *s, size_t len)
{
  uint32_t h = (uint32_t)len ^ 0x9e3779b9u;
  size_t step = (len >> 5) + 1;
  size_t l1;
  for (l1 = len; l1 >= step; l1 -= step)
    h = h ^ ((h << 5) + (h >> 2) + (uint8_t)s[l1 - 1]);
  return h;
}

void lj_str_resize(lua_State *L, uint32_t newsize)
{
  global_State *g = G(L);
  GCstr **newhash = (GCstr **)calloc(newsize, sizeof(GCstr *));
  uint32_t i, newmask = newsize - 1;
  if (!newhash) return;
  if (g->strt.hash) {
    for (i = 0; i <= g->strt.mask; i++) {
      GCstr *s = g->strt.hash[i];
      while (s) {
        GCstr *next = s->hnext;
        uint32_t h = s->hash & newmask;
        s->hnext = newhash[h];
        newhash[h] = s;
        s = next;
      }
    }
    free(g->strt.hash);
  }
  g->strt.hash = newhash;
  g->strt.mask = newmask;
}

GCstr *lj_str_new(lua_State *L, const char *str, size_t len)
{
  global_State *g = G(L);
  uint32_t h;
  GCstr *s;
  if (len > 0x7fffff00u) lj_err_msg(L, "string length overflow");
  h = str_hash(str, len);
  for (s = g->strt.hash[h & g->strt.mask]; s; s = s->hnext) {
    if (s->len == len && s->hash == h && memcmp(str, s->data, len) == 0) {
      if (s->marked & 1) {
        /* Keep string alive if it's being resurrected during GC; harmless. */
      }
      return s;
    }
  }
  s = (GCstr *)lj_mem_alloc(L, sizeof(GCstr) + len);
  s->gct = LJ_TSTR;
  s->marked = 0;
  s->gcnext = NULL;
  s->reserved = 0;
  s->hash = h;
  s->len = (uint32_t)len;
  memcpy(s->data, str, len);
  s->data[len] = '\0';
  s->hnext = g->strt.hash[h & g->strt.mask];
  g->strt.hash[h & g->strt.mask] = s;
  if (++g->strt.count > g->strt.mask + 1 && g->strt.mask < 0x3fffffff)
    lj_str_resize(L, (g->strt.mask + 1) * 2);
