  for (i = 0; i <= g->strt.mask; i++) {
    GCstr *s = g->strt.hash[i];
    while (s) {
      GCstr *next = s->hnext;
      free(s);
      s = next;
    }
  }
  free(g->strt.hash);
  g->strt.hash = NULL;
}

int lj_str_cmp(GCstr *a, GCstr *b)
{
  size_t la = a->len, lb = b->len;
  size_t n = la < lb ? la : lb;
  int r = memcmp(a->data, b->data, n);
  if (r != 0) return r < 0 ? -1 : 1;
  return la < lb ? -1 : (la > lb ? 1 : 0);
}

/* Format a number like the reference implementation ("%.14g"). */
size_t lj_str_fmtnum(char *buf, double n)
{
  if (n != n) { memcpy(buf, "nan", 4); return 3; }
  if (n == (double)INFINITY) { memcpy(buf, "inf", 4); return 3; }
  if (n == -(double)INFINITY) { memcpy(buf, "-inf", 5); return 4; }
  if (n == 0.0) {
    if (signbit(n)) { memcpy(buf, "-0", 3); return 2; }
    buf[0] = '0'; buf[1] = 0; return 1;
  }
  if (n == floor(n) && n > -1e14 && n < 1e14) {
    long long i = (long long)n;
    char tmp[24];
    int p = 0, neg = 0;
    size_t len;
    if (i < 0) { neg = 1; i = -i; }
    while (i > 0) { tmp[p++] = (char)('0' + (i % 10)); i /= 10; }
    len = 0;
    if (neg) buf[len++] = '-';
    while (p > 0) buf[len++] = tmp[--p];
    buf[len] = 0;
    return len;
  }
  return (size_t)snprintf(buf, 64, "%.14g", n);
}

GCstr *lj_str_fromnum(lua_State *L, double n)
{
  char buf[64];
  size_t len = lj_str_fmtnum(buf, n);
  return lj_str_new(L, buf, len);
}

/* -- String to number conversion ----------------------------------------- */

static int casecmp_prefix(const char *p, const char *e, const char *w)
{
  size_t n = strlen(w);
  if ((size_t)(e - p) < n) return 0;
  while (*w) {
    if (tolower((unsigned char)*p) != *w) return 0;
    p++; w++;
  }
  return 1;
}

