static int casecmp_prefix(const char *p, const char *e, const char *w)
{
  size_t n = strlen(w);
  if ((size_t)(e - p) < n) return 0;
  while (*w) {
    if (tolower((unsigned char)*p) != *w) return 0;
    p++; w++;
  }
  return 1;
}

