** opt: STRSCAN_OPT_LL allows LL/ULL suffixes, STRSCAN_OPT_IMAG allows i suffix.
** For I64/U64 results, o->u.u64 holds the integer.
*/
int lj_strscan_scan(const char *p, size_t len, TValue *o, int opt)
{
  const char *e = p + len;
  const char *start;
  int neg = 0;
