uint32_t lj_fls(uint32_t x)
{
  return 31u - (uint32_t)__builtin_clz(x);
}

static inline uint32_t rol32(uint32_t x, int n)
{
  return (x << n) | (x >> (32 - n));
}

static inline uint32_t hashrot(uint32_t lo, uint32_t hi)
{
  lo ^= hi; hi = rol32(hi, 14);
  lo -= hi; hi = rol32(hi, 5);
  hi ^= lo; hi -= rol32(lo, 13);
  return hi;
}

uint32_t lj_tab_hsize2hbits(uint32_t s)
{
