/* Tables with an array part [0, asize) and a hash part with chained
** scatter nodes, laid out to give the same traversal order as the
** reference implementation. */
#include "lj.h"

const TValue lj_nilobj = {{0}, LJ_TNIL};

#define LJ_MAX_ABITS 28
#define LJ_MAX_ASIZE ((1u << (LJ_MAX_ABITS - 1)) + 1)
#define HASH_BIAS ((uint32_t)-0x04c11db7)

uint32_t lj_fls(uint32_t x)
{
  return 31u - (uint32_t)__builtin_clz(x);
}

static inline uint32_t rol32(uint32_t x, int n)
{
  return (x << n) | (x >> (32 - n));
}

static inline uint32_t hashrot(uint32_t lo, uint32_t hi)
{
  lo ^= hi; hi = rol32(hi, 14);
  lo -= hi; hi = rol32(hi, 5);
  hi ^= lo; hi -= rol32(lo, 13);
  return hi;
}

uint32_t lj_tab_hsize2hbits(uint32_t s)
{
  if (s == 0) return 0;
  if (s == 1) return 1;
  return 1 + lj_fls(s - 1);
}

static inline Node *hashkey(const GCtab *t, cTValue *key)
{
  Node *n = t->node;
  switch (key->tt) {
  case LJ_TSTR:
    return &n[strV(key)->hash & t->hmask];
  case LJ_TNUM: {
    uint64_t u = key->u.u64;
    uint32_t lo = (uint32_t)u, hi = (uint32_t)(u >> 32);
    return &n[hashrot(lo, hi << 1) & t->hmask];
  }
  case LJ_TFALSE: return &n[0];
  case LJ_TTRUE: return &n[1 & t->hmask];
  default: {
    uint64_t p = (uint64_t)(uintptr_t)key->u.p;
    uint32_t lo = (uint32_t)p;
    return &n[hashrot(lo, lo + HASH_BIAS) & t->hmask];
  }
  }
}

static inline int keyeq(cTValue *a, cTValue *b)
{
  if (a->tt != b->tt) return 0;
  if (a->tt == LJ_TNUM) return a->u.n == b->u.n;
  if (a->tt <= LJ_TTRUE) return 1;
  return a->u.p == b->u.p;
}

static void clearhpart(GCtab *t)
{
  uint32_t i, hmask = t->hmask;
  Node *node = t->node;
  for (i = 0; i <= hmask; i++) {
    Node *n = &node[i];
    n->next = NULL;
    setnilV(&n->key);
    setnilV(&n->val);
  }
}

static void newhpart(lua_State *L, GCtab *t, uint32_t hbits)
{
  if (hbits) {
    uint32_t hsize = 1u << hbits;
    if (hbits > LJ_MAX_ABITS + 2) lj_err_msg(L, "table overflow");
    t->node = (Node *)lj_mem_alloc(L, hsize * sizeof(Node));
    t->hmask = hsize - 1;
    t->freetop = &t->node[hsize];
    clearhpart(t);
  } else {
    t->node = &G(L)->nilnode;
    t->hmask = 0;
    t->freetop = &G(L)->nilnode;
  }
}

GCtab *lj_tab_new(lua_State *L, uint32_t asize, uint32_t hbits)
{
  GCtab *t = (GCtab *)lj_gc_newobj(L, sizeof(GCtab), LJ_TTAB);
  uint32_t i;
  t->nomm = (uint8_t)~0;
  t->weak = 0;
  t->metatable = NULL;
  t->gclist = NULL;
  t->asize = 0;
  t->array = NULL;
  t->node = &G(L)->nilnode;
  t->hmask = 0;
  t->freetop = &G(L)->nilnode;
  if (asize > 0) {
    if (asize > LJ_MAX_ASIZE) lj_err_msg(L, "table overflow");
    t->array = (TValue *)lj_mem_alloc(L, asize * sizeof(TValue));
    for (i = 0; i < asize; i++) setnilV(&t->array[i]);
    t->asize = asize;
  }
  if (hbits) newhpart(L, t, hbits);
  return t;
}

GCtab *lj_tab_dup(lua_State *L, const GCtab *kt)
{
  GCtab *t = lj_tab_new(L, kt->asize, kt->hmask > 0 ? lj_fls(kt->hmask) + 1 : 0);
  uint32_t i;
  for (i = 0; i < kt->asize; i++) copyTV(&t->array[i], &kt->array[i]);
  if (kt->hmask > 0) {
    Node *node = t->node;
    const Node *knode = kt->node;
    for (i = 0; i <= kt->hmask; i++) {
      const Node *kn = &knode[i];
      Node *n = &node[i];
      n->key = kn->key;
      n->val = kn->val;
      n->next = kn->next ? &node[kn->next - knode] : NULL;
    }
    t->freetop = &node[kt->freetop - knode];
  }
  return t;
}

void lj_tab_free(global_State *g, GCtab *t)
{
  if (t->hmask > 0 || (t->node && t->node != &g->nilnode))
    lj_mem_free(g, t->node, (t->hmask + 1) * sizeof(Node));
  if (t->asize > 0) lj_mem_free(g, t->array, t->asize * sizeof(TValue));
  lj_mem_free(g, t, sizeof(GCtab));
}

void lj_tab_clear(GCtab *t)
{
  uint32_t i;
  for (i = 0; i < t->asize; i++) setnilV(&t->array[i]);
  if (t->hmask > 0) {
    clearhpart(t);
    t->freetop = &t->node[t->hmask + 1];
  }
}

/* -- Lookup ------------------------------------------------------------- */

cTValue *lj_tab_getint(GCtab *t, int32_t key)
{
  if ((uint32_t)key < t->asize) return &t->array[key];
  {
    TValue k;
    Node *n;
    setnumV(&k, (double)key);
    n = hashkey(t, &k);
    do {
      if (n->key.tt == LJ_TNUM && n->key.u.n == (double)key) return &n->val;
    } while ((n = n->next));
  }
  return NULL;
}

cTValue *lj_tab_getstr(GCtab *t, GCstr *key)
{
  Node *n = &t->node[key->hash & t->hmask];
  do {
    if (n->key.tt == LJ_TSTR && strV(&n->key) == key) return &n->val;
  } while ((n = n->next));
  return NULL;
}

static cTValue *getgeneric(GCtab *t, cTValue *key)
{
  Node *n = hashkey(t, key);
  do {
    if (keyeq(&n->key, key)) return &n->val;
  } while ((n = n->next));
  return NULL;
}

cTValue *lj_tab_get(lua_State *L, GCtab *t, cTValue *key)
{
  cTValue *tv;
  (void)L;
  switch (key->tt) {
  case LJ_TSTR:
    tv = lj_tab_getstr(t, strV(key));
    break;
  case LJ_TNUM: {
    double nk = key->u.n;
    int32_t k = (int32_t)nk;
    if (nk == (double)k && (uint32_t)k < t->asize) return &t->array[k];
    if (nk == 0) { TValue z; setnumV(&z, 0.0); tv = getgeneric(t, &z); }
    else tv = getgeneric(t, key);
    break;
  }
  case LJ_TNIL:
    return &lj_nilobj;
  default:
    tv = getgeneric(t, key);
    break;
  }
  return tv ? tv : &lj_nilobj;
}

/* -- Resizing ----------------------------------------------------------- */

void lj_tab_resize(lua_State *L, GCtab *t, uint32_t asize, uint32_t hbits)
{
  global_State *g = G(L);
  Node *oldnode = t->node;
  uint32_t oldasize = t->asize;
  uint32_t oldhmask = t->hmask;
  int olddummy = (oldnode == &g->nilnode);
  uint32_t i;
  if (asize > oldasize) {
    if (asize > LJ_MAX_ASIZE) lj_err_msg(L, "table overflow");
    t->array = (TValue *)lj_mem_realloc(L, t->array, oldasize * sizeof(TValue), asize * sizeof(TValue));
    for (i = oldasize; i < asize; i++) setnilV(&t->array[i]);
    t->asize = asize;
  }
  newhpart(L, t, hbits);
  t->nomm = 0;
  if (asize < oldasize) {
    TValue *array = t->array;
    t->asize = asize;
    for (i = asize; i < oldasize; i++) {
      if (!tvisnil(&array[i])) {
        TValue *v = lj_tab_setint(L, t, (int32_t)i);
        copyTV(v, &array[i]);
      }
    }
    if (asize > 0) {
      t->array = (TValue *)lj_mem_realloc(L, array, oldasize * sizeof(TValue), asize * sizeof(TValue));
    } else {
      lj_mem_free(g, array, oldasize * sizeof(TValue));
      t->array = NULL;
    }
  }
  if (!olddummy) {
    for (i = 0; i <= oldhmask; i++) {
      Node *n = &oldnode[i];
      if (!tvisnil(&n->val)) {
        TValue *v = lj_tab_set(L, t, &n->key);
        copyTV(v, &n->val);
      }
    }
    lj_mem_free(g, oldnode, (oldhmask + 1) * sizeof(Node));
  }
}

void lj_tab_reasize(lua_State *L, GCtab *t, uint32_t nasize)
{
  lj_tab_resize(L, t, nasize + 1, t->hmask > 0 ? lj_fls(t->hmask) + 1 : 0);
}

static uint32_t countint(cTValue *key, uint32_t *bins)
{
  if (tvisnum(key)) {
    double nk = key->u.n;
    int32_t k = (int32_t)nk;
    if ((uint32_t)k < LJ_MAX_ASIZE && nk == (double)k) {
      bins[(k > 2 ? lj_fls((uint32_t)(k - 1)) : 0)]++;
      return 1;
    }
  }
  return 0;
}

static uint32_t countarray(const GCtab *t, uint32_t *bins)
{
  uint32_t na = 0, b, i = 0;
  if (t->asize == 0) return 0;
  for (b = 0; b < LJ_MAX_ABITS; b++) {
    uint32_t n = 0, top = 2u << b;
    if (top >= t->asize) {
      top = t->asize - 1;
      if (i > top) break;
    }
    for (; i <= top; i++)
      if (!tvisnil(&t->array[i])) n++;
    bins[b] += n;
    na += n;
  }
  return na;
}

static uint32_t counthash(const GCtab *t, uint32_t *bins, uint32_t *narray)
{
  uint32_t total = 0, na = 0, i, hmask = t->hmask;
  Node *node = t->node;
  if (t->hmask == 0 && t->node[0].key.tt == LJ_TNIL && tvisnil(&t->node[0].val)) {
    /* Dummy or empty. */
  }
  for (i = 0; i <= hmask; i++) {
    Node *n = &node[i];
    if (!tvisnil(&n->val)) {
      na += countint(&n->key, bins);
      total++;
    }
  }
  *narray += na;
  return total;
}

static uint32_t bestasize(uint32_t bins[], uint32_t *narray)
{
  uint32_t b, sum, na = 0, sz = 0, nn = *narray;
  for (b = 0, sum = 0; 2 * nn > (1u << b) && sum != nn; b++)
    if (bins[b] > 0 && 2 * (sum += bins[b]) > (1u << b)) {
      sz = (2u << b) + 1;
      na = sum;
    }
  *narray = sz;
  return na;
}

static void rehashtab(lua_State *L, GCtab *t, cTValue *ek)
{
  uint32_t bins[LJ_MAX_ABITS];
  uint32_t total, asize, na, i;
  for (i = 0; i < LJ_MAX_ABITS; i++) bins[i] = 0;
  asize = countarray(t, bins);
  total = 1 + asize;
  total += counthash(t, bins, &asize);
  asize += countint(ek, bins);
  na = bestasize(bins, &asize);
  total -= na;
  lj_tab_resize(L, t, asize, lj_tab_hsize2hbits(total));
}

/* -- Insertion ---------------------------------------------------------- */

TValue *lj_tab_newkey(lua_State *L, GCtab *t, cTValue *key)
{
  Node *n = hashkey(t, key);
  t->nomm = 0;
  if (!tvisnil(&n->val) || t->hmask == 0) {
    Node *nodebase = t->node;
    Node *collide, *freenode = t->freetop;
    do {
      if (freenode == nodebase) {
        rehashtab(L, t, key);
        return lj_tab_set(L, t, key);
      }
    } while (!tvisnil(&(--freenode)->key));
    t->freetop = freenode;
    collide = hashkey(t, &n->key);
    if (collide != n) {
      /* Colliding node is not in its main position: move it. */
      while (collide->next != n) collide = collide->next;
      collide->next = freenode;
      freenode->val = n->val;
      freenode->key = n->key;
      freenode->next = n->next;
      n->next = NULL;
      setnilV(&n->val);
      /* Rechain any live keys which have their main position at n. */
      {
        Node *prev = freenode, *nn;
        while ((nn = prev->next) != NULL) {
          if (!tvisnil(&nn->val) && hashkey(t, &nn->key) == n) {
            prev->next = nn->next;
            nn->next = n->next;
            n->next = nn;
          } else {
            prev = nn;
          }
        }
      }
    } else {
      freenode->next = n->next;
      n->next = freenode;
      n = freenode;
    }
  }
  n->key = *key;
  if (n->key.tt == LJ_TNUM && n->key.u.n == 0) n->key.u.n = 0.0;  /* -0 -> 0 */
  return &n->val;
}

TValue *lj_tab_setint(lua_State *L, GCtab *t, int32_t key)
{
  TValue k;
  Node *n;
  if ((uint32_t)key < t->asize) return &t->array[key];
  setnumV(&k, (double)key);
  n = hashkey(t, &k);
  do {
    if (n->key.tt == LJ_TNUM && n->key.u.n == (double)key) { t->nomm = 0; return &n->val; }
  } while ((n = n->next));
  return lj_tab_newkey(L, t, &k);
}

TValue *lj_tab_setstr(lua_State *L, GCtab *t, GCstr *key)
{
  TValue k;
  Node *n = &t->node[key->hash & t->hmask];
  t->nomm = 0;
  do {
    if (n->key.tt == LJ_TSTR && strV(&n->key) == key) return &n->val;
  } while ((n = n->next));
  setstrV(&k, key);
  return lj_tab_newkey(L, t, &k);
}

TValue *lj_tab_set(lua_State *L, GCtab *t, cTValue *key)
{
  Node *n;
  t->nomm = 0;
  switch (key->tt) {
  case LJ_TSTR:
    return lj_tab_setstr(L, t, strV(key));
  case LJ_TNUM: {
    double nk = key->u.n;
    int32_t k = (int32_t)nk;
    if (nk == (double)k) {
      return lj_tab_setint(L, t, k);
    }
    if (nk != nk) lj_err_msg(L, "table index is NaN");
    break;
  }
  case LJ_TNIL:
    lj_err_msg(L, "table index is nil");
  default:
    break;
  }
  n = hashkey(t, key);
  do {
    if (keyeq(&n->key, key)) return &n->val;
  } while ((n = n->next));
  return lj_tab_newkey(L, t, key);
}

/* -- Length & traversal --------------------------------------------------- */

static size_t unbound_search(GCtab *t, size_t j)
{
  cTValue *tv;
  size_t i = j;
  j++;
  while ((tv = lj_tab_getint(t, (int32_t)j)) && !tvisnil(tv)) {
    i = j;
    if (j > (size_t)(0x7fffffff - 2)) {
      i = 1;
      while ((tv = lj_tab_getint(t, (int32_t)i)) && !tvisnil(tv)) i++;
      return i - 1;
    }
    j *= 2;
  }
  while (j - i > 1) {
    size_t m = (i + j) / 2;
    cTValue *tvb = lj_tab_getint(t, (int32_t)m);
    if (tvb && !tvisnil(tvb)) i = m; else j = m;
  }
  return i;
}

size_t lj_tab_len(GCtab *t)
{
  size_t j = t->asize;
  if (j > 1 && tvisnil(&t->array[j - 1])) {
    size_t i = 1;
    while (j - i > 1) {
      size_t m = (i + j) >> 1;
      if (tvisnil(&t->array[m - 1])) j = m; else i = m;
    }
    return i - 1;
  }
  if (j) j--;
  if (t->hmask == 0) return j;
  return unbound_search(t, j);
}

static uint32_t keyindex(lua_State *L, GCtab *t, cTValue *key)
{
  if (tvisnil(key)) return 0;
  if (tvisnum(key)) {
    double nk = key->u.n;
    int32_t k = (int32_t)nk;
    if ((uint32_t)k < t->asize && nk == (double)k) return (uint32_t)k + 1;
  }
  {
    TValue kk = *key;
    Node *n;
    if (kk.tt == LJ_TNUM && kk.u.n == 0) kk.u.n = 0.0;
    n = hashkey(t, &kk);
    do {
      if (keyeq(&n->key, &kk)) return t->asize + (uint32_t)(n - t->node) + 1;
    } while ((n = n->next));
  }
  lj_err_msg(L, "invalid key to 'next'");
  return 0;
}

/* key[0] = key in/out, key[1] = value out. Returns 0 at end. */
int lj_tab_next(lua_State *L, GCtab *t, TValue *key)
{
  uint32_t i = keyindex(L, t, key);
  for (; i < t->asize; i++) {
    if (!tvisnil(&t->array[i])) {
      setnumV(key, (double)i);
      copyTV(key + 1, &t->array[i]);
      return 1;
    }
  }
  for (i -= t->asize; i <= t->hmask; i++) {
    Node *n = &t->node[i];
    if (!tvisnil(&n->val)) {
      copyTV(key, &n->key);
      copyTV(key + 1, &n->val);
      return 1;
    }
  }
  return 0;
}
