    nuv->v = level;
    setnilV(&nuv->tv);
    nuv->th = L;
    nuv->nextopen = uv;
    nuv->prevopen = prev;
    if (uv) uv->prevopen = nuv;
    if (prev) prev->nextopen = nuv; else L->openupval = nuv;
    return nuv;
  }
}

void lj_func_closeuv(lua_State *L, TValue *level)
{
