    uv->closed = 1;
    uv->nextopen = uv->prevopen = NULL;
  }
}

void lj_func_freeuv(global_State *g, GCupval *uv)
{
  if (!uv->closed) {
    /* Unlink from the open list of its thread. */
    lua_State *th = uv->th;
    if (uv->prevopen) uv->prevopen->nextopen = uv->nextopen;
    else if (th && th->openupval == uv) th->openupval = uv->nextopen;
    if (uv->nextopen) uv->nextopen->prevopen = uv->prevopen;
  }
  lj_mem_free(g, uv, sizeof(GCupval));
}
