/* State management: global state, threads, stack growth. */
#include "lj.h"
#include "lj_api.h"

#define BASIC_STACK_SIZE (2 * LUA_MINSTACK)
#define BASIC_CI_SIZE 8
#define LJ_MAX_CI 1000000

static const char *const mmnames[MM__MAX] = {
  "__index", "__newindex", "__gc", "__mode", "__eq", "__len",
  "__lt", "__le", "__concat", "__call",
  "__add", "__sub", "__mul", "__div", "__mod", "__pow", "__unm",
  "__metatable", "__tostring", "__new", "__pairs", "__ipairs", "__close"
};

static void stack_init(lua_State *L1, lua_State *L)
{
  int i;
  L1->base_ci = (CallInfo *)lj_mem_alloc(L, BASIC_CI_SIZE * sizeof(CallInfo));
  L1->ci = L1->base_ci;
  L1->size_ci = BASIC_CI_SIZE;
  L1->end_ci = L1->base_ci + L1->size_ci - 1;
  L1->stack = (TValue *)lj_mem_alloc(L, (BASIC_STACK_SIZE + LJ_STACK_EXTRA) * sizeof(TValue));
  L1->stacksize = BASIC_STACK_SIZE + LJ_STACK_EXTRA;
  for (i = 0; i < L1->stacksize; i++) setnilV(&L1->stack[i]);
  L1->top = L1->stack;
  L1->stack_last = L1->stack + (L1->stacksize - LJ_STACK_EXTRA) - 1;
