  L->stack = (TValue *)lj_mem_realloc(L, L->stack, (size_t)L->stacksize * sizeof(TValue), (size_t)realsize * sizeof(TValue));
  for (i = L->stacksize; i < realsize; i++) setnilV(&L->stack[i]);
