  L->stack_last = L->stack + newsize;
  correctstack(L, oldstack);
}

void lj_state_growstack(lua_State *L, int n)
{
  int cursize = (int)(L->stack_last - L->stack);
  int need = (int)(L->top - L->stack) + n;
  int newsize;
  if (cursize > LJ_STACK_MAX) {
    /* Already in error-handling extra space. */
    if (need > LJ_STACK_MAX + 200 + 2 * LUA_MINSTACK) {
      lj_err_throw(L, LUA_ERRERR);
    }
    newsize = need + LUA_MINSTACK;
    realloc_stack(L, newsize);
    return;
  }
  if (need > LJ_STACK_MAX) {
    /* Allow extra space for the error handler, then raise error. */
    realloc_stack(L, LJ_STACK_MAX + 200 + LUA_MINSTACK);
    lj_err_msg(L, "stack overflow");
  }
  newsize = cursize * 2;
  if (newsize < need + LUA_MINSTACK) newsize = need + LUA_MINSTACK;
  if (newsize > LJ_STACK_MAX) newsize = LJ_STACK_MAX;
  realloc_stack(L, newsize);
}

/* Shrink stack back after recovering from a stack overflow. */
void lj_state_shrinkstack(lua_State *L)
{
  int inuse = (int)(L->top - L->stack);
  CallInfo *ci;
  for (ci = L->base_ci; ci <= L->ci; ci++) {
    int t = (int)(ci->top - L->stack);
    if (t > inuse) inuse = t;
  }
  if ((int)(L->stack_last - L->stack) > LJ_STACK_MAX && inuse + 2 * LUA_MINSTACK < LJ_STACK_MAX) {
    realloc_stack(L, LJ_STACK_MAX);
  }
}

void lj_state_growci(lua_State *L)
{
  int newsize = L->size_ci * 2;
  CallInfo *old = L->base_ci;
  if (L->size_ci > LJ_MAX_CI) {
    lj_err_throw(L, LUA_ERRERR);
  }
  L->base_ci = (CallInfo *)lj_mem_realloc(L, L->base_ci, (size_t)L->size_ci * sizeof(CallInfo), (size_t)newsize * sizeof(CallInfo));
  L->ci = (L->ci - old) + L->base_ci;
  L->size_ci = newsize;
  L->end_ci = L->base_ci + L->size_ci - 1;
  if (L->size_ci > LJ_MAX_CI) {
    lj_err_msg(L, "stack overflow");
  }
}

void lj_state_close(lua_State *L)
{
  global_State *g = G(L);
  GCobj *o, *next;
  L = g->mainthread;
  lj_func_closeuv(L, L->stack);
  for (o = g->rootgc; o; o = next) {
    next = o->gch.gcnext;
    switch (o->gch.gct) {
    case LJ_TTHREAD:
      if (&o->th != L) lj_state_free(g, &o->th);
      break;
    default:
      break;
    }
  }
}
