/* Error handling and debug information helpers. */
#include <stdarg.h>
#include "lj.h"
#include "lj_api.h"

struct lua_longjmp {
  struct lua_longjmp *previous;
  jmp_buf b;
  volatile int status;
};

const char *const lj_typenames[] = {
  "nil", "boolean", "boolean", "userdata", "number", "string", "table",
  "function", "userdata", "thread", "cdata", "proto", "upval", "?", "?", "deadkey"
};

const char *lj_typename(cTValue *o)
{
  return lj_typenames[o->tt];
}

void lj_err_seterrorobj(lua_State *L, int status, TValue *oldtop)
{
  switch (status) {
  case LUA_ERRMEM:
    setstrV(oldtop, lj_str_newlit(L, "not enough memory"));
    break;
  case LUA_ERRERR:
    setstrV(oldtop, lj_str_newlit(L, "error in error handling"));
    break;
  case LUA_ERRSYNTAX:
  case LUA_ERRRUN:
    copyTV(oldtop, L->top - 1);
    break;
  }
  L->top = oldtop + 1;
}

LJ_NORET void lj_err_throw(lua_State *L, int status)
{
  if (L->errorJmp) {
    L->errorJmp->status = status;
    _longjmp(L->errorJmp->b, 1);
  } else {
    const char *msg = "?";
    if (status == LUA_ERRMEM) msg = "not enough memory";
    else if (L->top > L->base && tvisstr(L->top - 1)) msg = strdata(strV(L->top - 1));
    fprintf(stderr, "PANIC: unprotected error in call to Lua API (%s)\n", msg);
    fflush(stderr);
    exit(1);
  }
}

int lj_err_rawrunprotected(lua_State *L, void (*f)(lua_State *L, void *ud), void *ud)
{
  struct lua_longjmp lj;
  int oldnCcalls = L->nCcalls;
  lj.status = 0;
  lj.previous = L->errorJmp;
  L->errorJmp = &lj;
  if (_setjmp(lj.b) == 0) {
    f(L, ud);
  }
  L->errorJmp = lj.previous;
  L->nCcalls = oldnCcalls;
  return lj.status;
}

/* -- Debug info ----------------------------------------------------------- */

static int currentpc(CallInfo *ci)
{
  GCfunc *fn;
  if (!(ci->flags & CIST_LUA) || !tvisfunc(ci->func)) return -1;
  fn = funcV(ci->func);
  if (fn->isC || ci->savedpc == NULL) return -1;
  return (int)(ci->savedpc - fn->u.l.pt->code) - 1;
}

int lj_debug_currentline(lua_State *L, CallInfo *ci)
{
  int pc = currentpc(ci);
  GCproto *pt;
  (void)L;
  if (pc < 0) return -1;
  pt = funcV(ci->func)->u.l.pt;
  if (pc >= pt->sizecode) pc = pt->sizecode - 1;
  return pt->lineinfo ? pt->lineinfo[pc] : 0;
}

const char *lj_debug_getlocalname(GCproto *pt, int local_number, int pc)
{
  int i;
  for (i = 0; i < pt->sizevars && pt->vars[i].startpc <= pc; i++) {
    if (pc < pt->vars[i].endpc) {
      local_number--;
      if (local_number == 0) return strdata(pt->vars[i].name);
    }
  }
  return NULL;
}

static int filterpc(int pc, int jmptarget)
{
  if (pc < jmptarget) return -1;
  return pc;
}

/* Find last instruction before lastpc that modified register reg. */
static int findsetreg(GCproto *p, int lastpc, int reg)
{
  int pc;
  int setreg = -1;
  int jmptarget = 0;
  for (pc = 0; pc < lastpc; pc++) {
    BCIns i = p->code[pc];
    int op = GET_OPCODE(i);
    int a = GETARG_A(i);
    int change = 0;
    switch (op) {
    case OP_LOADNIL: {
      int b = GETARG_B(i);
      change = (a <= reg && reg <= b);
      break;
    }
    case OP_TFORLOOP:
      change = (reg >= a + 2);
      break;
    case OP_CALL:
    case OP_TAILCALL:
      change = (reg >= a);
      break;
    case OP_JMP: {
      int b = GETARG_sBx(i);
      int dest = pc + 1 + b;
      if (pc < dest && dest <= lastpc) {
        if (dest > jmptarget) jmptarget = dest;
      }
      change = 0;
      break;
    }
    case OP_FORPREP:
    case OP_FORLOOP:
      change = (reg >= a && reg <= a + 3);
      break;
    case OP_VARARG:
      change = (reg >= a);
      break;
    case OP_LOADBOOL:
      change = (reg == a);
      if (GETARG_C(i)) {
        /* Skips next instruction: treat as conditional. */
      }
      break;
    case OP_SELF:
      change = (reg == a || reg == a + 1);
      break;
    case OP_SETGLOBAL: case OP_SETUPVAL: case OP_SETTABLE: case OP_TSETM:
    case OP_EQ: case OP_LT: case OP_LE: case OP_TEST: case OP_RETURN:
    case OP_SETLIST: case OP_CLOSE:
      change = 0;
      break;
    default:
      change = (reg == a);
      break;
    }
    if (change) setreg = filterpc(pc, jmptarget);
  }
  return setreg;
}

static const char *kname(GCproto *p, int c)
{
  if (ISK(c) && tvisstr(&p->k[INDEXK(c)])) return strdata(strV(&p->k[INDEXK(c)]));
  return NULL;
}

static const char *upvalname(GCproto *p, int uv)
{
  if (p->uvnames && uv < p->nups && p->uvnames[uv]) return strdata(p->uvnames[uv]);
  return "?";
}

static const char *getobjname(GCproto *p, int lastpc, int reg, const char **name)
{
  int pc;
  *name = lj_debug_getlocalname(p, reg + 1, lastpc);
  if (*name) return "local";
  pc = findsetreg(p, lastpc, reg);
  if (pc != -1) {
    BCIns i = p->code[pc];
    switch (GET_OPCODE(i)) {
    case OP_MOVE: {
      int b = GETARG_B(i);
      if (b < GETARG_A(i)) return getobjname(p, pc, b, name);
      break;
    }
    case OP_GETGLOBAL: {
      int g = GETARG_Bx(i);
      if (tvisstr(&p->k[g])) { *name = strdata(strV(&p->k[g])); return "global"; }
      break;
    }
    case OP_GETTABLE: {
      int k = GETARG_C(i);
      *name = kname(p, k);
      if (*name) return "field";
      break;
    }
    case OP_GETUPVAL: {
      *name = upvalname(p, GETARG_B(i));
      return "upvalue";
    }
    case OP_SELF: {
      int k = GETARG_C(i);
      *name = kname(p, k);
      if (*name) return "method";
      break;
    }
    default: break;
    }
  }
  return NULL;
}

const char *lj_debug_varname_slot(lua_State *L, CallInfo *ci, TValue *slot, const char **name)
{
  GCproto *pt;
  int pc;
  (void)L;
  *name = NULL;
  if (!(ci->flags & CIST_LUA)) return NULL;
  if (slot < ci->base || slot >= ci->top) return NULL;
  pt = funcV(ci->func)->u.l.pt;
  pc = currentpc(ci);
  if (pc < 0) return NULL;
  return getobjname(pt, pc, (int)(slot - ci->base), name);
