/* Get name of function called at ci (from the caller's perspective). */
const char *lj_debug_funcname(lua_State *L, CallInfo *ci, const char **name)
{
  CallInfo *pci;
  (void)L;
  *name = NULL;
  if (ci->flags & CIST_MM) {
    int mm = (ci->flags >> 8) & 0xff;
    *name = strdata(G(L)->mmname[mm]);
    return "metamethod";
  }
  if (ci->flags & CIST_FIN) {
    *name = "__gc";
    return "metamethod";
  }
  if (ci <= L->base_ci) return NULL;
  pci = ci - 1;
  if ((pci->flags & CIST_LUA) && !(ci->flags & CIST_HOOKED)) {
    int pc = currentpc(pci);
    GCproto *pt = funcV(pci->func)->u.l.pt;
    BCIns i;
    if (pc < 0) return NULL;
    i = pt->code[pc];
    if (GET_OPCODE(i) == OP_CALL || GET_OPCODE(i) == OP_TAILCALL)
      return getobjname(pt, pc, GETARG_A(i), name);
    if (GET_OPCODE(i) == OP_TFORLOOP) {
      *name = "for iterator";
      return "for iterator";
    }
  }
  return NULL;
}

/* Like luaO_chunkid but with the reference's rules. */
void lj_debug_chunkid(char *out, const char *src, size_t bufflen)
{
  (void)bufflen;
  if (*src == '=') {
    strncpy(out, src + 1, 60);
    out[59] = '\0';
  } else if (*src == '@') {
    size_t len = strlen(src) - 1;
    src++;
    if (len >= 60) {
      src += len - (60 - 4);
      *out++ = '.'; *out++ = '.'; *out++ = '.';
    }
    strcpy(out, src);
  } else {
    size_t len;
    for (len = 0; len < 60 - 12; len++)
      if (((const unsigned char *)src)[len] < ' ') break;
    strcpy(out, "[string \""); out += 9;
    if (src[len] != '\0') {
      if (len > 60 - 15) len = 60 - 15;
      strncpy(out, src, len); out += len;
      strcpy(out, "..."); out += 3;
    } else {
      strcpy(out, src); out += len;
    }
    strcpy(out, "\"]");
  }
}

/* Push "chunk:line: msg" for a Lua frame, or msg otherwise. */
void lj_debug_addloc(lua_State *L, const char *msg, CallInfo *ci)
{
  if (ci && (ci->flags & CIST_LUA) && tvisfunc(ci->func) && !funcV(ci->func)->isC) {
    char buff[256];
    int line = lj_debug_currentline(L, ci);
    GCproto *pt = funcV(ci->func)->u.l.pt;
    lj_debug_chunkid(buff, strdata(pt->source), sizeof(buff));
    lj_checkstack(L, 1);
    setstrV(L->top, lj_str_pushf(L, "%s:%d: %s", buff, line, msg));
    L->top++;
  } else {
    lj_checkstack(L, 1);
    setstrV(L->top, lj_str_newz(L, msg));
    L->top++;
  }
}

int lj_debug_getstack(lua_State *L, int level, CallInfo **pci)
{
  CallInfo *ci;
  for (ci = L->ci; level > 0 && ci > L->base_ci; ci--) level--;
  if (level == 0 && ci > L->base_ci) {
    *pci = ci;
    return 1;
  }
  return 0;
}

void lj_debug_where(lua_State *L, int level)
{
  CallInfo *ci;
  if (lj_debug_getstack(L, level, &ci) && (ci->flags & CIST_LUA)) {
    int line = lj_debug_currentline(L, ci);
    if (line > 0 || line == 0) {
      char buff[256];
      GCproto *pt = funcV(ci->func)->u.l.pt;
      lj_debug_chunkid(buff, strdata(pt->source), sizeof(buff));
      lj_checkstack(L, 1);
      setstrV(L->top, lj_str_pushf(L, "%s:%d: ", buff, line));
      L->top++;
      return;
    }
  }
  lj_checkstack(L, 1);
  setstrV(L->top, lj_str_newlit(L, ""));
  L->top++;
}

/* -- Error throwing --------------------------------------------------------- */

LJ_NORET void lj_err_run(lua_State *L)
{
  if (L->errfunc != 0) {
    TValue *errfunc = restorestack(L, L->errfunc);
    if (!tvisfunc(errfunc)) lj_err_throw(L, LUA_ERRERR);
    if (L->nCcalls > LUAI_MAXCCALLS + 50) lj_err_throw(L, LUA_ERRERR);
    lj_checkstack(L, 2);
    copyTV(L->top, L->top - 1);
    copyTV(L->top - 1, errfunc);
    L->top++;
    lj_vm_call(L, L->top - 2, 1);
  }
  lj_err_throw(L, LUA_ERRRUN);
}

LJ_NORET void lj_err_msg(lua_State *L, const char *msg)
{
