  lj_err_run(L);
}

LJ_NORET void lj_err_callermsg(lua_State *L, const char *msg)
{
  lj_debug_where(L, 1);
  setstrV(L->top - 1, lj_str_pushf(L, "%s%s", strdata(strV(L->top - 1)), msg));
  lj_err_run(L);
}

LJ_NORET void lj_err_runerror(lua_State *L, const char *fmt, ...)
{
  va_list argp;
  GCstr *s;
  va_start(argp, fmt);
  s = lj_str_pushvf(L, fmt, argp);
  va_end(argp);
  lj_checkstack(L, 1);
  setstrV(L->top, s); L->top++;  /* anchor */
  lj_debug_addloc(L, strdata(s), L->ci);
  copyTV(L->top - 2, L->top - 1);
  L->top--;
  lj_err_run(L);
}

/* Error without location. */
LJ_NORET void lj_err_plain(lua_State *L, const char *fmt, ...)
{
  va_list argp;
  GCstr *s;
  va_start(argp, fmt);
  s = lj_str_pushvf(L, fmt, argp);
  va_end(argp);
  lj_checkstack(L, 1);
  setstrV(L->top, s); L->top++;
  lj_err_run(L);
}

LJ_NORET void lj_err_typeop(lua_State *L, cTValue *o, const char *op)
{
  const char *name = NULL;
  const char *kind = NULL;
  const char *t = lj_typename(o);
