  if ((ci->flags & CIST_LUA) && o >= ci->base && o < ci->top)
    kind = lj_debug_varname_slot(L, ci, (TValue *)o, &name);
  if (kind)
    lj_err_runerror(L, "attempt to %s %s '%s' (a %s value)", op, kind, name, t);
  else
    lj_err_runerror(L, "attempt to %s a %s value", op, t);
}

LJ_NORET void lj_err_arith(lua_State *L, cTValue *p1, cTValue *p2)
{
  TValue tmp;
  if (!lj_vm_tonumber(p1, &tmp)) p2 = p1;
  lj_err_typeop(L, p2, "perform arithmetic on");
}

LJ_NORET void lj_err_concat(lua_State *L, cTValue *p1, cTValue *p2)
{
  if (tvisstr(p1) || tvisnum(p1)) p1 = p2;
  lj_err_typeop(L, p1, "concatenate");
}

LJ_NORET void lj_err_compare(lua_State *L, cTValue *p1, cTValue *p2)
{
  const char *t1 = lj_typename(p1);
  const char *t2 = lj_typename(p2);
  if (t1 == t2 || strcmp(t1, t2) == 0)
    lj_err_runerror(L, "attempt to compare two %s values", t1);
  else
    lj_err_runerror(L, "attempt to compare %s with %s", t1, t2);
}

LJ_NORET void lj_err_call(lua_State *L, cTValue *fo)
{
  lj_err_typeop(L, fo, "call");
}

/* Argument errors from C functions. */
LJ_NORET void lj_err_arg(lua_State *L, int narg, const char *msg)
{
  const char *fname = NULL;
  const char *what = lj_debug_funcname(L, L->ci, &fname);
  char buf[512];
  if (what && strcmp(what, "method") == 0) {
    narg--;
    if (narg == 0) {
      snprintf(buf, sizeof(buf), "calling '%s' on bad self (%s)", fname, msg);
      lj_err_callermsg(L, buf);
    }
  }
  if (fname == NULL) fname = "?";
  snprintf(buf, sizeof(buf), "bad argument #%d to '%s' (%s)", narg, fname, msg);
  lj_err_callermsg(L, buf);
}

LJ_NORET void lj_err_argtype(lua_State *L, int narg, const char *xname)
{
  char buf[256];
  const char *tname;
  TValue *o = L->base + narg - 1;
  if (o < L->top) {
    tname = lj_typename(o);
  } else {
    tname = "no value";
  }
  snprintf(buf, sizeof(buf), "%s expected, got %s", xname, tname);
  lj_err_arg(L, narg, buf);
}

LJ_NORET void lj_err_argt(lua_State *L, int narg, int tt)
{
  lj_err_argtype(L, narg, lj_typenames[tt]);
}
