static TValue api_scratch;

TValue *lj_api_index2adr(lua_State *L, int idx)
{
  if (idx > 0) {
    TValue *o = L->base + (idx - 1);
    if (o >= L->top) return (TValue *)&lj_nilobj;
    return o;
  } else if (idx > LUA_REGISTRYINDEX) {
    return L->top + idx;
  } else switch (idx) {
  case LUA_REGISTRYINDEX:
    return &G(L)->registry;
  case LUA_ENVIRONINDEX: {
    GCfunc *fn = funcV(L->ci->func);
    settabV(&api_scratch, fn->env);
    return &api_scratch;
  }
  case LUA_GLOBALSINDEX:
    settabV(&api_scratch, L->env);
    return &api_scratch;
  default: {
    GCfunc *fn = funcV(L->ci->func);
    idx = LUA_GLOBALSINDEX - idx;
    if (fn->isC && idx <= fn->nupvalues) return &fn->u.c.upvalue[idx - 1];
    return (TValue *)&lj_nilobj;
  }
  }
}

int lua_gettop(lua_State *L)
{
  return (int)(L->top - L->base);
}

void lua_settop(lua_State *L, int idx)
{
  if (idx >= 0) {
    TValue *newtop = L->base + idx;
    if (newtop > L->top) {
      lj_checkstack(L, (int)(newtop - L->top));
      while (L->top < newtop) setnilV(L->top++);
    }
    L->top = newtop;
  } else {
    L->top += idx + 1;
  }
}

void lua_pushvalue(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  lj_checkstack(L, 1);
  copyTV(L->top, o);
  L->top++;
}

void lua_remove(lua_State *L, int idx)
{
  TValue *p = index2adr(L, idx);
  while (++p < L->top) copyTV(p - 1, p);
  L->top--;
}

void lua_insert(lua_State *L, int idx)
{
  TValue *p = index2adr(L, idx);
  TValue *q;
  for (q = L->top; q > p; q--) copyTV(q, q - 1);
  copyTV(p, L->top);
}

void lua_replace(lua_State *L, int idx)
{
  if (idx == LUA_ENVIRONINDEX) {
    GCfunc *fn = funcV(L->ci->func);
    if (!tvistab(L->top - 1)) lj_err_msg(L, "table expected");
    fn->env = tabV(L->top - 1);
  } else if (idx == LUA_GLOBALSINDEX) {
    if (tvistab(L->top - 1)) L->env = tabV(L->top - 1);
  } else {
    TValue *o = index2adr(L, idx);
    copyTV(o, L->top - 1);
  }
  L->top--;
}

int lua_checkstack(lua_State *L, int sz)
{
  if (sz > 8000 || (L->top - L->stack) + sz > LJ_STACK_MAX) return 0;
  lj_checkstack(L, sz);
  if (L->ci->top < L->top + sz) L->ci->top = L->top + sz;
  return 1;
}

void lua_xmove(lua_State *from, lua_State *to, int n)
{
  int i;
  if (from == to) return;
  lj_checkstack(to, n);
  from->top -= n;
  for (i = 0; i < n; i++) {
    copyTV(to->top, from->top + i);
    to->top++;
  }
}

