int lua_gc(lua_State *L, int what, int data)
{
  global_State *g = G(L);
  int res = 0;
  switch (what) {
  case LUA_GCSTOP:
    g->gcrunning = 0;
    break;
  case LUA_GCRESTART:
    g->gcrunning = 1;
    if (g->threshold < g->totalbytes) g->threshold = g->totalbytes;
    break;
  case LUA_GCCOLLECT:
    lj_gc_fullgc(L);
    break;
  case LUA_GCCOUNT:
    res = (int)(g->totalbytes >> 10);
    break;
  case LUA_GCCOUNTB:
    res = (int)(g->totalbytes & 0x3ff);
    break;
  case LUA_GCSTEP:
    lj_gc_fullgc(L);
    res = 1;
    break;
  case LUA_GCSETPAUSE:
    res = g->gcpause;
    g->gcpause = data;
    break;
  case LUA_GCSETSTEPMUL:
    res = g->gcstepmul;
    g->gcstepmul = data;
    break;
  case LUA_GCISRUNNING:
    res = g->gcrunning;
    break;
  default:
    res = -1;
  }
  return res;
}

int lua_error(lua_State *L)
{
  lj_err_run(L);
}

int lua_next(lua_State *L, int idx)
{
  TValue *t = index2adr(L, idx);
  int more;
  lj_checkstack(L, 1);
  more = lj_tab_next(L, tabV(t), L->top - 1);
  if (more) {
    L->top++;
  } else {
    L->top--;
  }
  return more;
}

void lua_concat(lua_State *L, int n)
{
  if (n >= 2) {
    lj_vm_concat(L, n, (int)(L->top - L->base) - 1);
    L->top -= (n - 1);
  } else if (n == 0) {
    lua_pushlstring(L, "", 0);
  }
}

void *lua_newuserdata(lua_State *L, size_t size)
{
  GCudata *u = (GCudata *)lj_gc_newobj(L, offsetof(GCudata, align) + size + 8, LJ_TUDATA);
  u->udtype = 0;
  u->finalized = 0;
  u->len = (uint32_t)size;
  u->metatable = NULL;
  u->env = L->env;
  u->gclist = NULL;
  lj_checkstack(L, 1);
  setudataV(L->top, u);
  L->top++;
  return (void *)u->align;
}

void lj_udata_free(global_State *g, GCudata *ud)
{
  lj_mem_free(g, ud, offsetof(GCudata, align) + ud->len + 8);
}

/* -- Auxiliary library ------------------------------------------------------ */

int luaL_typerror(lua_State *L, int narg, const char *tname)
{
  lj_err_argtype(L, narg, tname);
}

int luaL_argerror(lua_State *L, int narg, const char *extramsg)
{
  lj_err_arg(L, narg, extramsg);
}

static void tag_error(lua_State *L, int narg, int tag)
{
  luaL_typerror(L, narg, lua_typename(L, tag));
}

void luaL_where(lua_State *L, int level)
{
  lj_debug_where(L, level);
}

int luaL_error(lua_State *L, const char *fmt, ...)
{
  va_list argp;
  va_start(argp, fmt);
  luaL_where(L, 1);
  lua_pushvfstring(L, fmt, argp);
  va_end(argp);
  lua_concat(L, 2);
  lua_error(L);
}

int luaL_checkoption(lua_State *L, int narg, const char *def, const char *const lst[])
{
  const char *name = (def) ? luaL_optstring(L, narg, def) : luaL_checkstring(L, narg);
  int i;
  for (i = 0; lst[i]; i++)
    if (strcmp(lst[i], name) == 0) return i;
  return luaL_argerror(L, narg, lua_pushfstring(L, "invalid option '%s'", name));
}

int luaL_newmetatable(lua_State *L, const char *tname)
{
  lua_getfield(L, LUA_REGISTRYINDEX, tname);
  if (!lua_isnil(L, -1)) return 0;
  lua_pop(L, 1);
  lua_newtable(L);
  lua_pushvalue(L, -1);
  lua_setfield(L, LUA_REGISTRYINDEX, tname);
  return 1;
}

void *luaL_checkudata(lua_State *L, int ud, const char *tname)
{
  void *p = lua_touserdata(L, ud);
  if (p != NULL && lua_type(L, ud) == LUA_TUSERDATA) {
    if (lua_getmetatable(L, ud)) {
      lua_getfield(L, LUA_REGISTRYINDEX, tname);
      if (lua_rawequal(L, -1, -2)) {
        lua_pop(L, 2);
        return p;
      }
      lua_pop(L, 2);
    }
  }
  luaL_typerror(L, ud, tname);
  return NULL;
}

void luaL_checkstack(lua_State *L, int space, const char *mes)
{
  if (!lua_checkstack(L, space))
    luaL_error(L, "stack overflow (%s)", mes);
}

void luaL_checktype(lua_State *L, int narg, int t)
{
  if (lua_type(L, narg) != t) tag_error(L, narg, t);
}

void luaL_checkany(lua_State *L, int narg)
{
  if (lua_type(L, narg) == LUA_TNONE)
    luaL_argerror(L, narg, "value expected");
}

void lj_lib_checkany(lua_State *L, int narg)
{
  luaL_checkany(L, narg);
}

const char *luaL_checklstring(lua_State *L, int narg, size_t *len)
{
  const char *s = lua_tolstring(L, narg, len);
  if (!s) tag_error(L, narg, LUA_TSTRING);
  return s;
}

const char *luaL_optlstring(lua_State *L, int narg, const char *def, size_t *len)
{
  if (lua_isnoneornil(L, narg)) {
    if (len) *len = (def ? strlen(def) : 0);
    return def;
  }
  return luaL_checklstring(L, narg, len);
}

lua_Number luaL_checknumber(lua_State *L, int narg)
{
  TValue n;
  TValue *o = index2adr(L, narg);
  if (!lj_vm_tonumber(o, &n)) tag_error(L, narg, LUA_TNUMBER);
  return n.u.n;
}

lua_Number luaL_optnumber(lua_State *L, int narg, lua_Number def)
{
  return luaL_opt(L, luaL_checknumber, narg, def);
}

lua_Integer luaL_checkinteger(lua_State *L, int narg)
{
  return (lua_Integer)lj_num2i64(luaL_checknumber(L, narg));
}

lua_Integer luaL_optinteger(lua_State *L, int narg, lua_Integer def)
{
  return luaL_opt(L, luaL_checkinteger, narg, def);
}

int32_t lj_lib_checkint(lua_State *L, int narg)
{
  return lj_num2int32(luaL_checknumber(L, narg));
}

int32_t lj_lib_optint(lua_State *L, int narg, int32_t def)
{
  if (lua_isnoneornil(L, narg)) return def;
  return lj_lib_checkint(L, narg);
}

double lj_lib_checknum(lua_State *L, int narg)
{
  return luaL_checknumber(L, narg);
}

GCstr *lj_lib_checkstr(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (o < L->top) {
    if (tvisstr(o)) return strV(o);
    if (tvisnum(o)) {
      GCstr *s = lj_str_fromnum(L, o->u.n);
      setstrV(o, s);
      return s;
    }
  }
  lj_err_argt(L, narg, LJ_TSTR);
}

GCstr *lj_lib_optstr(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  return (o < L->top && !tvisnil(o)) ? lj_lib_checkstr(L, narg) : NULL;
}

GCtab *lj_lib_checktab(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (!(o < L->top && tvistab(o))) lj_err_argt(L, narg, LJ_TTAB);
  return tabV(o);
}

GCtab *lj_lib_checktabornil(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (o < L->top) {
    if (tvistab(o)) return tabV(o);
    if (tvisnil(o)) return NULL;
  }
  lj_err_arg(L, narg, "nil or table expected");
}

GCfunc *lj_lib_checkfunc(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (!(o < L->top && tvisfunc(o))) lj_err_argt(L, narg, LJ_TFUNC);
  return funcV(o);
}

int luaL_getmetafield(lua_State *L, int obj, const char *event)
{
  if (!lua_getmetatable(L, obj)) return 0;
  lua_pushstring(L, event);
  lua_rawget(L, -2);
  if (lua_isnil(L, -1)) {
    lua_pop(L, 2);
    return 0;
  } else {
    lua_remove(L, -2);
    return 1;
  }
}

int luaL_callmeta(lua_State *L, int obj, const char *event)
{
  obj = obj > 0 || obj <= LUA_REGISTRYINDEX ? obj : lua_gettop(L) + obj + 1;
  if (!luaL_getmetafield(L, obj, event)) return 0;
  lua_pushvalue(L, obj);
  lua_call(L, 1, 1);
  return 1;
}

const char *luaL_findtable(lua_State *L, int idx, const char *fname, int szhint)
{
  const char *e;
  lua_pushvalue(L, idx);
  do {
    e = strchr(fname, '.');
    if (e == NULL) e = fname + strlen(fname);
    lua_pushlstring(L, fname, (size_t)(e - fname));
    lua_rawget(L, -2);
    if (lua_isnil(L, -1)) {
      lua_pop(L, 1);
      lua_createtable(L, 0, (*e == '.' ? 1 : szhint));
      lua_pushlstring(L, fname, (size_t)(e - fname));
      lua_pushvalue(L, -2);
      lua_settable(L, -4);
    } else if (!lua_istable(L, -1)) {
      lua_pop(L, 2);
      return fname;
    }
    lua_remove(L, -2);
    fname = e + 1;
  } while (*e == '.');
  return NULL;
}

void luaL_openlib(lua_State *L, const char *libname, const luaL_Reg *l, int nup)
{
  if (libname) {
    luaL_findtable(L, LUA_REGISTRYINDEX, "_LOADED", 16);
    lua_getfield(L, -1, libname);
    if (!lua_istable(L, -1)) {
      lua_pop(L, 1);
      if (luaL_findtable(L, LUA_GLOBALSINDEX, libname, 0) != NULL)
        luaL_error(L, "name conflict for module '%s'", libname);
      lua_pushvalue(L, -1);
      lua_setfield(L, -3, libname);
    }
    lua_remove(L, -2);
    lua_insert(L, -(nup + 1));
  }
  for (; l && l->name; l++) {
    int i;
    for (i = 0; i < nup; i++) lua_pushvalue(L, -nup);
    lua_pushcclosure(L, l->func, nup);
    lua_setfield(L, -(nup + 2), l->name);
  }
  lua_pop(L, nup);
}

void luaL_register(lua_State *L, const char *libname, const luaL_Reg *l)
{
  luaL_openlib(L, libname, l, 0);
}

void lj_lib_pushcf(lua_State *L, lua_CFunction f, int ffid)
{
  GCfunc *fn = lj_func_newC(L, 0, f, L->env);
  fn->ffid = (uint8_t)ffid;
  lj_checkstack(L, 1);
  setfuncV(L->top, fn);
  L->top++;
}

GCfunc *lj_lib_pushcc(lua_State *L, lua_CFunction f, int ffid, int nup)
{
  GCfunc *fn = lj_func_newC(L, nup, f, L->env);
  int i;
  fn->ffid = (uint8_t)ffid;
  L->top -= nup;
  for (i = 0; i < nup; i++) copyTV(&fn->u.c.upvalue[i], L->top + i);
  lj_checkstack(L, 1);
  setfuncV(L->top, fn);
  L->top++;
  return fn;
}

void lj_lib_register(lua_State *L, const char *libname, const LJLibReg *l)
{
  if (libname) {
    luaL_findtable(L, LUA_REGISTRYINDEX, "_LOADED", 16);
    lua_getfield(L, -1, libname);
    if (!lua_istable(L, -1)) {
      lua_pop(L, 1);
      if (luaL_findtable(L, LUA_GLOBALSINDEX, libname, 0) != NULL)
        luaL_error(L, "name conflict for module '%s'", libname);
      lua_pushvalue(L, -1);
      lua_setfield(L, -3, libname);
    }
    lua_remove(L, -2);
  }
  for (; l->name; l++) {
    lj_lib_pushcf(L, l->func, l->ffid);
    lua_setfield(L, -2, l->name);
  }
}

#define FREELIST_REF 0

int luaL_ref(lua_State *L, int t)
{
  int ref;
  t = t > 0 || t <= LUA_REGISTRYINDEX ? t : lua_gettop(L) + t + 1;
  if (lua_isnil(L, -1)) {
    lua_pop(L, 1);
    return LUA_REFNIL;
  }
  lua_rawgeti(L, t, FREELIST_REF);
  ref = (int)lua_tointeger(L, -1);
  lua_pop(L, 1);
  if (ref != 0) {
    lua_rawgeti(L, t, ref);
    lua_rawseti(L, t, FREELIST_REF);
  } else {
    ref = (int)lua_objlen(L, t);
    ref++;
  }
  lua_rawseti(L, t, ref);
  return ref;
}

void luaL_unref(lua_State *L, int t, int ref)
{
  if (ref >= 0) {
    t = t > 0 || t <= LUA_REGISTRYINDEX ? t : lua_gettop(L) + t + 1;
    lua_rawgeti(L, t, FREELIST_REF);
    lua_rawseti(L, t, ref);
    lua_pushinteger(L, ref);
    lua_rawseti(L, t, FREELIST_REF);
  }
}

typedef struct LoadF {
  int extraline;
  FILE *f;
  char buff[8192];
} LoadF;

static const char *getF(lua_State *L, void *ud, size_t *size)
{
  LoadF *lf = (LoadF *)ud;
  (void)L;
  if (lf->extraline) {
    lf->extraline = 0;
    *size = 1;
    return "\n";
  }
  if (feof(lf->f)) return NULL;
  *size = fread(lf->buff, 1, sizeof(lf->buff), lf->f);
  return (*size > 0) ? lf->buff : NULL;
}

static int errfile(lua_State *L, const char *what, int fnameindex)
{
  const char *serr = strerror(errno);
  const char *filename = lua_tostring(L, fnameindex) + 1;
  lua_pushfstring(L, "cannot %s %s: %s", what, filename, serr);
  lua_remove(L, fnameindex);
  return LUA_ERRFILE;
}

int luaL_loadfilex(lua_State *L, const char *filename, const char *mode)
{
  LoadF lf;
  int status, readstatus;
  int c;
  int fnameindex = lua_gettop(L) + 1;
  lf.extraline = 0;
  if (filename == NULL) {
    lua_pushliteral(L, "=stdin");
    lf.f = stdin;
  } else {
    lua_pushfstring(L, "@%s", filename);
    lf.f = fopen(filename, "rb");
    if (lf.f == NULL) return errfile(L, "open", fnameindex);
  }
  c = getc(lf.f);
  if (c == '#') {
    lf.extraline = 1;
    while ((c = getc(lf.f)) != EOF && c != '\n') ;
    if (c == '\n') c = getc(lf.f);
  }
  ungetc(c, lf.f);
  status = lua_loadx(L, getF, &lf, lua_tostring(L, -1), mode);
  readstatus = ferror(lf.f);
  if (filename) fclose(lf.f);
  if (readstatus) {
    lua_settop(L, fnameindex);
    return errfile(L, "read", fnameindex);
  }
  lua_remove(L, fnameindex);
  return status;
}

int luaL_loadfile(lua_State *L, const char *filename)
{
  return luaL_loadfilex(L, filename, NULL);
}

typedef struct LoadS {
  const char *s;
  size_t size;
} LoadS;

static const char *getS(lua_State *L, void *ud, size_t *size)
{
  LoadS *ls = (LoadS *)ud;
  (void)L;
  if (ls->size == 0) return NULL;
  *size = ls->size;
  ls->size = 0;
  return ls->s;
}

int luaL_loadbufferx(lua_State *L, const char *buff, size_t size, const char *name, const char *mode)
{
  LoadS ls;
  ls.s = buff;
  ls.size = size;
  return lua_loadx(L, getS, &ls, name, mode);
}

int luaL_loadbuffer(lua_State *L, const char *buff, size_t size, const char *name)
{
  return luaL_loadbufferx(L, buff, size, name, NULL);
}

int luaL_loadstring(lua_State *L, const char *s)
{
  return luaL_loadbuffer(L, s, strlen(s), s);
}

const char *luaL_gsub(lua_State *L, const char *s, const char *p, const char *r)
{
  const char *wild;
  size_t l = strlen(p);
  luaL_Buffer b;
  luaL_buffinit(L, &b);
  while ((wild = strstr(s, p)) != NULL) {
    luaL_addlstring(&b, s, (size_t)(wild - s));
    luaL_addstring(&b, r);
    s = wild + l;
  }
  luaL_addstring(&b, s);
  luaL_pushresult(&b);
  return lua_tostring(L, -1);
}

int luaL_fileresult(lua_State *L, int stat, const char *fname)
{
  int en = errno;
  if (stat) {
    lua_pushboolean(L, 1);
    return 1;
  } else {
    lua_pushnil(L);
    if (fname)
      lua_pushfstring(L, "%s: %s", fname, strerror(en));
    else
      lua_pushfstring(L, "%s", strerror(en));
    lua_pushinteger(L, en);
    return 3;
  }
}

/* -- Buffers ---------------------------------------------------------------- */

void luaL_buffinit(lua_State *L, luaL_Buffer *B)
{
  B->L = L;
  B->b = B->init;
  B->n = 0;
  B->cap = sizeof(B->init);
}

char *luaL_prepbuffsize(luaL_Buffer *B, size_t sz)
{
  if (B->n + sz > B->cap) {
    size_t ncap = B->cap * 2;
    while (ncap < B->n + sz) ncap *= 2;
    if (B->b == B->init) {
      char *nb = (char *)malloc(ncap);
      if (!nb) lj_err_throw(B->L, LUA_ERRMEM);
      memcpy(nb, B->b, B->n);
      B->b = nb;
    } else {
      char *nb = (char *)realloc(B->b, ncap);
      if (!nb) lj_err_throw(B->L, LUA_ERRMEM);
      B->b = nb;
    }
    B->cap = ncap;
  }
  return B->b + B->n;
}

void luaL_addlstring(luaL_Buffer *B, const char *s, size_t l)
{
  if (l == 0) return;
  luaL_prepbuffsize(B, l);
  memcpy(B->b + B->n, s, l);
  B->n += l;
}

void luaL_addstring(luaL_Buffer *B, const char *s)
{
  luaL_addlstring(B, s, strlen(s));
}

void luaL_addvalue(luaL_Buffer *B)
{
  lua_State *L = B->L;
  size_t vl;
  const char *s = lua_tolstring(L, -1, &vl);
  luaL_addlstring(B, s, vl);
  lua_pop(L, 1);
}

void luaL_bufffree(luaL_Buffer *B)
{
  if (B->b != B->init) free(B->b);
  B->b = B->init;
  B->n = 0;
  B->cap = sizeof(B->init);
}

void luaL_pushresult(luaL_Buffer *B)
{
  lua_pushlstring(B->L, B->b, B->n);
  luaL_bufffree(B);
}
