cd /workspace/src && cat > lj_api.c <<'EOF'
/* Public C API (Lua 5.1 compatible subset) and auxiliary library. */
#include <stdarg.h>
#include <errno.h>
#include "lj.h"
#include "lj_api.h"

static TValue api_scratch;

TValue *lj_api_index2adr(lua_State *L, int idx)
{
  if (idx > 0) {
    TValue *o = L->base + (idx - 1);
    if (o >= L->top) return (TValue *)&lj_nilobj;
    return o;
  } else if (idx > LUA_REGISTRYINDEX) {
    return L->top + idx;
  } else switch (idx) {
  case LUA_REGISTRYINDEX:
    return &G(L)->registry;
  case LUA_ENVIRONINDEX: {
    GCfunc *fn = funcV(L->ci->func);
    settabV(&api_scratch, fn->env);
    return &api_scratch;
  }
  case LUA_GLOBALSINDEX:
    settabV(&api_scratch, L->env);
    return &api_scratch;
  default: {
    GCfunc *fn = funcV(L->ci->func);
    idx = LUA_GLOBALSINDEX - idx;
    if (fn->isC && idx <= fn->nupvalues) return &fn->u.c.upvalue[idx - 1];
    return (TValue *)&lj_nilobj;
  }
  }
}

int lua_gettop(lua_State *L)
{
  return (int)(L->top - L->base);
}

void lua_settop(lua_State *L, int idx)
{
  if (idx >= 0) {
    TValue *newtop = L->base + idx;
    if (newtop > L->top) {
      lj_checkstack(L, (int)(newtop - L->top));
      while (L->top < newtop) setnilV(L->top++);
    }
    L->top = newtop;
  } else {
    L->top += idx + 1;
  }
}

void lua_pushvalue(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  lj_checkstack(L, 1);
  copyTV(L->top, o);
  L->top++;
}

void lua_remove(lua_State *L, int idx)
{
  TValue *p = index2adr(L, idx);
  while (++p < L->top) copyTV(p - 1, p);
  L->top--;
}

void lua_insert(lua_State *L, int idx)
{
  TValue *p = index2adr(L, idx);
  TValue *q;
  for (q = L->top; q > p; q--) copyTV(q, q - 1);
  copyTV(p, L->top);
}

void lua_replace(lua_State *L, int idx)
{
  if (idx == LUA_ENVIRONINDEX) {
    GCfunc *fn = funcV(L->ci->func);
    if (!tvistab(L->top - 1)) lj_err_msg(L, "table expected");
    fn->env = tabV(L->top - 1);
  } else if (idx == LUA_GLOBALSINDEX) {
    if (tvistab(L->top - 1)) L->env = tabV(L->top - 1);
  } else {
    TValue *o = index2adr(L, idx);
    copyTV(o, L->top - 1);
  }
  L->top--;
}

int lua_checkstack(lua_State *L, int sz)
{
  if (sz > 8000 || (L->top - L->stack) + sz > LJ_STACK_MAX) return 0;
  lj_checkstack(L, sz);
  if (L->ci->top < L->top + sz) L->ci->top = L->top + sz;
  return 1;
}

void lua_xmove(lua_State *from, lua_State *to, int n)
{
  int i;
  if (from == to) return;
  lj_checkstack(to, n);
  from->top -= n;
  for (i = 0; i < n; i++) {
    copyTV(to->top, from->top + i);
    to->top++;
  }
}

static const int tt2lua[16] = {
  LUA_TNIL, LUA_TBOOLEAN, LUA_TBOOLEAN, LUA_TLIGHTUSERDATA, LUA_TNUMBER,
  LUA_TSTRING, LUA_TTABLE, LUA_TFUNCTION, LUA_TUSERDATA, LUA_TTHREAD,
  LUA_TCDATA, 9, 9, 9, 9, 9
};

int lua_type(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  if (o == &lj_nilobj) return LUA_TNONE;
  return tt2lua[o->tt];
}

const char *lua_typename(lua_State *L, int t)
{
  static const char *const names[] = {
    "nil", "boolean", "userdata", "number", "string", "table", "function",
    "userdata", "thread", "proto", "cdata"
  };
  (void)L;
  if (t == LUA_TNONE) return "no value";
  return names[t];
}

int lua_iscfunction(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  return tvisfunc(o) && funcV(o)->isC;
}

int lua_isnumber(lua_State *L, int idx)
{
  TValue n;
  TValue *o = index2adr(L, idx);
  return lj_vm_tonumber(o, &n);
}

int lua_isstring(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  return tvisstr(o) || tvisnum(o);
}

int lua_isuserdata(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  return tvisudata(o) || tvislightud(o);
}

int lua_rawequal(lua_State *L, int idx1, int idx2)
{
  TValue *o1 = index2adr(L, idx1);
  TValue *o2 = index2adr(L, idx2);
  if (o1 == &lj_nilobj || o2 == &lj_nilobj) return 0;
  if (o1->tt != o2->tt) return 0;
  if (o1->tt == LJ_TNUM) return o1->u.n == o2->u.n;
  if (o1->tt <= LJ_TTRUE) return 1;
  return o1->u.p == o2->u.p;
}

int lua_equal(lua_State *L, int idx1, int idx2)
{
  TValue *o1 = index2adr(L, idx1);
  TValue *o2 = index2adr(L, idx2);
  if (o1 == &lj_nilobj || o2 == &lj_nilobj) return 0;
  return lj_vm_equal(L, o1, o2);
}

int lua_lessthan(lua_State *L, int idx1, int idx2)
{
  TValue *o1 = index2adr(L, idx1);
  TValue *o2 = index2adr(L, idx2);
  if (o1 == &lj_nilobj || o2 == &lj_nilobj) return 0;
  return lj_vm_lessthan(L, o1, o2);
}

lua_Number lua_tonumber(lua_State *L, int idx)
{
  TValue n;
  TValue *o = index2adr(L, idx);
  if (lj_vm_tonumber(o, &n)) return n.u.n;
  return 0;
}

lua_Integer lua_tointeger(lua_State *L, int idx)
{
  TValue n;
  TValue *o = index2adr(L, idx);
  if (lj_vm_tonumber(o, &n)) return (lua_Integer)lj_num2i64(n.u.n);
  return 0;
}

int lua_toboolean(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  return !tvisfalse(o);
}

const char *lua_tolstring(lua_State *L, int idx, size_t *len)
{
  TValue *o = index2adr(L, idx);
  if (tvisnum(o)) {
    GCstr *s = lj_str_fromnum(L, o->u.n);
    o = index2adr(L, idx);
    setstrV(o, s);
  } else if (!tvisstr(o)) {
    if (len) *len = 0;
    return NULL;
  }
  if (len) *len = strV(o)->len;
  return strdata(strV(o));
}

size_t lua_objlen(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  switch (o->tt) {
  case LJ_TSTR: return strV(o)->len;
  case LJ_TUDATA: return udataV(o)->len;
  case LJ_TTAB: return lj_tab_len(tabV(o));
  case LJ_TNUM: {
    GCstr *s = lj_str_fromnum(L, o->u.n);
    return s->len;
  }
  default: return 0;
  }
}

lua_CFunction lua_tocfunction(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  return (tvisfunc(o) && funcV(o)->isC) ? funcV(o)->u.c.f : NULL;
}

extern void *lj_cdata_ptr(GCcdata *cd);

void *lua_touserdata(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  if (tvisudata(o)) return (void *)udataV(o)->align;
  if (tvislightud(o)) return lightudV(o);
  return NULL;
}

lua_State *lua_tothread(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  return tvisthread(o) ? threadV(o) : NULL;
}

const void *lua_topointer(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  switch (o->tt) {
  case LJ_TTAB: case LJ_TFUNC: case LJ_TTHREAD: case LJ_TPROTO:
    return o->u.p;
  case LJ_TUDATA:
    return (void *)udataV(o)->align;
  case LJ_TLIGHTUD:
    return o->u.p;
  case LJ_TCDATA:
    return lj_cdata_ptr(cdataV(o));
  default:
    return NULL;
  }
}

void lua_pushnil(lua_State *L)
{
  lj_checkstack(L, 1);
  setnilV(L->top);
  L->top++;
}

void lua_pushnumber(lua_State *L, lua_Number n)
{
  lj_checkstack(L, 1);
  setnumV(L->top, n);
  L->top++;
}

void lua_pushinteger(lua_State *L, lua_Integer n)
{
  lj_checkstack(L, 1);
  setnumV(L->top, (double)n);
  L->top++;
}

void lua_pushlstring(lua_State *L, const char *s, size_t len)
{
  GCstr *str = lj_str_new(L, s, len);
  lj_checkstack(L, 1);
  setstrV(L->top, str);
  L->top++;
}

void lua_pushstring(lua_State *L, const char *s)
{
  if (s == NULL) lua_pushnil(L);
  else lua_pushlstring(L, s, strlen(s));
}

void lua_pushstr(lua_State *L, GCstr *s)
{
  lj_checkstack(L, 1);
  setstrV(L->top, s);
  L->top++;
}

void lua_pushtv(lua_State *L, cTValue *o)
{
  lj_checkstack(L, 1);
  copyTV(L->top, o);
  L->top++;
}

const char *lua_pushvfstring(lua_State *L, const char *fmt, va_list argp)
{
  GCstr *s = lj_str_pushvf(L, fmt, argp);
  lua_pushstr(L, s);
  return strdata(s);
}

const char *lua_pushfstring(lua_State *L, const char *fmt, ...)
{
  const char *ret;
  va_list argp;
  va_start(argp, fmt);
  ret = lua_pushvfstring(L, fmt, argp);
  va_end(argp);
  return ret;
}

void lua_pushcclosure(lua_State *L, lua_CFunction fn, int n)
{
  GCfunc *cl = lj_func_newC(L, n, fn, funcV(L->ci->func) && tvisfunc(L->ci->func) ? funcV(L->ci->func)->env : L->env);
  int i;
  L->top -= n;
  for (i = 0; i < n; i++) copyTV(&cl->u.c.upvalue[i], L->top + i);
  lj_checkstack(L, 1);
  setfuncV(L->top, cl);
  L->top++;
}

void lua_pushboolean(lua_State *L, int b)
{
  lj_checkstack(L, 1);
  setboolV(L->top, b != 0);
  L->top++;
}

void lua_pushlightuserdata(lua_State *L, void *p)
{
  lj_checkstack(L, 1);
  setlightudV(L->top, p);
  L->top++;
}

int lua_pushthread(lua_State *L)
{
  lj_checkstack(L, 1);
  setthreadV(L->top, L);
  L->top++;
  return (G(L)->mainthread == L);
}

void lua_gettable(lua_State *L, int idx)
{
  TValue *t = index2adr(L, idx);
  TValue key = L->top[-1];
  lj_vm_gettable(L, t, &key, L->top - 1);
}

void lua_getfield(lua_State *L, int idx, const char *k)
{
  TValue *t = index2adr(L, idx);
  TValue key;
  TValue tt = *t;
  setstrV(&key, lj_str_newz(L, k));
  lj_checkstack(L, 1);
  setnilV(L->top);
  L->top++;
  lj_vm_gettable(L, &tt, &key, L->top - 1);
}

void lua_rawget(lua_State *L, int idx)
{
  TValue *t = index2adr(L, idx);
  cTValue *v = lj_tab_get(L, tabV(t), L->top - 1);
  copyTV(L->top - 1, v);
}

void lua_rawgeti(lua_State *L, int idx, int n)
{
  TValue *o = index2adr(L, idx);
  cTValue *v = lj_tab_getint(tabV(o), n);
  lj_checkstack(L, 1);
  if (v) copyTV(L->top, v); else setnilV(L->top);
  L->top++;
}

void lua_createtable(lua_State *L, int narray, int nrec)
{
  GCtab *t = lj_tab_new(L, narray > 0 ? (uint32_t)narray + 1 : 0, lj_tab_hsize2hbits((uint32_t)nrec));
  lj_checkstack(L, 1);
  settabV(L->top, t);
  L->top++;
}

int lua_getmetatable(lua_State *L, int objindex)
{
  TValue *obj = index2adr(L, objindex);
  GCtab *mt = NULL;
  if (obj == &lj_nilobj) return 0;
  mt = lj_meta_getmt(L, obj);
  if (mt == NULL) return 0;
  lj_checkstack(L, 1);
  settabV(L->top, mt);
  L->top++;
  return 1;
}

void lua_getfenv(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  lj_checkstack(L, 1);
  switch (o->tt) {
  case LJ_TFUNC:
    if (funcV(o)->env) settabV(L->top, funcV(o)->env); else setnilV(L->top);
    break;
  case LJ_TUDATA:
    if (udataV(o)->env) settabV(L->top, udataV(o)->env); else setnilV(L->top);
    break;
  case LJ_TTHREAD:
    settabV(L->top, threadV(o)->env);
    break;
  default:
    setnilV(L->top);
    break;
  }
  L->top++;
}

void lua_settable(lua_State *L, int idx)
{
  TValue *t = index2adr(L, idx);
  TValue tt = *t;
  lj_vm_settable(L, &tt, L->top - 2, L->top - 1);
  L->top -= 2;
}

void lua_setfield(lua_State *L, int idx, const char *k)
{
  TValue *t = index2adr(L, idx);
  TValue tt = *t;
  TValue key;
  setstrV(&key, lj_str_newz(L, k));
  lj_vm_settable(L, &tt, &key, L->top - 1);
  L->top--;
}

void lua_rawset(lua_State *L, int idx)
{
  TValue *t = index2adr(L, idx);
  TValue *v = lj_tab_set(L, tabV(t), L->top - 2);
  copyTV(v, L->top - 1);
  L->top -= 2;
}

void lua_rawseti(lua_State *L, int idx, int n)
{
  TValue *o = index2adr(L, idx);
  TValue *v = lj_tab_setint(L, tabV(o), n);
  copyTV(v, L->top - 1);
  L->top--;
}

int lua_setmetatable(lua_State *L, int objindex)
{
  TValue *obj = index2adr(L, objindex);
  GCtab *mt = NULL;
  if (!tvisnil(L->top - 1)) mt = tabV(L->top - 1);
  switch (obj->tt) {
  case LJ_TTAB:
    tabV(obj)->metatable = mt;
    break;
  case LJ_TUDATA:
    udataV(obj)->metatable = mt;
    break;
  default:
    G(L)->basemt[obj->tt == LJ_TTRUE ? LJ_TFALSE : obj->tt] = mt;
    if (obj->tt == LJ_TSTR) G(L)->strmt = mt;
    break;
  }
  L->top--;
  return 1;
}

int lua_setfenv(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  int res = 1;
  GCtab *env = tabV(L->top - 1);
  switch (o->tt) {
  case LJ_TFUNC: funcV(o)->env = env; break;
  case LJ_TUDATA: udataV(o)->env = env; break;
  case LJ_TTHREAD: threadV(o)->env = env; break;
  default: res = 0; break;
  }
  L->top--;
  return res;
}

void lua_call(lua_State *L, int nargs, int nresults)
{
  TValue *func = L->top - (nargs + 1);
  lj_vm_call(L, func, nresults);
}

struct CallS {
  TValue *func;
  int nresults;
};

static void f_call(lua_State *L, void *ud)
{
  struct CallS *c = (struct CallS *)ud;
  lj_vm_call(L, c->func, c->nresults);
}

int lua_pcall(lua_State *L, int nargs, int nresults, int errfunc)
{
  struct CallS c;
  int status;
  ptrdiff_t func;
  if (errfunc == 0) func = 0;
  else func = savestack(L, index2adr(L, errfunc));
  c.func = L->top - (nargs + 1);
  c.nresults = nresults;
  status = lj_vm_pcall(L, f_call, &c, savestack(L, c.func), func);
  return status;
}

struct CCallS {
  lua_CFunction func;
  void *ud;
};

static void f_Ccall(lua_State *L, void *ud)
{
  struct CCallS *c = (struct CCallS *)ud;
  GCfunc *cl = lj_func_newC(L, 0, c->func, L->env);
  setfuncV(L->top, cl);
  L->top++;
  setlightudV(L->top, c->ud);
  L->top++;
  lj_vm_call(L, L->top - 2, 0);
}

int lua_cpcall(lua_State *L, lua_CFunction func, void *ud)
{
  struct CCallS c;
  c.func = func;
  c.ud = ud;
  lj_checkstack(L, 2);
  return lj_vm_pcall(L, f_Ccall, &c, savestack(L, L->top), 0);
}

int lua_loadx(lua_State *L, lua_Reader reader, void *data, const char *chunkname, const char *mode)
{
  if (!chunkname) chunkname = "?";
  return lj_load(L, reader, data, chunkname, mode);
}

int lua_load(lua_State *L, lua_Reader reader, void *data, const char *chunkname)
{
  return lua_loadx(L, reader, data, chunkname, NULL);
}

int lua_status(lua_State *L)
{
  return L->status;
}

int lua_gc(lua_State *L, int what, int data)
{
  global_State *g = G(L);
  int res = 0;
  switch (what) {
  case LUA_GCSTOP:
    g->gcrunning = 0;
    break;
  case LUA_GCRESTART:
    g->gcrunning = 1;
    if (g->threshold < g->totalbytes) g->threshold = g->totalbytes;
    break;
  case LUA_GCCOLLECT:
    lj_gc_fullgc(L);
    break;
  case LUA_GCCOUNT:
    res = (int)(g->totalbytes >> 10);
    break;
  case LUA_GCCOUNTB:
    res = (int)(g->totalbytes & 0x3ff);
    break;
  case LUA_GCSTEP:
    lj_gc_fullgc(L);
    res = 1;
    break;
  case LUA_GCSETPAUSE:
    res = g->gcpause;
    g->gcpause = data;
    break;
  case LUA_GCSETSTEPMUL:
    res = g->gcstepmul;
    g->gcstepmul = data;
    break;
  case LUA_GCISRUNNING:
    res = g->gcrunning;
    break;
  default:
    res = -1;
  }
  return res;
}

int lua_error(lua_State *L)
{
  lj_err_run(L);
}

int lua_next(lua_State *L, int idx)
{
  TValue *t = index2adr(L, idx);
  int more;
  lj_checkstack(L, 1);
  more = lj_tab_next(L, tabV(t), L->top - 1);
  if (more) {
    L->top++;
  } else {
    L->top--;
  }
  return more;
}

void lua_concat(lua_State *L, int n)
{
  if (n >= 2) {
    lj_vm_concat(L, n, (int)(L->top - L->base) - 1);
    L->top -= (n - 1);
  } else if (n == 0) {
    lua_pushlstring(L, "", 0);
  }
}

void *lua_newuserdata(lua_State *L, size_t size)
{
  GCudata *u = (GCudata *)lj_gc_newobj(L, offsetof(GCudata, align) + size + 8, LJ_TUDATA);
  u->udtype = 0;
  u->finalized = 0;
  u->len = (uint32_t)size;
  u->metatable = NULL;
  u->env = L->env;
  u->gclist = NULL;
  lj_checkstack(L, 1);
  setudataV(L->top, u);
  L->top++;
  return (void *)u->align;
}

void lj_udata_free(global_State *g, GCudata *ud)
{
  lj_mem_free(g, ud, offsetof(GCudata, align) + ud->len + 8);
}

/* -- Auxiliary library ------------------------------------------------------ */

int luaL_typerror(lua_State *L, int narg, const char *tname)
{
  lj_err_argtype(L, narg, tname);
}

int luaL_argerror(lua_State *L, int narg, const char *extramsg)
{
  lj_err_arg(L, narg, extramsg);
}

static void tag_error(lua_State *L, int narg, int tag)
{
  luaL_typerror(L, narg, lua_typename(L, tag));
}

void luaL_where(lua_State *L, int level)
{
  lj_debug_where(L, level);
}

int luaL_error(lua_State *L, const char *fmt, ...)
{
  va_list argp;
  va_start(argp, fmt);
  luaL_where(L, 1);
  lua_pushvfstring(L, fmt, argp);
  va_end(argp);
  lua_concat(L, 2);
  lua_error(L);
}

int luaL_checkoption(lua_State *L, int narg, const char *def, const char *const lst[])
{
  const char *name = (def) ? luaL_optstring(L, narg, def) : luaL_checkstring(L, narg);
  int i;
  for (i = 0; lst[i]; i++)
    if (strcmp(lst[i], name) == 0) return i;
  return luaL_argerror(L, narg, lua_pushfstring(L, "invalid option '%s'", name));
}

int luaL_newmetatable(lua_State *L, const char *tname)
{
  lua_getfield(L, LUA_REGISTRYINDEX, tname);
  if (!lua_isnil(L, -1)) return 0;
  lua_pop(L, 1);
  lua_newtable(L);
  lua_pushvalue(L, -1);
  lua_setfield(L, LUA_REGISTRYINDEX, tname);
  return 1;
}

void *luaL_checkudata(lua_State *L, int ud, const char *tname)
{
  void *p = lua_touserdata(L, ud);
  if (p != NULL && lua_type(L, ud) == LUA_TUSERDATA) {
    if (lua_getmetatable(L, ud)) {
      lua_getfield(L, LUA_REGISTRYINDEX, tname);
      if (lua_rawequal(L, -1, -2)) {
        lua_pop(L, 2);
        return p;
      }
      lua_pop(L, 2);
    }
  }
  luaL_typerror(L, ud, tname);
  return NULL;
}

void luaL_checkstack(lua_State *L, int space, const char *mes)
{
  if (!lua_checkstack(L, space))
    luaL_error(L, "stack overflow (%s)", mes);
}

void luaL_checktype(lua_State *L, int narg, int t)
{
  if (lua_type(L, narg) != t) tag_error(L, narg, t);
}

void luaL_checkany(lua_State *L, int narg)
{
  if (lua_type(L, narg) == LUA_TNONE)
    luaL_argerror(L, narg, "value expected");
}

void lj_lib_checkany(lua_State *L, int narg)
{
  luaL_checkany(L, narg);
}

const char *luaL_checklstring(lua_State *L, int narg, size_t *len)
{
  const char *s = lua_tolstring(L, narg, len);
  if (!s) tag_error(L, narg, LUA_TSTRING);
  return s;
}

const char *luaL_optlstring(lua_State *L, int narg, const char *def, size_t *len)
{
  if (lua_isnoneornil(L, narg)) {
    if (len) *len = (def ? strlen(def) : 0);
    return def;
  }
  return luaL_checklstring(L, narg, len);
}

lua_Number luaL_checknumber(lua_State *L, int narg)
{
  TValue n;
  TValue *o = index2adr(L, narg);
  if (!lj_vm_tonumber(o, &n)) tag_error(L, narg, LUA_TNUMBER);
  return n.u.n;
}

lua_Number luaL_optnumber(lua_State *L, int narg, lua_Number def)
{
  return luaL_opt(L, luaL_checknumber, narg, def);
}

lua_Integer luaL_checkinteger(lua_State *L, int narg)
{
  return (lua_Integer)lj_num2i64(luaL_checknumber(L, narg));
}

lua_Integer luaL_optinteger(lua_State *L, int narg, lua_Integer def)
{
  return luaL_opt(L, luaL_checkinteger, narg, def);
}

int32_t lj_lib_checkint(lua_State *L, int narg)
{
  return lj_num2int32(luaL_checknumber(L, narg));
}

int32_t lj_lib_optint(lua_State *L, int narg, int32_t def)
{
  if (lua_isnoneornil(L, narg)) return def;
  return lj_lib_checkint(L, narg);
}

double lj_lib_checknum(lua_State *L, int narg)
{
  return luaL_checknumber(L, narg);
}

GCstr *lj_lib_checkstr(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (o < L->top) {
    if (tvisstr(o)) return strV(o);
    if (tvisnum(o)) {
      GCstr *s = lj_str_fromnum(L, o->u.n);
      setstrV(o, s);
      return s;
    }
  }
  lj_err_argt(L, narg, LJ_TSTR);
}

GCstr *lj_lib_optstr(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  return (o < L->top && !tvisnil(o)) ? lj_lib_checkstr(L, narg) : NULL;
}

GCtab *lj_lib_checktab(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (!(o < L->top && tvistab(o))) lj_err_argt(L, narg, LJ_TTAB);
  return tabV(o);
}

GCtab *lj_lib_checktabornil(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
