        uint32_t cp = 0;
        int any = 0;
        lex_next(ls);
        if (ls->c != '{') goto err_xesc;
        lex_next(ls);
        while (hexval(ls->c) >= 0) {
          cp = (cp << 4) | (uint32_t)hexval(ls->c);
          if (cp >= 0x110000) goto err_xesc;
          any = 1;
          lex_next(ls);
        }
        if (!any || ls->c != '}') goto err_xesc;
        lex_next(ls);
        if (cp < 0x80) {
          save(ls, (int)cp);
        } else if (cp < 0x800) {
          save(ls, (int)(0xc0 | (cp >> 6)));
          save(ls, (int)(0x80 | (cp & 0x3f)));
        } else if (cp < 0x10000) {
          save(ls, (int)(0xe0 | (cp >> 12)));
          save(ls, (int)(0x80 | ((cp >> 6) & 0x3f)));
          save(ls, (int)(0x80 | (cp & 0x3f)));
        } else {
          save(ls, (int)(0xf0 | (cp >> 18)));
          save(ls, (int)(0x80 | ((cp >> 12) & 0x3f)));
          save(ls, (int)(0x80 | ((cp >> 6) & 0x3f)));
          save(ls, (int)(0x80 | (cp & 0x3f)));
        }
        continue;
      }
      case '\n':
      case '\r':
        save(ls, '\n');
        inclinenumber(ls);
        continue;
      case END_OF_STREAM:
        continue;  /* will raise error next loop */
      default:
        if (!isdigit(ls->c)) {
