            lex_next(ls);
          } while (++i < 3 && isdigit(ls->c));
          if (c > 255) goto err_xesc;
          save(ls, c);
          continue;
        }
      }
      save(ls, c);
      lex_next(ls);
      continue;
    err_xesc:
      lex_tokerror(ls, TK_string, "invalid escape sequence");
    }
    default:
      save_and_next(ls);
    }
  }
  save_and_next(ls);  /* skip delimiter */
  {
    GCstr *s = lj_lex_newstr(ls, ls->sb + 1, ls->sbn - 2);
    setstrV(&t->val, s);
  }
}

static int isident(int c)
{
  return isalnum(c) || c == '_' || c >= 0x80;
}

static void read_numeral(LexState *ls, Token *t)
{
  int c, xp = 'e';
  int fmt;
  if ((c = ls->c) == '0') {
    save_and_next(ls);
    if ((ls->c | 0x20) == 'x') xp = 'p';
  }
  while (isident(ls->c) || ls->c == '.' ||
         ((ls->c == '-' || ls->c == '+') && (c | 0x20) == xp)) {
    c = ls->c;
    save_and_next(ls);
  }
  fmt = lj_strscan_scan(ls->sb, ls->sbn, &t->val, STRSCAN_OPT_LL | STRSCAN_OPT_IMAG);
  if (fmt == STRSCAN_NUM) {
    t->tok = TK_number;
  } else if (fmt == STRSCAN_ERROR) {
    lex_tokerror(ls, TK_number, "malformed number");
  } else {
    t->tok = TK_cdata;
    t->cdkind = fmt;
  }
}

static int llex(LexState *ls, Token *t)
{
  ls->sbn = 0;
  for (;;) {
    switch (ls->c) {
    case '\n':
    case '\r':
      inclinenumber(ls);
      continue;
    case '-':
      lex_next(ls);
      if (ls->c != '-') return '-';
      lex_next(ls);
      if (ls->c == '[') {
        int sep = skip_sep(ls);
        ls->sbn = 0;
        if (sep >= 0) {
          read_long_string(ls, NULL, sep);
          ls->sbn = 0;
          continue;
        }
      }
      while (!currIsNewline(ls) && ls->c != END_OF_STREAM) lex_next(ls);
      ls->sbn = 0;
      continue;
    case '[': {
      int sep = skip_sep(ls);
      if (sep >= 0) {
        read_long_string(ls, t, sep);
        return TK_string;
      } else if (sep == -1) {
        return '[';
      } else {
        lex_tokerror(ls, TK_string, "invalid long string delimiter");
      }
    }
    case '=':
      lex_next(ls);
      if (ls->c != '=') return '=';
      lex_next(ls);
      return TK_eq;
    case '<':
      lex_next(ls);
      if (ls->c != '=') return '<';
      lex_next(ls);
      return TK_le;
    case '>':
      lex_next(ls);
      if (ls->c != '=') return '>';
      lex_next(ls);
      return TK_ge;
    case '~':
      lex_next(ls);
      if (ls->c != '=') return '~';
      lex_next(ls);
      return TK_ne;
    case ':':
      lex_next(ls);
      if (ls->c != ':') return ':';
      lex_next(ls);
      return TK_label;
    case '"':
    case '\'':
      read_string(ls, ls->c, t);
      return TK_string;
    case '.':
      save_and_next(ls);
      if (ls->c == '.') {
        lex_next(ls);
        if (ls->c == '.') {
          lex_next(ls);
          return TK_dots;
        }
        return TK_concat;
      } else if (!isdigit(ls->c)) {
        return '.';
      } else {
        read_numeral(ls, t);
        return t->tok;
      }
    case END_OF_STREAM:
      return TK_eof;
    default:
      if (isspace(ls->c)) {
        lex_next(ls);
        continue;
      } else if (isdigit(ls->c)) {
        read_numeral(ls, t);
        return t->tok;
      } else if (isident(ls->c)) {
        GCstr *ts;
        do {
          save_and_next(ls);
        } while (isident(ls->c));
        ts = lj_lex_newstr(ls, ls->sb, ls->sbn);
        if (ts->reserved > 0) return ts->reserved - 1 + TK_RESERVED_FIRST;
        setstrV(&t->val, ts);
        return TK_name;
      } else {
        int c = ls->c;
        lex_next(ls);
        return c;
      }
    }
  }
}

static void scan_token(LexState *ls, Token *t)
{
  t->tok = llex(ls, t);
  /* Record text for error messages. */
  if (t->tok == TK_name || t->tok == TK_string || t->tok == TK_number || t->tok == TK_cdata) {
    t->text = lj_lex_newstr(ls, ls->sb, ls->sbn);
    if (t->tok == TK_cdata) {
      /* keep */
    }
  } else {
    t->text = NULL;
  }
}

void lj_lex_next(LexState *ls)
{
  ls->lastline = ls->linenumber;
  if (ls->la.tok != TK_eof + 1) {
    ls->t = ls->la;
    ls->la.tok = TK_eof + 1;
  } else {
    scan_token(ls, &ls->t);
  }
}

int lj_lex_lookahead(LexState *ls)
{
  scan_token(ls, &ls->la);
  return ls->la.tok;
}

void lj_lex_setup(lua_State *L, LexState *ls)
{
  ls->L = L;
  ls->la.tok = TK_eof + 1;
  ls->linenumber = 1;
  ls->lastline = 1;
  ls->level = 0;
  ls->sb = NULL;
  ls->sbn = ls->sbcap = 0;
  ls->n = 0;
  ls->p = NULL;
  ls->eof_seen = 0;
  lex_next(ls);
  /* Skip UTF-8 BOM. */
  if (ls->c == 0xef) {
    /* Peek ahead: requires two more bytes. */
    if (ls->n >= 2 && (unsigned char)ls->p[0] == 0xbb && (unsigned char)ls->p[1] == 0xbf) {
      ls->n -= 2;
      ls->p += 2;
      lex_next(ls);
    }
  }
  if (ls->c == '#') {
    do {
      lex_next(ls);
      if (ls->c == END_OF_STREAM) return;
    } while (!currIsNewline(ls));
  }
}
