/* Lexical analyzer. */
#include <stdarg.h>
#include <ctype.h>
#include "lj.h"
#include "lj_lex.h"
#include "lj_api.h"

static const char *const tokennames[] = {
  "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
  "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return", "then",
  "true", "until", "while",
  "..", "...", "==", ">=", "<=", "~=", "::",
  "<number>", "<name>", "<string>", "<number>", "<eof>"
};

void lj_lex_init(lua_State *L)
{
  int i;
  for (i = 0; i < NUM_RESERVED; i++) {
    GCstr *s = lj_str_newz(L, tokennames[i]);
    s->reserved = (uint8_t)(i + 1);
  }
}

#define END_OF_STREAM (-1)

static int lex_fill(LexState *ls)
{
  size_t sz;
  const char *buf;
  if (ls->eof_seen) return END_OF_STREAM;
  buf = ls->reader(ls->L, ls->rdata, &sz);
  if (buf == NULL || sz == 0) { ls->eof_seen = 1; return END_OF_STREAM; }
  ls->p = buf;
  ls->n = sz;
  ls->n--;
  return (unsigned char)*ls->p++;
}

static inline int lex_next(LexState *ls)
{
  return (ls->c = (ls->n > 0) ? (ls->n--, (unsigned char)*ls->p++) : lex_fill(ls));
}

static void save(LexState *ls, int c)
{
  if (ls->sbn + 1 > ls->sbcap) {
    size_t ncap = ls->sbcap ? ls->sbcap * 2 : 256;
    ls->sb = (char *)realloc(ls->sb, ncap);
    if (!ls->sb) lj_err_throw(ls->L, LUA_ERRMEM);
    ls->sbcap = ncap;
  }
  ls->sb[ls->sbn++] = (char)c;
}

static inline void save_and_next(LexState *ls)
{
  save(ls, ls->c);
  lex_next(ls);
}

#define currIsNewline(ls) (ls->c == '\n' || ls->c == '\r')

static void inclinenumber(LexState *ls)
{
  int old = ls->c;
  lex_next(ls);
  if (currIsNewline(ls) && ls->c != old) lex_next(ls);
  if (++ls->linenumber >= 0x7fffff00) lj_lex_error(ls, 0, "chunk has too many lines");
}

GCstr *lj_lex_newstr(LexState *ls, const char *s, size_t len)
{
  lua_State *L = ls->L;
  GCstr *str = lj_str_new(L, s, len);
  TValue key;
  TValue *v;
  setstrV(&key, str);
  v = lj_tab_set(L, ls->anchor, &key);
  setboolV(v, 1);
  return str;
}

const char *lj_lex_token2str(LexState *ls, int tok, char *buf)
{
  (void)ls;
  if (tok > TK_RESERVED_FIRST - 1 && tok <= TK_eof) return tokennames[tok - TK_RESERVED_FIRST];
  if (tok < 32 || tok == 127) {
    sprintf(buf, "char(%d)", tok);
    return buf;
  }
  buf[0] = (char)tok;
  buf[1] = 0;
  return buf;
}

LJ_NORET void lj_lex_error(LexState *ls, int tok, const char *fmt, ...)
{
  char chunk[256];
  char msg[512];
  char tbuf[32];
  const char *tokstr = NULL;
  va_list argp;
  lua_State *L = ls->L;
  GCstr *s;
  va_start(argp, fmt);
  vsnprintf(msg, sizeof(msg), fmt, argp);
  va_end(argp);
  if (tok) {
    if (tok == TK_name || tok == TK_string || tok == TK_number) {
      save(ls, '\0');
      tokstr = ls->sb;
    } else {
      tokstr = lj_lex_token2str(ls, tok, tbuf);
    }
  }
  lj_debug_chunkid(chunk, ls->chunkname, sizeof(chunk));
  if (tokstr)
    s = lj_str_pushf(L, "%s:%d: %s near '%s'", chunk, ls->linenumber, msg, tokstr);
  else
    s = lj_str_pushf(L, "%s:%d: %s", chunk, ls->linenumber, msg);
  lj_checkstack(L, 1);
  setstrV(L->top, s);
  L->top++;
  lj_err_throw(L, LUA_ERRSYNTAX);
}

/* Error referring to the current token. */
static LJ_NORET void lex_tokerror(LexState *ls, int tok, const char *msg)
{
  lj_lex_error(ls, tok, "%s", msg);
}

static int skip_sep(LexState *ls)
{
  int count = 0;
  int s = ls->c;
  save_and_next(ls);
  while (ls->c == '=') {
    save_and_next(ls);
    count++;
  }
  return (ls->c == s) ? count : (-count) - 1;
}

static void read_long_string(LexState *ls, Token *t, int sep)
{
  int startline = ls->linenumber;
  (void)startline;
  save_and_next(ls);  /* skip 2nd `[' */
  if (currIsNewline(ls)) inclinenumber(ls);
  for (;;) {
    switch (ls->c) {
    case END_OF_STREAM:
      lex_tokerror(ls, TK_eof, t ? "unfinished long string" : "unfinished long comment");
      break;
    case ']':
      if (skip_sep(ls) == sep) {
        save_and_next(ls);  /* skip 2nd `]' */
        goto endloop;
      }
      break;
    case '\n':
    case '\r':
      save(ls, '\n');
      inclinenumber(ls);
      if (!t) ls->sbn = 0;
      break;
    default:
      if (t) save_and_next(ls);
      else lex_next(ls);
    }
  }
endloop:
  if (t) {
    GCstr *s = lj_lex_newstr(ls, ls->sb + (2 + sep), ls->sbn - 2 * (2 + sep));
    setstrV(&t->val, s);
  }
}

static int hexval(int c)
{
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

static void read_string(LexState *ls, int del, Token *t)
{
  save_and_next(ls);
  while (ls->c != del) {
    switch (ls->c) {
    case END_OF_STREAM:
      lex_tokerror(ls, TK_eof, "unfinished string");
      continue;
    case '\n':
    case '\r':
      lex_tokerror(ls, TK_string, "unfinished string");
      continue;
    case '\\': {
      int c;
      lex_next(ls);  /* do not save the `\' */
      switch (ls->c) {
      case 'a': c = '\a'; break;
      case 'b': c = '\b'; break;
      case 'f': c = '\f'; break;
      case 'n': c = '\n'; break;
      case 'r': c = '\r'; break;
      case 't': c = '\t'; break;
      case 'v': c = '\v'; break;
      case 'x': {
        int h1, h2;
        lex_next(ls);
        h1 = hexval(ls->c);
        if (h1 < 0) goto err_xesc;
        lex_next(ls);
        h2 = hexval(ls->c);
        if (h2 < 0) goto err_xesc;
        c = (h1 << 4) | h2;
        break;
      }
      case 'z': {
        lex_next(ls);
        while (ls->c != END_OF_STREAM && (isspace(ls->c))) {
          if (currIsNewline(ls)) inclinenumber(ls);
          else lex_next(ls);
        }
        continue;
      }
      case 'u': {
        uint32_t cp = 0;
        int any = 0;
        lex_next(ls);
        if (ls->c != '{') goto err_xesc;
        lex_next(ls);
        while (hexval(ls->c) >= 0) {
          cp = (cp << 4) | (uint32_t)hexval(ls->c);
          if (cp >= 0x110000) goto err_xesc;
          any = 1;
          lex_next(ls);
        }
        if (!any || ls->c != '}') goto err_xesc;
        lex_next(ls);
        if (cp < 0x80) {
          save(ls, (int)cp);
        } else if (cp < 0x800) {
          save(ls, (int)(0xc0 | (cp >> 6)));
          save(ls, (int)(0x80 | (cp & 0x3f)));
        } else if (cp < 0x10000) {
          save(ls, (int)(0xe0 | (cp >> 12)));
          save(ls, (int)(0x80 | ((cp >> 6) & 0x3f)));
          save(ls, (int)(0x80 | (cp & 0x3f)));
        } else {
          save(ls, (int)(0xf0 | (cp >> 18)));
          save(ls, (int)(0x80 | ((cp >> 12) & 0x3f)));
          save(ls, (int)(0x80 | ((cp >> 6) & 0x3f)));
          save(ls, (int)(0x80 | (cp & 0x3f)));
        }
        continue;
      }
      case '\n':
      case '\r':
        save(ls, '\n');
        inclinenumber(ls);
        continue;
      case END_OF_STREAM:
        continue;  /* will raise error next loop */
      default:
        if (!isdigit(ls->c)) {
          if (ls->c == '\\' || ls->c == '"' || ls->c == '\'') {
            c = ls->c;
            break;
          }
          goto err_xesc;
        } else {
          int i = 0;
          c = 0;
          do {
            c = 10 * c + (ls->c - '0');
            lex_next(ls);
          } while (++i < 3 && isdigit(ls->c));
          if (c > 255) goto err_xesc;
          save(ls, c);
          continue;
        }
      }
      save(ls, c);
      lex_next(ls);
      continue;
    err_xesc:
      lex_tokerror(ls, TK_string, "invalid escape sequence");
    }
    default:
      save_and_next(ls);
    }
  }
  save_and_next(ls);  /* skip delimiter */
  {
    GCstr *s = lj_lex_newstr(ls, ls->sb + 1, ls->sbn - 2);
    setstrV(&t->val, s);
  }
}

static int isident(int c)
{
  return isalnum(c) || c == '_' || c >= 0x80;
}

static void read_numeral(LexState *ls, Token *t)
{
  int c, xp = 'e';
  int fmt;
  if ((c = ls->c) == '0') {
    save_and_next(ls);
    if ((ls->c | 0x20) == 'x') xp = 'p';
  }
  while (isident(ls->c) || ls->c == '.' ||
         ((ls->c == '-' || ls->c == '+') && (c | 0x20) == xp)) {
    c = ls->c;
    save_and_next(ls);
  }
  fmt = lj_strscan_scan(ls->sb, ls->sbn, &t->val, STRSCAN_OPT_LL | STRSCAN_OPT_IMAG);
  if (fmt == STRSCAN_NUM) {
    t->tok = TK_number;
  } else if (fmt == STRSCAN_ERROR) {
    lex_tokerror(ls, TK_number, "malformed number");
  } else {
    t->tok = TK_cdata;
    t->cdkind = fmt;
  }
}

static int llex(LexState *ls, Token *t)
{
  ls->sbn = 0;
  for (;;) {
    switch (ls->c) {
    case '\n':
    case '\r':
      inclinenumber(ls);
      continue;
    case '-':
      lex_next(ls);
      if (ls->c != '-') return '-';
      lex_next(ls);
      if (ls->c == '[') {
        int sep = skip_sep(ls);
        ls->sbn = 0;
        if (sep >= 0) {
          read_long_string(ls, NULL, sep);
          ls->sbn = 0;
          continue;
        }
      }
      while (!currIsNewline(ls) && ls->c != END_OF_STREAM) lex_next(ls);
      ls->sbn = 0;
      continue;
    case '[': {
      int sep = skip_sep(ls);
      if (sep >= 0) {
        read_long_string(ls, t, sep);
        return TK_string;
      } else if (sep == -1) {
        return '[';
      } else {
        lex_tokerror(ls, TK_string, "invalid long string delimiter");
      }
    }
    case '=':
      lex_next(ls);
      if (ls->c != '=') return '=';
      lex_next(ls);
      return TK_eq;
    case '<':
      lex_next(ls);
      if (ls->c != '=') return '<';
      lex_next(ls);
      return TK_le;
    case '>':
      lex_next(ls);
      if (ls->c != '=') return '>';
      lex_next(ls);
      return TK_ge;
    case '~':
      lex_next(ls);
      if (ls->c != '=') return '~';
      lex_next(ls);
      return TK_ne;
    case ':':
      lex_next(ls);
      if (ls->c != ':') return ':';
      lex_next(ls);
      return TK_label;
    case '"':
    case '\'':
