        if (ts->reserved > 0) return ts->reserved - 1 + TK_RESERVED_FIRST;
        setstrV(&t->val, ts);
        return TK_name;
      } else {
        int c = ls->c;
        lex_next(ls);
        return c;
      }
    }
  }
}

static void scan_token(LexState *ls, Token *t)
{
  t->tok = llex(ls, t);
