  if (t->tok == TK_name || t->tok == TK_string || t->tok == TK_number || t->tok == TK_cdata) {
    t->text = lj_lex_newstr(ls, ls->sb, ls->sbn);
    if (t->tok == TK_cdata) {
      /* keep */
    }
  } else {
    t->text = NULL;
  }
}

void lj_lex_next(LexState *ls)
{
  ls->lastline = ls->linenumber;
  if (ls->la.tok != TK_eof + 1) {
    ls->t = ls->la;
    ls->la.tok = TK_eof + 1;
  } else {
