  ls->la.tok = TK_eof + 1;
  ls->linenumber = 1;
  ls->lastline = 1;
  ls->level = 0;
  ls->sb = NULL;
  ls->sbn = ls->sbcap = 0;
  ls->n = 0;
  ls->p = NULL;
  ls->eof_seen = 0;
  lex_next(ls);
  /* Skip UTF-8 BOM. */
  if (ls->c == 0xef) {
    /* Peek ahead: requires two more bytes. */
    if (ls->n >= 2 && (unsigned char)ls->p[0] == 0xbb && (unsigned char)ls->p[1] == 0xbf) {
      ls->n -= 2;
      ls->p += 2;
      lex_next(ls);
    }
  }
  if (ls->c == '#') {
    do {
      lex_next(ls);
      if (ls->c == END_OF_STREAM) return;
    } while (!currIsNewline(ls));
  }
}
