  struct FuncState *prev;
  LexState *ls;
  lua_State *L;
  BlockCnt *bl;
  int pc;
  int lasttarget;
  int jpc;
  int freereg;
  int nk;
  int np;
  int nlocvars;
  int nactvar;
  int nups;
