output.arguments:
{"command":"cd /workspace/src && cat > lj_vm.c <<'EOF'
/* The virtual machine: interpreter loop, calls, metamethods. */
#include "lj.h"
#include "lj_api.h"

#define PCRLUA 0
#define PCRC 1
#define MAXTAGLOOP 100

int lj_vm_nextmm = -1;   /* metamethod id for the next call (for debug info) */

/* -- Conversions ------------------------------------------------------------ */

int lj_vm_tonumber(cTValue *obj, TValue *n)
{
  if (tvisnum(obj)) {
    *n = *obj;
    return 1;
  }
  if (tvisstr(obj)) {
    double d;
    if (lj_strscan_num(strdata(strV(obj)), strV(obj)->len, &d)) {
      setnumV(n, d);
      return 1;
    }
  }
  return 0;
}

int lj_vm_tostring(lua_State *L, TValue *obj)
{
  if (tvisstr(obj)) return 1;
  if (tvisnum(obj)) {
    setstrV(obj, lj_str_fromnum(L, obj->u.n));
    return 1;
  }
  return 0;
}

double lj_vm_modi(double a, double b)
{
  return a - floor(a / b) * b;
}

double lj_vm_powi(double x, double y)
{
  return pow(x, y);
}

double lj_vm_foldarith(double x, double y, int op)
{
  switch (op) {
  case OP_ADD: return x + y;
  case OP_SUB: return x - y;
  case OP_MUL: return x * y;
  case OP_DIV: return x / y;
  case OP_MOD: return lj_vm_modi(x, y);
  case OP_POW: return pow(x, y);
  case OP_UNM: return -x;
  default: return 0;
  }
}

/* -- Metatables ------------------------------------------------------------- */

cTValue *lj_meta_cache(lua_State *L, GCtab *mt, int mm)
{
  cTValue *mo = lj_tab_getstr(mt, G(L)->mmname[mm]);
  if (mo == NULL || tvisnil(mo)) {
    if (mm < 8) mt->nomm |= (uint8_t)(1u << mm);
    return NULL;
  }
  return mo;
}

extern GCtab *lj_ffi_getmt(lua_State *L, cTValue *o);

GCtab *lj_meta_getmt(lua_State *L, cTValue *o)
{
  switch (o->tt) {
  case LJ_TTAB: return tabV(o)->metatable;
  case LJ_TUDATA: return udataV(o)->metatable;
  case LJ_TSTR: return G(L)->strmt;
  case LJ_TTRUE: return G(L)->basemt[LJ_TFALSE];
  case LJ_TCDATA: return G(L)->basemt[LJ_TCDATA];
  default: return G(L)->basemt[o->tt];
  }
}

cTValue *lj_meta_lookup(lua_State *L, cTValue *o, int mm)
{
  GCtab *mt = lj_meta_getmt(L, o);
  cTValue *mo;
  if (mt == NULL) return NULL;
  mo = lj_tab_getstr(mt, G(L)->mmname[mm]);
  if (mo == NULL || tvisnil(mo)) return NULL;
  return mo;
}

/* Call metamethod f(p1, p2) and store result in *res (stack offset). */
static void callTMres(lua_State *L, ptrdiff_t res, cTValue *f, cTValue *p1, cTValue *p2, int mm)
{
  TValue *top;
  lj_checkstack(L, 3);
  top = L->top;
  copyTV(top, f);
  copyTV(top + 1, p1);
  copyTV(top + 2, p2);
  L->top = top + 3;
  lj_vm_nextmm = mm;
  lj_vm_call(L, top, 1);
  L->top--;
  copyTV(restorestack(L, res), L->top);
}

static void callTM(lua_State *L, cTValue *f, cTValue *p1, cTValue *p2, cTValue *p3, int mm)
{
  TValue *top;
  lj_checkstack(L, 4);
  top = L->top;
  copyTV(top, f);
  copyTV(top + 1, p1);
  copyTV(top + 2, p2);
  copyTV(top + 3, p3);
  L->top = top + 4;
  lj_vm_nextmm = mm;
  lj_vm_call(L, top, 0);
}

extern int lj_ffi_index(lua_State *L, cTValue *o, cTValue *k, TValue *res);
extern int lj_ffi_newindex(lua_State *L, cTValue *o, cTValue *k, cTValue *v);

void lj_vm_gettable(lua_State *L, cTValue *t, cTValue *key, TValue *res)
{
  int loop;
  ptrdiff_t resoff = savestack(L, res);
  int resonstack = (res >= L->stack && res < L->stack + L->stacksize);
  TValue tv = *t, kv = *key;
  cTValue *tp = t;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    cTValue *tm;
    if (tvistab(&tv)) {
      GCtab *h = tabV(&tv);
      cTValue *v = lj_tab_get(L, h, &kv);
      if (!tvisnil(v)) {
        if (resonstack) copyTV(restorestack(L, resoff), v); else copyTV(res, v);
        return;
      }
      tm = fasttm(L, h->metatable, MM_index);
      if (tm == NULL) {
        if (resonstack) setnilV(restorestack(L, resoff)); else setnilV(res);
        return;
      }
    } else {
      tm = lj_meta_lookup(L, &tv, MM_index);
      if (tm == NULL) {
        if (tviscdata(&tv)) {
          TValue r;
          lj_ffi_index(L, &tv, &kv, &r);
          if (resonstack) copyTV(restorestack(L, resoff), &r); else copyTV(res, &r);
          return;
        }
        lj_err_typeop(L, tp, "index");
      }
    }
    if (tvisfunc(tm)) {
      if (resonstack) {
        callTMres(L, resoff, tm, &tv, &kv, MM_index);
      } else {
        TValue *top = L->top;
        ptrdiff_t tmpoff = savestack(L, top);
        lj_checkstack(L, 1);
        setnilV(L->top); L->top++;
        callTMres(L, tmpoff, tm, &tv, &kv, MM_index);
        copyTV(res, restorestack(L, tmpoff));
        L->top--;
      }
      return;
    }
    tv = *tm;
    tp = tm;
    /* Object from metatable is not on the stack: no variable name. */
  }
  lj_err_msg(L, "loop in gettable");
}

void lj_vm_settable(lua_State *L, cTValue *t, cTValue *key, cTValue *val)
{
  int loop;
  TValue tv = *t, kv = *key, vv = *val;
  cTValue *tp = t;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    cTValue *tm;
    if (tvistab(&tv)) {
      GCtab *h = tabV(&tv);
      cTValue *oldval = lj_tab_get(L, h, &kv);
      if (!tvisnil(oldval)) {
        copyTV((TValue *)oldval, &vv);
        return;
      }
      tm = fasttm(L, h->metatable, MM_newindex);
      if (tm == NULL) {
        TValue *slot = lj_tab_set(L, h, &kv);
        copyTV(slot, &vv);
        return;
      }
    } else {
      tm = lj_meta_lookup(L, &tv, MM_newindex);
      if (tm == NULL) {
        if (tviscdata(&tv)) {
          lj_ffi_newindex(L, &tv, &kv, &vv);
          return;
        }
        lj_err_typeop(L, tp, "index");
      }
    }
    if (tvisfunc(tm)) {
      callTM(L, tm, &tv, &kv, &vv, MM_newindex);
      return;
    }
    tv = *tm;
    tp = tm;
  }
  lj_err_msg(L, "loop in settable");
}

static int call_binTM(lua_State *L, cTValue *p1, cTValue *p2, TValue *res, int mm)
{
  cTValue *tm = lj_meta_lookup(L, p1, mm);
  if (tm == NULL) tm = lj_meta_lookup(L, p2, mm);
  if (tm == NULL) return 0;
  {
    TValue tmv = *tm, a = *p1, b = *p2;
    callTMres(L, savestack(L, res), &tmv, &a, &b, mm);
  }
  return 1;
}

extern int lj_ffi_arith(lua_State *L, TValue *ra, cTValue *rb, cTValue *rc, int mm);

void lj_vm_arith(lua_State *L, TValue *ra, cTValue *rb, cTValue *rc, int op)
{
  TValue tempb, tempc;
  cTValue *b, *c;
  if ((b = lj_vm_tonumber(rb, &tempb) ? &tempb : NULL) != NULL &&
      (c = lj_vm_tonumber(rc, &tempc) ? &tempc : NULL) != NULL) {
    double nb = b->u.n, nc = c->u.n;
    setnumV(ra, lj_vm_foldarith(nb, nc, op));
  } else {
    int mm;
    switch (op) {
    case OP_ADD: mm = MM_add; break;
    case OP_SUB: mm = MM_sub; break;
    case OP_MUL: mm = MM_mul; break;
    case OP_DIV: mm = MM_div; break;
    case OP_MOD: mm = MM_mod; break;
    case OP_POW: mm = MM_pow; break;
    default: mm = MM_unm; break;
    }
    if (!call_binTM(L, rb, rc, ra, mm)) {
      if (tviscdata(rb) || tviscdata(rc)) {
        if (lj_ffi_arith(L, ra, rb, rc, mm)) return;
      }
      lj_err_arith(L, rb, rc);
    }
  }
}

extern int lj_ffi_len(lua_State *L, cTValue *o, TValue *res);

void lj_vm_objlen(lua_State *L, TValue *ra, cTValue *rb)
{
  switch (rb->tt) {
  case LJ_TTAB:
    setnumV(ra, (double)lj_tab_len(tabV(rb)));
    break;
  case LJ_TSTR:
    setnumV(ra, (double)strV(rb)->len);
    break;
  default: {
    cTValue *tm = lj_meta_lookup(L, rb, MM_len);
    if (tm == NULL) {
      if (tviscdata(rb)) {
        TValue r;
        if (lj_ffi_len(L, rb, &r)) { copyTV(ra, &r); return; }
      }
      lj_err_typeop(L, rb, "get length of");
    }
    {
      TValue tmv = *tm, a = *rb;
      callTMres(L, savestack(L, ra), &tmv, &a, &a, MM_len);
    }
  }
  }
}

extern int lj_ffi_equal(lua_State *L, cTValue *a, cTValue *b);

int lj_vm_equal(lua_State *L, cTValue *a, cTValue *b)
{
  cTValue *tm;
  if (a->tt != b->tt) {
    if (tviscdata(a) || tviscdata(b)) return lj_ffi_equal(L, a, b);
    return 0;
  }
  switch (a->tt) {
  case LJ_TNIL: case LJ_TFALSE: case LJ_TTRUE: return 1;
  case LJ_TNUM: return a->u.n == b->u.n;
  case LJ_TLIGHTUD: return a->u.p == b->u.p;
  case LJ_TTAB: case LJ_TUDATA: {
    GCtab *mt1, *mt2;
    if (a->u.p == b->u.p) return 1;
    mt1 = (a->tt == LJ_TTAB) ? tabV(a)->metatable : udataV(a)->metatable;
    mt2 = (b->tt == LJ_TTAB) ? tabV(b)->metatable : udataV(b)->metatable;
    tm = fasttm(L, mt1, MM_eq);
    if (tm == NULL) return 0;
    if (mt1 != mt2) {
      cTValue *tm2 = fasttm(L, mt2, MM_eq);
      if (tm2 == NULL) return 0;
      if (!(tm->tt == tm2->tt && tm->u.p == tm2->u.p)) return 0;
    }
    break;
  }
  case LJ_TCDATA:
    if (a->u.p == b->u.p) return 1;
    return lj_ffi_equal(L, a, b);
  default:
    return a->u.p == b->u.p;
  }
  {
    TValue tmv = *tm, av = *a, bv = *b;
    TValue *top = L->top;
    ptrdiff_t off = savestack(L, top);
    lj_checkstack(L, 1);
    setnilV(L->top); L->top++;
    callTMres(L, off, &tmv, &av, &bv, MM_eq);
    {
      int r = !tvisfalse(restorestack(L, off));
      L->top--;
      return r;
    }
  }
}

extern int lj_ffi_compare(lua_State *L, cTValue *a, cTValue *b, int le, int *res);

static int call_orderTM(lua_State *L, cTValue *p1, cTValue *p2, int mm)
{
  cTValue *tm1 = lj_meta_lookup(L, p1, mm);
  cTValue *tm2;
  if (tm1 == NULL) return -1;
  tm2 = lj_meta_lookup(L, p2, mm);
  if (tm2 == NULL || !(tm1->tt == tm2->tt && tm1->u.p == tm2->u.p)) return -1;
  {
    TValue tmv = *tm1, a = *p1, b = *p2;
    ptrdiff_t off;
    int r;
    lj_checkstack(L, 1);
    off = savestack(L, L->top);
    setnilV(L->top); L->top++;
    callTMres(L, off, &tmv, &a, &b, mm);
    r = !tvisfalse(restorestack(L, off));
    L->top--;
    return r;
  }
}

int lj_vm_lessthan(lua_State *L, cTValue *l, cTValue *r)
{
  int res;
  if (tvisnum(l) && tvisnum(r)) return l->u.n < r->u.n;
  if (l->tt != r->tt) {
    if (tviscdata(l) || tviscdata(r)) {
      if (lj_ffi_compare(L, l, r, 0, &res)) return res;
    }
    lj_err_compare(L, l, r);
  }
  if (tvisstr(l)) return lj_str_cmp(strV(l), strV(r)) < 0;
  if (tviscdata(l)) {
    if (lj_ffi_compare(L, l, r, 0, &res)) return res;
  }
  if ((res = call_orderTM(L, l, r, MM_lt)) != -1) return res;
  lj_err_compare(L, l, r);
}

int lj_vm_lessequal(lua_State *L, cTValue *l, cTValue *r)
{
  int res;
  if (tvisnum(l) && tvisnum(r)) return l->u.n <= r->u.n;
  if (l->tt != r->tt) {
    if (tviscdata(l) || tviscdata(r)) {
      if (lj_ffi_compare(L, l, r, 1, &res)) return res;
    }
    lj_err_compare(L, l, r);
  }
  if (tvisstr(l)) return lj_str_cmp(strV(l), strV(r)) <= 0;
  if (tviscdata(l)) {
    if (lj_ffi_compare(L, l, r, 1, &res)) return res;
  }
  if ((res = call_orderTM(L, l, r, MM_le)) != -1) return res;
  if ((res = call_orderTM(L, r, l, MM_lt)) != -1) return !res;
  lj_err_compare(L, l, r);
}

void lj_vm_concat(lua_State *L, int total, int last)
{
  do {
    TValue *top = L->base + last + 1;
    int n = 2;
    if (!(tvisstr(top - 2) || tvisnum(top - 2)) || !lj_vm_tostring(L, top - 1)) {
      ptrdiff_t off = savestack(L, top - 2);
      if (!call_binTM(L, top - 2, top - 1, top - 2, MM_concat)) {
        top = restorestack(L, off) + 2;
        lj_err_concat(L, top - 2, top - 1);
      }
    } else if (strV(top - 1)->len == 0) {
      lj_vm_tostring(L, top - 2);
    } else {
      size_t tl = strV(top - 1)->len;
      char *buffer;
      int i;
      for (n = 1; n < total && lj_vm_tostring(L, top - n - 1); n++) {
        size_t l = strV(top - n - 1)->len;
        if (l >= ((size_t)0x7fffff00) - tl) lj_err_msg(L, "string length overflow");
        tl += l;
      }
      buffer = (char *)malloc(tl ? tl : 1);
      if (!buffer) lj_err_throw(L, LUA_ERRMEM);
      tl = 0;
      for (i = n; i > 0; i--) {
        size_t l = strV(top - i)->len;
        memcpy(buffer + tl, strdata(strV(top - i)), l);
        tl += l;
      }
      {
        GCstr *s = lj_str_new(L, buffer, tl);
        free(buffer);
        setstrV(top - n, s);
      }
    }
    total -= n - 1;
    last -= n - 1;
  } while (total > 1);
}

/* -- Calls ------------------------------------------------------------------- */

TValue *lj_vm_tryfuncTM(lua_State *L, TValue *func)
{
  cTValue *tm = lj_meta_lookup(L, func, MM_call);
  TValue *p;
  ptrdiff_t funcr = savestack(L, func);
  if (tm == NULL || !tvisfunc(tm)) {
    if (tviscdata(func)) {
      extern int lj_ffi_call_tm(lua_State *L, TValue *func);
      if (lj_ffi_call_tm(L, func)) return restorestack(L, funcr);
    }
    lj_err_call(L, func);
  }
  {
    TValue tmv = *tm;
    lj_checkstack(L, 1);
    func = restorestack(L, funcr);
    for (p = L->top; p > func; p--) copyTV(p, p - 1);
    L->top++;
    copyTV(func, &tmv);
  }
  return func;
}

static inline CallInfo *inc_ci(lua_State *L)
{
  if (L->ci == L->end_ci) lj_state_growci(L);
  return ++L->ci;
}

static TValue *adjust_varargs(lua_State *L, GCproto *p, int actual)
{
  int i;
  int nfixargs = p->numparams;
  TValue *base, *fixed;
  for (; actual < nfixargs; ++actual) setnilV(L->top++);
  fixed = L->top - actual;
  base = L->top;
  for (i = 0; i < nfixargs; i++) {
    copyTV(L->top++, fixed + i);
    setnilV(fixed + i);
  }
  return base;
}

static LJ_NORET void stack_overflow_lua(lua_State *L, TValue *func, GCproto *p)
{
  /* Report error at the callee's first line, like the reference. */
  CallInfo *ci;
  if (L->ci == L->end_ci) lj_state_growci(L);
  ci = ++L->ci;
  ci->func = func;
  ci->base = func + 1;
  ci->top = L->top;
  ci->savedpc = p->code + 1;
  ci->nresults = 0;
  ci->tailcalls = 0;
  ci->flags = CIST_LUA;
  L->base = ci->base;
  lj_err_msg(L, "stack overflow");
}

void lj_vm_callhook(lua_State *L, int event, int line);

#define HOOK_CALL 0
#define HOOK_RET 1
#define HOOK_LINE 2
#define HOOK_COUNT 3
#define HOOK_TAILCALL 4
#define MASK_CALL (1 << HOOK_CALL)
#define MASK_RET (1 << HOOK_RET)
#define MASK_LINE (1 << HOOK_LINE)
#define MASK_COUNT (1 << HOOK_COUNT)

int lj_vm_precall(lua_State *L, TValue *func, int nresults)
{
  GCfunc *cl;
  ptrdiff_t funcr;
  int mm = lj_vm_nextmm;
  lj_vm_nextmm = -1;
  if (!tvisfunc(func)) func = lj_vm_tryfuncTM(L, func);
  funcr = savestack(L, func);
  cl = funcV(func);
  if (!cl->isC) {
    CallInfo *ci;
    TValue *st, *base;
    GCproto *p = cl->u.l.pt;
    if (LJ_UNLIKELY((char *)L->stack_last - (char *)L->top <= (ptrdiff_t)(p->maxstack + 4) * (ptrdiff_t)sizeof(TValue))) {
      int need = (int)(L->top - L->stack) + p->maxstack + 4;
      if (need > LJ_STACK_MAX && (L->stack_last - L->stack) <= LJ_STACK_MAX)
        stack_overflow_lua(L, func, p);
      lj_state_growstack(L, p->maxstack + 4);
    }
    func = restorestack(L, funcr);
    if (!p->is_vararg) {
      base = func + 1;
      if (L->top > base + p->numparams) L->top = base + p->numparams;
    } else {
      int nargs = (int)(L->top - func) - 1;
      base = adjust_varargs(L, p, nargs);
      func = restorestack(L, funcr);
    }
    ci = inc_ci(L);
    ci->func = func;
    L->base = ci->base = base;
    ci->top = L->base + p->maxstack;
    ci->savedpc = p->code;
    ci->tailcalls = 0;
    ci->nresults = nresults;
    ci->flags = CIST_LUA | (mm >= 0 ? (CIST_MM | (mm << 8)) : 0);
    for (st = L->top; st < ci->top; st++) setnilV(st);
    L->top = ci->top;
    if (L->hookmask & MASK_CALL) {
      ci->savedpc++;
      lj_vm_callhook(L, HOOK_CALL, -1);
      ci->savedpc--;
    }
    return PCRLUA;
  } else {
    CallInfo *ci;
    int n;
    lj_checkstack(L, LUA_MINSTACK);
    ci = inc_ci(L);
    ci->func = restorestack(L, funcr);
    L->base = ci->base = ci->func + 1;
    ci->top = L->top + LUA_MINSTACK;
    ci->nresults = nresults;
    ci->tailcalls = 0;
    ci->savedpc = NULL;
    ci->flags = (mm >= 0 ? (CIST_MM | (mm << 8)) : 0);
    if (L->hookmask & MASK_CALL) lj_vm_callhook(L, HOOK_CALL, -1);
    n = (*funcV(ci->func)->u.c.f)(L);
    lj_vm_poscall(L, L->top - n);
    return PCRC;
  }
}

int lj_vm_poscall(lua_State *L, TValue *firstResult)
{
  TValue *res;
  int wanted, i;
  CallInfo *ci;
  if (L->hookmask & MASK_RET) {
    ptrdiff_t fr = savestack(L, firstResult);
    lj_vm_callhook(L, HOOK_RET, -1);
    firstResult = restorestack(L, fr);
  }
  ci = L->ci--;
  res = ci->func;
  wanted = ci->nresults;
  L->base = (ci - 1)->base;
  for (i = wanted; i != 0 && firstResult < L->top; i--)
    copyTV(res++, firstResult++);
  while (i-- > 0) setnilV(res++);
  L->top = res;
  return (wanted - LUA_MULTRET);
}

extern char *lj_co_cstack_limit(lua_State *L);

void lj_vm_call(lua_State *L, TValue *func, int nResults)
{
  char probe;
  if (LJ_UNLIKELY(++L->nCcalls >= 7000 || &probe < L->cstack_limit)) {
    if (L->nCcalls >= 7000 + 50 || &probe < L->cstack_limit - 32768) {
      L->nCcalls--;
      lj_err_throw(L, LUA_ERRERR);
    }
    L->nCcalls--;
    lj_err_msg(L, "stack overflow");
  }
  if (lj_vm_precall(L, func, nResults) == PCRLUA) {
    L->ci->flags |= CIST_FRESH;
    lj_vm_execute(L, 1);
  }
  L->nCcalls--;
  lj_gc_check(L);
}

int lj_vm_pcall(lua_State *L, void (*func)(lua_State *L, void *ud), void *u, ptrdiff_t old_top, ptrdiff_t ef)
{
  int status;
  ptrdiff_t old_ci = saveci(L, L->ci);
  uint8_t old_allowhooks = L->allowhook;
  ptrdiff_t old_errfunc = L->errfunc;
  int oldnCcalls = L->nCcalls;
  L->errfunc = ef;
  status = lj_err_rawrunprotected(L, func, u);
  if (status != 0) {
    extern void lj_state_shrinkstack(lua_State *L);
    TValue *oldtop = restorestack(L, old_top);
    lj_func_closeuv(L, oldtop);
    lj_err_seterrorobj(L, status, oldtop);
    L->nCcalls = oldnCcalls;
    L->ci = restoreci(L, old_ci);
    L->base = L->ci->base;
    L->allowhook = old_allowhooks;
    lj_state_shrinkstack(L);
  }
  L->errfunc = old_errfunc;
  return status;
}

/* -- Hooks ---------------------------------------------------------------- */

extern void lj_debug_hookcall(lua_State *L, int event, int line);

void lj_vm_callhook(lua_State *L, int event, int line)
{
  if (!L->allowhook || tvisnil(&L->hookf)) return;
  lj_debug_hookcall(L, event, line);
}

/* -- Interpreter ------------------------------------------------------------ */

#define RA(i) (base + GETARG_A(i))
#define RB(i) (base + GETARG_B(i))
#define RC(i) (base + GETARG_C(i))
#define RKB(i) (ISK(GETARG_B(i)) ? k + INDEXK(GETARG_B(i)) : base + GETARG_B(i))
#define RKC(i) (ISK(GETARG_C(i)) ? k + INDEXK(GETARG_C(i)) : base + GETARG_C(i))
#define KBx(i) (k + GETARG_Bx(i))
#define dojump(pc, i) ((pc) += (i))
#define Protect(x) { ci->savedpc = pc; {x;}; base = L->base; }
#define savepc() (ci->savedpc = pc)

static void traceexec(lua_State *L, const BCIns *pc)
{
  uint8_t mask = L->hookmask;
  CallInfo *ci = L->ci;
  GCproto *p = funcV(ci->func)->u.l.pt;
  const BCIns *oldpc = ci->savedpc;
  ci->savedpc = pc;
  if ((mask & MASK_COUNT) && L->hookcount == 0) {
    L->hookcount = L->basehookcount;
    lj_vm_callhook(L, HOOK_COUNT, -1);
  }
  if (mask & MASK_LINE) {
    int npc = (int)(pc - p->code) - 1;
    int newline = p->lineinfo[npc];
    int oldnpc = oldpc ? (int)(oldpc - p->code) - 1 : -1;
    if (npc == 0 || pc <= oldpc || oldnpc < 0 || newline != p->lineinfo[oldnpc])
      lj_vm_callhook(L, HOOK_LINE, newline);
  }
}

static LJ_NORET void for_error(lua_State *L, const char *what)
{
  lj_err_runerror(L, "'for' %s must be a number", what);
}

void lj_vm_execute(lua_State *L, int nexeccalls)
{
  GCfunc *cl;
  TValue *base;
  TValue *k;
  const BCIns *pc;
  CallInfo *ci;
reentry:
  ci = L->ci;
  pc = ci->savedpc;
  cl = funcV(ci->func);
  base = L->base;
  k = cl->u.l.pt->k;
  for (;;) {
    const BCIns i = *pc++;
    TValue *ra;
    if (LJ_UNLIKELY(L->hookmask & (MASK_LINE | MASK_COUNT))) {
      if ((L->hookmask & MASK_COUNT) && --L->hookcount == 0) {
        traceexec(L, pc); base = L->base;
      } else if (L->hookmask & MASK_LINE) {
        traceexec(L, pc); base = L->base;
      }
    }
    ra = RA(i);
    switch (GET_OPCODE(i)) {
    case OP_MOVE:
      copyTV(ra, RB(i));
      continue;
    case OP_LOADK:
      copyTV(ra, KBx(i));
      continue;
    case OP_LOADBOOL:
      setboolV(ra, GETARG_B(i));
      if (GETARG_C(i)) pc++;
      continue;
    case OP_LOADNIL: {
      TValue *rb = RB(i);
      do {
        setnilV(rb--);
      } while (rb >= ra);
      continue;
    }
    case OP_GETUPVAL:
      copyTV(ra, cl->u.l.uv[GETARG_B(i)]->v);
      continue;
    case OP_GETGLOBAL: {
      TValue *rb = KBx(i);
      GCtab *env = cl->env;
      cTValue *v = lj_tab_getstr(env, strV(rb));
      if (v && !tvisnil(v)) {
        copyTV(ra, v);
      } else if (env->metatable == NULL || (env->metatable->nomm & 1)) {
        setnilV(ra);
      } else {
        TValue g;
        settabV(&g, env);
        Protect(lj_vm_gettable(L, &g, rb, ra));
      }
      continue;
    }
    case OP_GETTABLE: {
      TValue *rb = RB(i);
      TValue *rc = RKC(i);
      if (tvistab(rb)) {
        GCtab *t = tabV(rb);
        cTValue *v;
        if (tvisstr(rc)) {
          v = lj_tab_getstr(t, strV(rc));
          if (v == NULL) v = &lj_nilobj;
        } else if (tvisnum(rc)) {
          double nk = rc->u.n;
          int32_t ik = (int32_t)nk;
          if ((uint32_t)ik < t->asize && (double)ik == nk) v = &t->array[ik];
          else v = lj_tab_get(L, t, rc);
        } else {
          v = lj_tab_get(L, t, rc);
        }
        if (!tvisnil(v) || t->metatable == NULL || (t->metatable->nomm & (1u << MM_index))) {
          copyTV(ra, v);
          continue;
        }
      }
      Protect(lj_vm_gettable(L, rb, rc, ra));
      continue;
    }
    case OP_SETGLOBAL: {
      GCtab *env = cl->env;
      TValue *rb = KBx(i);
      cTValue *v = lj_tab_getstr(env, strV(rb));
      if (v && !tvisnil(v)) {
        copyTV((TValue *)v, ra);
      } else if (env->metatable == NULL || (env->metatable->nomm & (1u << MM_newindex))) {
        TValue *slot;
        Protect(slot = lj_tab_setstr(L, env, strV(rb)));
        ra = RA(i);
        copyTV(slot, ra);
      } else {
        TValue g;
        settabV(&g, env);
        Protect(lj_vm_settable(L, &g, rb, ra));
      }
      continue;
    }
    case OP_SETUPVAL: {
      GCupval *uv = cl->u.l.uv[GETARG_B(i)];
      copyTV(uv->v, ra);
      continue;
    }
    case OP_SETTABLE: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      if (tvistab(ra)) {
        GCtab *t = tabV(ra);
        TValue *v = NULL;
        if (tvisstr(rb)) {
          v = (TValue *)lj_tab_getstr(t, strV(rb));
        } else if (tvisnum(rb)) {
          double nk = rb->u.n;
          int32_t ik = (int32_t)nk;
          if ((uint32_t)ik < t->asize && (double)ik == nk) v = &t->array[ik];
          else v = (TValue *)lj_tab_get(L, t, rb);
        } else if (!tvisnil(rb)) {
          v = (TValue *)lj_tab_get(L, t, rb);
        }
        if (v && !tvisnil(v)) {
          copyTV(v, rc);
          continue;
        }
        if (t->metatable == NULL || (t->metatable->nomm & (1u << MM_newindex)) ||
            fasttm(L, t->metatable, MM_newindex) == NULL) {
          TValue val = *rc;
          Protect(v = lj_tab_set(L, t, rb));
          copyTV(v, &val);
          continue;
        }
      }
      Protect(lj_vm_settable(L, ra, rb, rc));
      continue;
    }
    case OP_NEWTABLE: {
      uint32_t bx = (uint32_t)GETARG_Bx(i);
      uint32_t asize = bx & 0x7ff;
      uint32_t hbits = bx >> 11;
      settabV(ra, lj_tab_new(L, asize, hbits));
      Protect(lj_gc_check(L));
      continue;
    }
    case OP_TDUP: {
      settabV(ra, lj_tab_dup(L, tabV(KBx(i))));
      Protect(lj_gc_check(L));
      continue;
    }
    case OP_SELF: {
      TValue *rb = RB(i);
      TValue *rc = RKC(i);
      TValue obj = *rb;
      copyTV(ra + 1, &obj);
      if (tvistab(&obj)) {
        GCtab *t = tabV(&obj);
        cTValue *v = lj_tab_getstr(t, strV(rc));
        if (v == NULL) v = &lj_nilobj;
        if (!tvisnil(v) || t->metatable == NULL || (t->metatable->nomm & (1u << MM_index))) {
          copyTV(ra, v);
          continue;
        }
      } else if (tvisstr(&obj) && G(L)->strmt) {
        GCtab *mt = G(L)->strmt;
        cTValue *idx = lj_tab_getstr(mt, G(L)->mmname[MM_index]);
        if (idx && tvistab(idx)) {
          cTValue *v = lj_tab_getstr(tabV(idx), strV(rc));
          if (v && !tvisnil(v)) {
            copyTV(ra, v);
            continue;
          }
        }
      }
      Protect(lj_vm_gettable(L, ra + 1, rc, ra));
      continue;
    }
#define ARITH_OP(opc, expr) \
    case opc: { \
      TValue *rb = RKB(i); \
      TValue *rc = RKC(i); \
      if (tvisnum(rb) && tvisnum(rc)) { \
        double nb = rb->u.n, nc = rc->u.n; \
        setnumV(ra, (expr)); \
      } else { \
        Protect(lj_vm_arith(L, ra, rb, rc, opc)); \
      } \
      continue; \
    }
    ARITH_OP(OP_ADD, nb + nc)
    ARITH_OP(OP_SUB, nb - nc)
    ARITH_OP(OP_MUL, nb * nc)
    ARITH_OP(OP_DIV, nb / nc)
    ARITH_OP(OP_MOD, nb - floor(nb / nc) * nc)
    ARITH_OP(OP_POW, pow(nb, nc))
    case OP_UNM: {
      TValue *rb = RB(i);
      if (tvisnum(rb)) {
        setnumV(ra, -rb->u.n);
      } else {
        Protect(lj_vm_arith(L, ra, rb, rb, OP_UNM));
      }
      continue;
    }
    case OP_NOT: {
      int res = tvisfalse(RB(i));
      setboolV(ra, res);
      continue;
    }
    case OP_LEN: {
      TValue *rb = RB(i);
      if (tvisstr(rb)) {
        setnumV(ra, (double)strV(rb)->len);
      } else if (tvistab(rb)) {
        setnumV(ra, (double)lj_tab_len(tabV(rb)));
      } else {
        Protect(lj_vm_objlen(L, ra, rb));
      }
      continue;
    }
    case OP_CONCAT: {
      int b = GETARG_B(i);
      int c = GETARG_C(i);
      Protect(lj_vm_concat(L, c - b + 1, c); lj_gc_check(L));
      copyTV(RA(i), base + b);
      continue;
    }
    case OP_JMP: {
      int a = GETARG_A(i);
      if (a > 0 && L->openupval) lj_func_closeuv(L, base + a - 1);
      dojump(pc, GETARG_sBx(i));
      continue;
    }
    case OP_EQ: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      int res;
      if (rb->tt == rc->tt && (rb->tt != LJ_TTAB && rb->tt != LJ_TUDATA && rb->tt != LJ_TCDATA)) {
        if (rb->tt == LJ_TNUM) res = rb->u.n == rc->u.n;
        else if (rb->tt <= LJ_TTRUE) res = 1;
        else res = rb->u.p == rc->u.p;
      } else {
        Protect(res = lj_vm_equal(L, rb, rc));
      }
      if (res == GETARG_A(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    }
    case OP_LT: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      int res;
      if (tvisnum(rb) && tvisnum(rc)) res = rb->u.n < rc->u.n;
      else Protect(res = lj_vm_lessthan(L, rb, rc));
      if (res == GETARG_A(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    }
    case OP_LE: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      int res;
      if (tvisnum(rb) && tvisnum(rc)) res = rb->u.n <= rc->u.n;
      else Protect(res = lj_vm_lessequal(L, rb, rc));
      if (res == GETARG_A(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    }
    case OP_TEST:
      if (tvisfalse(ra) != GETARG_C(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    case OP_TESTSET: {
      TValue *rb = RB(i);
      if (tvisfalse(rb) != GETARG_C(i)) {
        copyTV(ra, rb);
        dojump(pc, GETARG_sBx(*pc));
      }
      pc++;
      continue;
    }
    case OP_CALL: {
      int b = GETARG_B(i);
      int nresults = GETARG_C(i) - 1;
      if (b != 0) L->top = ra + b;
      savepc();
      if (lj_vm_precall(L, ra, nresults) == PCRLUA) {
        nexeccalls++;
        goto reentry;
      }
      if (nresults >= 0) L->top = ci->top;
      base = L->base;
      lj_gc_check(L);
      continue;
    }
    case OP_TAILCALL: {
      int b = GETARG_B(i);
      TValue *func;
      int aux;
      if (b != 0) L->top = ra + b;
      savepc();
      if (!tvisfunc(ra)) {
        ra = lj_vm_tryfuncTM(L, ra);
        base = L->base;
      }
      if (L->openupval) lj_func_closeuv(L, base);
      func = ci->func;
      for (aux = 0; ra + aux < L->top; aux++) copyTV(func + aux, ra + aux);
      L->top = func + aux;
      {
        GCfunc *ncl = funcV(func);
        if (!ncl->isC) {
          GCproto *p = ncl->u.l.pt;
          TValue *st, *nbase;
          ptrdiff_t funcr = savestack(L, func);
          int fresh = ci->flags & CIST_FRESH;
          if ((char *)L->stack_last - (char *)L->top <= (ptrdiff_t)(p->maxstack + 4) * (ptrdiff_t)sizeof(TValue)) {
            int need = (int)(L->top - L->stack) + p->maxstack + 4;
            if (need > LJ_STACK_MAX && (L->stack_last - L->stack) <= LJ_STACK_MAX) {
              L->ci--;
              stack_overflow_lua(L, func, p);
            }
            lj_state_growstack(L, p->maxstack + 4);
            ci = L->ci;
          }
          func = restorestack(L, funcr);
          if (!p->is_vararg) {
            nbase = func + 1;
            if (L->top > nbase + p->numparams) L->top = nbase + p->numparams;
          } else {
            int nargs = (int)(L->top - func) - 1;
            nbase = adjust_varargs(L, p, nargs);
            func = restorestack(L, funcr);
          }
          ci->func = func;
          L->base = ci->base = nbase;
          ci->top = nbase + p->maxstack;
          ci->savedpc = p->code;
          ci->tailcalls++;
          ci->flags = CIST_LUA | CIST_TAIL | fresh;
          for (st = L->top; st < ci->top; st++) setnilV(st);
          L->top = ci->top;
          if (L->hookmask & MASK_CALL) {
            ci->savedpc++;
            lj_vm_callhook(L, HOOK_CALL, -1);
            ci->savedpc--;
          }
          goto reentry;
        } else {
          /* Tail call of a C function: replace the current frame. */
          int n, wanted;
          int fresh = ci->flags & CIST_FRESH;
          ptrdiff_t funcr = savestack(L, func);
          lj_checkstack(L, LUA_MINSTACK);
          ci = L->ci;
          func = restorestack(L, funcr);
          L->base = ci->base = func + 1;
          ci->top = L->top + LUA_MINSTACK;
          ci->savedpc = NULL;
          ci->flags = CIST_TAIL;
          ci->tailcalls++;
          if (L->hookmask & MASK_CALL) lj_vm_callhook(L, HOOK_CALL, -1);
          n = (*funcV(ci->func)->u.c.f)(L);
          wanted = L->ci->nresults;
          lj_vm_poscall(L, L->top - n);
          lj_gc_check(L);
          if (fresh) return;
          if (wanted >= 0) L->top = L->ci->top;
          goto reentry;
        }
      }
    }
    case OP_RETURN: {
      int b = GETARG_B(i);
      int fresh;
      if (b != 0) L->top = ra + b - 1;
      if (L->openupval) lj_func_closeuv(L, base);
      savepc();
      fresh = ci->flags & CIST_FRESH;
      b = lj_vm_poscall(L, ra);
      if (fresh) return;
      if (b) L->top = L->ci->top;
      goto reentry;
    }
    case OP_FORLOOP: {
      double step = ra[2].u.n;
      double idx = ra[0].u.n + step;
      double limit = ra[1].u.n;
      if (step >= 0 ? idx <= limit : limit <= idx) {
        dojump(pc, GETARG_sBx(i));
        setnumV(ra, idx);
        setnumV(ra + 3, idx);
      }
      continue;
    }
    case OP_FORPREP: {
      TValue *init = ra;
      TValue *plimit = ra + 1;
      TValue *pstep = ra + 2;
      TValue tmp;
      savepc();
      if (!tvisnum(init)) {
        if (!lj_vm_tonumber(init, &tmp)) for_error(L, "initial value");
        copyTV(init, &tmp);
      }
      if (!tvisnum(plimit)) {
        if (!lj_vm_tonumber(plimit, &tmp)) for_error(L, "limit");
        copyTV(plimit, &tmp);
      }
      if (!tvisnum(pstep)) {
        if (!lj_vm_tonumber(pstep, &tmp)) for_error(L, "step");
        copyTV(pstep, &tmp);
      }
      {
        double idx = init->u.n, limit = plimit->u.n, step = pstep->u.n;
        if (step >= 0 ? idx <= limit : limit <= idx) {
          setnumV(ra + 3, idx);
        } else {
          dojump(pc, GETARG_sBx(i) + 1);
        }
      }
      continue;
    }
    case OP_TFORLOOP: {
      TValue *cb = ra + 3;
      copyTV(cb + 2, ra + 2);
      copyTV(cb + 1, ra + 1);
      copyTV(cb, ra);
      L->top = cb + 3;
      Protect(lj_vm_call(L, cb, GETARG_C(i)));
      L->top = ci->top;
      cb = RA(i) + 3;
      if (!tvisnil(cb)) {
        copyTV(cb - 1, cb);
        dojump(pc, GETARG_sBx(*pc));
      }
      pc++;
      continue;
    }
    case OP_SETLIST:
      continue;
    case OP_TSETM: {
      GCtab *t = tabV(ra - 1);
      int n = (int)(L->top - ra);
      int32_t start = (int32_t)KBx(i)->u.n;
      int j;
      savepc();
      if (n > 0 && (uint32_t)(start + n - 1) >= t->asize)
        lj_tab_reasize(L, t, (uint32_t)(start + n - 1));
      ra = RA(i);
      for (j = 0; j < n; j++) {
        TValue *v = lj_tab_setint(L, t, start + j);
        copyTV(v, ra + j);
      }
      L->top = ci->top;
      continue;
    }
    case OP_CLOSE:
      lj_func_closeuv(L, ra);
      continue;
    case OP_CLOSURE: {
      GCproto *p = cl->u.l.pt->p[GETARG_Bx(i)];
      GCfunc *ncl = lj_func_newL(L, p, cl->env);
      int j, nup = p->nups;
      for (j = 0; j < nup; j++) {
        if (p->uvinstack[j])
          ncl->u.l.uv[j] = lj_func_findupval(L, base + p->uvidx[j]);
        else
          ncl->u.l.uv[j] = cl->u.l.uv[p->uvidx[j]];
      }
      setfuncV(ra, ncl);
      Protect(lj_gc_check(L));
      continue;
    }
    case OP_VARARG: {
      int b = GETARG_B(i) - 1;
      int j;
      int n = (int)(base - ci->func) - cl->u.l.pt->numparams - 1;
      if (b == LUA_MULTRET) {
        Protect(lj_checkstack(L, n));
        ra = RA(i);
        b = n;
        L->top = ra + n;
      }
      for (j = 0; j < b; j++) {
        if (j < n) {
          copyTV(ra + j, base - n + j);
        } else {
          setnilV(ra + j);
        }
      }
      continue;
    }
    default:
      continue;
    }
  }
  (void)nexeccalls;
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > lj_vm.c <<'EOF'
/* The virtual machine: interpreter loop, calls, metamethods. */
#include "lj.h"
#include "lj_api.h"

#define PCRLUA 0
#define PCRC 1
#define MAXTAGLOOP 100

int lj_vm_nextmm = -1;   /* metamethod id for the next call (for debug info) */

/* -- Conversions ------------------------------------------------------------ */

int lj_vm_tonumber(cTValue *obj, TValue *n)
{
  if (tvisnum(obj)) {
    *n = *obj;
    return 1;
  }
  if (tvisstr(obj)) {
    double d;
    if (lj_strscan_num(strdata(strV(obj)), strV(obj)->len, &d)) {
      setnumV(n, d);
      return 1;
    }
  }
  return 0;
}

int lj_vm_tostring(lua_State *L, TValue *obj)
{
  if (tvisstr(obj)) return 1;
  if (tvisnum(obj)) {
    setstrV(obj, lj_str_fromnum(L, obj->u.n));
    return 1;
  }
  return 0;
}

double lj_vm_modi(double a, double b)
{
  return a - floor(a / b) * b;
}

double lj_vm_powi(double x, double y)
{
  return pow(x, y);
}

double lj_vm_foldarith(double x, double y, int op)
{
  switch (op) {
  case OP_ADD: return x + y;
  case OP_SUB: return x - y;
  case OP_MUL: return x * y;
  case OP_DIV: return x / y;
  case OP_MOD: return lj_vm_modi(x, y);
  case OP_POW: return pow(x, y);
  case OP_UNM: return -x;
  default: return 0;
  }
}

/* -- Metatables ------------------------------------------------------------- */

cTValue *lj_meta_cache(lua_State *L, GCtab *mt, int mm)
{
  cTValue *mo = lj_tab_getstr(mt, G(L)->mmname[mm]);
  if (mo == NULL || tvisnil(mo)) {
    if (mm < 8) mt->nomm |= (uint8_t)(1u << mm);
    return NULL;
  }
  return mo;
}

extern GCtab *lj_ffi_getmt(lua_State *L, cTValue *o);

GCtab *lj_meta_getmt(lua_State *L, cTValue *o)
{
  switch (o->tt) {
  case LJ_TTAB: return tabV(o)->metatable;
  case LJ_TUDATA: return udataV(o)->metatable;
  case LJ_TSTR: return G(L)->strmt;
  case LJ_TTRUE: return G(L)->basemt[LJ_TFALSE];
  case LJ_TCDATA: return G(L)->basemt[LJ_TCDATA];
  default: return G(L)->basemt[o->tt];
  }
}

cTValue *lj_meta_lookup(lua_State *L, cTValue *o, int mm)
{
  GCtab *mt = lj_meta_getmt(L, o);
  cTValue *mo;
  if (mt == NULL) return NULL;
  mo = lj_tab_getstr(mt, G(L)->mmname[mm]);
  if (mo == NULL || tvisnil(mo)) return NULL;
  return mo;
}

/* Call metamethod f(p1, p2) and store result in *res (stack offset). */
static void callTMres(lua_State *L, ptrdiff_t res, cTValue *f, cTValue *p1, cTValue *p2, int mm)
{
  TValue *top;
  lj_checkstack(L, 3);
  top = L->top;
  copyTV(top, f);
  copyTV(top + 1, p1);
  copyTV(top + 2, p2);
  L->top = top + 3;
  lj_vm_nextmm = mm;
  lj_vm_call(L, top, 1);
  L->top--;
  copyTV(restorestack(L, res), L->top);
}

static void callTM(lua_State *L, cTValue *f, cTValue *p1, cTValue *p2, cTValue *p3, int mm)
{
  TValue *top;
  lj_checkstack(L, 4);
  top = L->top;
  copyTV(top, f);
  copyTV(top + 1, p1);
  copyTV(top + 2, p2);
  copyTV(top + 3, p3);
  L->top = top + 4;
  lj_vm_nextmm = mm;
  lj_vm_call(L, top, 0);
}

extern int lj_ffi_index(lua_State *L, cTValue *o, cTValue *k, TValue *res);
extern int lj_ffi_newindex(lua_State *L, cTValue *o, cTValue *k, cTValue *v);

void lj_vm_gettable(lua_State *L, cTValue *t, cTValue *key, TValue *res)
{
  int loop;
  ptrdiff_t resoff = savestack(L, res);
  int resonstack = (res >= L->stack && res < L->stack + L->stacksize);
  TValue tv = *t, kv = *key;
  cTValue *tp = t;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    cTValue *tm;
    if (tvistab(&tv)) {
      GCtab *h = tabV(&tv);
      cTValue *v = lj_tab_get(L, h, &kv);
      if (!tvisnil(v)) {
        if (resonstack) copyTV(restorestack(L, resoff), v); else copyTV(res, v);
        return;
      }
      tm = fasttm(L, h->metatable, MM_index);
      if (tm == NULL) {
        if (resonstack) setnilV(restorestack(L, resoff)); else setnilV(res);
        return;
      }
    } else {
      tm = lj_meta_lookup(L, &tv, MM_index);
      if (tm == NULL) {
        if (tviscdata(&tv)) {
          TValue r;
          lj_ffi_index(L, &tv, &kv, &r);
          if (resonstack) copyTV(restorestack(L, resoff), &r); else copyTV(res, &r);
          return;
        }
        lj_err_typeop(L, tp, "index");
      }
    }
    if (tvisfunc(tm)) {
      if (resonstack) {
        callTMres(L, resoff, tm, &tv, &kv, MM_index);
      } else {
        TValue *top = L->top;
        ptrdiff_t tmpoff = savestack(L, top);
        lj_checkstack(L, 1);
        setnilV(L->top); L->top++;
        callTMres(L, tmpoff, tm, &tv, &kv, MM_index);
        copyTV(res, restorestack(L, tmpoff));
        L->top--;
      }
      return;
    }
    tv = *tm;
    tp = tm;
    /* Object from metatable is not on the stack: no variable name. */
  }
  lj_err_msg(L, "loop in gettable");
}

void lj_vm_settable(lua_State *L, cTValue *t, cTValue *key, cTValue *val)
{
  int loop;
  TValue tv = *t, kv = *key, vv = *val;
  cTValue *tp = t;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    cTValue *tm;
    if (tvistab(&tv)) {
      GCtab *h = tabV(&tv);
      cTValue *oldval = lj_tab_get(L, h, &kv);
      if (!tvisnil(oldval)) {
        copyTV((TValue *)oldval, &vv);
        return;
      }
      tm = fasttm(L, h->metatable, MM_newindex);
      if (tm == NULL) {
        TValue *slot = lj_tab_set(L, h, &kv);
        copyTV(slot, &vv);
        return;
      }
    } else {
      tm = lj_meta_lookup(L, &tv, MM_newindex);
      if (tm == NULL) {
        if (tviscdata(&tv)) {
          lj_ffi_newindex(L, &tv, &kv, &vv);
          return;
        }
        lj_err_typeop(L, tp, "index");
      }
    }
    if (tvisfunc(tm)) {
      callTM(L, tm, &tv, &kv, &vv, MM_newindex);
      return;
    }
    tv = *tm;
    tp = tm;
  }
  lj_err_msg(L, "loop in settable");
}

static int call_binTM(lua_State *L, cTValue *p1, cTValue *p2, TValue *res, int mm)
{
  cTValue *tm = lj_meta_lookup(L, p1, mm);
  if (tm == NULL) tm = lj_meta_lookup(L, p2, mm);
  if (tm == NULL) return 0;
  {
    TValue tmv = *tm, a = *p1, b = *p2;
    callTMres(L, savestack(L, res), &tmv, &a, &b, mm);
  }
  return 1;
}

extern int lj_ffi_arith(lua_State *L, TValue *ra, cTValue *rb, cTValue *rc, int mm);

void lj_vm_arith(lua_State *L, TValue *ra, cTValue *rb, cTValue *rc, int op)
{
  TValue tempb, tempc;
  cTValue *b, *c;
  if ((b = lj_vm_tonumber(rb, &tempb) ? &tempb : NULL) != NULL &&
      (c = lj_vm_tonumber(rc, &tempc) ? &tempc : NULL) != NULL) {
    double nb = b->u.n, nc = c->u.n;
    setnumV(ra, lj_vm_foldarith(nb, nc, op));
  } else {
    int mm;
    switch (op) {
    case OP_ADD: mm = MM_add; break;
    case OP_SUB: mm = MM_sub; break;
    case OP_MUL: mm = MM_mul; break;
    case OP_DIV: mm = MM_div; break;
    case OP_MOD: mm = MM_mod; break;
    case OP_POW: mm = MM_pow; break;
    default: mm = MM_unm; break;
    }
    if (!call_binTM(L, rb, rc, ra, mm)) {
      if (tviscdata(rb) || tviscdata(rc)) {
        if (lj_ffi_arith(L, ra, rb, rc, mm)) return;
      }
      lj_err_arith(L, rb, rc);
    }
  }
}

extern int lj_ffi_len(lua_State *L, cTValue *o, TValue *res);

void lj_vm_objlen(lua_State *L, TValue *ra, cTValue *rb)
{
  switch (rb->tt) {
  case LJ_TTAB:
    setnumV(ra, (double)lj_tab_len(tabV(rb)));
    break;
  case LJ_TSTR:
    setnumV(ra, (double)strV(rb)->len);
    break;
  default: {
    cTValue *tm = lj_meta_lookup(L, rb, MM_len);
    if (tm == NULL) {
      if (tviscdata(rb)) {
        TValue r;
        if (lj_ffi_len(L, rb, &r)) { copyTV(ra, &r); return; }
      }
      lj_err_typeop(L, rb, "get length of");
    }
    {
      TValue tmv = *tm, a = *rb;
      callTMres(L, savestack(L, ra), &tmv, &a, &a, MM_len);
    }
  }
  }
}

extern int lj_ffi_equal(lua_State *L, cTValue *a, cTValue *b);

int lj_vm_equal(lua_State *L, cTValue *a, cTValue *b)
{
  cTValue *tm;
  if (a->tt != b->tt) {
    if (tviscdata(a) || tviscdata(b)) return lj_ffi_equal(L, a, b);
    return 0;
  }
  switch (a->tt) {
  case LJ_TNIL: case LJ_TFALSE: case LJ_TTRUE: return 1;
  case LJ_TNUM: return a->u.n == b->u.n;
  case LJ_TLIGHTUD: return a->u.p == b->u.p;
  case LJ_TTAB: case LJ_TUDATA: {
    GCtab *mt1, *mt2;
    if (a->u.p == b->u.p) return 1;
    mt1 = (a->tt == LJ_TTAB) ? tabV(a)->metatable : udataV(a)->metatable;
    mt2 = (b->tt == LJ_TTAB) ? tabV(b)->metatable : udataV(b)->metatable;
    tm = fasttm(L, mt1, MM_eq);
    if (tm == NULL) return 0;
    if (mt1 != mt2) {
      cTValue *tm2 = fasttm(L, mt2, MM_eq);
      if (tm2 == NULL) return 0;
      if (!(tm->tt == tm2->tt && tm->u.p == tm2->u.p)) return 0;
    }
    break;
  }
  case LJ_TCDATA:
    if (a->u.p == b->u.p) return 1;
    return lj_ffi_equal(L, a, b);
  default:
    return a->u.p == b->u.p;
  }
  {
    TValue tmv = *tm, av = *a, bv = *b;
    TValue *top = L->top;
    ptrdiff_t off = savestack(L, top);
    lj_checkstack(L, 1);
    setnilV(L->top); L->top++;
    callTMres(L, off, &tmv, &av, &bv, MM_eq);
    {
      int r = !tvisfalse(restorestack(L, off));
      L->top--;
      return r;
    }
  }
}

extern int lj_ffi_compare(lua_State *L, cTValue *a, cTValue *b, int le, int *res);

static int call_orderTM(lua_State *L, cTValue *p1, cTValue *p2, int mm)
{
  cTValue *tm1 = lj_meta_lookup(L, p1, mm);
  cTValue *tm2;
  if (tm1 == NULL) return -1;
  tm2 = lj_meta_lookup(L, p2, mm);
  if (tm2 == NULL || !(tm1->tt == tm2->tt && tm1->u.p == tm2->u.p)) return -1;
  {
    TValue tmv = *tm1, a = *p1, b = *p2;
    ptrdiff_t off;
    int r;
    lj_checkstack(L, 1);
    off = savestack(L, L->top);
    setnilV(L->top); L->top++;
    callTMres(L, off, &tmv, &a, &b, mm);
    r = !tvisfalse(restorestack(L, off));
    L->top--;
    return r;
  }
}

int lj_vm_lessthan(lua_State *L, cTValue *l, cTValue *r)
{
  int res;
  if (tvisnum(l) && tvisnum(r)) return l->u.n < r->u.n;
  if (l->tt != r->tt) {
    if (tviscdata(l) || tviscdata(r)) {
      if (lj_ffi_compare(L, l, r, 0, &res)) return res;
    }
    lj_err_compare(L, l, r);
  }
  if (tvisstr(l)) return lj_str_cmp(strV(l), strV(r)) < 0;
  if (tviscdata(l)) {
    if (lj_ffi_compare(L, l, r, 0, &res)) return res;
  }
  if ((res = call_orderTM(L, l, r, MM_lt)) != -1) return res;
  lj_err_compare(L, l, r);
}

int lj_vm_lessequal(lua_State *L, cTValue *l, cTValue *r)
{
  int res;
  if (tvisnum(l) && tvisnum(r)) return l->u.n <= r->u.n;
  if (l->tt != r->tt) {
    if (tviscdata(l) || tviscdata(r)) {
      if (lj_ffi_compare(L, l, r, 1, &res)) return res;
    }
    lj_err_compare(L, l, r);
  }
  if (tvisstr(l)) return lj_str_cmp(strV(l), strV(r)) <= 0;
  if (tviscdata(l)) {
    if (lj_ffi_compare(L, l, r, 1, &res)) return res;
  }
  if ((res = call_orderTM(L, l, r, MM_le)) != -1) return res;
  if ((res = call_orderTM(L, r, l, MM_lt)) != -1) return !res;
  lj_err_compare(L, l, r);
}

void lj_vm_concat(lua_State *L, int total, int last)
{
  do {
    TValue *top = L->base + last + 1;
    int n = 2;
    if (!(tvisstr(top - 2) || tvisnum(top - 2)) || !lj_vm_tostring(L, top - 1)) {
      ptrdiff_t off = savestack(L, top - 2);
      if (!call_binTM(L, top - 2, top - 1, top - 2, MM_concat)) {
        top = restorestack(L, off) + 2;
        lj_err_concat(L, top - 2, top - 1);
      }
    } else if (strV(top - 1)->len == 0) {
      lj_vm_tostring(L, top - 2);
    } else {
      size_t tl = strV(top - 1)->len;
      char *buffer;
      int i;
      for (n = 1; n < total && lj_vm_tostring(L, top - n - 1); n++) {
        size_t l = strV(top - n - 1)->len;
        if (l >= ((size_t)0x7fffff00) - tl) lj_err_msg(L, "string length overflow");
        tl += l;
      }
      buffer = (char *)malloc(tl ? tl : 1);
      if (!buffer) lj_err_throw(L, LUA_ERRMEM);
      tl = 0;
      for (i = n; i > 0; i--) {
        size_t l = strV(top - i)->len;
        memcpy(buffer + tl, strdata(strV(top - i)), l);
        tl += l;
      }
      {
        GCstr *s = lj_str_new(L, buffer, tl);
        free(buffer);
        setstrV(top - n, s);
      }
    }
    total -= n - 1;
    last -= n - 1;
  } while (total > 1);
}

/* -- Calls ------------------------------------------------------------------- */

TValue *lj_vm_tryfuncTM(lua_State *L, TValue *func)
{
  cTValue *tm = lj_meta_lookup(L, func, MM_call);
  TValue *p;
  ptrdiff_t funcr = savestack(L, func);
  if (tm == NULL || !tvisfunc(tm)) {
    if (tviscdata(func)) {
      extern int lj_ffi_call_tm(lua_State *L, TValue *func);
      if (lj_ffi_call_tm(L, func)) return restorestack(L, funcr);
    }
    lj_err_call(L, func);
  }
  {
    TValue tmv = *tm;
    lj_checkstack(L, 1);
    func = restorestack(L, funcr);
    for (p = L->top; p > func; p--) copyTV(p, p - 1);
    L->top++;
    copyTV(func, &tmv);
  }
  return func;
}

static inline CallInfo *inc_ci(lua_State *L)
{
  if (L->ci == L->end_ci) lj_state_growci(L);
  return ++L->ci;
}

static TValue *adjust_varargs(lua_State *L, GCproto *p, int actual)
{
  int i;
  int nfixargs = p->numparams;
  TValue *base, *fixed;
  for (; actual < nfixargs; ++actual) setnilV(L->top++);
  fixed = L->top - actual;
  base = L->top;
  for (i = 0; i < nfixargs; i++) {
    copyTV(L->top++, fixed + i);
    setnilV(fixed + i);
  }
  return base;
}

static LJ_NORET void stack_overflow_lua(lua_State *L, TValue *func, GCproto *p)
{
  /* Report error at the callee's first line, like the reference. */
  CallInfo *ci;
  if (L->ci == L->end_ci) lj_state_growci(L);
  ci = ++L->ci;
  ci->func = func;
  ci->base = func + 1;
  ci->top = L->top;
  ci->savedpc = p->code + 1;
  ci->nresults = 0;
  ci->tailcalls = 0;
  ci->flags = CIST_LUA;
  L->base = ci->base;
  lj_err_msg(L, "stack overflow");
}

void lj_vm_callhook(lua_State *L, int event, int line);

#define HOOK_CALL 0
#define HOOK_RET 1
#define HOOK_LINE 2
#define HOOK_COUNT 3
#define HOOK_TAILCALL 4
#define MASK_CALL (1 << HOOK_CALL)
#define MASK_RET (1 << HOOK_RET)
#define MASK_LINE (1 << HOOK_LINE)
#define MASK_COUNT (1 << HOOK_COUNT)

int lj_vm_precall(lua_State *L, TValue *func, int nresults)
{
  GCfunc *cl;
  ptrdiff_t funcr;
  int mm = lj_vm_nextmm;
  lj_vm_nextmm = -1;
  if (!tvisfunc(func)) func = lj_vm_tryfuncTM(L, func);
  funcr = savestack(L, func);
  cl = funcV(func);
  if (!cl->isC) {
    CallInfo *ci;
    TValue *st, *base;
    GCproto *p = cl->u.l.pt;
    if (LJ_UNLIKELY((char *)L->stack_last - (char *)L->top <= (ptrdiff_t)(p->maxstack + 4) * (ptrdiff_t)sizeof(TValue))) {
      int need = (int)(L->top - L->stack) + p->maxstack + 4;
      if (need > LJ_STACK_MAX && (L->stack_last - L->stack) <= LJ_STACK_MAX)
        stack_overflow_lua(L, func, p);
      lj_state_growstack(L, p->maxstack + 4);
    }
    func = restorestack(L, funcr);
    if (!p->is_vararg) {
      base = func + 1;
      if (L->top > base + p->numparams) L->top = base + p->numparams;
    } else {
      int nargs = (int)(L->top - func) - 1;
      base = adjust_varargs(L, p, nargs);
      func = restorestack(L, funcr);
    }
    ci = inc_ci(L);
    ci->func = func;
    L->base = ci->base = base;
    ci->top = L->base + p->maxstack;
    ci->savedpc = p->code;
    ci->tailcalls = 0;
    ci->nresults = nresults;
    ci->flags = CIST_LUA | (mm >= 0 ? (CIST_MM | (mm << 8)) : 0);
    for (st = L->top; st < ci->top; st++) setnilV(st);
    L->top = ci->top;
    if (L->hookmask & MASK_CALL) {
      ci->savedpc++;
      lj_vm_callhook(L, HOOK_CALL, -1);
      ci->savedpc--;
    }
    return PCRLUA;
  } else {
    CallInfo *ci;
    int n;
    lj_checkstack(L, LUA_MINSTACK);
    ci = inc_ci(L);
    ci->func = restorestack(L, funcr);
    L->base = ci->base = ci->func + 1;
    ci->top = L->top + LUA_MINSTACK;
    ci->nresults = nresults;
    ci->tailcalls = 0;
    ci->savedpc = NULL;
    ci->flags = (mm >= 0 ? (CIST_MM | (mm << 8)) : 0);
    if (L->hookmask & MASK_CALL) lj_vm_callhook(L, HOOK_CALL, -1);
    n = (*funcV(ci->func)->u.c.f)(L);
    lj_vm_poscall(L, L->top - n);
    return PCRC;
  }
}

int lj_vm_poscall(lua_State *L, TValue *firstResult)
{
  TValue *res;
  int wanted, i;
  CallInfo *ci;
  if (L->hookmask & MASK_RET) {
    ptrdiff_t fr = savestack(L, firstResult);
    lj_vm_callhook(L, HOOK_RET, -1);
    firstResult = restorestack(L, fr);
  }
  ci = L->ci--;
  res = ci->func;
  wanted = ci->nresults;
  L->base = (ci - 1)->base;
  for (i = wanted; i != 0 && firstResult < L->top; i--)
    copyTV(res++, firstResult++);
  while (i-- > 0) setnilV(res++);
  L->top = res;
  return (wanted - LUA_MULTRET);
}

extern char *lj_co_cstack_limit(lua_State *L);

void lj_vm_call(lua_State *L, TValue *func, int nResults)
{
  char probe;
  if (LJ_UNLIKELY(++L->nCcalls >= 7000 || &probe < L->cstack_limit)) {
    if (L->nCcalls >= 7000 + 50 || &probe < L->cstack_limit - 32768) {
      L->nCcalls--;
      lj_err_throw(L, LUA_ERRERR);
    }
    L->nCcalls--;
    lj_err_msg(L, "stack overflow");
  }
  if (lj_vm_precall(L, func, nResults) == PCRLUA) {
    L->ci->flags |= CIST_FRESH;
    lj_vm_execute(L, 1);
  }
  L->nCcalls--;
  lj_gc_check(L);
}

int lj_vm_pcall(lua_State *L, void (*func)(lua_State *L, void *ud), void *u, ptrdiff_t old_top, ptrdiff_t ef)
{
  int status;
  ptrdiff_t old_ci = saveci(L, L->ci);
  uint8_t old_allowhooks = L->allowhook;
  ptrdiff_t old_errfunc = L->errfunc;
  int oldnCcalls = L->nCcalls;
  L->errfunc = ef;
  status = lj_err_rawrunprotected(L, func, u);
  if (status != 0) {
    extern void lj_state_shrinkstack(lua_State *L);
    TValue *oldtop = restorestack(L, old_top);
    lj_func_closeuv(L, oldtop);
    lj_err_seterrorobj(L, status, oldtop);
    L->nCcalls = oldnCcalls;
    L->ci = restoreci(L, old_ci);
    L->base = L->ci->base;
    L->allowhook = old_allowhooks;
    lj_state_shrinkstack(L);
  }
  L->errfunc = old_errfunc;
  return status;
}

/* -- Hooks ---------------------------------------------------------------- */

extern void lj_debug_hookcall(lua_State *L, int event, int line);

void lj_vm_callhook(lua_State *L, int event, int line)
{
  if (!L->allowhook || tvisnil(&L->hookf)) return;
  lj_debug_hookcall(L, event, line);
}

/* -- Interpreter ------------------------------------------------------------ */

#define RA(i) (base + GETARG_A(i))
#define RB(i) (base + GETARG_B(i))
#define RC(i) (base + GETARG_C(i))
#define RKB(i) (ISK(GETARG_B(i)) ? k + INDEXK(GETARG_B(i)) : base + GETARG_B(i))
#define RKC(i) (ISK(GETARG_C(i)) ? k + INDEXK(GETARG_C(i)) : base + GETARG_C(i))
#define KBx(i) (k + GETARG_Bx(i))
#define dojump(pc, i) ((pc) += (i))
#define Protect(x) { ci->savedpc = pc; {x;}; base = L->base; }
#define savepc() (ci->savedpc = pc)

static void traceexec(lua_State *L, const BCIns *pc)
{
  uint8_t mask = L->hookmask;
  CallInfo *ci = L->ci;
  GCproto *p = funcV(ci->func)->u.l.pt;
  const BCIns *oldpc = ci->savedpc;
  ci->savedpc = pc;
  if ((mask & MASK_COUNT) && L->hookcount == 0) {
    L->hookcount = L->basehookcount;
    lj_vm_callhook(L, HOOK_COUNT, -1);
  }
  if (mask & MASK_LINE) {
    int npc = (int)(pc - p->code) - 1;
    int newline = p->lineinfo[npc];
    int oldnpc = oldpc ? (int)(oldpc - p->code) - 1 : -1;
    if (npc == 0 || pc <= oldpc || oldnpc < 0 || newline != p->lineinfo[oldnpc])
      lj_vm_callhook(L, HOOK_LINE, newline);
  }
}

static LJ_NORET void for_error(lua_State *L, const char *what)
{
  lj_err_runerror(L, "'for' %s must be a number", what);
}

void lj_vm_execute(lua_State *L, int nexeccalls)
{
  GCfunc *cl;
  TValue *base;
  TValue *k;
  const BCIns *pc;
  CallInfo *ci;
reentry:
  ci = L->ci;
  pc = ci->savedpc;
  cl = funcV(ci->func);
  base = L->base;
  k = cl->u.l.pt->k;
  for (;;) {
    const BCIns i = *pc++;
    TValue *ra;
    if (LJ_UNLIKELY(L->hookmask & (MASK_LINE | MASK_COUNT))) {
      if ((L->hookmask & MASK_COUNT) && --L->hookcount == 0) {
        traceexec(L, pc); base = L->base;
      } else if (L->hookmask & MASK_LINE) {
        traceexec(L, pc); base = L->base;
      }
    }
    ra = RA(i);
    switch (GET_OPCODE(i)) {
    case OP_MOVE:
      copyTV(ra, RB(i));
      continue;
    case OP_LOADK:
      copyTV(ra, KBx(i));
      continue;
    case OP_LOADBOOL:
      setboolV(ra, GETARG_B(i));
      if (GETARG_C(i)) pc++;
      continue;
    case OP_LOADNIL: {
      TValue *rb = RB(i);
      do {
        setnilV(rb--);
      } while (rb >= ra);
      continue;
    }
    case OP_GETUPVAL:
      copyTV(ra, cl->u.l.uv[GETARG_B(i)]->v);
      continue;
    case OP_GETGLOBAL: {
      TValue *rb = KBx(i);
      GCtab *env = cl->env;
      cTValue *v = lj_tab_getstr(env, strV(rb));
      if (v && !tvisnil(v)) {
        copyTV(ra, v);
      } else if (env->metatable == NULL || (env->metatable->nomm & 1)) {
        setnilV(ra);
      } else {
        TValue g;
        settabV(&g, env);
        Protect(lj_vm_gettable(L, &g, rb, ra));
      }
      continue;
    }
    case OP_GETTABLE: {
      TValue *rb = RB(i);
      TValue *rc = RKC(i);
      if (tvistab(rb)) {
        GCtab *t = tabV(rb);
        cTValue *v;
        if (tvisstr(rc)) {
          v = lj_tab_getstr(t, strV(rc));
          if (v == NULL) v = &lj_nilobj;
        } else if (tvisnum(rc)) {
          double nk = rc->u.n;
          int32_t ik = (int32_t)nk;
          if ((uint32_t)ik < t->asize && (double)ik == nk) v = &t->array[ik];
          else v = lj_tab_get(L, t, rc);
        } else {
          v = lj_tab_get(L, t, rc);
        }
        if (!tvisnil(v) || t->metatable == NULL || (t->metatable->nomm & (1u << MM_index))) {
          copyTV(ra, v);
          continue;
        }
      }
      Protect(lj_vm_gettable(L, rb, rc, ra));
      continue;
    }
    case OP_SETGLOBAL: {
      GCtab *env = cl->env;
      TValue *rb = KBx(i);
      cTValue *v = lj_tab_getstr(env, strV(rb));
      if (v && !tvisnil(v)) {
        copyTV((TValue *)v, ra);
      } else if (env->metatable == NULL || (env->metatable->nomm & (1u << MM_newindex))) {
        TValue *slot;
        Protect(slot = lj_tab_setstr(L, env, strV(rb)));
        ra = RA(i);
        copyTV(slot, ra);
      } else {
        TValue g;
        settabV(&g, env);
        Protect(lj_vm_settable(L, &g, rb, ra));
      }
      continue;
    }
    case OP_SETUPVAL: {
      GCupval *uv = cl->u.l.uv[GETARG_B(i)];
      copyTV(uv->v, ra);
      continue;
    }
    case OP_SETTABLE: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      if (tvistab(ra)) {
        GCtab *t = tabV(ra);
        TValue *v = NULL;
        if (tvisstr(rb)) {
          v = (TValue *)lj_tab_getstr(t, strV(rb));
        } else if (tvisnum(rb)) {
          double nk = rb->u.n;
          int32_t ik = (int32_t)nk;
          if ((uint32_t)ik < t->asize && (double)ik == nk) v = &t->array[ik];
          else v = (TValue *)lj_tab_get(L, t, rb);
        } else if (!tvisnil(rb)) {
          v = (TValue *)lj_tab_get(L, t, rb);
        }
        if (v && !tvisnil(v)) {
          copyTV(v, rc);
          continue;
        }
        if (t->metatable == NULL || (t->metatable->nomm & (1u << MM_newindex)) ||
            fasttm(L, t->metatable, MM_newindex) == NULL) {
          TValue val = *rc;
          Protect(v = lj_tab_set(L, t, rb));
          copyTV(v, &val);
          continue;
        }
      }
      Protect(lj_vm_settable(L, ra, rb, rc));
      continue;
    }
    case OP_NEWTABLE: {
      uint32_t bx = (uint32_t)GETARG_Bx(i);
      uint32_t asize = bx & 0x7ff;
      uint32_t hbits = bx >> 11;
      settabV(ra, lj_tab_new(L, asize, hbits));
      Protect(lj_gc_check(L));
      continue;
    }
    case OP_TDUP: {
      settabV(ra, lj_tab_dup(L, tabV(KBx(i))));
      Protect(lj_gc_check(L));
      continue;
    }
    case OP_SELF: {
      TValue *rb = RB(i);
      TValue *rc = RKC(i);
      TValue obj = *rb;
      copyTV(ra + 1, &obj);
      if (tvistab(&obj)) {
        GCtab *t = tabV(&obj);
        cTValue *v = lj_tab_getstr(t, strV(rc));
        if (v == NULL) v = &lj_nilobj;
        if (!tvisnil(v) || t->metatable == NULL || (t->metatable->nomm & (1u << MM_index))) {
          copyTV(ra, v);
          continue;
        }
      } else if (tvisstr(&obj) && G(L)->strmt) {
        GCtab *mt = G(L)->strmt;
        cTValue *idx = lj_tab_getstr(mt, G(L)->mmname[MM_index]);
        if (idx && tvistab(idx)) {
          cTValue *v = lj_tab_getstr(tabV(idx), strV(rc));
          if (v && !tvisnil(v)) {
            copyTV(ra, v);
            continue;
          }
        }
      }
      Protect(lj_vm_gettable(L, ra + 1, rc, ra));
      continue;
    }
#define ARITH_OP(opc, expr) \
    case opc: { \
      TValue *rb = RKB(i); \
      TValue *rc = RKC(i); \
      if (tvisnum(rb) && tvisnum(rc)) { \
        double nb = rb->u.n, nc = rc->u.n; \
        setnumV(ra, (expr)); \
      } else { \
        Protect(lj_vm_arith(L, ra, rb, rc, opc)); \
      } \
      continue; \
    }
    ARITH_OP(OP_ADD, nb + nc)
    ARITH_OP(OP_SUB, nb - nc)
    ARITH_OP(OP_MUL, nb * nc)
    ARITH_OP(OP_DIV, nb / nc)
    ARITH_OP(OP_MOD, nb - floor(nb / nc) * nc)
    ARITH_OP(OP_POW, pow(nb, nc))
    case OP_UNM: {
      TValue *rb = RB(i);
      if (tvisnum(rb)) {
        setnumV(ra, -rb->u.n);
      } else {
        Protect(lj_vm_arith(L, ra, rb, rb, OP_UNM));
      }
      continue;
    }
    case OP_NOT: {
      int res = tvisfalse(RB(i));
      setboolV(ra, res);
      continue;
    }
    case OP_LEN: {
      TValue *rb = RB(i);
      if (tvisstr(rb)) {
        setnumV(ra, (double)strV(rb)->len);
      } else if (tvistab(rb)) {
        setnumV(ra, (double)lj_tab_len(tabV(rb)));
      } else {
        Protect(lj_vm_objlen(L, ra, rb));
      }
      continue;
    }
    case OP_CONCAT: {
      int b = GETARG_B(i);
      int c = GETARG_C(i);
      Protect(lj_vm_concat(L, c - b + 1, c); lj_gc_check(L));
      copyTV(RA(i), base + b);
      continue;
    }
    case OP_JMP: {
      int a = GETARG_A(i);
      if (a > 0 && L->openupval) lj_func_closeuv(L, base + a - 1);
      dojump(pc, GETARG_sBx(i));
      continue;
    }
    case OP_EQ: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      int res;
      if (rb->tt == rc->tt && (rb->tt != LJ_TTAB && rb->tt != LJ_TUDATA && rb->tt != LJ_TCDATA)) {
        if (rb->tt == LJ_TNUM) res = rb->u.n == rc->u.n;
        else if (rb->tt <= LJ_TTRUE) res = 1;
        else res = rb->u.p == rc->u.p;
      } else {
        Protect(res = lj_vm_equal(L, rb, rc));
      }
      if (res == GETARG_A(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    }
    case OP_LT: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      int res;
      if (tvisnum(rb) && tvisnum(rc)) res = rb->u.n < rc->u.n;
      else Protect(res = lj_vm_lessthan(L, rb, rc));
      if (res == GETARG_A(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    }
    case OP_LE: {
      TValue *rb = RKB(i);
      TValue *rc = RKC(i);
      int res;
      if (tvisnum(rb) && tvisnum(rc)) res = rb->u.n <= rc->u.n;
      else Protect(res = lj_vm_lessequal(L, rb, rc));
      if (res == GETARG_A(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    }
    case OP_TEST:
      if (tvisfalse(ra) != GETARG_C(i)) dojump(pc, GETARG_sBx(*pc));
      pc++;
      continue;
    case OP_TESTSET: {
      TValue *rb = RB(i);
      if (tvisfalse(rb) != GETARG_C(i)) {
        copyTV(ra, rb);
        dojump(pc, GETARG_sBx(*pc));
      }
      pc++;
      continue;
    }
    case OP_CALL: {
      int b = GETARG_B(i);
      int nresults = GETARG_C(i) - 1;
      if (b != 0) L->top = ra + b;
      savepc();
      if (lj_vm_precall(L, ra, nresults) == PCRLUA) {
        nexeccalls++;
        goto reentry;
      }
      if (nresults >= 0) L->top = ci->top;
      base = L->base;
      lj_gc_check(L);
      continue;
    }
    case OP_TAILCALL: {
      int b = GETARG_B(i);
      TValue *func;
      int aux;
      if (b != 0) L->top = ra + b;
      savepc();
      if (!tvisfunc(ra)) {
        ra = lj_vm_tryfuncTM(L, ra);
        base = L->base;
      }
      if (L->openupval) lj_func_closeuv(L, base);
      func = ci->func;
      for (aux = 0; ra + aux < L->top; aux++) copyTV(func + aux, ra + aux);
      L->top = func + aux;
      {
        GCfunc *ncl = funcV(func);
        if (!ncl->isC) {
          GCproto *p = ncl->u.l.pt;
          TValue *st, *nbase;
          ptrdiff_t funcr = savestack(L, func);
          int fresh = ci->flags & CIST_FRESH;
          if ((char *)L->stack_last - (char *)L->top <= (ptrdiff_t)(p->maxstack + 4) * (ptrdiff_t)sizeof(TValue)) {
            int need = (int)(L->top - L->stack) + p->maxstack + 4;
            if (need > LJ_STACK_MAX && (L->stack_last - L->stack) <= LJ_STACK_MAX) {
              L->ci--;
              stack_overflow_lua(L, func, p);
            }
            lj_state_growstack(L, p->maxstack + 4);
            ci = L->ci;
          }
          func = restorestack(L, funcr);
          if (!p->is_vararg) {
            nbase = func + 1;
            if (L->top > nbase + p->numparams) L->top = nbase + p->numparams;
          } else {
            int nargs = (int)(L->top - func) - 1;
            nbase = adjust_varargs(L, p, nargs);
            func = restorestack(L, funcr);
          }
          ci->func = func;
          L->base = ci->base = nbase;
          ci->top = nbase + p->maxstack;
          ci->savedpc = p->code;
          ci->tailcalls++;
          ci->flags = CIST_LUA | CIST_TAIL | fresh;
          for (st = L->top; st < ci->top; st++) setnilV(st);
          L->top = ci->top;
          if (L->hookmask & MASK_CALL) {
            ci->savedpc++;
            lj_vm_callhook(L, HOOK_CALL, -1);
            ci->savedpc--;
          }
          goto reentry;
        } else {
          /* Tail call of a C function: replace the current frame. */
          int n, wanted;
          int fresh = ci->flags & CIST_FRESH;
          ptrdiff_t funcr = savestack(L, func);
          lj_checkstack(L, LUA_MINSTACK);
          ci = L->ci;
          func = restorestack(L, funcr);
          L->base = ci->base = func + 1;
          ci->top = L->top + LUA_MINSTACK;
          ci->savedpc = NULL;
          ci->flags = CIST_TAIL;
          ci->tailcalls++;
          if (L->hookmask & MASK_CALL) lj_vm_callhook(L, HOOK_CALL, -1);
          n = (*funcV(ci->func)->u.c.f)(L);
          wanted = L->ci->nresults;
          lj_vm_poscall(L, L->top - n);
          lj_gc_check(L);
          if (fresh) return;
          if (wanted >= 0) L->top = L->ci->top;
          goto reentry;
