      }
    }
    case OP_RETURN: {
      int b = GETARG_B(i);
      int fresh;
      if (b != 0) L->top = ra + b - 1;
      if (L->openupval) lj_func_closeuv(L, base);
      savepc();
      fresh = ci->flags & CIST_FRESH;
      b = lj_vm_poscall(L, ra);
      if (fresh) return;
      if (b) L->top = L->ci->top;
      goto reentry;
    }
    case OP_FORLOOP: {
      double step = ra[2].u.n;
      double idx = ra[0].u.n + step;
      double limit = ra[1].u.n;
      if (step >= 0 ? idx <= limit : limit <= idx) {
        dojump(pc, GETARG_sBx(i));
        setnumV(ra, idx);
        setnumV(ra + 3, idx);
      }
      continue;
    }
    case OP_FORPREP: {
      TValue *init = ra;
      TValue *plimit = ra + 1;
      TValue *pstep = ra + 2;
      TValue tmp;
      savepc();
      if (!tvisnum(init)) {
        if (!lj_vm_tonumber(init, &tmp)) for_error(L, "initial value");
        copyTV(init, &tmp);
      }
      if (!tvisnum(plimit)) {
        if (!lj_vm_tonumber(plimit, &tmp)) for_error(L, "limit");
        copyTV(plimit, &tmp);
      }
      if (!tvisnum(pstep)) {
        if (!lj_vm_tonumber(pstep, &tmp)) for_error(L, "step");
        copyTV(pstep, &tmp);
      }
      {
        double idx = init->u.n, limit = plimit->u.n, step = pstep->u.n;
        if (step >= 0 ? idx <= limit : limit <= idx) {
          setnumV(ra + 3, idx);
        } else {
          dojump(pc, GETARG_sBx(i) + 1);
        }
      }
      continue;
    }
    case OP_TFORLOOP: {
      TValue *cb = ra + 3;
      copyTV(cb + 2, ra + 2);
      copyTV(cb + 1, ra + 1);
      copyTV(cb, ra);
      L->top = cb + 3;
      Protect(lj_vm_call(L, cb, GETARG_C(i)));
      L->top = ci->top;
      cb = RA(i) + 3;
      if (!tvisnil(cb)) {
        copyTV(cb - 1, cb);
        dojump(pc, GETARG_sBx(*pc));
      }
      pc++;
      continue;
    }
    case OP_SETLIST:
      continue;
    case OP_TSETM: {
      GCtab *t = tabV(ra - 1);
      int n = (int)(L->top - ra);
      int32_t start = (int32_t)KBx(i)->u.n;
      int j;
      savepc();
      if (n > 0 && (uint32_t)(start + n - 1) >= t->asize)
        lj_tab_reasize(L, t, (uint32_t)(start + n - 1));
      ra = RA(i);
      for (j = 0; j < n; j++) {
        TValue *v = lj_tab_setint(L, t, start + j);
        copyTV(v, ra + j);
      }
