/* Coroutines implemented with separate C stacks. */
#include <sys/mman.h>
#include "lj.h"
#include "lj_api.h"

#define CO_STACK_SIZE (1024 * 1024)
#define CO_STACK_MARGIN (160 * 1024)

/* void lj_co_switch(void **save_sp, void *new_sp) */
__asm__(
  ".text\n"
  ".globl lj_co_switch\n"
  ".type lj_co_switch, @function\n"
  "lj_co_switch:\n"
  "  pushq %rbp\n"
  "  pushq %rbx\n"
  "  pushq %r12\n"
  "  pushq %r13\n"
  "  pushq %r14\n"
  "  pushq %r15\n"
  "  movq %rsp, (%rdi)\n"
  "  movq %rsi, %rsp\n"
  "  popq %r15\n"
  "  popq %r14\n"
  "  popq %r13\n"
  "  popq %r12\n"
  "  popq %rbx\n"
  "  popq %rbp\n"
  "  ret\n"
  ".size lj_co_switch, .-lj_co_switch\n"
);

void lj_co_switch(void **save_sp, void *new_sp);

static lua_State *co_starting;

static void *stack_alloc(global_State *g, size_t sz)
{
  void *p;
  if (sz == CO_STACK_SIZE && g->nfreestacks > 0)
    return g->freestacks[--g->nfreestacks];
  p = mmap(NULL, sz, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
  if (p == MAP_FAILED) return NULL;
  return p;
}

static void stack_free(global_State *g, void *p, size_t sz)
{
  if (sz == CO_STACK_SIZE && g->nfreestacks < 16) {
    g->freestacks[g->nfreestacks++] = p;
    return;
  }
  munmap(p, sz);
}

void lj_co_freestack(global_State *g, lua_State *co)
{
  if (co->ctx.stackmem) {
    stack_free(g, co->ctx.stackmem, co->ctx.stacksize);
    co->ctx.stackmem = NULL;
  }
}

/* Set up a fresh context that starts in entry(). */
static void ctx_init(CoCtx *ctx, void (*entry)(void))
{
  uintptr_t top = ((uintptr_t)ctx->stackmem + ctx->stacksize) & ~(uintptr_t)15;
  void **sp = (void **)(top - 16);
  sp[0] = (void *)entry;  /* return address for 'ret' */
  sp[1] = NULL;
  sp -= 6;
  {
    int i;
    for (i = 0; i < 6; i++) sp[i] = NULL;
  }
  ctx->sp = (void *)sp;
}

struct CoStart {
  int nargs;
};

static void co_body(lua_State *L, void *ud)
{
  int nargs = *(int *)ud;
  TValue *func = L->top - (nargs + 1);
  lj_vm_call(L, func, LUA_MULTRET);
}

static void co_entry(void)
{
  lua_State *co = co_starting;
  int nargs = co->nresume;
  int status;
  TValue *base;
  co->cstack_limit = (char *)co->ctx.stackmem + CO_STACK_MARGIN;
  base = co->top - (nargs + 1);
  {
    ptrdiff_t baseoff = savestack(co, base);
    status = lj_err_rawrunprotected(co, co_body, &nargs);
    if (status == 0) {
      co->nresume = (int)(co->top - restorestack(co, baseoff));
    } else {
      /* Error object is at top-1. */
      co->nresume = 1;
    }
  }
  co->status = (uint8_t)(status == 0 ? 0 : status);
  co->costate = CO_DEAD;
  /* Switch back to resumer; never returns. */
  lj_co_switch(&co->ctx.sp, co->resumer->ctx.sp);
  abort();
}

/* Resume coroutine co with narg arguments on L's stack. Returns status:
** 0 = yielded or finished (results moved to L), else error code with
** error object pushed on L. Number of results in co->nresume. */
int lj_co_resume(lua_State *L, lua_State *co, int narg)
{
  global_State *g = G(L);
  int status, n;
  if (co->costate != CO_SUSPENDED) {
    if (co->costate == CO_DEAD)
      lua_pushliteral(L, "cannot resume dead coroutine");
    else
      lua_pushliteral(L, "cannot resume non-suspended coroutine");
    return -1;
  }
  if (!co->started && co->ci == co->base_ci && co->top == co->base) {
    lua_pushliteral(L, "cannot resume dead coroutine");
    return -1;
  }
  if (L->nCcalls >= 7000) {
    lua_pushliteral(L, "C stack overflow");
    return -1;
  }
  lj_checkstack(co, narg + LUA_MINSTACK);
  lua_xmove(L, co, narg);
  co->nresume = narg;
  co->resumer = L;
  L->costate = CO_NORMAL;
  co->costate = CO_RUNNING;
  co->status = 0;
  g->curthread = co;
  co->nCcalls = L->nCcalls;
  if (!co->started) {
    co->ctx.stacksize = CO_STACK_SIZE;
    co->ctx.stackmem = stack_alloc(g, CO_STACK_SIZE);
    if (!co->ctx.stackmem) {
      g->curthread = L;
      L->costate = CO_RUNNING;
      co->costate = CO_SUSPENDED;
      lua_pushliteral(L, "not enough memory");
      return LUA_ERRMEM;
    }
    ctx_init(&co->ctx, co_entry);
    co->started = 1;
    co_starting = co;
  }
  lj_co_switch(&L->ctx.sp, co->ctx.sp);
  /* Back in resumer. */
  g->curthread = L;
  L->costate = CO_RUNNING;
  co->resumer = NULL;
  n = co->nresume;
  status = co->status;
  if (co->costate == CO_DEAD) {
    lj_co_freestack(g, co);
    if (status != 0 && status != LUA_YIELD) {
      lj_checkstack(L, 1);
      lua_xmove(co, L, 1);
      co->nresume = 1;
      return status;
    }
  } else {
    co->costate = CO_SUSPENDED;
  }
  lj_checkstack(L, n + LUA_MINSTACK);
  lua_xmove(co, L, n);
  co->nresume = n;
  return 0;
}

/* Yield nresults values from the top of L's stack. Returns number of values
** passed by the next resume (on top of L's stack). */
int lj_co_yield(lua_State *L, int nresults)
{
  if (L->resumer == NULL) {
    lj_err_msg(L, "attempt to yield across C-call boundary");
  }
  L->nresume = nresults;
  L->status = LUA_YIELD;
  lj_co_switch(&L->ctx.sp, L->resumer->ctx.sp);
  /* Resumed. */
  L->status = 0;
  return L->nresume;
}

/* -- Main stack ------------------------------------------------------------ */

static CoCtx main_ctx;
static void (*main_fn)(void *);
static void *main_arg;
static void *orig_sp;

static void main_entry(void)
{
  main_fn(main_arg);
  lj_co_switch(&main_ctx.sp, orig_sp);
  abort();
}

/* Run fn(arg) on a large private stack. */
void lj_co_runmain(void (*fn)(void *), void *arg, size_t stacksize)
{
  main_ctx.stacksize = stacksize;
  main_ctx.stackmem = mmap(NULL, stacksize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
  if (main_ctx.stackmem == MAP_FAILED) {
    fn(arg);
    return;
  }
  main_fn = fn;
  main_arg = arg;
  ctx_init(&main_ctx, main_entry);
  lj_co_switch(&orig_sp, main_ctx.sp);
}

char *lj_co_mainstack_base(void)
{
  return (char *)main_ctx.stackmem;
}
EOF
echo ok"}

