/* Base library and coroutine library. */
#include <ctype.h>
#include "lj.h"
#include "lj_api.h"

/* -- Object to string conversion ----------------------------------------- */

extern int lj_ffi_tostring(lua_State *L, cTValue *o, char *buf, size_t sz);

GCstr *lj_obj_tostr(lua_State *L, cTValue *o)
{
  char buf[128];
  switch (o->tt) {
  case LJ_TNIL: return lj_str_newlit(L, "nil");
  case LJ_TFALSE: return lj_str_newlit(L, "false");
  case LJ_TTRUE: return lj_str_newlit(L, "true");
  case LJ_TNUM: return lj_str_fromnum(L, o->u.n);
  case LJ_TSTR: return strV(o);
  case LJ_TFUNC:
    if (funcV(o)->ffid)
      snprintf(buf, sizeof(buf), "function: builtin#%d", funcV(o)->ffid);
    else
      snprintf(buf, sizeof(buf), "function: %p", (void *)o->u.p);
    break;
  case LJ_TTAB: snprintf(buf, sizeof(buf), "table: %p", (void *)o->u.p); break;
  case LJ_TUDATA: snprintf(buf, sizeof(buf), "userdata: %p", (void *)udataV(o)->align); break;
  case LJ_TLIGHTUD: snprintf(buf, sizeof(buf), "userdata: %p", o->u.p); break;
  case LJ_TTHREAD: snprintf(buf, sizeof(buf), "thread: %p", (void *)o->u.p); break;
  case LJ_TCDATA: {
    if (lj_ffi_tostring(L, o, buf, sizeof(buf)) == 0)
      snprintf(buf, sizeof(buf), "cdata: %p", (void *)o->u.p);
    break;
  }
  case LJ_TPROTO: snprintf(buf, sizeof(buf), "proto: %p", (void *)o->u.p); break;
  default: snprintf(buf, sizeof(buf), "%s: %p", lj_typename(o), (void *)o->u.p); break;
  }
  return lj_str_newz(L, buf);
}

/* Push tostring(L->base[idx-1]) honoring __tostring. */
void lj_tostring_push(lua_State *L, int idx)
{
  TValue *o = index2adr(L, idx);
  cTValue *mo;
  if (!tvisstr(o) && !tvisnum(o) && (mo = lj_meta_lookup(L, o, MM_tostring)) != NULL) {
    TValue f = *mo, a = *o;
    lj_checkstack(L, 2);
    copyTV(L->top, &f);
    copyTV(L->top + 1, &a);
    L->top += 2;
    lua_call(L, 1, 1);
    return;
  }
  {
    GCstr *s = lj_obj_tostr(L, index2adr(L, idx));
    lua_pushstr(L, s);
  }
}

static int lj_cf_tostring(lua_State *L)
{
  luaL_checkany(L, 1);
  lj_tostring_push(L, 1);
  return 1;
}

static GCfunc *tostring_builtin = NULL;

int lj_cf_print(lua_State *L)
{
  int n = lua_gettop(L);
  int i;
  TValue tsf;
  int shortcut;
  luaL_Buffer b;
  lua_getglobal(L, "tostring");
  tsf = L->top[-1];
  shortcut = tvisfunc(&tsf) && funcV(&tsf) == tostring_builtin;
  luaL_buffinit(L, &b);
  for (i = 1; i <= n; i++) {
    TValue *o = L->base + i - 1;
    size_t len;
    const char *s;
    if (shortcut && (tvisstr(o) || tvisnum(o))) {
      if (tvisstr(o)) {
        s = strdata(strV(o));
        len = strV(o)->len;
      } else {
        char nb[64];
        len = lj_str_fmtnum(nb, o->u.n);
        if (i > 1) luaL_addchar(&b, '\t');
        luaL_addlstring(&b, nb, len);
        continue;
      }
    } else {
      if (shortcut) {
        lj_tostring_push(L, i);
      } else {
        lua_pushvalue(L, -1 - (int)(L->top - L->base - n - 1) + 0);
        copyTV(L->top - 1, &tsf);
        lua_pushvalue(L, i);
        lua_call(L, 1, 1);
      }
      s = lua_tolstring(L, -1, &len);
      if (s == NULL) {
        luaL_bufffree(&b);
        luaL_error(L, "'tostring' must return a string to 'print'");
      }
    }
    if (i > 1) luaL_addchar(&b, '\t');
    luaL_addlstring(&b, s, len);
    if (!(shortcut && tvisstr(o))) lua_pop(L, 1);
  }
  luaL_addchar(&b, '\n');
  fwrite(b.b, 1, b.n, stdout);
  luaL_bufffree(&b);
  return 0;
}

/* -- Base functions -------------------------------------------------------- */

static int lj_cf_assert(lua_State *L)
{
  luaL_checkany(L, 1);
  if (!lua_toboolean(L, 1)) {
    if (L->top == L->base + 1) {
      luaL_error(L, "assertion failed!");
    } else if (tvisstr(L->base + 1) || tvisnum(L->base + 1)) {
      const char *msg = lua_tostring(L, 2);
      luaL_error(L, "%s", msg);
    } else {
      lua_settop(L, 2);
      lua_error(L);
    }
  }
  return lua_gettop(L);
}

static int lj_cf_type(lua_State *L)
{
  luaL_checkany(L, 1);
  lua_pushstring(L, luaL_typename(L, 1));
  return 1;
}

static int lj_cf_next(lua_State *L)
{
  GCtab *t = lj_lib_checktab(L, 1);
  lua_settop(L, 2);
  if (lj_tab_next(L, t, L->top - 1)) {
    L->top++;
    return 2;
  }
  lua_pushnil(L);
  return 1;
}

static int lj_cf_pairs(lua_State *L)
{
  if (L->top == L->base) luaL_argerror(L, 1, "value expected");
  lj_lib_checktab(L, 1);
  lua_pushvalue(L, lua_upvalueindex(1));
  lua_pushvalue(L, 1);
  lua_pushnil(L);
  return 3;
}

static int lj_cf_ipairs_aux(lua_State *L)
{
  GCtab *t = lj_lib_checktab(L, 1);
  int32_t i = lj_lib_checkint(L, 2) + 1;
  cTValue *v = lj_tab_getint(t, i);
  if (v == NULL || tvisnil(v)) return 0;
  lua_pushinteger(L, i);
  lua_pushtv(L, v);
  return 2;
}

static int lj_cf_ipairs(lua_State *L)
{
  if (L->top == L->base) luaL_argerror(L, 1, "value expected");
  lj_lib_checktab(L, 1);
  lua_pushvalue(L, lua_upvalueindex(1));
  lua_pushvalue(L, 1);
  lua_pushinteger(L, 0);
  return 3;
}

static int lj_cf_getmetatable(lua_State *L)
{
  luaL_checkany(L, 1);
  if (!lua_getmetatable(L, 1)) {
    lua_pushnil(L);
    return 1;
  }
  luaL_getmetafield(L, 1, "__metatable");
  return 1;
}

static int lj_cf_setmetatable(lua_State *L)
{
  GCtab *t = lj_lib_checktab(L, 1);
  GCtab *mt = lj_lib_checktabornil(L, 2);
  (void)mt;
  if (t->metatable && lj_tab_getstr(t->metatable, G(L)->mmname[MM_metatable]) &&
      !tvisnil(lj_tab_getstr(t->metatable, G(L)->mmname[MM_metatable])))
    luaL_error(L, "cannot change a protected metatable");
  lua_settop(L, 2);
  lua_setmetatable(L, 1);
  return 1;
}

static void getfunc(lua_State *L, int opt)
{
  if (lua_isfunction(L, 1)) {
    lua_pushvalue(L, 1);
  } else {
    CallInfo *ci;
    int level = opt ? luaL_optint(L, 1, 1) : luaL_checkint(L, 1);
    luaL_argcheck(L, level >= 0, 1, "level must be non-negative");
    if (level == 0) {
      lua_pushnil(L);
      return;
    }
    if (!lj_debug_getstack(L, level, &ci))
      luaL_argerror(L, 1, "invalid level");
    lua_pushtv(L, ci->func);
    if (lua_isnil(L, -1))
      luaL_error(L, "no function environment for tail call at level %d", level);
  }
}

static int lj_cf_getfenv(lua_State *L)
{
  getfunc(L, 1);
  if (lua_isnil(L, -1)) {
    lua_pushvalue(L, LUA_GLOBALSINDEX);
  } else if (lua_iscfunction(L, -1)) {
    lua_pushvalue(L, LUA_GLOBALSINDEX);
  } else {
    lua_getfenv(L, -1);
  }
  return 1;
}

static int lj_cf_setfenv(lua_State *L)
{
  luaL_checktype(L, 2, LUA_TTABLE);
  getfunc(L, 0);
  lua_pushvalue(L, 2);
  if (lua_isnumber(L, 1) && lua_tonumber(L, 1) == 0) {
    lua_pushthread(L);
    lua_insert(L, -2);
    lua_setfenv(L, -2);
    return 0;
  } else if (lua_iscfunction(L, -2) || lua_setfenv(L, -2) == 0) {
    luaL_error(L, "'setfenv' cannot change environment of given object");
  }
  return 1;
}

static int lj_cf_rawget(lua_State *L)
{
  lj_lib_checktab(L, 1);
  luaL_checkany(L, 2);
  lua_settop(L, 2);
  lua_rawget(L, 1);
  return 1;
}

static int lj_cf_rawset(lua_State *L)
{
  lj_lib_checktab(L, 1);
  luaL_checkany(L, 2);
  luaL_checkany(L, 3);
  lua_settop(L, 3);
  lua_rawset(L, 1);
  return 1;
}

static int lj_cf_rawequal(lua_State *L)
{
  luaL_checkany(L, 1);
  luaL_checkany(L, 2);
  lua_pushboolean(L, lua_rawequal(L, 1, 2));
  return 1;
}

static int lj_cf_unpack(lua_State *L)
{
  GCtab *t = lj_lib_checktab(L, 1);
  int32_t i, e, n;
  i = lj_lib_optint(L, 2, 1);
  e = lua_isnoneornil(L, 3) ? (int32_t)lj_tab_len(t) : lj_lib_checkint(L, 3);
  if (i > e) return 0;
  n = e - i + 1;
  if (n <= 0 || n >= 8000 || !lua_checkstack(L, n))
    luaL_error(L, "too many results to unpack");
  for (; i <= e; i++) {
    cTValue *v = lj_tab_getint(t, i);
    if (v) copyTV(L->top, v); else setnilV(L->top);
    L->top++;
  }
  return n;
}

static int lj_cf_select(lua_State *L)
{
  int n = lua_gettop(L);
  if (lua_type(L, 1) == LUA_TSTRING && *lua_tostring(L, 1) == '#') {
    lua_pushinteger(L, n - 1);
    return 1;
  } else {
    int32_t i = lj_lib_checkint(L, 1);
    if (i < 0) i = n + i;
    else if (i > n) i = n;
    luaL_argcheck(L, 1 <= i, 1, "index out of range");
    return n - i;
  }
}

static int lj_cf_tonumber(lua_State *L)
{
  int base = luaL_optint(L, 2, 10);
  if (base == 10) {
    TValue *o = L->base;
    luaL_checkany(L, 1);
    if (tvisnum(o)) {
      lua_settop(L, 1);
      return 1;
    }
    if (tvisstr(o)) {
      double d;
      if (lj_strscan_num(strdata(strV(o)), strV(o)->len, &d)) {
        lua_pushnumber(L, d);
        return 1;
      }
    } else if (tviscdata(o)) {
      extern int lj_ffi_tonumber(lua_State *L, cTValue *o, double *d);
      double d;
      if (lj_ffi_tonumber(L, o, &d)) {
        lua_pushnumber(L, d);
        return 1;
      }
    }
  } else {
    const char *p = luaL_checkstring(L, 1);
    char *ep;
    int neg = 0;
    unsigned long long ul;
    luaL_argcheck(L, 2 <= base && base <= 36, 2, "base out of range");
    while (isspace((unsigned char)*p)) p++;
    if (*p == '-') { p++; neg = 1; } else if (*p == '+') { p++; }
    if (isalnum((unsigned char)*p)) {
      ul = strtoull(p, &ep, base);
      if (p != ep) {
        while (isspace((unsigned char)*ep)) ep++;
        if (*ep == '\0') {
          double n = (double)ul;
          if (neg) n = -n;
          lua_pushnumber(L, n);
          return 1;
        }
      }
    }
  }
  lua_pushnil(L);
  return 1;
}

static int lj_cf_error(lua_State *L)
{
  int level = luaL_optint(L, 2, 1);
  lua_settop(L, 1);
  if (lua_isstring(L, 1) && level > 0) {
    luaL_where(L, level);
    lua_pushvalue(L, 1);
    lua_concat(L, 2);
  }
  lua_error(L);
  return 0;
}

static int lj_cf_pcall(lua_State *L)
{
  int status;
  luaL_checkany(L, 1);
  status = lua_pcall(L, lua_gettop(L) - 1, LUA_MULTRET, 0);
  lua_pushboolean(L, (status == 0));
  lua_insert(L, 1);
  return lua_gettop(L);
}

static int lj_cf_xpcall(lua_State *L)
{
  int status;
  int n = lua_gettop(L);
  luaL_checkany(L, 1);
  luaL_checkany(L, 2);
  if (!lua_isfunction(L, 2)) luaL_typerror(L, 2, "function");
  /* Rearrange: f, err, args... -> err, f, args... */
  {
    TValue f = L->base[0];
    L->base[0] = L->base[1];
    L->base[1] = f;
  }
  status = lua_pcall(L, n - 2, LUA_MULTRET, 1);
  lua_pushboolean(L, (status == 0));
  lua_replace(L, 1);
  return lua_gettop(L);
}

static int load_aux(lua_State *L, int status, int envarg)
{
  if (status == 0) {
    if (envarg && !lua_isnoneornil(L, envarg)) {
      lua_pushvalue(L, envarg);
      lua_setfenv(L, -2);
    }
    return 1;
  } else {
    lua_pushnil(L);
    lua_insert(L, -2);
    return 2;
  }
}

static int lj_cf_loadstring(lua_State *L)
{
  size_t l;
  const char *s = luaL_checklstring(L, 1, &l);
  const char *chunkname = luaL_optstring(L, 2, s);
  const char *mode = luaL_optstring(L, 3, NULL);
  return load_aux(L, luaL_loadbufferx(L, s, l, chunkname, mode), 4);
}

static const char *generic_reader(lua_State *L, void *ud, size_t *size)
{
  (void)ud;
  luaL_checkstack(L, 2, "too many nested functions");
  lua_pushvalue(L, 1);
  lua_call(L, 0, 1);
  if (lua_isnil(L, -1)) {
    lua_pop(L, 1);
    *size = 0;
    return NULL;
  } else if (lua_isstring(L, -1)) {
    lua_replace(L, 5);
    return lua_tolstring(L, 5, size);
  } else {
    luaL_error(L, "reader function must return a string");
  }
  return NULL;
}

static int lj_cf_load(lua_State *L)
{
  int status;
  if (lua_type(L, 1) == LUA_TSTRING || lua_type(L, 1) == LUA_TNUMBER) {
    return lj_cf_loadstring(L);
  } else {
    const char *cname = luaL_optstring(L, 2, "=(load)");
    const char *mode = luaL_optstring(L, 3, NULL);
    luaL_checktype(L, 1, LUA_TFUNCTION);
    lua_settop(L, 5);
    status = lua_loadx(L, generic_reader, NULL, cname, mode);
    return load_aux(L, status, 4);
  }
}

static int lj_cf_loadfile(lua_State *L)
{
  const char *fname = luaL_optstring(L, 1, NULL);
  const char *mode = luaL_optstring(L, 2, NULL);
  return load_aux(L, luaL_loadfilex(L, fname, mode), 3);
}

static int lj_cf_dofile(lua_State *L)
{
  const char *fname = luaL_optstring(L, 1, NULL);
  int n = lua_gettop(L);
  if (luaL_loadfile(L, fname) != 0) lua_error(L);
  lua_call(L, 0, LUA_MULTRET);
  return lua_gettop(L) - n;
}

static int lj_cf_gcinfo(lua_State *L)
{
  lua_pushinteger(L, lua_gc(L, LUA_GCCOUNT, 0));
  return 1;
}

static int lj_cf_collectgarbage(lua_State *L)
{
  static const char *const opts[] = {"stop", "restart", "collect",
    "count", "step", "setpause", "setstepmul", "isrunning", NULL};
  static const int optsnum[] = {LUA_GCSTOP, LUA_GCRESTART, LUA_GCCOLLECT,
    LUA_GCCOUNT, LUA_GCSTEP, LUA_GCSETPAUSE, LUA_GCSETSTEPMUL, LUA_GCISRUNNING};
  int o = luaL_checkoption(L, 1, "collect", opts);
  int ex = luaL_optint(L, 2, 0);
  int res = lua_gc(L, optsnum[o], ex);
  switch (optsnum[o]) {
  case LUA_GCCOUNT: {
    int b = lua_gc(L, LUA_GCCOUNTB, 0);
    lua_pushnumber(L, res + ((lua_Number)b / 1024));
    return 1;
  }
  case LUA_GCSTEP:
    lua_pushboolean(L, 0);
    return 1;
  case LUA_GCISRUNNING:
    lua_pushboolean(L, res);
    return 1;
  default:
    lua_pushnumber(L, res);
    return 1;
  }
}

static int lj_cf_newproxy(lua_State *L)
{
  lua_settop(L, 1);
  lua_newuserdata(L, 0);
  if (lua_toboolean(L, 1) == 0) {
    return 1;
  } else if (lua_isboolean(L, 1)) {
    lua_newtable(L);
    lua_pushvalue(L, -1);
    lua_pushboolean(L, 1);
    lua_rawset(L, lua_upvalueindex(1));
  } else {
    int validproxy = 0;
    if (lua_getmetatable(L, 1)) {
      lua_rawget(L, lua_upvalueindex(1));
      validproxy = lua_toboolean(L, -1);
      lua_pop(L, 1);
    }
    luaL_argcheck(L, validproxy, 1, "boolean or proxy expected");
    lua_getmetatable(L, 1);
  }
  lua_setmetatable(L, 2);
  return 1;
}

/* -- Coroutine library --------------------------------------------------- */

static lua_State *getco(lua_State *L)
{
  lua_State *co = lua_tothread(L, 1);
  if (!co) luaL_typerror(L, 1, "coroutine");
  return co;
}

static int lj_cf_coroutine_status(lua_State *L)
{
  lua_State *co = getco(L);
  if (co == L) lua_pushliteral(L, "running");
  else switch (co->costate) {
  case CO_SUSPENDED: lua_pushliteral(L, "suspended"); break;
  case CO_RUNNING: lua_pushliteral(L, "running"); break;
  case CO_NORMAL: lua_pushliteral(L, "normal"); break;
  default: lua_pushliteral(L, "dead"); break;
  }
  return 1;
}

static int lj_cf_coroutine_running(lua_State *L)
{
  if (lua_pushthread(L)) lua_pushnil(L);
  return 1;
}

static int lj_cf_coroutine_isyieldable(lua_State *L)
{
  lua_pushboolean(L, L->resumer != NULL);
  return 1;
}

static int lj_cf_coroutine_create(lua_State *L)
{
  lua_State *NL;
  luaL_argcheck(L, lua_isfunction(L, 1), 1, "function expected");
  NL = lj_state_new(L);
  lj_checkstack(L, 1);
  setthreadV(L->top, NL);
  L->top++;
  lua_pushvalue(L, 1);
  lua_xmove(L, NL, 1);
  return 1;
}

static int lj_cf_coroutine_yield(lua_State *L)
{
  int n = lua_gettop(L);
  return lj_co_yield(L, n);
}

static int auxresume(lua_State *L, lua_State *co, int narg)
{
  int status = lj_co_resume(L, co, narg);
  if (status == 0) {
    return co->nresume;
  }
  return -1;  /* error object on top */
}

static int lj_cf_coroutine_resume(lua_State *L)
{
  lua_State *co = getco(L);
  int r = auxresume(L, co, lua_gettop(L) - 1);
  if (r < 0) {
    lua_pushboolean(L, 0);
    lua_insert(L, -2);
    return 2;
  } else {
    lua_pushboolean(L, 1);
    lua_insert(L, -(r + 1));
    return r + 1;
  }
}

static int lj_cf_coroutine_wrap_aux(lua_State *L)
{
  lua_State *co = lua_tothread(L, lua_upvalueindex(1));
  int r = auxresume(L, co, lua_gettop(L));
  if (r < 0) {
    lua_error(L);
  }
  return r;
}

static int lj_cf_coroutine_wrap(lua_State *L)
{
  lj_cf_coroutine_create(L);
  lj_lib_pushcc(L, lj_cf_coroutine_wrap_aux, 36, 1);
  return 1;
}

/* -- Registration ------------------------------------------------------------ */

int luaopen_base(lua_State *L)
{
  GCtab *g = L->env;
  TValue gv;
  settabV(&gv, g);
  /* _G */
  lua_pushtv(L, &gv);
  lua_setglobal(L, "_G");
  /* Register functions in order of their builtin ids. */
  lj_lib_pushcf(L, lj_cf_assert, 2); lua_setglobal(L, "assert");
  lj_lib_pushcf(L, lj_cf_type, 3); lua_setglobal(L, "type");
  lj_lib_pushcf(L, lj_cf_next, 4); lua_setglobal(L, "next");
  lua_getglobal(L, "next");
  lj_lib_pushcc(L, lj_cf_pairs, 5, 1); lua_setglobal(L, "pairs");
  lj_lib_pushcf(L, lj_cf_ipairs_aux, 6);
  lj_lib_pushcc(L, lj_cf_ipairs, 7, 1); lua_setglobal(L, "ipairs");
  lj_lib_pushcf(L, lj_cf_getmetatable, 8); lua_setglobal(L, "getmetatable");
  lj_lib_pushcf(L, lj_cf_setmetatable, 9); lua_setglobal(L, "setmetatable");
  lj_lib_pushcf(L, lj_cf_getfenv, 10); lua_setglobal(L, "getfenv");
  lj_lib_pushcf(L, lj_cf_setfenv, 11); lua_setglobal(L, "setfenv");
  lj_lib_pushcf(L, lj_cf_rawget, 12); lua_setglobal(L, "rawget");
  lj_lib_pushcf(L, lj_cf_rawset, 13); lua_setglobal(L, "rawset");
  lj_lib_pushcf(L, lj_cf_rawequal, 14); lua_setglobal(L, "rawequal");
  lj_lib_pushcf(L, lj_cf_unpack, 15); lua_setglobal(L, "unpack");
  lj_lib_pushcf(L, lj_cf_select, 16); lua_setglobal(L, "select");
  lj_lib_pushcf(L, lj_cf_tonumber, 17); lua_setglobal(L, "tonumber");
  lj_lib_pushcf(L, lj_cf_tostring, 18);
  tostring_builtin = funcV(L->top - 1);
  lua_setglobal(L, "tostring");
  lj_lib_pushcf(L, lj_cf_error, 19); lua_setglobal(L, "error");
  lj_lib_pushcf(L, lj_cf_pcall, 20); lua_setglobal(L, "pcall");
  lj_lib_pushcf(L, lj_cf_xpcall, 21); lua_setglobal(L, "xpcall");
  lj_lib_pushcf(L, lj_cf_loadfile, 22); lua_setglobal(L, "loadfile");
  lj_lib_pushcf(L, lj_cf_load, 23); lua_setglobal(L, "load");
  lj_lib_pushcf(L, lj_cf_loadstring, 24); lua_setglobal(L, "loadstring");
  lj_lib_pushcf(L, lj_cf_dofile, 25); lua_setglobal(L, "dofile");
  lj_lib_pushcf(L, lj_cf_gcinfo, 26); lua_setglobal(L, "gcinfo");
  lj_lib_pushcf(L, lj_cf_collectgarbage, 27); lua_setglobal(L, "collectgarbage");
  /* newproxy needs a weak table upvalue. */
  lua_createtable(L, 0, 1);
  lua_pushvalue(L, -1);
  lua_setmetatable(L, -2);
  lua_pushliteral(L, "kv");
  lua_setfield(L, -2, "__mode");
  lj_lib_pushcc(L, lj_cf_newproxy, 28, 1); lua_setglobal(L, "newproxy");
  lj_lib_pushcf(L, lj_cf_print, 29); lua_setglobal(L, "print");
  lua_pushliteral(L, "Lua 5.1");
  lua_setglobal(L, "_VERSION");
  /* Coroutine library. */
  {
    static const LJLibReg co_funcs[] = {
      {"status", lj_cf_coroutine_status, 30},
      {"running", lj_cf_coroutine_running, 31},
      {"isyieldable", lj_cf_coroutine_isyieldable, 32},
      {"create", lj_cf_coroutine_create, 33},
