/* -- Pattern matching ------------------------------------------------------ */

#define CAP_UNFINISHED (-1)
#define CAP_POSITION (-2)
#define LUA_MAXCAPTURES 32
#define L_ESC '%'
#define SPECIALS "^$*+?.([%-"
#define MAXCCALLS 200

typedef struct MatchState {
  const char *src_init;
  const char *src_end;
  lua_State *L;
  int level;
  int depth;
  struct {
    const char *init;
    ptrdiff_t len;
  } capture[LUA_MAXCAPTURES];
} MatchState;

static int check_capture(MatchState *ms, int l)
{
  l -= '1';
  if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNFINISHED)
    lj_err_callermsg(ms->L, "invalid capture index");
  return l;
}

static int capture_to_close(MatchState *ms)
{
  int level = ms->level;
  for (level--; level >= 0; level--)
    if (ms->capture[level].len == CAP_UNFINISHED) return level;
  lj_err_callermsg(ms->L, "invalid pattern capture");
  return 0;
}

static const char *classend(MatchState *ms, const char *p)
{
  switch (*p++) {
  case L_ESC:
    if (*p == '\0')
      lj_err_callermsg(ms->L, "malformed pattern (ends with '%')");
    return p + 1;
  case '[':
    if (*p == '^') p++;
    do {
      if (*p == '\0')
        lj_err_callermsg(ms->L, "malformed pattern (missing ']')");
      if (*(p++) == L_ESC && *p != '\0')
        p++;
    } while (*p != ']');
    return p + 1;
  default:
    return p;
  }
}

static int match_class(int c, int cl)
{
  int res;
  switch (tolower(cl)) {
  case 'a': res = isalpha(c); break;
  case 'c': res = iscntrl(c); break;
  case 'd': res = isdigit(c); break;
  case 'g': res = isgraph(c); break;
  case 'l': res = islower(c); break;
  case 'p': res = ispunct(c); break;
  case 's': res = isspace(c); break;
  case 'u': res = isupper(c); break;
  case 'w': res = isalnum(c); break;
  case 'x': res = isxdigit(c); break;
  case 'z': res = (c == 0); break;
  default: return (cl == c);
  }
  if (isupper(cl)) res = !res;
  return res;
}

static int matchbracketclass(int c, const char *p, const char *ec)
{
  int sig = 1;
  if (*(p + 1) == '^') {
    sig = 0;
    p++;
  }
  while (++p < ec) {
    if (*p == L_ESC) {
      p++;
      if (match_class(c, (unsigned char)*p))
        return sig;
    } else if ((*(p + 1) == '-') && (p + 2 < ec)) {
      p += 2;
      if ((unsigned char)*(p - 2) <= c && c <= (unsigned char)*p)
        return sig;
    } else if ((unsigned char)*p == c) {
      return sig;
    }
  }
  return !sig;
}

static int singlematch(int c, const char *p, const char *ep)
{
  switch (*p) {
  case '.': return 1;
  case L_ESC: return match_class(c, (unsigned char)*(p + 1));
  case '[': return matchbracketclass(c, p, ep - 1);
  default: return ((unsigned char)*p == c);
  }
}

static const char *match(MatchState *ms, const char *s, const char *p);

static const char *matchbalance(MatchState *ms, const char *s, const char *p)
{
  if (*p == 0 || *(p + 1) == 0)
    lj_err_callermsg(ms->L, "unbalanced pattern");
  if (*s != *p) return NULL;
  else {
    int b = *p;
    int e = *(p + 1);
    int cont = 1;
    while (++s < ms->src_end) {
      if (*s == e) {
        if (--cont == 0) return s + 1;
      } else if (*s == b) {
        cont++;
      }
    }
  }
  return NULL;
}

static const char *max_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{
  ptrdiff_t i = 0;
  while ((s + i) < ms->src_end && singlematch((unsigned char)*(s + i), p, ep))
    i++;
  while (i >= 0) {
    const char *res = match(ms, (s + i), ep + 1);
    if (res) return res;
    i--;
  }
  return NULL;
}

static const char *min_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{
  for (;;) {
    const char *res = match(ms, s, ep + 1);
    if (res != NULL)
      return res;
    else if (s < ms->src_end && singlematch((unsigned char)*s, p, ep))
      s++;
    else
      return NULL;
  }
}

static const char *start_capture(MatchState *ms, const char *s, const char *p, int what)
{
  const char *res;
  int level = ms->level;
  if (level >= LUA_MAXCAPTURES) lj_err_callermsg(ms->L, "too many captures");
  ms->capture[level].init = s;
  ms->capture[level].len = what;
  ms->level = level + 1;
  if ((res = match(ms, s, p)) == NULL)
    ms->level--;
  return res;
}

static const char *end_capture(MatchState *ms, const char *s, const char *p)
{
  int l = capture_to_close(ms);
  const char *res;
  ms->capture[l].len = s - ms->capture[l].init;
  if ((res = match(ms, s, p)) == NULL)
    ms->capture[l].len = CAP_UNFINISHED;
  return res;
}

static const char *match_capture(MatchState *ms, const char *s, int l)
{
  size_t len;
  l = check_capture(ms, l);
  len = (size_t)ms->capture[l].len;
  if ((size_t)(ms->src_end - s) >= len &&
      memcmp(ms->capture[l].init, s, len) == 0)
    return s + len;
  return NULL;
}

static const char *match(MatchState *ms, const char *s, const char *p)
{
  if (++ms->depth > MAXCCALLS * 50)
    lj_err_callermsg(ms->L, "pattern too complex");
init:
  switch (*p) {
  case '(': {
    const char *r;
    if (*(p + 1) == ')')
      r = start_capture(ms, s, p + 2, CAP_POSITION);
    else
      r = start_capture(ms, s, p + 1, CAP_UNFINISHED);
    ms->depth--;
    return r;
  }
  case ')': {
    const char *r = end_capture(ms, s, p + 1);
    ms->depth--;
    return r;
  }
  case L_ESC: {
    switch (*(p + 1)) {
    case 'b': {
      s = matchbalance(ms, s, p + 2);
      if (s == NULL) break;
      p += 4;
      goto init;
    }
    case 'f': {
      const char *ep;
      int previous;
      p += 2;
      if (*p != '[')
        lj_err_callermsg(ms->L, "missing '[' after '%f' in pattern");
      ep = classend(ms, p);
      previous = (s == ms->src_init) ? '\0' : (unsigned char)*(s - 1);
      if (matchbracketclass(previous, p, ep - 1) ||
          !matchbracketclass((s < ms->src_end) ? (unsigned char)*s : '\0', p, ep - 1)) {
        s = NULL;
        break;
      }
      p = ep;
      goto init;
    }
    default: {
      if (isdigit((unsigned char)*(p + 1))) {
        s = match_capture(ms, s, (unsigned char)*(p + 1));
        if (s == NULL) break;
        p += 2;
        goto init;
      }
      goto dflt;
    }
    }
    break;
  }
  case '\0':
    break;
  case '$': {
    if (*(p + 1) == '\0') {
      if (s != ms->src_end) s = NULL;
      break;
    }
    goto dflt;
  }
  default:
  dflt: {
    const char *ep = classend(ms, p);
    int m = s < ms->src_end && singlematch((unsigned char)*s, p, ep);
    switch (*ep) {
    case '?': {
      const char *res;
      if (m && ((res = match(ms, s + 1, ep + 1)) != NULL)) {
        s = res;
        break;
      }
      p = ep + 1;
      goto init;
    }
    case '*':
      s = max_expand(ms, s, p, ep);
      break;
    case '+':
      s = (m ? max_expand(ms, s + 1, p, ep) : NULL);
      break;
    case '-':
      s = min_expand(ms, s, p, ep);
      break;
    default:
      if (!m) {
        s = NULL;
        break;
      }
      s++;
      p = ep;
      goto init;
    }
    break;
  }
  }
  ms->depth--;
  return s;
}

static const char *lmemfind(const char *s1, size_t l1, const char *s2, size_t l2)
{
  if (l2 == 0) return s1;
  else if (l2 > l1) return NULL;
  else {
    const char *init;
    l2--;
    l1 = l1 - l2;
    while (l1 > 0 && (init = (const char *)memchr(s1, *s2, l1)) != NULL) {
      init++;
      if (memcmp(init, s2 + 1, l2) == 0)
        return init - 1;
      else {
        l1 -= (size_t)(init - s1);
        s1 = init;
      }
    }
    return NULL;
  }
}

static void push_onecapture(MatchState *ms, int i, const char *s, const char *e)
{
  if (i >= ms->level) {
    if (i == 0)
      lua_pushlstring(ms->L, s, (size_t)(e - s));
    else
      lj_err_callermsg(ms->L, "invalid capture index");
  } else {
    ptrdiff_t l = ms->capture[i].len;
    if (l == CAP_UNFINISHED) lj_err_callermsg(ms->L, "unfinished capture");
    if (l == CAP_POSITION)
      lua_pushinteger(ms->L, ms->capture[i].init - ms->src_init + 1);
    else
      lua_pushlstring(ms->L, ms->capture[i].init, (size_t)l);
  }
}

static int push_captures(MatchState *ms, const char *s, const char *e)
{
  int i;
  int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  luaL_checkstack(ms->L, nlevels, "too many captures");
  for (i = 0; i < nlevels; i++)
    push_onecapture(ms, i, s, e);
  return nlevels;
}

static int has_specials(const char *p, size_t l)
{
  size_t i;
  for (i = 0; i < l; i++)
    if (strchr(SPECIALS, p[i])) return 1;
  return 0;
}

static int str_find_aux(lua_State *L, int find)
{
  GCstr *ss = lj_lib_checkstr(L, 1);
  GCstr *ps = lj_lib_checkstr(L, 2);
  size_t l1 = ss->len, l2 = ps->len;
  const char *s = strdata(ss), *p = strdata(ps);
  int32_t init = posrelat(lj_lib_optint(L, 3, 1), l1) - 1;
  if (init < 0) init = 0;
  else if ((size_t)init > l1) init = (int32_t)l1;
  if (find && (lua_toboolean(L, 4) || !has_specials(p, l2))) {
    const char *s2 = lmemfind(s + init, l1 - (size_t)init, p, l2);
    if (s2) {
      lua_pushinteger(L, s2 - s + 1);
      lua_pushinteger(L, (lua_Integer)(s2 - s + l2));
      return 2;
    }
  } else {
    MatchState ms;
    int anchor = (*p == '^') ? (p++, 1) : 0;
    const char *s1 = s + init;
    ms.L = L;
    ms.src_init = s;
    ms.src_end = s + l1;
    do {
      const char *res;
      ms.level = 0;
      ms.depth = 0;
      if ((res = match(&ms, s1, p)) != NULL) {
        if (find) {
          lua_pushinteger(L, s1 - s + 1);
          lua_pushinteger(L, res - s);
          return push_captures(&ms, NULL, 0) + 2;
        } else {
          return push_captures(&ms, s1, res);
        }
      }
    } while (s1++ < ms.src_end && !anchor);
  }
  lua_pushnil(L);
  return 1;
}

static int str_find(lua_State *L) { return str_find_aux(L, 1); }
static int str_match(lua_State *L) { return str_find_aux(L, 0); }

static int gmatch_aux(lua_State *L)
{
  MatchState ms;
  size_t ls;
  const char *s = lua_tolstring(L, lua_upvalueindex(1), &ls);
  const char *p = lua_tostring(L, lua_upvalueindex(2));
  const char *src;
  ms.L = L;
  ms.src_init = s;
  ms.src_end = s + ls;
  for (src = s + (size_t)lua_tointeger(L, lua_upvalueindex(3)); src <= ms.src_end; src++) {
    const char *e;
    ms.level = 0;
    ms.depth = 0;
    if ((e = match(&ms, src, p)) != NULL) {
      lua_Integer newstart = e - s;
      if (e == src) newstart++;
      lua_pushinteger(L, newstart);
      lua_replace(L, lua_upvalueindex(3));
      return push_captures(&ms, src, e);
    }
  }
  return 0;
}

static int str_gmatch(lua_State *L)
{
  lj_lib_checkstr(L, 1);
  lj_lib_checkstr(L, 2);
  lua_settop(L, 2);
  lua_pushinteger(L, 0);
  lj_lib_pushcc(L, gmatch_aux, 86, 3);
  return 1;
}

static void add_s(MatchState *ms, luaL_Buffer *b, const char *s, const char *e)
{
  size_t l, i;
  const char *news = lua_tolstring(ms->L, 3, &l);
  for (i = 0; i < l; i++) {
    if (news[i] != L_ESC) {
      luaL_addchar(b, news[i]);
    } else {
      i++;
      if (!isdigit((unsigned char)news[i])) {
        luaL_addchar(b, news[i]);
      } else if (news[i] == '0') {
        luaL_addlstring(b, s, (size_t)(e - s));
      } else {
        push_onecapture(ms, news[i] - '1', s, e);
        luaL_addvalue(b);
      }
    }
  }
}

static void add_value(MatchState *ms, luaL_Buffer *b, const char *s, const char *e)
{
  lua_State *L = ms->L;
  switch (lua_type(L, 3)) {
  case LUA_TNUMBER:
  case LUA_TSTRING: {
    add_s(ms, b, s, e);
    return;
  }
  case LUA_TFUNCTION: {
    int n;
    lua_pushvalue(L, 3);
    n = push_captures(ms, s, e);
    lua_call(L, n, 1);
    break;
  }
  case LUA_TTABLE: {
    push_onecapture(ms, 0, s, e);
    lua_gettable(L, 3);
    break;
  }
  }
  if (!lua_toboolean(L, -1)) {
    lua_pop(L, 1);
    lua_pushlstring(L, s, (size_t)(e - s));
  } else if (!lua_isstring(L, -1)) {
    luaL_bufffree(b);
    luaL_error(L, "invalid replacement value (a %s)", luaL_typename(L, -1));
  }
  luaL_addvalue(b);
}

static int str_gsub(lua_State *L)
{
  GCstr *ss = lj_lib_checkstr(L, 1);
  GCstr *ps = lj_lib_checkstr(L, 2);
  const char *src = strdata(ss);
  size_t srcl = ss->len;
  const char *p = strdata(ps);
  int tr = lua_type(L, 3);
  int32_t max_s = lj_lib_optint(L, 4, (int32_t)(srcl + 1));
  int anchor = (*p == '^') ? (p++, 1) : 0;
  int32_t n = 0;
  MatchState ms;
  luaL_Buffer b;
  if (!(tr == LUA_TNUMBER || tr == LUA_TSTRING || tr == LUA_TFUNCTION || tr == LUA_TTABLE))
    lj_err_argtype(L, 3, "string/function/table");
  if (tr == LUA_TNUMBER) lj_lib_checkstr(L, 3);
  luaL_buffinit(L, &b);
  ms.L = L;
  ms.src_init = src;
  ms.src_end = src + srcl;
  while (n < max_s) {
    const char *e;
    ms.level = 0;
    ms.depth = 0;
    e = match(&ms, src, p);
    if (e) {
      n++;
      add_value(&ms, &b, src, e);
    }
    if (e && e > src)
      src = e;
    else if (src < ms.src_end)
      luaL_addchar(&b, *src++);
    else
      break;
    if (anchor) break;
  }
  luaL_addlstring(&b, src, (size_t)(ms.src_end - src));
  luaL_pushresult(&b);
  lua_pushinteger(L, n);
  return 2;
}

/* -- Format -------------------------------------------------------------- */

static void addquoted(luaL_Buffer *b, GCstr *str)
{
  size_t l = str->len;
  const char *s = strdata(str);
  luaL_addchar(b, '"');
  while (l--) {
    unsigned char c = (unsigned char)*s;
    if (c == '"' || c == '\\' || c == '\n') {
      luaL_addchar(b, '\\');
      luaL_addchar(b, c);
    } else if (c < 32 || c == 127) {
      char buf[8];
      if (l > 0 && isdigit((unsigned char)s[1]))
        snprintf(buf, sizeof(buf), "\\%03d", c);
      else
        snprintf(buf, sizeof(buf), "\\%d", c);
      luaL_addstring(b, buf);
    } else {
      luaL_addchar(b, c);
    }
    s++;
  }
  luaL_addchar(b, '"');
}

#define FMT_FLAGS "-+ #0"

static int str_format(lua_State *L)
{
  int arg = 1, top = lua_gettop(L);
  GCstr *fs = lj_lib_checkstr(L, 1);
  const char *strfrmt = strdata(fs);
  const char *strfrmt_end = strfrmt + fs->len;
  luaL_Buffer b;
  luaL_buffinit(L, &b);
  while (strfrmt < strfrmt_end) {
    if (*strfrmt != '%') {
      luaL_addchar(&b, *strfrmt++);
    } else if (*++strfrmt == '%') {
      luaL_addchar(&b, *strfrmt++);
    } else {
      char form[40];
      char buff[512];
      const char *p = strfrmt;
      char *f = form;
      int nwidth = 0, nprec = 0;
      *f++ = '%';
      while (*p != '\0' && strchr(FMT_FLAGS, *p) != NULL && (f - form) < 10) *f++ = *p++;
      while (isdigit((unsigned char)*p)) { if (++nwidth > 2) { *f++ = *p++; goto badopt; } *f++ = *p++; }
      if (*p == '.') {
        *f++ = *p++;
        while (isdigit((unsigned char)*p)) { if (++nprec > 2) { *f++ = *p++; goto badopt; } *f++ = *p++; }
      }
      if (0) {
      badopt:
        *f = '\0';
        luaL_bufffree(&b);
        luaL_error(L, "invalid option '%s' to 'format'", form);
      }
      *f = '\0';
      strfrmt = p;
      if (++arg > top && *p != '\0') {
        if (strchr("diouxXcaAeEfFgGqs", *p)) {
          luaL_bufffree(&b);
          luaL_argerror(L, arg, "value expected");
        }
      }
      switch (*strfrmt++) {
      case 'c': {
        size_t fl = strlen(form);
        form[fl] = 'c'; form[fl + 1] = 0;
        snprintf(buff, sizeof(buff), form, (int)lj_lib_checkint(L, arg));
        luaL_addlstring(&b, buff, strlen(buff) + ((int)lj_lib_checkint(L, arg) == 0 && nwidth == 0 ? 1 : 0));
        break;
      }
      case 'd': case 'i': {
        size_t fl = strlen(form);
        double n = lj_lib_checknum(L, arg);
        int64_t v = lj_num2i64(n);
        form[fl] = 'l'; form[fl + 1] = 'l'; form[fl + 2] = 'd'; form[fl + 3] = 0;
        snprintf(buff, sizeof(buff), form, (long long)v);
        luaL_addstring(&b, buff);
        break;
      }
      case 'o': case 'u': case 'x': case 'X': {
        size_t fl = strlen(form);
        double n = lj_lib_checknum(L, arg);
        uint64_t v;
        if (n >= 9223372036854775808.0 && n < 18446744073709551616.0) v = (uint64_t)n;
        else v = (uint64_t)lj_num2i64(n);
        form[fl] = 'l'; form[fl + 1] = 'l'; form[fl + 2] = strfrmt[-1]; form[fl + 3] = 0;
        snprintf(buff, sizeof(buff), form, (unsigned long long)v);
        luaL_addstring(&b, buff);
        break;
      }
      case 'e': case 'E': case 'f': case 'F': case 'g': case 'G': case 'a': case 'A': {
        size_t fl = strlen(form);
        double n = lj_lib_checknum(L, arg);
        if (n != n) {
          /* Canonical NaN output. */
          char sform[40];
          size_t i, j = 0;
          for (i = 0; i < fl; i++) {
            char c = form[i];
            if (c == '.') {
              while (i + 1 < fl && isdigit((unsigned char)form[i + 1])) i++;
              continue;
            }
            if (c == '0' && j > 0 && strchr(FMT_FLAGS, sform[j - 1])) continue;
            if (c == '0' && j == 1) continue;
            if (c == '#' || c == '+' || c == ' ') continue;
            sform[j++] = c;
          }
          sform[j++] = 's'; sform[j] = 0;
          snprintf(buff, sizeof(buff), sform, (strfrmt[-1] >= 'a') ? "nan" : "NAN");
        } else {
          form[fl] = strfrmt[-1]; form[fl + 1] = 0;
          snprintf(buff, sizeof(buff), form, n);
        }
        luaL_addstring(&b, buff);
        break;
      }
      case 'q': {
        GCstr *s = lj_lib_checkstr(L, arg);
        addquoted(&b, s);
        continue;
      }
      case 's': {
        size_t l;
        const char *s;
        lj_tostring_push(L, arg);
        s = lua_tolstring(L, -1, &l);
        if (s == NULL) {
          luaL_bufffree(&b);
          luaL_error(L, "'tostring' must return a string to 'format'");
        }
        if (!strchr(form, '.') && l >= 100) {
          luaL_addlstring(&b, s, l);
        } else if (strlen(form) == 1) {
          luaL_addlstring(&b, s, l);
        } else {
          size_t fl = strlen(form);
          char *big;
          size_t need = l + 128;
          form[fl] = 's'; form[fl + 1] = 0;
          big = (char *)malloc(need);
          snprintf(big, need, form, s);
          luaL_addstring(&b, big);
          free(big);
        }
        lua_pop(L, 1);
        break;
      }
      default: {
        size_t fl = strlen(form);
        if (strfrmt[-1] != '\0') { form[fl] = strfrmt[-1]; form[fl + 1] = 0; }
        else strfrmt--;
        luaL_bufffree(&b);
        luaL_error(L, "invalid option '%s' to 'format'", form);
      }
      }
    }
  }
  luaL_pushresult(&b);
  return 1;
}

int luaopen_string(lua_State *L)
{
  static const LJLibReg funcs[] = {
    {"len", str_len, 0},
    {"byte", str_byte, 76},
    {"char", str_char, 77},
    {"sub", str_sub, 78},
    {"rep", str_rep, 79},
    {"reverse", str_reverse, 80},
    {"lower", str_lower, 81},
    {"upper", str_upper, 82},
    {"dump", str_dump, 83},
    {"find", str_find, 84},
    {"match", str_match, 85},
    {"gmatch", str_gmatch, 87},
    {"gsub", str_gsub, 88},
    {"format", str_format, 89},
    {NULL, NULL, 0}
  };
  lj_lib_register(L, "string", funcs);
  /* String metatable. */
  lua_createtable(L, 0, 1);
  lua_pushvalue(L, -2);
  lua_setfield(L, -2, "__index");
  G(L)->strmt = tabV(L->top - 1);
  G(L)->basemt[LJ_TSTR] = G(L)->strmt;
  lua_pop(L, 1);
  return 1;
}
