/* String library. */
#include <ctype.h>
#include "lj.h"
#include "lj_api.h"

static int32_t posrelat(int32_t pos, size_t len)
{
  if (pos < 0) pos += (int32_t)len + 1;
  return (pos >= 0) ? pos : 0;
}

static int str_len(lua_State *L)
{
  GCstr *s;
  TValue *o = L->base;
  if (o < L->top && (tvisstr(o) || tvisnum(o))) {
    s = lj_lib_checkstr(L, 1);
  } else {
    if (o >= L->top) { lua_pushnil(L); }
    luaL_typerror(L, 1, "string");
  }
  lua_pushinteger(L, (lua_Integer)s->len);
  return 1;
}

static int str_sub(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  size_t l = s->len;
  int32_t start = posrelat(lj_lib_checkint(L, 2), l);
  int32_t end = posrelat(lj_lib_optint(L, 3, -1), l);
  if (start < 1) start = 1;
  if ((size_t)end > l) end = (int32_t)l;
  if (start <= end)
    lua_pushlstring(L, strdata(s) + start - 1, (size_t)(end - start + 1));
  else
    lua_pushliteral(L, "");
  return 1;
}

static int str_reverse(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  size_t l = s->len, i;
  char *buf = (char *)malloc(l ? l : 1);
  for (i = 0; i < l; i++) buf[i] = strdata(s)[l - 1 - i];
  lua_pushlstring(L, buf, l);
  free(buf);
  return 1;
}

static int str_lower(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  size_t l = s->len, i;
  char *buf = (char *)malloc(l ? l : 1);
  for (i = 0; i < l; i++) {
    unsigned char c = (unsigned char)strdata(s)[i];
    buf[i] = (char)((c >= 'A' && c <= 'Z') ? c + 32 : c);
  }
  lua_pushlstring(L, buf, l);
  free(buf);
  return 1;
}

static int str_upper(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  size_t l = s->len, i;
  char *buf = (char *)malloc(l ? l : 1);
  for (i = 0; i < l; i++) {
    unsigned char c = (unsigned char)strdata(s)[i];
    buf[i] = (char)((c >= 'a' && c <= 'z') ? c - 32 : c);
  }
  lua_pushlstring(L, buf, l);
  free(buf);
  return 1;
}

static int str_rep(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  int32_t k = lj_lib_checkint(L, 2);
  GCstr *sep = lj_lib_optstr(L, 3);
  size_t len = s->len, seplen = sep ? sep->len : 0;
  size_t tot;
  char *buf, *p;
  int32_t i;
  if (k <= 0) {
    lua_pushliteral(L, "");
    return 1;
  }
  tot = len * (size_t)k + seplen * (size_t)(k - 1);
  if (len != 0 && tot / len < (size_t)k / 2) luaL_error(L, "not enough memory");
  if (tot >= 0x7fffff00u) lj_err_msg(L, "not enough memory");
  if (tot == 0) {
    lua_pushliteral(L, "");
    return 1;
  }
  buf = (char *)malloc(tot);
  if (!buf) lj_err_throw(L, LUA_ERRMEM);
  p = buf;
  for (i = 0; i < k; i++) {
    memcpy(p, strdata(s), len); p += len;
    if (sep && i < k - 1) { memcpy(p, strdata(sep), seplen); p += seplen; }
  }
  lua_pushlstring(L, buf, tot);
  free(buf);
  return 1;
}

static int str_byte(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  size_t l = s->len;
  int32_t posi = posrelat(lj_lib_optint(L, 2, 1), l);
  int32_t pose = posrelat(lj_lib_optint(L, 3, posi), l);
  int n, i;
  if (posi <= 0) posi = 1;
  if ((size_t)pose > l) pose = (int32_t)l;
  if (posi > pose) return 0;
  n = (int)(pose - posi + 1);
  if (posi + n <= pose || !lua_checkstack(L, n))
    luaL_error(L, "string slice too long");
  for (i = 0; i < n; i++)
    lua_pushinteger(L, (unsigned char)strdata(s)[posi + i - 1]);
  return n;
}

static int str_char(lua_State *L)
{
  int n = lua_gettop(L);
  int i;
  char *buf = (char *)malloc(n ? (size_t)n : 1);
  for (i = 1; i <= n; i++) {
    int32_t c = lj_lib_checkint(L, i);
    if ((uint32_t)c > 255) {
      free(buf);
      luaL_argerror(L, i, "invalid value");
    }
    buf[i - 1] = (char)c;
  }
  lua_pushlstring(L, buf, (size_t)n);
  free(buf);
  return 1;
}

extern int lj_bcdump(lua_State *L, GCproto *pt, luaL_Buffer *b, int strip);

static int str_dump(lua_State *L)
{
  GCfunc *fn;
  int strip;
  luaL_Buffer b;
  if (!(L->base < L->top && tvisfunc(L->base))) lj_err_argt(L, 1, LJ_TFUNC);
  fn = funcV(L->base);
  strip = L->base + 1 < L->top && lua_toboolean(L, 2);
  if (fn->isC) luaL_error(L, "unable to dump given function");
  luaL_buffinit(L, &b);
  lj_bcdump(L, fn->u.l.pt, &b, strip);
  luaL_pushresult(&b);
  return 1;
}

/* -- Pattern matching ------------------------------------------------------ */

#define CAP_UNFINISHED (-1)
#define CAP_POSITION (-2)
#define LUA_MAXCAPTURES 32
#define L_ESC '%'
#define SPECIALS "^$*+?.([%-"
#define MAXCCALLS 200

typedef struct MatchState {
  const char *src_init;
  const char *src_end;
  lua_State *L;
  int level;
  int depth;
  struct {
    const char *init;
    ptrdiff_t len;
  } capture[LUA_MAXCAPTURES];
} MatchState;

static int check_capture(MatchState *ms, int l)
{
  l -= '1';
  if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNFINISHED)
    lj_err_callermsg(ms->L, "invalid capture index");
  return l;
}

static int capture_to_close(MatchState *ms)
{
  int level = ms->level;
  for (level--; level >= 0; level--)
    if (ms->capture[level].len == CAP_UNFINISHED) return level;
  lj_err_callermsg(ms->L, "invalid pattern capture");
  return 0;
}

static const char *classend(MatchState *ms, const char *p)
{
  switch (*p++) {
  case L_ESC:
    if (*p == '\0')
      lj_err_callermsg(ms->L, "malformed pattern (ends with '%')");
    return p + 1;
  case '[':
    if (*p == '^') p++;
    do {
      if (*p == '\0')
        lj_err_callermsg(ms->L, "malformed pattern (missing ']')");
      if (*(p++) == L_ESC && *p != '\0')
        p++;
    } while (*p != ']');
    return p + 1;
  default:
    return p;
  }
}

static int match_class(int c, int cl)
{
  int res;
  switch (tolower(cl)) {
  case 'a': res = isalpha(c); break;
  case 'c': res = iscntrl(c); break;
  case 'd': res = isdigit(c); break;
  case 'g': res = isgraph(c); break;
  case 'l': res = islower(c); break;
  case 'p': res = ispunct(c); break;
  case 's': res = isspace(c); break;
  case 'u': res = isupper(c); break;
  case 'w': res = isalnum(c); break;
  case 'x': res = isxdigit(c); break;
  case 'z': res = (c == 0); break;
  default: return (cl == c);
  }
  if (isupper(cl)) res = !res;
  return res;
}

static int matchbracketclass(int c, const char *p, const char *ec)
{
  int sig = 1;
  if (*(p + 1) == '^') {
    sig = 0;
    p++;
  }
  while (++p < ec) {
    if (*p == L_ESC) {
      p++;
      if (match_class(c, (unsigned char)*p))
        return sig;
    } else if ((*(p + 1) == '-') && (p + 2 < ec)) {
      p += 2;
      if ((unsigned char)*(p - 2) <= c && c <= (unsigned char)*p)
        return sig;
    } else if ((unsigned char)*p == c) {
      return sig;
    }
  }
  return !sig;
}

static int singlematch(int c, const char *p, const char *ep)
{
  switch (*p) {
  case '.': return 1;
  case L_ESC: return match_class(c, (unsigned char)*(p + 1));
  case '[': return matchbracketclass(c, p, ep - 1);
  default: return ((unsigned char)*p == c);
  }
}

static const char *match(MatchState *ms, const char *s, const char *p);

static const char *matchbalance(MatchState *ms, const char *s, const char *p)
{
  if (*p == 0 || *(p + 1) == 0)
    lj_err_callermsg(ms->L, "unbalanced pattern");
  if (*s != *p) return NULL;
  else {
    int b = *p;
    int e = *(p + 1);
    int cont = 1;
    while (++s < ms->src_end) {
      if (*s == e) {
        if (--cont == 0) return s + 1;
      } else if (*s == b) {
        cont++;
      }
    }
  }
  return NULL;
}

static const char *max_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{
  ptrdiff_t i = 0;
  while ((s + i) < ms->src_end && singlematch((unsigned char)*(s + i), p, ep))
    i++;
  while (i >= 0) {
    const char *res = match(ms, (s + i), ep + 1);
    if (res) return res;
    i--;
  }
  return NULL;
}

static const char *min_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{
  for (;;) {
    const char *res = match(ms, s, ep + 1);
    if (res != NULL)
      return res;
    else if (s < ms->src_end && singlematch((unsigned char)*s, p, ep))
      s++;
    else
      return NULL;
  }
}

static const char *start_capture(MatchState *ms, const char *s, const char *p, int what)
{
  const char *res;
  int level = ms->level;
  if (level >= LUA_MAXCAPTURES) lj_err_callermsg(ms->L, "too many captures");
  ms->capture[level].init = s;
  ms->capture[level].len = what;
  ms->level = level + 1;
  if ((res = match(ms, s, p)) == NULL)
    ms->level--;
  return res;
}

static const char *end_capture(MatchState *ms, const char *s, const char *p)
{
  int l = capture_to_close(ms);
  const char *res;
  ms->capture[l].len = s - ms->capture[l].init;
  if ((res = match(ms, s, p)) == NULL)
    ms->capture[l].len = CAP_UNFINISHED;
  return res;
}

static const char *match_capture(MatchState *ms, const char *s, int l)
{
  size_t len;
  l = check_capture(ms, l);
  len = (size_t)ms->capture[l].len;
  if ((size_t)(ms->src_end - s) >= len &&
      memcmp(ms->capture[l].init, s, len) == 0)
    return s + len;
  return NULL;
}

static const char *match(MatchState *ms, const char *s, const char *p)
{
  if (++ms->depth > MAXCCALLS * 50)
    lj_err_callermsg(ms->L, "pattern too complex");
init:
  switch (*p) {
  case '(': {
    const char *r;
    if (*(p + 1) == ')')
      r = start_capture(ms, s, p + 2, CAP_POSITION);
    else
      r = start_capture(ms, s, p + 1, CAP_UNFINISHED);
    ms->depth--;
    return r;
  }
  case ')': {
    const char *r = end_capture(ms, s, p + 1);
    ms->depth--;
    return r;
  }
  case L_ESC: {
    switch (*(p + 1)) {
    case 'b': {
      s = matchbalance(ms, s, p + 2);
      if (s == NULL) break;
      p += 4;
      goto init;
    }
    case 'f': {
      const char *ep;
      int previous;
      p += 2;
      if (*p != '[')
        lj_err_callermsg(ms->L, "missing '[' after '%f' in pattern");
      ep = classend(ms, p);
      previous = (s == ms->src_init) ? '\0' : (unsigned char)*(s - 1);
      if (matchbracketclass(previous, p, ep - 1) ||
          !matchbracketclass((s < ms->src_end) ? (unsigned char)*s : '\0', p, ep - 1)) {
        s = NULL;
        break;
      }
      p = ep;
      goto init;
    }
    default: {
      if (isdigit((unsigned char)*(p + 1))) {
        s = match_capture(ms, s, (unsigned char)*(p + 1));
        if (s == NULL) break;
        p += 2;
        goto init;
      }
      goto dflt;
    }
    }
    break;
  }
  case '\0':
    break;
  case '$': {
    if (*(p + 1) == '\0') {
      if (s != ms->src_end) s = NULL;
      break;
    }
    goto dflt;
  }
  default:
  dflt: {
    const char *ep = classend(ms, p);
    int m = s < ms->src_end && singlematch((unsigned char)*s, p, ep);
    switch (*ep) {
    case '?': {
      const char *res;
      if (m && ((res = match(ms, s + 1, ep + 1)) != NULL)) {
        s = res;
        break;
      }
      p = ep + 1;
      goto init;
    }
    case '*':
      s = max_expand(ms, s, p, ep);
      break;
    case '+':
      s = (m ? max_expand(ms, s + 1, p, ep) : NULL);
      break;
    case '-':
      s = min_expand(ms, s, p, ep);
      break;
    default:
      if (!m) {
        s = NULL;
        break;
      }
      s++;
      p = ep;
      goto init;
    }
    break;
  }
  }
  ms->depth--;
  return s;
}

static const char *lmemfind(const char *s1, size_t l1, const char *s2, size_t l2)
{
  if (l2 == 0) return s1;
  else if (l2 > l1) return NULL;
  else {
    const char *init;
    l2--;
    l1 = l1 - l2;
    while (l1 > 0 && (init = (const char *)memchr(s1, *s2, l1)) != NULL) {
      init++;
      if (memcmp(init, s2 + 1, l2) == 0)
        return init - 1;
      else {
        l1 -= (size_t)(init - s1);
        s1 = init;
      }
    }
    return NULL;
  }
}

static void push_onecapture(MatchState *ms, int i, const char *s, const char *e)
{
  if (i >= ms->level) {
    if (i == 0)
      lua_pushlstring(ms->L, s, (size_t)(e - s));
    else
      lj_err_callermsg(ms->L, "invalid capture index");
  } else {
    ptrdiff_t l = ms->capture[i].len;
    if (l == CAP_UNFINISHED) lj_err_callermsg(ms->L, "unfinished capture");
    if (l == CAP_POSITION)
      lua_pushinteger(ms->L, ms->capture[i].init - ms->src_init + 1);
    else
      lua_pushlstring(ms->L, ms->capture[i].init, (size_t)l);
  }
}

static int push_captures(MatchState *ms, const char *s, const char *e)
{
  int i;
  int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  luaL_checkstack(ms->L, nlevels, "too many captures");
  for (i = 0; i < nlevels; i++)
    push_onecapture(ms, i, s, e);
  return nlevels;
}

static int has_specials(const char *p, size_t l)
{
  size_t i;
  for (i = 0; i < l; i++)
    if (strchr(SPECIALS, p[i])) return 1;
  return 0;
}

static int str_find_aux(lua_State *L, int find)
{
  GCstr *ss = lj_lib_checkstr(L, 1);
  GCstr *ps = lj_lib_checkstr(L, 2);
  size_t l1 = ss->len, l2 = ps->len;
  const char *s = strdata(ss), *p = strdata(ps);
  int32_t init = posrelat(lj_lib_optint(L, 3, 1), l1) - 1;
  if (init < 0) init = 0;
  else if ((size_t)init > l1) init = (int32_t)l1;
  if (find && (lua_toboolean(L, 4) || !has_specials(p, l2))) {
    const char *s2 = lmemfind(s + init, l1 - (size_t)init, p, l2);
    if (s2) {
      lua_pushinteger(L, s2 - s + 1);
      lua_pushinteger(L, (lua_Integer)(s2 - s + l2));
      return 2;
    }
  } else {
    MatchState ms;
    int anchor = (*p == '^') ? (p++, 1) : 0;
    const char *s1 = s + init;
    ms.L = L;
    ms.src_init = s;
    ms.src_end = s + l1;
    do {
      const char *res;
      ms.level = 0;
      ms.depth = 0;
      if ((res = match(&ms, s1, p)) != NULL) {
        if (find) {
          lua_pushinteger(L, s1 - s + 1);
          lua_pushinteger(L, res - s);
          return push_captures(&ms, NULL, 0) + 2;
        } else {
          return push_captures(&ms, s1, res);
        }
      }
    } while (s1++ < ms.src_end && !anchor);
  }
  lua_pushnil(L);
  return 1;
}

static int str_find(lua_State *L) { return str_find_aux(L, 1); }
static int str_match(lua_State *L) { return str_find_aux(L, 0); }

static int gmatch_aux(lua_State *L)
{
  MatchState ms;
  size_t ls;
  const char *s = lua_tolstring(L, lua_upvalueindex(1), &ls);
  const char *p = lua_tostring(L, lua_upvalueindex(2));
  const char *src;
  ms.L = L;
  ms.src_init = s;
  ms.src_end = s + ls;
  for (src = s + (size_t)lua_tointeger(L, lua_upvalueindex(3)); src <= ms.src_end; src++) {
    const char *e;
    ms.level = 0;
    ms.depth = 0;
    if ((e = match(&ms, src, p)) != NULL) {
      lua_Integer newstart = e - s;
      if (e == src) newstart++;
      lua_pushinteger(L, newstart);
      lua_replace(L, lua_upvalueindex(3));
      return push_captures(&ms, src, e);
    }
  }
  return 0;
}

static int str_gmatch(lua_State *L)
{
  lj_lib_checkstr(L, 1);
  lj_lib_checkstr(L, 2);
  lua_settop(L, 2);
  lua_pushinteger(L, 0);
  lj_lib_pushcc(L, gmatch_aux, 86, 3);
