static void addquoted(luaL_Buffer *b, GCstr *str)
{
  size_t l = str->len;
  const char *s = strdata(str);
  luaL_addchar(b, '"');
  while (l--) {
    unsigned char c = (unsigned char)*s;
    if (c == '"' || c == '\\' || c == '\n') {
      luaL_addchar(b, '\\');
      luaL_addchar(b, c);
    } else if (c < 32 || c == 127) {
      char buf[8];
      if (l > 0 && isdigit((unsigned char)s[1]))
        snprintf(buf, sizeof(buf), "\\%03d", c);
      else
        snprintf(buf, sizeof(buf), "\\%d", c);
      luaL_addstring(b, buf);
    } else {
      luaL_addchar(b, c);
    }
    s++;
  }
  luaL_addchar(b, '"');
}

