typedef union { uint64_t u64; double d; } U64double;

typedef struct PRNGState { uint64_t u[4]; } PRNGState;

static PRNGState prng;

#define TW223_GEN(rs, z, r, i, k, q, s) \
  z = rs->u[i]; \
  z = (((z << q) ^ z) >> (k - s)) ^ ((z & ((uint64_t)(int64_t)-1 << (64 - k))) << s); \
  r ^= z; rs->u[i] = z;

static uint64_t prng_u64(PRNGState *rs)
{
  uint64_t z, r = 0;
  TW223_GEN(rs, z, r, 0, 63, 31, 18)
  TW223_GEN(rs, z, r, 1, 58, 19, 28)
  TW223_GEN(rs, z, r, 2, 55, 24, 7)
  TW223_GEN(rs, z, r, 3, 47, 21, 8)
  return r;
}

static uint64_t prng_u64d(PRNGState *rs)
{
  uint64_t r = prng_u64(rs);
  return (r & 0x000fffffffffffffULL) | 0x3ff0000000000000ULL;
}

static void random_seed(PRNGState *rs, double d)
{
  uint32_t r = 0x11090601;
  int i;
  for (i = 0; i < 4; i++) {
    U64double u;
    uint32_t m = 1u << (r & 255);
    r >>= 8;
    u.d = d = d * 3.14159265358979323846 + 2.7182818284590452354;
    if (u.u64 < m) u.u64 += m;
    rs->u[i] = u.u64;
  }
  for (i = 0; i < 10; i++) (void)prng_u64(rs);
}

uint64_t lj_prng_u64(void)
{
  return prng_u64(&prng);
}

static int math_random(lua_State *L)
{
  int n = (int)(L->top - L->base);
  U64double u;
  double d;
  u.u64 = prng_u64d(&prng);
  d = u.d - 1.0;
  if (n > 0) {
    double r1 = lj_lib_checknum(L, 1);
    if (n == 1) {
      d = floor(d * r1) + 1.0;
    } else {
      double r2 = lj_lib_checknum(L, 2);
      d = floor(d * (r2 - r1 + 1.0)) + r1;
    }
  }
  lua_pushnumber(L, d);
  return 1;
}

