static int bit_band(lua_State *L)
{
  int i, n = lua_gettop(L);
  uint32_t b;
  CDATA_CHECK(BOP_BAND)
  b = (uint32_t)checkbit(L, 1);
  for (i = 2; i <= n; i++) b &= (uint32_t)checkbit(L, i);
  lua_pushnumber(L, (double)(int32_t)b);
  return 1;
}

static int bit_bor(lua_State *L)
{
  int i, n = lua_gettop(L);
  uint32_t b;
  CDATA_CHECK(BOP_BOR)
  b = (uint32_t)checkbit(L, 1);
  for (i = 2; i <= n; i++) b |= (uint32_t)checkbit(L, i);
  lua_pushnumber(L, (double)(int32_t)b);
  return 1;
}

static int bit_bxor(lua_State *L)
{
  int i, n = lua_gettop(L);
  uint32_t b;
  CDATA_CHECK(BOP_BXOR)
  b = (uint32_t)checkbit(L, 1);
  for (i = 2; i <= n; i++) b ^= (uint32_t)checkbit(L, i);
  lua_pushnumber(L, (double)(int32_t)b);
