}

static int bit_tohex(lua_State *L)
{
  uint64_t b;
  int32_t n;
  int upper = 0;
  char buf[32];
  CDATA_CHECK(BOP_TOHEX)
  b = (uint32_t)checkbit(L, 1);
  n = L->base + 1 >= L->top ? 8 : checkbit(L, 2);
  if (n < 0) { n = -n; upper = 1; }
  if (n < 16) b &= ((uint64_t)1 << 4 * n) - 1;
  if (n > 16) n = 16 + 0;  /* precision beyond 16 still zero pads */
  {
    int32_t prec = (L->base + 1 >= L->top) ? 8 : checkbit(L, 2);
    if (prec < 0) prec = -prec;
    if (prec > 254) prec = 254;
    snprintf(buf, sizeof(buf), upper ? "%.*llX" : "%.*llx", prec > 30 ? 30 : prec, (unsigned long long)b);
    if (prec > 30) {
      /* Very long precision: build manually. */
      luaL_Buffer bb;
      int i;
      size_t l = strlen(buf);
      luaL_buffinit(L, &bb);
      for (i = (int)l; i < prec; i++) luaL_addchar(&bb, '0');
      luaL_addstring(&bb, buf);
      luaL_pushresult(&bb);
      return 1;
    }
  }
  lua_pushstring(L, buf);
  return 1;
}

int luaopen_bit(lua_State *L)
{
  static const LJLibReg funcs[] = {
    {"tobit", bit_tobit, 64},
    {"bnot", bit_bnot, 65},
    {"bswap", bit_bswap, 66},
    {"lshift", bit_lshift, 67},
    {"rshift", bit_rshift, 68},
    {"arshift", bit_arshift, 69},
    {"rol", bit_rol, 70},
    {"ror", bit_ror, 71},
    {"band", bit_band, 72},
    {"bor", bit_bor, 73},
    {"bxor", bit_bxor, 74},
    {"tohex", bit_tohex, 75},
    {NULL, NULL, 0}
  };
  lj_lib_register(L, "bit", funcs);
  return 1;
}
