/* OS library. */
#include <errno.h>
#include <time.h>
#include <locale.h>
#include <unistd.h>
#include "lj.h"
#include "lj_api.h"

static int os_execute(lua_State *L)
{
  const char *cmd = luaL_optstring(L, 1, NULL);
  int stat;
  fflush(NULL);
  stat = system(cmd);
  if (cmd == NULL) {
    lua_pushinteger(L, stat ? 1 : 0);
    return 1;
  }
  lua_pushinteger(L, stat);
  return 1;
}

static int os_remove(lua_State *L)
{
  const char *filename = luaL_checkstring(L, 1);
  return luaL_fileresult(L, remove(filename) == 0, filename);
}

static int os_rename(lua_State *L)
{
  const char *fromname = luaL_checkstring(L, 1);
  const char *toname = luaL_checkstring(L, 2);
  return luaL_fileresult(L, rename(fromname, toname) == 0, fromname);
}

static int os_tmpname(lua_State *L)
{
  char buf[32];
  int fd;
  strcpy(buf, "/tmp/lua_XXXXXX");
  fd = mkstemp(buf);
  if (fd != -1) close(fd);
  else luaL_error(L, "unable to generate a unique filename");
  lua_pushstring(L, buf);
  return 1;
}

static int os_getenv(lua_State *L)
{
  lua_pushstring(L, getenv(luaL_checkstring(L, 1)));
  return 1;
}

extern void lj_main_exit(lua_State *L, int status, int closestate);

static int os_exit(lua_State *L)
{
  int status;
  if (L->base < L->top && tvisbool(L->base))
    status = boolV(L->base) ? EXIT_SUCCESS : EXIT_FAILURE;
  else
    status = luaL_optint(L, 1, EXIT_SUCCESS);
  lj_main_exit(L, status, lua_toboolean(L, 2));
  return 0;
}

static int os_clock(lua_State *L)
{
  lua_pushnumber(L, ((lua_Number)clock()) * (1.0 / CLOCKS_PER_SEC));
  return 1;
}

static void setfield(lua_State *L, const char *key, int value)
{
  lua_pushinteger(L, value);
  lua_setfield(L, -2, key);
}

static void setboolfield(lua_State *L, const char *key, int value)
{
  if (value < 0) return;
  lua_pushboolean(L, value);
  lua_setfield(L, -2, key);
}

static int getboolfield(lua_State *L, const char *key)
{
  int res;
  lua_getfield(L, -1, key);
  res = lua_isnil(L, -1) ? -1 : lua_toboolean(L, -1);
  lua_pop(L, 1);
  return res;
}

static int getfield(lua_State *L, const char *key, int d)
{
  int res;
  lua_getfield(L, -1, key);
  if (lua_isnumber(L, -1)) {
    res = (int)lua_tointeger(L, -1);
  } else {
    if (d < 0)
      luaL_error(L, "field '%s' missing in date table", key);
    res = d;
  }
  lua_pop(L, 1);
  return res;
}

static int os_date(lua_State *L)
{
  const char *s = luaL_optstring(L, 1, "%c");
  time_t t = luaL_opt(L, (time_t)luaL_checknumber, 2, time(NULL));
  struct tm *stm, rtm;
  if (*s == '!') {
    stm = gmtime_r(&t, &rtm);
    s++;
  } else {
    stm = localtime_r(&t, &rtm);
  }
  if (stm == NULL) {
    lua_pushnil(L);
  } else if (strcmp(s, "*t") == 0) {
    lua_createtable(L, 0, 9);
    setfield(L, "sec", stm->tm_sec);
    setfield(L, "min", stm->tm_min);
    setfield(L, "hour", stm->tm_hour);
    setfield(L, "day", stm->tm_mday);
    setfield(L, "month", stm->tm_mon + 1);
    setfield(L, "year", stm->tm_year + 1900);
    setfield(L, "wday", stm->tm_wday + 1);
    setfield(L, "yday", stm->tm_yday + 1);
    setboolfield(L, "isdst", stm->tm_isdst);
  } else {
    char cc[3];
    luaL_Buffer b;
    cc[0] = '%';
    cc[2] = '\0';
    luaL_buffinit(L, &b);
    for (; *s; s++) {
      if (*s != '%' || *(s + 1) == '\0') {
        luaL_addchar(&b, *s);
      } else {
        size_t reslen;
        char buff[200];
        cc[1] = *(++s);
        reslen = strftime(buff, sizeof(buff), cc, stm);
        luaL_addlstring(&b, buff, reslen);
      }
    }
    luaL_pushresult(&b);
  }
  return 1;
}

static int os_time(lua_State *L)
{
  time_t t;
  if (lua_isnoneornil(L, 1)) {
    t = time(NULL);
  } else {
    struct tm ts;
    luaL_checktype(L, 1, LUA_TTABLE);
    lua_settop(L, 1);
    ts.tm_sec = getfield(L, "sec", 0);
    ts.tm_min = getfield(L, "min", 0);
    ts.tm_hour = getfield(L, "hour", 12);
    ts.tm_mday = getfield(L, "day", -1);
    ts.tm_mon = getfield(L, "month", -1) - 1;
    ts.tm_year = getfield(L, "year", -1) - 1900;
    ts.tm_isdst = getboolfield(L, "isdst");
    t = mktime(&ts);
  }
  if (t == (time_t)(-1))
    lua_pushnil(L);
  else
    lua_pushnumber(L, (lua_Number)t);
  return 1;
}

static int os_difftime(lua_State *L)
{
  lua_pushnumber(L, difftime((time_t)(luaL_checknumber(L, 1)), (time_t)(luaL_optnumber(L, 2, 0))));
  return 1;
}

static int os_setlocale(lua_State *L)
{
  static const int cat[] = {LC_ALL, LC_COLLATE, LC_CTYPE, LC_MONETARY, LC_NUMERIC, LC_TIME};
  static const char *const catnames[] = {"all", "collate", "ctype", "monetary", "numeric", "time", NULL};
  const char *l = luaL_optstring(L, 1, NULL);
  int op = luaL_checkoption(L, 2, "all", catnames);
  lua_pushstring(L, setlocale(cat[op], l));
  return 1;
}

int luaopen_os(lua_State *L)
{
  static const LJLibReg funcs[] = {
    {"execute", os_execute, 116},
    {"remove", os_remove, 117},
    {"rename", os_rename, 118},
    {"tmpname", os_tmpname, 119},
    {"getenv", os_getenv, 120},
    {"exit", os_exit, 121},
    {"clock", os_clock, 122},
    {"date", os_date, 123},
    {"time", os_time, 124},
    {"difftime", os_difftime, 125},
    {"setlocale", os_setlocale, 126},
    {NULL, NULL, 0}
  };
  lj_lib_register(L, "os", funcs);
  return 1;
}
