/* I/O library. */
#include <errno.h>
#include <ctype.h>
#include <unistd.h>
#include "lj.h"
#include "lj_api.h"

#define IOFILE_TYPE_FILE 0
#define IOFILE_TYPE_PIPE 1
#define IOFILE_TYPE_STDF 2

typedef struct IOFileUD {
  FILE *fp;
  int type;
  int closed;
} IOFileUD;

static GCtab *io_mt = NULL;
static TValue io_input, io_output;
static GCudata *io_stdin_ud, *io_stdout_ud, *io_stderr_ud;

void lj_io_mark(void (*mark)(GCobj *))
{
  if (io_mt) mark((GCobj *)io_mt);
  if (tvisudata(&io_input)) mark(io_input.u.gc);
  if (tvisudata(&io_output)) mark(io_output.u.gc);
}

static IOFileUD *io_tofilep(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (!(o < L->top && tvisudata(o) && udataV(o)->udtype == 1))
    lj_err_argtype(L, narg, "FILE*");
  return (IOFileUD *)udataV(o)->align;
}

static IOFileUD *io_tofile(lua_State *L, int narg)
{
  IOFileUD *iof = io_tofilep(L, narg);
  if (iof->closed) lj_err_msg(L, "attempt to use a closed file");
  return iof;
}

static IOFileUD *io_file_new(lua_State *L)
{
  IOFileUD *iof = (IOFileUD *)lua_newuserdata(L, sizeof(IOFileUD));
  GCudata *ud = udataV(L->top - 1);
  ud->udtype = 1;
  ud->metatable = io_mt;
  iof->fp = NULL;
  iof->type = IOFILE_TYPE_FILE;
  iof->closed = 0;
  return iof;
}

static int io_pushresult(lua_State *L, int ok, const char *fname)
{
  return luaL_fileresult(L, ok, fname);
}

static int io_file_close(lua_State *L, IOFileUD *iof)
{
  int ok;
  if (iof->type == IOFILE_TYPE_FILE) {
    ok = (fclose(iof->fp) == 0);
    iof->fp = NULL;
  } else if (iof->type == IOFILE_TYPE_PIPE) {
    int stat = pclose(iof->fp);
    iof->fp = NULL;
    ok = (stat != -1);
    iof->closed = 1;
    if (ok) {
      lua_pushboolean(L, 1);
      return 1;
    }
    return io_pushresult(L, 0, NULL);
  } else {
    lua_pushnil(L);
    lua_pushliteral(L, "cannot close standard file");
    return 2;
  }
  iof->closed = 1;
  return io_pushresult(L, ok, NULL);
}

/* -- Reading ---------------------------------------------------------------- */

static int io_read_number(lua_State *L, FILE *fp)
{
  char buf[200];
  int n = 0, c;
  double d;
  /* Skip whitespace. */
  do { c = getc(fp); } while (c != EOF && isspace(c));
  while (c != EOF && n < (int)sizeof(buf) - 1 &&
         (isalnum(c) || c == '.' || c == '+' || c == '-')) {
    buf[n++] = (char)c;
    c = getc(fp);
  }
  if (c != EOF) ungetc(c, fp);
  buf[n] = 0;
  /* Accept the longest prefix that is a valid number. */
  while (n > 0) {
    if (lj_strscan_num(buf, (size_t)n, &d)) {
      lua_pushnumber(L, d);
      return 1;
    }
    n--;
  }
  lua_pushnil(L);
  return 0;
}

static int io_read_line(lua_State *L, FILE *fp, int chop)
{
  luaL_Buffer b;
  int c;
  int any = 0;
  luaL_buffinit(L, &b);
  for (;;) {
    c = getc(fp);
    if (c == EOF) break;
    any = 1;
    if (c == '\n') {
      if (!chop) luaL_addchar(&b, '\n');
      luaL_pushresult(&b);
      return 1;
    }
    luaL_addchar(&b, c);
  }
  luaL_pushresult(&b);
  return any;
}

static void io_read_all(lua_State *L, FILE *fp)
{
  luaL_Buffer b;
  size_t n;
  char buf[4096];
  luaL_buffinit(L, &b);
  while ((n = fread(buf, 1, sizeof(buf), fp)) > 0)
    luaL_addlstring(&b, buf, n);
  luaL_pushresult(&b);
}

static int io_read_chars(lua_State *L, FILE *fp, size_t n)
{
  luaL_Buffer b;
  size_t rlen, nr;
  char buf[4096];
  luaL_buffinit(L, &b);
  while (n > 0) {
    rlen = n < sizeof(buf) ? n : sizeof(buf);
    nr = fread(buf, 1, rlen, fp);
    luaL_addlstring(&b, buf, nr);
    n -= nr;
    if (nr < rlen) break;
  }
  {
    int ok = b.n > 0;
    luaL_pushresult(&b);
    return ok;
  }
}

static int io_test_eof(lua_State *L, FILE *fp)
{
  int c = getc(fp);
  ungetc(c, fp);
  lua_pushlstring(L, NULL, 0);
  return (c != EOF);
}

static int io_file_read(lua_State *L, FILE *fp, int start)
{
  int ok, n, nargs = (int)(L->top - L->base) - start;
  clearerr(fp);
  if (nargs == 0) {
    ok = io_read_line(L, fp, 1);
    n = start + 1;
  } else {
    luaL_checkstack(L, nargs + LUA_MINSTACK, "too many arguments");
    ok = 1;
    for (n = start; nargs-- && ok; n++) {
      TValue *o = L->base + n;
      if (tvisstr(o)) {
        const char *p = strdata(strV(o));
        if (*p == '*') p++;
        if (*p == 'n') ok = io_read_number(L, fp);
        else if ((*p & ~0x20) == 'L') ok = io_read_line(L, fp, (*p == 'l'));
        else if (*p == 'a') { io_read_all(L, fp); }
        else luaL_argerror(L, n + 1, "invalid format");
      } else if (tvisnum(o)) {
        size_t len = (size_t)lj_lib_checkint(L, n + 1);
        ok = len ? io_read_chars(L, fp, len) : io_test_eof(L, fp);
      } else {
        luaL_argerror(L, n + 1, "invalid option");
      }
    }
  }
  if (ferror(fp))
    return io_pushresult(L, 0, NULL);
  if (!ok) {
    lua_pop(L, 1);
    lua_pushnil(L);
  }
  return n - start;
}

static int io_file_write(lua_State *L, FILE *fp, int start)
{
  TValue *tv;
  int status = 1;
  for (tv = L->base + start; tv < L->top; tv++) {
    if (tvisstr(tv)) {
      size_t len = strV(tv)->len;
      status = status && (fwrite(strdata(strV(tv)), 1, len, fp) == len);
    } else if (tvisnum(tv)) {
      char buf[64];
      size_t len = lj_str_fmtnum(buf, tv->u.n);
      status = status && (fwrite(buf, 1, len, fp) == len);
    } else {
      lj_err_argt(L, (int)(tv - L->base) + 1, LJ_TSTR);
    }
  }
  return io_pushresult(L, status, NULL);
}

/* -- File methods -------------------------------------------------------- */

static int io_method_close(lua_State *L)
{
  IOFileUD *iof;
  if (L->base == L->top) {
    lua_pushtv(L, &io_output);
    lua_insert(L, 1);
  }
  iof = io_tofile(L, 1);
  return io_file_close(L, iof);
}

static int io_method_read(lua_State *L)
{
  return io_file_read(L, io_tofile(L, 1)->fp, 1);
}

static int io_method_write(lua_State *L)
{
  return io_file_write(L, io_tofile(L, 1)->fp, 1);
}

static int io_method_flush(lua_State *L)
{
  return io_pushresult(L, fflush(io_tofile(L, 1)->fp) == 0, NULL);
}

static int io_method_seek(lua_State *L)
{
  static const int mode[] = {SEEK_SET, SEEK_CUR, SEEK_END};
  static const char *const modenames[] = {"set", "cur", "end", NULL};
  FILE *fp = io_tofile(L, 1)->fp;
  int op = luaL_checkoption(L, 2, "cur", modenames);
  double ofs = luaL_optnumber(L, 3, 0);
  int res = fseeko(fp, (off_t)ofs, mode[op]);
  if (res) return io_pushresult(L, 0, NULL);
  lua_pushnumber(L, (double)ftello(fp));
  return 1;
}

static int io_method_setvbuf(lua_State *L)
{
  static const int mode[] = {_IONBF, _IOFBF, _IOLBF};
  static const char *const modenames[] = {"no", "full", "line", NULL};
  FILE *fp = io_tofile(L, 1)->fp;
  int op = luaL_checkoption(L, 2, NULL, modenames);
  lua_Integer sz = luaL_optinteger(L, 3, BUFSIZ);
  int res = setvbuf(fp, NULL, mode[op], (size_t)sz);
  return io_pushresult(L, res == 0, NULL);
}

static int io_iter_aux(lua_State *L)
{
  IOFileUD *iof = (IOFileUD *)lua_touserdata(L, lua_upvalueindex(1));
  int n = (int)lua_tointeger(L, lua_upvalueindex(2));
  int i, r;
  if (iof->closed) luaL_error(L, "file is already closed");
  L->top = L->base;
  for (i = 1; i <= n; i++) lua_pushvalue(L, lua_upvalueindex(2 + i));
  r = io_file_read(L, iof->fp, 0);
  if (ferror(iof->fp)) luaL_error(L, "%s", strerror(errno));
  if (lua_isnil(L, -r) && lua_toboolean(L, lua_upvalueindex(3 + n))) {
    io_file_close(L, iof);
    return 0;
  }
  return r;
}

static int io_file_lines(lua_State *L, int toclose)
{
  int n = lua_gettop(L) - 1;
  int i;
  lua_pushvalue(L, 1);
  lua_pushinteger(L, n);
  for (i = 2; i <= n + 1; i++) lua_pushvalue(L, i);
  lua_pushboolean(L, toclose);
  lj_lib_pushcc(L, io_iter_aux, 0, n + 3);
  return 1;
}

static int io_method_lines(lua_State *L)
{
  io_tofile(L, 1);
  return io_file_lines(L, 0);
}

static int io_method_gc(lua_State *L)
{
  IOFileUD *iof = io_tofilep(L, 1);
  if (!iof->closed && iof->type != IOFILE_TYPE_STDF && iof->fp) io_file_close(L, iof);
  return 0;
}

static int io_method_tostring(lua_State *L)
{
  IOFileUD *iof = io_tofilep(L, 1);
  if (iof->closed)
    lua_pushliteral(L, "file (closed)");
  else
    lua_pushfstring(L, "file (%p)", (void *)iof->fp);
  return 1;
}

/* -- Library functions ------------------------------------------------------ */

static int io_open(lua_State *L)
{
  const char *fname = luaL_checkstring(L, 1);
  const char *mode = luaL_optstring(L, 2, "r");
  IOFileUD *iof = io_file_new(L);
  iof->fp = fopen(fname, mode);
  if (iof->fp == NULL) return io_pushresult(L, 0, fname);
  return 1;
}

static int io_popen(lua_State *L)
{
  const char *fname = luaL_checkstring(L, 1);
  const char *mode = luaL_optstring(L, 2, "r");
  IOFileUD *iof = io_file_new(L);
  iof->type = IOFILE_TYPE_PIPE;
  fflush(NULL);
  iof->fp = popen(fname, mode);
  if (iof->fp == NULL) return io_pushresult(L, 0, fname);
  return 1;
}

static int io_tmpfile(lua_State *L)
{
  IOFileUD *iof = io_file_new(L);
  iof->fp = tmpfile();
  if (iof->fp == NULL) return io_pushresult(L, 0, NULL);
  return 1;
}

static int io_close(lua_State *L)
{
  return io_method_close(L);
}

static IOFileUD *io_stdfile(lua_State *L, TValue *o)
{
  IOFileUD *iof = (IOFileUD *)udataV(o)->align;
  if (iof->closed) lj_err_msg(L, "attempt to use a closed file");
  (void)L;
  return iof;
}

static int io_read(lua_State *L)
{
  return io_file_read(L, io_stdfile(L, &io_input)->fp, 0);
}

static int io_write(lua_State *L)
{
  return io_file_write(L, io_stdfile(L, &io_output)->fp, 0);
}

static int io_flush(lua_State *L)
{
  return io_pushresult(L, fflush(io_stdfile(L, &io_output)->fp) == 0, NULL);
}

static int io_std_getset(lua_State *L, TValue *slot, const char *mode)
{
  if (L->base < L->top && !tvisnil(L->base)) {
    if (tvisudata(L->base) && udataV(L->base)->udtype == 1) {
      io_tofile(L, 1);
      copyTV(slot, L->base);
    } else {
      const char *s = luaL_checkstring(L, 1);
      IOFileUD *iof = io_file_new(L);
      iof->fp = fopen(s, mode);
      if (iof->fp == NULL) luaL_argerror(L, 1, lua_pushfstring(L, "%s: %s", s, strerror(errno)));
      copyTV(slot, L->top - 1);
    }
  }
  lua_pushtv(L, slot);
  return 1;
}

static int io_input_f(lua_State *L) { return io_std_getset(L, &io_input, "r"); }
static int io_output_f(lua_State *L) { return io_std_getset(L, &io_output, "w"); }

static int io_lines(lua_State *L)
{
  if (L->base == L->top) lua_pushnil(L);
  if (!tvisnil(L->base)) {
    const char *fname = luaL_checkstring(L, 1);
    IOFileUD *iof = io_file_new(L);
    iof->fp = fopen(fname, "r");
    if (iof->fp == NULL) luaL_argerror(L, 1, lua_pushfstring(L, "%s: %s", fname, strerror(errno)));
    lua_replace(L, 1);
    return io_file_lines(L, 1);
  } else {
    copyTV(L->base, &io_input);
    io_tofile(L, 1);
    return io_file_lines(L, 0);
  }
}

static int io_type(lua_State *L)
{
  TValue *o = L->base;
  luaL_checkany(L, 1);
  if (tvisudata(o) && udataV(o)->udtype == 1) {
    IOFileUD *iof = (IOFileUD *)udataV(o)->align;
    if (iof->closed) lua_pushliteral(L, "closed file");
    else lua_pushliteral(L, "file");
  } else {
    lua_pushnil(L);
  }
  return 1;
}

static GCudata *io_std_new(lua_State *L, FILE *fp, const char *name)
{
  IOFileUD *iof = io_file_new(L);
  GCudata *ud = udataV(L->top - 1);
  iof->fp = fp;
  iof->type = IOFILE_TYPE_STDF;
  lua_setfield(L, -2, name);
  return ud;
}

int luaopen_io(lua_State *L)
{
  static const LJLibReg methods[] = {
    {"close", io_method_close, 96},
    {"read", io_method_read, 97},
    {"write", io_method_write, 98},
    {"flush", io_method_flush, 99},
    {"seek", io_method_seek, 100},
    {"setvbuf", io_method_setvbuf, 101},
    {"lines", io_method_lines, 102},
    {"__gc", io_method_gc, 103},
    {"__tostring", io_method_tostring, 104},
    {NULL, NULL, 0}
  };
  static const LJLibReg funcs[] = {
    {"open", io_open, 105},
    {"popen", io_popen, 106},
    {"tmpfile", io_tmpfile, 107},
    {"close", io_close, 108},
    {"read", io_read, 109},
    {"write", io_write, 110},
    {"flush", io_flush, 111},
    {"input", io_input_f, 112},
    {"output", io_output_f, 113},
    {"lines", io_lines, 114},
    {"type", io_type, 115},
    {NULL, NULL, 0}
  };
  luaL_newmetatable(L, "FILE*");
  io_mt = tabV(L->top - 1);
  lj_lib_register(L, NULL, methods);
  lua_pushvalue(L, -1);
  lua_setfield(L, -2, "__index");
  lua_pop(L, 1);
  lj_lib_register(L, "io", funcs);
  io_stdin_ud = io_std_new(L, stdin, "stdin");
  io_stdout_ud = io_std_new(L, stdout, "stdout");
  io_stderr_ud = io_std_new(L, stderr, "stderr");
  setudataV(&io_input, io_stdin_ud);
  setudataV(&io_output, io_stdout_ud);
  return 1;
}
