/* Debug library. */
#include "lj.h"
#include "lj_api.h"

typedef struct DebugInfo {
  const char *name;
  const char *namewhat;
  const char *what;
  const char *source;
  int currentline;
  int nups;
  int nparams;
  int isvararg;
  int linedefined;
  int lastlinedefined;
  char short_src[256];
} DebugInfo;

static void funcinfo(DebugInfo *ar, GCfunc *cl)
{
  if (cl->isC) {
    ar->source = "=[C]";
    ar->linedefined = -1;
    ar->lastlinedefined = -1;
    ar->what = "C";
    ar->nparams = 0;
    ar->isvararg = 1;
  } else {
    GCproto *p = cl->u.l.pt;
    ar->source = strdata(p->source);
    ar->linedefined = p->linedefined;
    ar->lastlinedefined = p->lastlinedefined;
    ar->what = (ar->linedefined == 0) ? "main" : "Lua";
    ar->nparams = p->numparams;
    ar->isvararg = p->is_vararg;
  }
  lj_debug_chunkid(ar->short_src, ar->source, sizeof(ar->short_src));
}

static lua_State *getthread(lua_State *L, int *arg)
{
  if (lua_isthread(L, 1)) {
    *arg = 1;
    return lua_tothread(L, 1);
  }
  *arg = 0;
  return L;
}

static void settabss(lua_State *L, const char *i, const char *v)
{
  lua_pushstring(L, v);
  lua_setfield(L, -2, i);
}

static void settabsi(lua_State *L, const char *i, int v)
{
  lua_pushinteger(L, v);
  lua_setfield(L, -2, i);
}

static void settabsb(lua_State *L, const char *i, int v)
{
  lua_pushboolean(L, v);
  lua_setfield(L, -2, i);
}

static int db_getinfo(lua_State *L)
{
  DebugInfo ar;
  int arg;
  lua_State *L1 = getthread(L, &arg);
  const char *options = luaL_optstring(L, arg + 2, "flnSu");
  CallInfo *ci = NULL;
  TValue fn;
  const char *p;
  memset(&ar, 0, sizeof(ar));
  if (lua_isnumber(L, arg + 1)) {
    int level = (int)lua_tointeger(L, arg + 1);
    if (L1 == L) {
      /* Level 0 is getinfo itself. */
    }
    if (level < 0 || !lj_debug_getstack(L1, level, &ci)) {
      lua_pushnil(L);
      return 1;
    }
    fn = *ci->func;
  } else if (lua_isfunction(L, arg + 1)) {
    fn = *index2adr(L, arg + 1);
  } else {
    return luaL_argerror(L, arg + 1, "function or level expected");
  }
  for (p = options; *p; p++) {
    if (!strchr("SlnufL", *p)) return luaL_argerror(L, arg + 2, "invalid option");
  }
  lua_createtable(L, 0, 16);
  for (p = options; *p; p++) {
    switch (*p) {
    case 'S':
      funcinfo(&ar, funcV(&fn));
      settabss(L, "source", ar.source);
      settabss(L, "short_src", ar.short_src);
      settabsi(L, "linedefined", ar.linedefined);
      settabsi(L, "lastlinedefined", ar.lastlinedefined);
      settabss(L, "what", ar.what);
      break;
    case 'l':
      settabsi(L, "currentline", ci ? lj_debug_currentline(L1, ci) : -1);
      break;
    case 'u':
      settabsi(L, "nups", funcV(&fn)->nupvalues);
      funcinfo(&ar, funcV(&fn));
      settabsi(L, "nparams", ar.nparams);
      settabsb(L, "isvararg", ar.isvararg);
      break;
    case 'n': {
      const char *name = NULL;
      const char *what = ci ? lj_debug_funcname(L1, ci, &name) : NULL;
      if (what) {
        settabss(L, "name", name);
        settabss(L, "namewhat", what);
      } else {
        settabss(L, "namewhat", "");
      }
      break;
    }
    case 'f':
      lua_pushtv(L, &fn);
      lua_setfield(L, -2, "func");
      break;
    case 'L': {
      GCfunc *cl = funcV(&fn);
      if (cl->isC) {
        lua_pushnil(L);
      } else {
        GCproto *pt = cl->u.l.pt;
        int i;
        lua_createtable(L, 0, 0);
        for (i = 0; i < pt->sizecode; i++) {
          lua_pushboolean(L, 1);
          lua_rawseti(L, -2, pt->lineinfo[i]);
        }
      }
      lua_setfield(L, -2, "activelines");
      break;
    }
    }
  }
  return 1;
}

static const char *getlocalname(lua_State *L1, CallInfo *ci, int n, TValue **pos)
{
  GCfunc *fn = funcV(ci->func);
  const char *name = NULL;
  if (!fn->isC && (ci->flags & CIST_LUA)) {
    GCproto *pt = fn->u.l.pt;
    int pc = (int)(ci->savedpc - pt->code) - 1;
    if (n < 0) {
      /* Varargs. */
      int nva = (int)(ci->base - ci->func) - pt->numparams - 1;
      if (pt->is_vararg && -n <= nva) {
        *pos = ci->base - nva + (-n - 1);
        return "(*vararg)";
      }
      return NULL;
    }
    name = lj_debug_getlocalname(pt, n, pc < 0 ? 0 : pc);
  }
  if (n > 0) {
    TValue *limit = (ci == L1->ci) ? L1->top : (ci + 1)->func;
    if (limit - ci->base >= n && n > 0) {
      *pos = ci->base + (n - 1);
      return name ? name : "(*temporary)";
    }
  }
  return NULL;
}

static int db_getlocal(lua_State *L)
{
  int arg;
  lua_State *L1 = getthread(L, &arg);
  CallInfo *ci;
  const char *name;
  TValue *pos = NULL;
  int n = luaL_checkint(L, arg + 2);
  if (lua_isfunction(L, arg + 1)) {
    GCfunc *fn = funcV(index2adr(L, arg + 1));
    if (fn->isC) { lua_pushnil(L); return 1; }
    lua_pushstring(L, lj_debug_getlocalname(fn->u.l.pt, n, 0));
    return 1;
  }
  if (!lj_debug_getstack(L1, luaL_checkint(L, arg + 1), &ci))
    return luaL_argerror(L, arg + 1, "level out of range");
  name = getlocalname(L1, ci, n, &pos);
  if (name) {
    lua_pushstring(L, name);
    lua_pushtv(L, pos);
    return 2;
  }
  lua_pushnil(L);
  return 1;
}

static int db_setlocal(lua_State *L)
{
  int arg;
  lua_State *L1 = getthread(L, &arg);
  CallInfo *ci;
  const char *name;
  TValue *pos = NULL;
  if (!lj_debug_getstack(L1, luaL_checkint(L, arg + 1), &ci))
    return luaL_argerror(L, arg + 1, "level out of range");
  luaL_checkany(L, arg + 3);
  name = getlocalname(L1, ci, luaL_checkint(L, arg + 2), &pos);
  if (name) copyTV(pos, index2adr(L, arg + 3));
  lua_pushstring(L, name);
  return 1;
}

static int auxupvalue(lua_State *L, int get)
{
  GCfunc *fn;
  int n = luaL_checkint(L, 2);
  luaL_checktype(L, 1, LUA_TFUNCTION);
  fn = funcV(index2adr(L, 1));
  if (n < 1 || n > fn->nupvalues) return 0;
  if (fn->isC) {
    if (get) {
      lua_pushliteral(L, "");
      lua_pushtv(L, &fn->u.c.upvalue[n - 1]);
      return 2;
    }
    copyTV(&fn->u.c.upvalue[n - 1], index2adr(L, 3));
    lua_pushliteral(L, "");
    return 1;
  } else {
    GCproto *pt = fn->u.l.pt;
    const char *name = (pt->uvnames && pt->uvnames[n - 1]) ? strdata(pt->uvnames[n - 1]) : "";
    if (get) {
      lua_pushstring(L, name);
      lua_pushtv(L, fn->u.l.uv[n - 1]->v);
      return 2;
    }
    copyTV(fn->u.l.uv[n - 1]->v, index2adr(L, 3));
    lua_pushstring(L, name);
    return 1;
  }
}

static int db_getupvalue(lua_State *L) { return auxupvalue(L, 1); }

static int db_setupvalue(lua_State *L)
{
  luaL_checkany(L, 3);
  return auxupvalue(L, 0);
}

static int db_upvalueid(lua_State *L)
{
  GCfunc *fn;
  int n = luaL_checkint(L, 2);
  luaL_checktype(L, 1, LUA_TFUNCTION);
  fn = funcV(index2adr(L, 1));
  if (n < 1 || n > fn->nupvalues) luaL_argerror(L, 2, "invalid upvalue index");
  if (fn->isC) lua_pushlightuserdata(L, &fn->u.c.upvalue[n - 1]);
  else lua_pushlightuserdata(L, fn->u.l.uv[n - 1]);
  return 1;
}

static int db_upvaluejoin(lua_State *L)
{
  GCfunc *f1, *f2;
  int n1 = luaL_checkint(L, 2);
  int n2 = luaL_checkint(L, 4);
  luaL_checktype(L, 1, LUA_TFUNCTION);
  luaL_checktype(L, 3, LUA_TFUNCTION);
  f1 = funcV(index2adr(L, 1));
  f2 = funcV(index2adr(L, 3));
  luaL_argcheck(L, !f1->isC, 1, "Lua function expected");
  luaL_argcheck(L, !f2->isC, 3, "Lua function expected");
  luaL_argcheck(L, n1 >= 1 && n1 <= f1->nupvalues, 2, "invalid upvalue index");
  luaL_argcheck(L, n2 >= 1 && n2 <= f2->nupvalues, 4, "invalid upvalue index");
  f1->u.l.uv[n1 - 1] = f2->u.l.uv[n2 - 1];
  return 0;
}

static int db_getregistry(lua_State *L)
{
  lua_pushvalue(L, LUA_REGISTRYINDEX);
  return 1;
}

static int db_getmetatable(lua_State *L)
{
  luaL_checkany(L, 1);
  if (!lua_getmetatable(L, 1)) lua_pushnil(L);
  return 1;
}

static int db_setmetatable(lua_State *L)
{
  int t = lua_type(L, 2);
  luaL_argcheck(L, t == LUA_TNIL || t == LUA_TTABLE, 2, "nil or table expected");
  lua_settop(L, 2);
  lua_pushboolean(L, lua_setmetatable(L, 1));
  return 1;
}

static int db_getfenv(lua_State *L)
{
  lua_getfenv(L, 1);
  return 1;
}

static int db_setfenv(lua_State *L)
{
  luaL_checktype(L, 2, LUA_TTABLE);
  lua_settop(L, 2);
  if (lua_setfenv(L, 1) == 0)
    luaL_error(L, "'setfenv' cannot change environment of given object");
  return 1;
}

/* -- Hooks --------------------------------------------------------------- */

#define HOOK_CALL 0
#define HOOK_RET 1
#define HOOK_LINE 2
#define HOOK_COUNT 3

void lj_debug_hookcall(lua_State *L, int event, int line)
{
  static const char *const hooknames[] = {"call", "return", "line", "count", "tail return"};
  TValue *top = L->top;
  ptrdiff_t topoff;
  CallInfo *ci = L->ci;
  ptrdiff_t citop = savestack(L, ci->top);
  lj_checkstack(L, LUA_MINSTACK);
  topoff = savestack(L, L->top);
  (void)top;
  L->allowhook = 0;
  lua_pushtv(L, &L->hookf);
  lua_pushstring(L, hooknames[event]);
  if (line >= 0) lua_pushinteger(L, line); else lua_pushnil(L);
  if (L->ci->top < L->top + LUA_MINSTACK) L->ci->top = L->top + LUA_MINSTACK;
  {
    extern int lj_vm_nextmm;
    lj_vm_call(L, L->top - 3, 0);
  }
  L->allowhook = 1;
  L->ci->top = restorestack(L, citop);
  L->top = restorestack(L, topoff);
}

static int makemask(const char *smask, int count)
{
  int mask = 0;
  if (strchr(smask, 'c')) mask |= (1 << HOOK_CALL);
  if (strchr(smask, 'r')) mask |= (1 << HOOK_RET);
  if (strchr(smask, 'l')) mask |= (1 << HOOK_LINE);
  if (count > 0) mask |= (1 << HOOK_COUNT);
  return mask;
}

static char *unmakemask(int mask, char *smask)
{
  int i = 0;
  if (mask & (1 << HOOK_CALL)) smask[i++] = 'c';
  if (mask & (1 << HOOK_RET)) smask[i++] = 'r';
  if (mask & (1 << HOOK_LINE)) smask[i++] = 'l';
  smask[i] = '\0';
  return smask;
}

static int db_sethook(lua_State *L)
{
  int arg, mask, count;
  lua_State *L1 = getthread(L, &arg);
  if (lua_isnoneornil(L, arg + 1)) {
    lua_settop(L, arg + 1);
    mask = 0;
    count = 0;
    setnilV(&L1->hookf);
  } else {
    const char *smask = luaL_checkstring(L, arg + 2);
    luaL_checktype(L, arg + 1, LUA_TFUNCTION);
    count = luaL_optint(L, arg + 3, 0);
    mask = makemask(smask, count);
    copyTV(&L1->hookf, index2adr(L, arg + 1));
  }
  L1->hookmask = (uint8_t)mask;
  L1->basehookcount = count;
  L1->hookcount = count;
  /* Make sure the current Lua frame does not trigger a line event for
  ** the rest of its current line. */
  return 0;
}

static int db_gethook(lua_State *L)
{
  int arg;
  lua_State *L1 = getthread(L, &arg);
  char buff[5];
  int mask = L1->hookmask;
  if (tvisnil(&L1->hookf)) lua_pushnil(L);
  else lua_pushtv(L, &L1->hookf);
  lua_pushstring(L, unmakemask(mask, buff));
  lua_pushinteger(L, L1->basehookcount);
  return 3;
}

static int db_debug(lua_State *L)
{
  for (;;) {
    char buffer[250];
    fputs("lua_debug> ", stderr);
    fflush(stderr);
    if (fgets(buffer, sizeof(buffer), stdin) == 0 || strcmp(buffer, "cont\n") == 0)
      return 0;
    if (luaL_loadbuffer(L, buffer, strlen(buffer), "=(debug command)") ||
        lua_pcall(L, 0, 0, 0)) {
      const char *s = lua_tostring(L, -1);
      fputs(s ? s : "(error object is not a string)", stderr);
      fputs("\n", stderr);
      fflush(stderr);
    }
    lua_settop(L, 0);
  }
}

/* -- Traceback --------------------------------------------------------- */

#define LEVELS1 12
#define LEVELS2 10

void luaL_traceback(lua_State *L, lua_State *L1, const char *msg, int level)
{
  luaL_Buffer b;
  CallInfo *ci;
  int top = 1;
  int lim;
  int nlevels = 0;
  CallInfo *c2;
  luaL_buffinit(L, &b);
  if (msg) {
    luaL_addstring(&b, msg);
    luaL_addchar(&b, '\n');
  }
  luaL_addstring(&b, "stack traceback:");
  /* Count levels. */
  for (c2 = L1->ci; c2 > L1->base_ci; c2--) nlevels++;
  lim = LEVELS1;
  while (lj_debug_getstack(L1, level, &ci)) {
    DebugInfo ar;
    GCfunc *fn;
    char buf[512];
    if (level > lim && top) {
      /* Skip middle levels if too many. */
      int remaining = nlevels - level;
      if (remaining > LEVELS2) {
        luaL_addstring(&b, "\n\t...");
        level = nlevels - LEVELS2;
        top = 0;
        continue;
      }
      top = 0;
    }
    level++;
    if (!tvisfunc(ci->func)) continue;
    fn = funcV(ci->func);
    memset(&ar, 0, sizeof(ar));
    funcinfo(&ar, fn);
    luaL_addstring(&b, "\n\t");
    if (fn->isC) {
      luaL_addstring(&b, "[C]:");
    } else {
      int line = lj_debug_currentline(L1, ci);
      if (line > 0 || line == 0)
        snprintf(buf, sizeof(buf), "%s:%d:", ar.short_src, line);
      else
        snprintf(buf, sizeof(buf), "%s:", ar.short_src);
      luaL_addstring(&b, buf);
    }
    {
      const char *name = NULL;
      const char *what = lj_debug_funcname(L1, ci, &name);
      if (what && name) {
        snprintf(buf, sizeof(buf), " in function '%s'", name);
        luaL_addstring(&b, buf);
      } else if (*ar.what == 'm') {
        luaL_addstring(&b, " in main chunk");
      } else if (*ar.what == 'C') {
        snprintf(buf, sizeof(buf), " at %p", (void *)fn->u.c.f);
        luaL_addstring(&b, buf);
      } else {
        snprintf(buf, sizeof(buf), " in function <%s:%d>", ar.short_src, ar.linedefined);
        luaL_addstring(&b, buf);
      }
    }
  }
  luaL_pushresult(&b);
}

static int db_traceback(lua_State *L)
{
  int arg;
  lua_State *L1 = getthread(L, &arg);
  const char *msg = lua_tostring(L, arg + 1);
  if (msg == NULL && !lua_isnoneornil(L, arg + 1)) {
    lua_pushvalue(L, arg + 1);
  } else if (msg == NULL && L->top > L->base + arg) {
    /* Explicit nil message: return nil (reference behavior). */
    lua_pushnil(L);
  } else {
    int level = luaL_optint(L, arg + 2, (L == L1) ? 1 : 0);
    luaL_traceback(L, L1, msg, level);
  }
  return 1;
}

int luaopen_debug(lua_State *L)
{
  static const LJLibReg funcs[] = {
    {"getregistry", db_getregistry, 127},
    {"getmetatable", db_getmetatable, 128},
    {"setmetatable", db_setmetatable, 129},
    {"getfenv", db_getfenv, 130},
    {"setfenv", db_setfenv, 131},
    {"getinfo", db_getinfo, 132},
    {"getlocal", db_getlocal, 133},
    {"setlocal", db_setlocal, 134},
    {"getupvalue", db_getupvalue, 135},
    {"setupvalue", db_setupvalue, 136},
    {"upvalueid", db_upvalueid, 137},
    {"upvaluejoin", db_upvaluejoin, 138},
    {"sethook", db_sethook, 139},
    {"gethook", db_gethook, 140},
    {"debug", db_debug, 141},
    {"traceback", db_traceback, 142},
    {NULL, NULL, 0}
  };
  lj_lib_register(L, "debug", funcs);
  return 1;
}
EOF
echo ok"}

