}

/* -- Hooks --------------------------------------------------------------- */

#define HOOK_CALL 0
#define HOOK_RET 1
#define HOOK_LINE 2
#define HOOK_COUNT 3

void lj_debug_hookcall(lua_State *L, int event, int line)
{
  static const char *const hooknames[] = {"call", "return", "line", "count", "tail return"};
  TValue *top = L->top;
  ptrdiff_t topoff;
  CallInfo *ci = L->ci;
  ptrdiff_t citop = savestack(L, ci->top);
  lj_checkstack(L, LUA_MINSTACK);
  topoff = savestack(L, L->top);
  (void)top;
  L->allowhook = 0;
  lua_pushtv(L, &L->hookf);
  lua_pushstring(L, hooknames[event]);
  if (line >= 0) lua_pushinteger(L, line); else lua_pushnil(L);
  if (L->ci->top < L->top + LUA_MINSTACK) L->ci->top = L->top + LUA_MINSTACK;
  {
    extern int lj_vm_nextmm;
    lj_vm_call(L, L->top - 3, 0);
  }
  L->allowhook = 1;
  L->ci->top = restorestack(L, citop);
  L->top = restorestack(L, topoff);
}

static int makemask(const char *smask, int count)
{
  int mask = 0;
  if (strchr(smask, 'c')) mask |= (1 << HOOK_CALL);
  if (strchr(smask, 'r')) mask |= (1 << HOOK_RET);
  if (strchr(smask, 'l')) mask |= (1 << HOOK_LINE);
  if (count > 0) mask |= (1 << HOOK_COUNT);
  return mask;
}

static char *unmakemask(int mask, char *smask)
{
  int i = 0;
  if (mask & (1 << HOOK_CALL)) smask[i++] = 'c';
  if (mask & (1 << HOOK_RET)) smask[i++] = 'r';
  if (mask & (1 << HOOK_LINE)) smask[i++] = 'l';
  smask[i] = '\0';
  return smask;
}

static int db_sethook(lua_State *L)
{
  int arg, mask, count;
  lua_State *L1 = getthread(L, &arg);
  if (lua_isnoneornil(L, arg + 1)) {
    lua_settop(L, arg + 1);
    mask = 0;
    count = 0;
    setnilV(&L1->hookf);
  } else {
    const char *smask = luaL_checkstring(L, arg + 2);
    luaL_checktype(L, arg + 1, LUA_TFUNCTION);
    count = luaL_optint(L, arg + 3, 0);
    mask = makemask(smask, count);
    copyTV(&L1->hookf, index2adr(L, arg + 1));
  }
  L1->hookmask = (uint8_t)mask;
  L1->basehookcount = count;
  L1->hookcount = count;
  /* Make sure the current Lua frame does not trigger a line event for
  ** the rest of its current line. */
  return 0;
}

static int db_gethook(lua_State *L)
{
  int arg;
  lua_State *L1 = getthread(L, &arg);
  char buff[5];
  int mask = L1->hookmask;
  if (tvisnil(&L1->hookf)) lua_pushnil(L);
  else lua_pushtv(L, &L1->hookf);
  lua_pushstring(L, unmakemask(mask, buff));
  lua_pushinteger(L, L1->basehookcount);
  return 3;
}

static int db_debug(lua_State *L)
{
  for (;;) {
    char buffer[250];
    fputs("lua_debug> ", stderr);
    fflush(stderr);
    if (fgets(buffer, sizeof(buffer), stdin) == 0 || strcmp(buffer, "cont\n") == 0)
      return 0;
    if (luaL_loadbuffer(L, buffer, strlen(buffer), "=(debug command)") ||
        lua_pcall(L, 0, 0, 0)) {
      const char *s = lua_tostring(L, -1);
      fputs(s ? s : "(error object is not a string)", stderr);
      fputs("\n", stderr);
      fflush(stderr);
    }
    lua_settop(L, 0);
  }
}

/* -- Traceback --------------------------------------------------------- */

#define LEVELS1 12
#define LEVELS2 10

void luaL_traceback(lua_State *L, lua_State *L1, const char *msg, int level)
{
  luaL_Buffer b;
  CallInfo *ci;
  int top = 1;
  int lim;
  int nlevels = 0;
  CallInfo *c2;
  luaL_buffinit(L, &b);
  if (msg) {
    luaL_addstring(&b, msg);
    luaL_addchar(&b, '\n');
  }
  luaL_addstring(&b, "stack traceback:");
  /* Count levels. */
  for (c2 = L1->ci; c2 > L1->base_ci; c2--) nlevels++;
  lim = LEVELS1;
  while (lj_debug_getstack(L1, level, &ci)) {
    DebugInfo ar;
    GCfunc *fn;
    char buf[512];
    if (level > lim && top) {
      /* Skip middle levels if too many. */
      int remaining = nlevels - level;
      if (remaining > LEVELS2) {
        luaL_addstring(&b, "\n\t...");
        level = nlevels - LEVELS2;
        top = 0;
        continue;
      }
      top = 0;
    }
    level++;
    if (!tvisfunc(ci->func)) continue;
    fn = funcV(ci->func);
    memset(&ar, 0, sizeof(ar));
    funcinfo(&ar, fn);
    luaL_addstring(&b, "\n\t");
    if (fn->isC) {
      luaL_addstring(&b, "[C]:");
    } else {
      int line = lj_debug_currentline(L1, ci);
      if (line > 0 || line == 0)
        snprintf(buf, sizeof(buf), "%s:%d:", ar.short_src, line);
      else
        snprintf(buf, sizeof(buf), "%s:", ar.short_src);
      luaL_addstring(&b, buf);
    }
    {
      const char *name = NULL;
      const char *what = lj_debug_funcname(L1, ci, &name);
      if (what && name) {
        snprintf(buf, sizeof(buf), " in function '%s'", name);
        luaL_addstring(&b, buf);
      } else if (*ar.what == 'm') {
        luaL_addstring(&b, " in main chunk");
      } else if (*ar.what == 'C') {
        snprintf(buf, sizeof(buf), " at %p", (void *)fn->u.c.f);
        luaL_addstring(&b, buf);
      } else {
        snprintf(buf, sizeof(buf), " in function <%s:%d>", ar.short_src, ar.linedefined);
        luaL_addstring(&b, buf);
      }
    }
  }
  luaL_pushresult(&b);
}

static int db_traceback(lua_State *L)
{
  int arg;
  lua_State *L1 = getthread(L, &arg);
  const char *msg = lua_tostring(L, arg + 1);
  if (msg == NULL && !lua_isnoneornil(L, arg + 1)) {
    lua_pushvalue(L, arg + 1);
  } else if (msg == NULL && L->top > L->base + arg) {
    /* Explicit nil message: return nil (reference behavior). */
    lua_pushnil(L);
  } else {
    int level = luaL_optint(L, arg + 2, (L == L1) ? 1 : 0);
    luaL_traceback(L, L1, msg, level);
  }
  return 1;
}

