static void setpath(lua_State *L, const char *fieldname, const char *envname, const char *def)
{
  const char *path = lj_ignore_env ? NULL : getenv(envname);
  if (path == NULL) {
    lua_pushstring(L, def);
  } else {
    path = luaL_gsub(L, path, ";;", ";\1;");
    luaL_gsub(L, path, "\1", def);
    lua_remove(L, -2);
  }
