}

static const lua_CFunction package_loaders[] = {
  lj_cf_package_loader_preload,
  lj_cf_package_loader_lua,
  lj_cf_package_loader_c,
  lj_cf_package_loader_croot,
  NULL
};

int luaopen_package(lua_State *L)
{
  int i;
  GCfunc *pkgfn;
  luaL_newmetatable(L, "_LOADLIB");
  lua_pop(L, 1);
  /* Create package table; functions get it as environment. */
  lua_createtable(L, 0, 16);
  {
    static const luaL_Reg funcs[] = {
      {"loadlib", lj_cf_package_loadlib},
      {"searchpath", lj_cf_package_searchpath},
      {"seeall", lj_cf_package_seeall},
      {NULL, NULL}
    };
    const luaL_Reg *r;
    for (r = funcs; r->name; r++) {
      GCfunc *fn = lj_func_newC(L, 0, r->func, tabV(L->top - 1));
      lj_checkstack(L, 1);
      setfuncV(L->top, fn); L->top++;
      lua_setfield(L, -2, r->name);
    }
  }
