  for (i = 0; package_loaders[i] != NULL; i++) {
    GCfunc *fn = lj_func_newC(L, 0, package_loaders[i], tabV(L->top - 2));
    lj_checkstack(L, 1);
    setfuncV(L->top, fn); L->top++;
    lua_rawseti(L, -2, i + 1);
  }
  lua_setfield(L, -2, "loaders");
  setpath(L, "path", "LUA_PATH", LUA_PATH_DEFAULT);
  setpath(L, "cpath", "LUA_CPATH", LUA_CPATH_DEFAULT);
  lua_pushliteral(L, "/\n;\n?\n!\n-\n");
  lua_setfield(L, -2, "config");
  luaL_findtable(L, LUA_REGISTRYINDEX, "_LOADED", 16);
  lua_setfield(L, -2, "loaded");
  luaL_findtable(L, LUA_REGISTRYINDEX, "_PRELOAD", 4);
  lua_setfield(L, -2, "preload");
  /* package.loaded.package = package */
  lua_getfield(L, LUA_REGISTRYINDEX, "_LOADED");
  lua_pushvalue(L, -2);
  lua_setfield(L, -2, "package");
  lua_pop(L, 1);
  lua_pushvalue(L, -1);
  lua_setglobal(L, "package");
  /* Global functions module and require with package env. */
  pkgfn = lj_func_newC(L, 0, lj_cf_package_module, tabV(L->top - 1));
  lj_checkstack(L, 1);
  setfuncV(L->top, pkgfn); L->top++;
  lua_setglobal(L, "module");
  pkgfn = lj_func_newC(L, 0, lj_cf_package_require, tabV(L->top - 1));
  setfuncV(L->top, pkgfn); L->top++;
  lua_setglobal(L, "require");
  lua_pop(L, 1);
  return 0;
}
