{
  const char *f = searchpath(L, luaL_checkstring(L, 1), luaL_checkstring(L, 2),
                             luaL_optstring(L, 3, "."), luaL_optstring(L, 4, "/"));
  if (f != NULL) {
    return 1;
  } else {
    lua_pushnil(L);
    lua_insert(L, -2);
    return 2;
  }
}

