static int ll_loadfunc(lua_State *L, const char *path, const char *name, int r)
{
  void **reg = ll_register(L, path);
  if (*reg == NULL) {
    *reg = dlopen(path, RTLD_NOW | (*name == '*' ? RTLD_GLOBAL : RTLD_LOCAL));
    if (*reg == NULL) {
      lua_pushstring(L, dlerror());
      return 1;
    }
  }
  if (*name == '*') {
    lua_pushboolean(L, 1);
    return 0;
  } else {
    lua_CFunction f = (lua_CFunction)(uintptr_t)dlsym(*reg, name);
    if (f == NULL) {
      lua_pushstring(L, dlerror());
      return 2;
    }
    lua_pushcfunction(L, f);
    return 0;
  }
  (void)r;
}

