cat > main.c <<'EOF'
/* Standalone interpreter. */
#include <signal.h>
#include <unistd.h>
#include "lj.h"
#include "lj_api.h"

#define FLAGS_INTERACTIVE 1
#define FLAGS_VERSION 2
#define FLAGS_EXEC 4
#define FLAGS_OPTION 8
#define FLAGS_NOENV 16

static const char *progname = "luajit";
static lua_State *globalL = NULL;
extern int lj_ignore_env;

static void l_message(const char *msg)
{
  if (progname) {
    fputs(progname, stderr);
    fputc(':', stderr);
    fputc(' ', stderr);
  }
  fputs(msg, stderr);
  fputc('\n', stderr);
  fflush(stderr);
}

static int report(lua_State *L, int status)
{
  if (status && !lua_isnil(L, -1)) {
    const char *msg = lua_tostring(L, -1);
    if (msg == NULL) msg = "(error object is not a string)";
    l_message(msg);
    lua_pop(L, 1);
  }
  return status;
}

static int traceback(lua_State *L)
{
  if (!lua_isstring(L, 1)) {
    if (lua_isnoneornil(L, 1) || !luaL_callmeta(L, 1, "__tostring") || !lua_isstring(L, -1))
      return 1;
    lua_remove(L, 1);
  }
  luaL_traceback(L, L, lua_tostring(L, 1), 1);
  return 1;
}

static int docall(lua_State *L, int narg, int clear)
{
  int status;
  int base = lua_gettop(L) - narg;
  lua_pushcfunction(L, traceback);
  lua_insert(L, base);
  status = lua_pcall(L, narg, (clear ? 0 : LUA_MULTRET), base);
  lua_remove(L, base);
  if (status != 0) lua_gc(L, LUA_GCCOLLECT, 0);
  return status;
}

static void print_version(void)
{
  fputs("LuaJIT 2.1.1772570160 -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/\n", stdout);
  fflush(stdout);
}

static void print_usage(void)
{
  fputs("usage: ", stderr);
  fputs(progname, stderr);
  fputs(" [options]... [script [args]...].\n"
        "Available options are:\n"
        "  -e chunk  Execute string 'chunk'.\n"
        "  -l name   Require library 'name'.\n"
        "  -b ...    Save or list bytecode.\n"
        "  -j cmd    Perform LuaJIT control command.\n"
        "  -O[opt]   Control LuaJIT optimizations.\n"
        "  -i        Enter interactive mode after executing 'script'.\n"
        "  -v        Show version information.\n"
        "  -E        Ignore environment variables.\n"
        "  --        Stop handling options.\n"
        "  -         Execute stdin and stop handling options.\n", stderr);
  fflush(stderr);
}

static void print_jit_status(lua_State *L)
{
  int n;
  const char *s;
  lua_getfield(L, LUA_REGISTRYINDEX, "_LOADED");
  lua_getfield(L, -1, "jit");
  lua_remove(L, -2);
  lua_getfield(L, -1, "status");
  lua_remove(L, -2);
  n = lua_gettop(L);
  lua_call(L, 0, LUA_MULTRET);
  fputs(lua_toboolean(L, n) ? "JIT: ON" : "JIT: OFF", stdout);
  for (n++; (s = lua_tostring(L, n)); n++) {
    putc(' ', stdout);
    fputs(s, stdout);
  }
  putc('\n', stdout);
  fflush(stdout);
  lua_settop(L, 0);
}

static void createargtable(lua_State *L, char **argv, int argc, int argf)
{
  int i;
  lua_createtable(L, argc - argf, argf);
  for (i = 0; i < argc; i++) {
    lua_pushstring(L, argv[i]);
    lua_rawseti(L, -2, i - argf);
  }
  lua_setglobal(L, "arg");
}

static int dofile(lua_State *L, const char *name)
{
  int status = luaL_loadfile(L, name) || docall(L, 0, 1);
  return report(L, status);
}

static int dostring(lua_State *L, const char *s, const char *name)
{
  int status = luaL_loadbuffer(L, s, strlen(s), name) || docall(L, 0, 1);
  return report(L, status);
}

static int dolibrary(lua_State *L, const char *name)
{
  lua_getglobal(L, "require");
  lua_pushstring(L, name);
  return report(L, docall(L, 1, 1));
}

static void write_prompt(lua_State *L, int firstline)
{
  const char *p;
  lua_getfield(L, LUA_GLOBALSINDEX, firstline ? "_PROMPT" : "_PROMPT2");
  p = lua_tostring(L, -1);
  if (p == NULL) p = firstline ? "> " : ">> ";
  fputs(p, stdout);
  fflush(stdout);
  lua_pop(L, 1);
}

static int incomplete(lua_State *L, int status)
{
  if (status == LUA_ERRSYNTAX) {
    size_t lmsg;
    const char *msg = lua_tolstring(L, -1, &lmsg);
    const char *tp = msg + lmsg - (sizeof("'<eof>'") - 1);
    if (lmsg >= sizeof("'<eof>'") - 1 && strstr(msg, "'<eof>'") == tp) {
      lua_pop(L, 1);
      return 1;
    }
  }
  return 0;
}

static int pushline(lua_State *L, int firstline)
{
  char buf[512];
  write_prompt(L, firstline);
  if (fgets(buf, sizeof(buf), stdin)) {
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') buf[len - 1] = '\0';
    if (firstline && buf[0] == '=')
      lua_pushfstring(L, "return %s", buf + 1);
    else
      lua_pushstring(L, buf);
    return 1;
  }
  return 0;
}

static int loadline(lua_State *L)
{
  int status;
  lua_settop(L, 0);
  if (!pushline(L, 1)) return -1;
  for (;;) {
    status = luaL_loadbuffer(L, lua_tostring(L, 1), lua_strlen(L, 1), "=stdin");
    if (!incomplete(L, status)) break;
    if (!pushline(L, 0)) return -1;
    lua_pushliteral(L, "\n");
    lua_insert(L, -2);
    lua_concat(L, 3);
  }
  lua_remove(L, 1);
  return status;
}

static void dotty(lua_State *L)
{
  int status;
  const char *oldprogname = progname;
  progname = NULL;
  while ((status = loadline(L)) != -1) {
    if (status == 0) status = docall(L, 0, 0);
    report(L, status);
    if (status == 0 && lua_gettop(L) > 0) {
      lua_getglobal(L, "print");
      lua_insert(L, 1);
      if (lua_pcall(L, lua_gettop(L) - 1, 0, 0) != 0)
        l_message(lua_pushfstring(L, "error calling 'print' (%s)", lua_tostring(L, -1)));
    }
  }
  lua_settop(L, 0);
  fputs("\n", stdout);
  fflush(stdout);
  progname = oldprogname;
}

static int handle_script(lua_State *L, char **argx)
{
  int status;
  const char *fname = argx[0];
  if (strcmp(fname, "-") == 0 && strcmp(argx[-1], "--") != 0)
    fname = NULL;
  status = luaL_loadfile(L, fname);
  if (status == 0) {
    int narg = 0;
    lua_getglobal(L, "arg");
    if (lua_istable(L, -1)) {
      do {
        narg++;
        lua_rawgeti(L, -narg, narg);
      } while (!lua_isnil(L, -1));
      lua_pop(L, 1);
      lua_remove(L, -narg);
      narg--;
    } else {
      lua_pop(L, 1);
    }
    status = docall(L, narg, 0);
  }
  return report(L, status);
}

static int loadjitmodule(lua_State *L)
{
  lua_getglobal(L, "require");
  lua_pushliteral(L, "jit.");
  lua_pushvalue(L, -3);
  lua_concat(L, 2);
  if (lua_pcall(L, 1, 1, 0)) {
    const char *msg = lua_tostring(L, -1);
    if (msg && !strncmp(msg, "module ", 7)) goto nomodule;
    return report(L, 1);
  }
  lua_getfield(L, -1, "start");
  if (lua_isnil(L, -1)) {
  nomodule:
    l_message("unknown luaJIT command or jit.* modules not installed");
    return 1;
  }
  lua_remove(L, -2);
  return 0;
}

static int runcmdopt(lua_State *L, const char *opt)
{
  int narg = 0;
  if (opt && *opt) {
    for (;;) {
      const char *p = strchr(opt, ',');
      narg++;
      if (!p) break;
      if (p == opt) lua_pushnil(L); else lua_pushlstring(L, opt, (size_t)(p - opt));
      opt = p + 1;
    }
    if (*opt) lua_pushstring(L, opt); else lua_pushnil(L);
  }
  return report(L, lua_pcall(L, narg, 0, 0));
}

static int dojitcmd(lua_State *L, const char *cmd)
{
  const char *opt = strchr(cmd, '=');
  lua_pushlstring(L, cmd, opt ? (size_t)(opt - cmd) : strlen(cmd));
  lua_getfield(L, LUA_REGISTRYINDEX, "_LOADED");
  lua_getfield(L, -1, "jit");
  lua_remove(L, -2);
  lua_pushvalue(L, -2);
  lua_gettable(L, -2);
  if (!lua_isfunction(L, -1)) {
    lua_pop(L, 2);
    if (loadjitmodule(L)) return 1;
  } else {
    lua_remove(L, -2);
  }
  lua_remove(L, -2);
  return runcmdopt(L, opt ? opt + 1 : opt);
}

static int dojitopt(lua_State *L, const char *opt)
{
  lua_getfield(L, LUA_REGISTRYINDEX, "_LOADED");
  lua_getfield(L, -1, "jit.opt");
  lua_remove(L, -2);
  lua_getfield(L, -1, "start");
  lua_remove(L, -2);
  return runcmdopt(L, opt);
}

static int dobytecode(lua_State *L, char **argv)
{
  (void)argv;
  lua_pushliteral(L, "bcsave");
  if (loadjitmodule(L)) return 1;
  return 0;
}

static int collectargs(char **argv, int *flags)
{
  int i;
  for (i = 1; argv[i] != NULL; i++) {
    if (argv[i][0] != '-') return i;
    switch (argv[i][1]) {
    case '-':
      if (argv[i][2] != '\0') return -1;
      return i + 1;
    case '\0':
      return i;
    case 'i':
      if (argv[i][2] != '\0') return -1;
      *flags |= FLAGS_INTERACTIVE;
      /* fallthrough */
    case 'v':
      if (argv[i][2] != '\0') return -1;
      *flags |= FLAGS_VERSION;
      break;
    case 'e':
      *flags |= FLAGS_EXEC;
      /* fallthrough */
    case 'j':
    case 'l':
      *flags |= FLAGS_OPTION;
      if (argv[i][2] == '\0') {
        i++;
        if (argv[i] == NULL) return -1;
      }
      break;
    case 'O':
      break;
    case 'b':
      if (*flags) return -1;
      *flags |= FLAGS_EXEC;
      return i + 1;
    case 'E':
      *flags |= FLAGS_NOENV;
      break;
    default:
      return -1;
    }
  }
  return i;
}

static int runargs(lua_State *L, char **argv, int argn)
{
  int i;
  for (i = 1; i < argn; i++) {
    if (argv[i] == NULL) continue;
    switch (argv[i][1]) {
    case 'e': {
      const char *chunk = argv[i] + 2;
      if (*chunk == '\0') chunk = argv[++i];
      if (dostring(L, chunk, "=(command line)") != 0) return 1;
      break;
    }
    case 'l': {
      const char *filename = argv[i] + 2;
      if (*filename == '\0') filename = argv[++i];
      if (dolibrary(L, filename)) return 1;
      break;
    }
    case 'j': {
      const char *cmd = argv[i] + 2;
      if (*cmd == '\0') cmd = argv[++i];
      if (dojitcmd(L, cmd)) return 1;
      break;
    }
    case 'O':
      if (dojitopt(L, argv[i] + 2)) return 1;
      break;
    case 'b':
      return dobytecode(L, argv + i);
    default:
      break;
    }
  }
  return 0;
}

static int handle_luainit(lua_State *L)
{
  const char *init = getenv("LUA_INIT");
  if (init == NULL) return 0;
  if (init[0] == '@')
    return dofile(L, init + 1);
  else
    return dostring(L, init, "=LUA_INIT");
}

static struct Smain {
  char **argv;
  int argc;
  int status;
} smain;

static int pmain(lua_State *L)
{
  struct Smain *s = &smain;
  char **argv = s->argv;
  int argn;
  int flags = 0;
  globalL = L;
  if (argv[0] && argv[0][0]) progname = argv[0];
  argn = collectargs(argv, &flags);
  if (argn < 0) {
    print_usage();
    s->status = 1;
    return 0;
  }
  if ((flags & FLAGS_NOENV)) {
    lj_ignore_env = 1;
    lua_pushboolean(L, 1);
    lua_setfield(L, LUA_REGISTRYINDEX, "LUA_NOENV");
  }
  lua_gc(L, LUA_GCSTOP, 0);
  luaL_openlibs(L);
  lua_gc(L, LUA_GCRESTART, -1);
  createargtable(L, argv, s->argc, argn);
  if (!(flags & FLAGS_NOENV)) {
    s->status = handle_luainit(L);
    if (s->status != 0) return 0;
  }
  if ((flags & FLAGS_VERSION)) print_version();
  s->status = runargs(L, argv, argn);
  if (s->status != 0) return 0;
  if (s->argc > argn) {
    s->status = handle_script(L, argv + argn);
    if (s->status != 0) return 0;
  }
  if ((flags & FLAGS_INTERACTIVE)) {
    print_jit_status(L);
    dotty(L);
  } else if (s->argc == argn && !(flags & (FLAGS_EXEC | FLAGS_VERSION))) {
    if (isatty(0)) {
      print_version();
      print_jit_status(L);
      dotty(L);
    } else {
      dofile(L, NULL);
    }
  }
  return 0;
}

static void close_state(lua_State *L)
{
  extern void lj_gc_freeall(lua_State *L);
  struct lua_longjmp;
  int status;
  (void)status;
  {
    /* Run all pending finalizers in protected mode. */
    extern int lj_err_rawrunprotected(lua_State *L, void (*f)(lua_State *L, void *ud), void *ud);
    struct { int dummy; } d;
    (void)d;
  }
  lj_gc_freeall(L);
}

static void f_close(lua_State *L, void *ud)
{
  (void)ud;
  close_state(L);
}

void lj_main_exit(lua_State *L, int status, int closestate)
{
  if (closestate) {
    lua_State *ML = G(L)->mainthread;
    lj_err_rawrunprotected(ML, f_close, NULL);
  }
  fflush(stdout);
  fflush(stderr);
  exit(status);
}

static int main_status;

static void real_main(void *ud)
{
  lua_State *L;
  int status;
  (void)ud;
  L = lj_state_newmain();
  if (L == NULL) {
    l_message("cannot create state: not enough memory");
    main_status = EXIT_FAILURE;
    return;
  }
  {
    extern char *lj_co_mainstack_base(void);
    char *base = lj_co_mainstack_base();
    L->cstack_limit = base ? base + 512 * 1024 : NULL;
    if (!base) {
      char probe;
      L->cstack_limit = &probe - 7 * 1024 * 1024;
    }
  }
  status = lua_cpcall(L, pmain, NULL);
  report(L, status);
  {
    int st = lj_err_rawrunprotected(L, f_close, NULL);
    (void)st;
  }
  fflush(stdout);
  main_status = (status || smain.status > 0) ? EXIT_FAILURE : EXIT_SUCCESS;
}

extern void lj_co_runmain(void (*fn)(void *), void *arg, size_t stacksize);

int main(int argc, char **argv)
{
  smain.argc = argc;
  smain.argv = argv;
  signal(SIGPIPE, SIG_DFL);
  lj_co_runmain(real_main, NULL, (size_t)1024 * 1024 * 1024);
  return main_status;
}
