  CT_TYPEDEF, CT_FIELD, CT_CONSTVAL, CT_EXTERN, CT_KW, CT_REF
};

#define CTF_CONST     0x0001
#define CTF_VOLATILE  0x0002
#define CTF_UNSIGNED  0x0004
#define CTF_FP        0x0008
#define CTF_BOOL      0x0010
#define CTF_VLA       0x0020
#define CTF_COMPLEX   0x0040
#define CTF_UNION     0x0080
#define CTF_VARARG    0x0100
#define CTF_INCOMPLETE 0x0200
#define CTF_VECTOR    0x0400
#define CTF_BITFIELD  0x0800
#define CTF_PACKED    0x1000
#define CTF_LONG      0x2000
#define CTF_QUAL (CTF_CONST | CTF_VOLATILE)

#define CTSIZE_INVALID 0xffffffffu

typedef struct CType {
  uint8_t kind;
  uint32_t flags;
  CTypeID cid;       /* child type */
  uint32_t size;
  uint32_t align;
  uint32_t nelem;    /* array length; for bitfields: bit size */
  GCstr *name;
  CTypeID next;      /* next field/param/constant in chain */
  CTypeID first;     /* first field/param/constant (struct/func/enum) */
  int64_t value;     /* field offset, constant value */
  uint32_t bitpos;
  uint32_t bitsize;
  void *addr;        /* resolved address for externs */
  uint32_t hnext;    /* intern hash chain */
} CType;

/* Predefined type ids. */
enum {
  CTID_NONE, CTID_VOID, CTID_CVOID, CTID_BOOL, CTID_CCHAR, CTID_INT8, CTID_UINT8,
  CTID_INT16, CTID_UINT16, CTID_INT32, CTID_UINT32, CTID_INT64, CTID_UINT64,
