  CTID_CTYPEID, CTID_LONGDOUBLE,
  CTID_PREDEF_MAX = 102
};

typedef struct CTState {
  CType *tab;
  uint32_t top;
  uint32_t sizetab;
  uint32_t *hash;     /* intern hash buckets */
  GCtab *tags;        /* struct/union/enum tag name -> id */
  GCtab *names;       /* typedef / extern / constant name -> id */
  GCtab *metatypes;   /* id -> metatable */
  GCtab *cbfuncs;     /* callback slot -> Lua function */
