/* FFI library: C type system, C declaration parser, conversions,
** cdata operations, C calls and callbacks. */
#include <stdarg.h>
#include <ctype.h>
#include <errno.h>
#include <dlfcn.h>
#include <sys/mman.h>
#include "lj.h"
#include "lj_api.h"
#include "lj_ffi.h"

static CTState *g_cts = NULL;

/* ======================================================================== */
/* -- C type table ------------------------------------------------------- */

#define CTHASH_SIZE 1024

static CTypeID cts_add(CTState *cts, uint8_t kind, uint32_t flags, CTypeID cid, uint32_t size, uint32_t align)
{
  CType *ct;
  CTypeID id;
  if (cts->top >= cts->sizetab) {
    uint32_t nsz = cts->sizetab * 2;
    cts->tab = (CType *)realloc(cts->tab, nsz * sizeof(CType));
    if (!cts->tab) abort();
    cts->sizetab = nsz;
  }
  if (cts->top >= 0x7fffff00) lj_err_msg(cts->L, "table overflow");
  id = cts->top++;
  ct = &cts->tab[id];
  memset(ct, 0, sizeof(CType));
  ct->kind = kind;
  ct->flags = flags;
  ct->cid = cid;
  ct->size = size;
  ct->align = align;
  return id;
}

CTypeID lj_ctype_new(CTState *cts, CType **ctp)
{
  CTypeID id = cts_add(cts, CT_KW, 0, 0, 0, 1);
  *ctp = &cts->tab[id];
  return id;
}

static uint32_t ct_hash(uint8_t kind, uint32_t flags, CTypeID cid, uint32_t size, uint32_t nelem)
{
  uint32_t h = kind * 0x9e3779b1u ^ flags * 0x85ebca6bu ^ cid * 0xc2b2ae35u ^ size * 0x27d4eb2fu ^ nelem * 0x165667b1u;
  h ^= h >> 15;
  return h & (CTHASH_SIZE - 1);
}

CTypeID lj_ctype_intern(CTState *cts, uint8_t kind, uint32_t flags, CTypeID cid, uint32_t size, uint32_t align, uint32_t nelem)
{
  uint32_t h = ct_hash(kind, flags, cid, size, nelem);
  CTypeID id = cts->hash[h];
  while (id) {
    CType *ct = &cts->tab[id];
    if (ct->kind == kind && ct->flags == flags && ct->cid == cid && ct->size == size &&
        ct->nelem == nelem && ct->align == align)
      return id;
    id = ct->hnext;
  }
  id = cts_add(cts, kind, flags, cid, size, align);
  cts->tab[id].nelem = nelem;
  cts->tab[id].hnext = cts->hash[h];
  cts->hash[h] = id;
  return id;
}

/* Resolve typedefs. */
CTypeID lj_ctype_rawid(CTState *cts, CTypeID id)
{
  while (cts->tab[id].kind == CT_TYPEDEF) id = cts->tab[id].cid;
  return id;
}

CType *lj_ctype_raw(CTState *cts, CTypeID id)
{
  return &cts->tab[lj_ctype_rawid(cts, id)];
}

/* Unqualified struct id (qualified structs link to their original). */
static CTypeID ctype_unqual_struct(CTState *cts, CTypeID id)
{
  id = lj_ctype_rawid(cts, id);
  while ((cts->tab[id].kind == CT_STRUCT || cts->tab[id].kind == CT_ENUM) && (cts->tab[id].flags & CTF_QUAL) && cts->tab[id].cid)
    id = cts->tab[id].cid;
  return id;
}

static CTypeID ctype_qualify(CTState *cts, CTypeID id, uint32_t qual)
{
  CType *ct;
  if (!qual) return id;
  id = lj_ctype_rawid(cts, id);
  ct = &cts->tab[id];
  if ((ct->flags & qual) == qual) return id;
  if (ct->kind == CT_STRUCT || ct->kind == CT_ENUM) {
    CTypeID orig = ctype_unqual_struct(cts, id);
    CType *o = &cts->tab[orig];
    CTypeID nid = lj_ctype_intern(cts, o->kind, (ct->flags | qual) & ~CTF_INCOMPLETE, orig, o->size, o->align, 0);
    CType *n = &cts->tab[nid];
    n->first = o->first;
    n->name = o->name;
    if (o->flags & CTF_INCOMPLETE) n->flags |= 0;
    return nid;
  }
  if (ct->kind == CT_ARRAY) {
    /* Qualifier applies to the element type. */
    CTypeID e = ctype_qualify(cts, ct->cid, qual);
    return lj_ctype_intern(cts, CT_ARRAY, ct->flags, e, ct->size, ct->align, ct->nelem);
  }
  return lj_ctype_intern(cts, ct->kind, ct->flags | qual, ct->cid, ct->size, ct->align, ct->nelem);
}

uint32_t lj_ctype_size(CTState *cts, CTypeID id)
{
  CType *ct = lj_ctype_raw(cts, id);
  if (ct->kind == CT_STRUCT && (cts->tab[ctype_unqual_struct(cts, id)].flags & CTF_INCOMPLETE))
    return CTSIZE_INVALID;
  return ct->size;
}

static const char *const predef_typedefs[][2] = {
