  cts_add(cts, CT_VOID, CTF_CONST, 0, CTSIZE_INVALID, 1);               /* CVOID */
  cts_add(cts, CT_NUM, CTF_BOOL | CTF_UNSIGNED, 0, 1, 1);               /* BOOL */
  cts_add(cts, CT_NUM, CTF_CONST, 0, 1, 1);                             /* CCHAR */
  cts_add(cts, CT_NUM, 0, 0, 1, 1);                                     /* INT8 */
  cts_add(cts, CT_NUM, CTF_UNSIGNED, 0, 1, 1);                          /* UINT8 */
