  cts_add(cts, CT_NUM, CTF_UNSIGNED | CTF_LONG, 0, 8, 8);               /* UINT64 */
  cts_add(cts, CT_NUM, CTF_FP, 0, 4, 4);                                /* FLOAT */
  cts_add(cts, CT_NUM, CTF_FP, 0, 8, 8);                                /* DOUBLE */
  cts_add(cts, CT_ARRAY, CTF_COMPLEX, CTID_FLOAT, 8, 4);                /* COMPLEX_FLOAT */
  cts->tab[CTID_COMPLEX_FLOAT].nelem = 2;
  cts_add(cts, CT_ARRAY, CTF_COMPLEX, CTID_DOUBLE, 16, 8);              /* COMPLEX_DOUBLE */
