  cts_add(cts, CT_PTR, 0, CTID_CCHAR, 8, 8);                            /* P_CCHAR */
  cts_add(cts, CT_PTR, 0, CTID_UINT8, 8, 8);                            /* P_UINT8 */
  cts_add(cts, CT_ARRAY, CTF_CONST | CTF_VLA, CTID_CCHAR, CTSIZE_INVALID, 1); /* A_CCHAR */
  cts_add(cts, CT_ENUM, 0, CTID_INT32, 4, 4);                           /* CTYPEID */
  cts_add(cts, CT_NUM, CTF_FP, 0, 16, 16);                              /* LONGDOUBLE */
  /* Register interned entries in hash. */
  for (i = 1; i < (int)cts->top; i++) {
    CType *ct = &cts->tab[i];
    if (ct->kind == CT_NUM || ct->kind == CT_PTR || ct->kind == CT_VOID || ct->kind == CT_ARRAY) {
      uint32_t h = ct_hash(ct->kind, ct->flags, ct->cid, ct->size, ct->nelem);
      ct->hnext = cts->hash[h];
      cts->hash[h] = (uint32_t)i;
    }
  }
