}

/* Unqualified struct id (qualified structs link to their original). */
static CTypeID ctype_unqual_struct(CTState *cts, CTypeID id)
{
  id = lj_ctype_rawid(cts, id);
  while ((cts->tab[id].kind == CT_STRUCT || cts->tab[id].kind == CT_ENUM) && (cts->tab[id].flags & CTF_QUAL) && cts->tab[id].cid)
    id = cts->tab[id].cid;
  return id;
}

static CTypeID ctype_qualify(CTState *cts, CTypeID id, uint32_t qual)
{
  CType *ct;
  if (!qual) return id;
  id = lj_ctype_rawid(cts, id);
  ct = &cts->tab[id];
  if ((ct->flags & qual) == qual) return id;
  if (ct->kind == CT_STRUCT || ct->kind == CT_ENUM) {
    CTypeID orig = ctype_unqual_struct(cts, id);
    CType *o = &cts->tab[orig];
    CTypeID nid = lj_ctype_intern(cts, o->kind, (ct->flags | qual) & ~CTF_INCOMPLETE, orig, o->size, o->align, 0);
    CType *n = &cts->tab[nid];
    n->first = o->first;
    n->name = o->name;
    if (o->flags & CTF_INCOMPLETE) n->flags |= 0;
    return nid;
  }
  if (ct->kind == CT_ARRAY) {
    /* Qualifier applies to the element type. */
    CTypeID e = ctype_qualify(cts, ct->cid, qual);
    return lj_ctype_intern(cts, CT_ARRAY, ct->flags, e, ct->size, ct->align, ct->nelem);
  }
  return lj_ctype_intern(cts, ct->kind, ct->flags | qual, ct->cid, ct->size, ct->align, ct->nelem);
}

uint32_t lj_ctype_size(CTState *cts, CTypeID id)
{
  CType *ct = lj_ctype_raw(cts, id);
  if (ct->kind == CT_STRUCT && (cts->tab[ctype_unqual_struct(cts, id)].flags & CTF_INCOMPLETE))
    return CTSIZE_INVALID;
  return ct->size;
}

