static void cts_set_name(CTState *cts, GCtab *t, GCstr *name, CTypeID id)
{
  TValue *v = lj_tab_setstr(cts->L, t, name);
  setnumV(v, (double)id);
}

static CTypeID cts_get_name(CTState *cts, GCtab *t, GCstr *name)
{
