}

CTState *lj_ctype_state(lua_State *L)
{
  CTState *cts = g_cts;
  int i;
  if (cts) { cts->L = L; return cts; }
  cts = (CTState *)calloc(1, sizeof(CTState));
  cts->sizetab = 512;
  cts->tab = (CType *)calloc(cts->sizetab, sizeof(CType));
  cts->hash = (uint32_t *)calloc(CTHASH_SIZE, sizeof(uint32_t));
  cts->top = 0;
  cts->L = L;
  g_cts = cts;
  G(L)->ctstate = cts;
  cts->tags = lj_tab_new(L, 0, 6);
  cts->names = lj_tab_new(L, 0, 7);
  cts->metatypes = lj_tab_new(L, 0, 4);
  cts->cbfuncs = lj_tab_new(L, 0, 4);
  cts->miscmap = lj_tab_new(L, 0, 4);
  /* Predefined types (ids must match the enum). */
  cts_add(cts, CT_KW, 0, 0, 0, 1);                                      /* NONE */
  cts_add(cts, CT_VOID, 0, 0, CTSIZE_INVALID, 1);                       /* VOID */
  cts_add(cts, CT_VOID, CTF_CONST, 0, CTSIZE_INVALID, 1);               /* CVOID */
  cts_add(cts, CT_NUM, CTF_BOOL | CTF_UNSIGNED, 0, 1, 1);               /* BOOL */
  cts_add(cts, CT_NUM, CTF_CONST, 0, 1, 1);                             /* CCHAR */
  cts_add(cts, CT_NUM, 0, 0, 1, 1);                                     /* INT8 */
  cts_add(cts, CT_NUM, CTF_UNSIGNED, 0, 1, 1);                          /* UINT8 */
  cts_add(cts, CT_NUM, 0, 0, 2, 2);                                     /* INT16 */
  cts_add(cts, CT_NUM, CTF_UNSIGNED, 0, 2, 2);                          /* UINT16 */
  cts_add(cts, CT_NUM, 0, 0, 4, 4);                                     /* INT32 */
  cts_add(cts, CT_NUM, CTF_UNSIGNED, 0, 4, 4);                          /* UINT32 */
  cts_add(cts, CT_NUM, CTF_LONG, 0, 8, 8);                              /* INT64 */
  cts_add(cts, CT_NUM, CTF_UNSIGNED | CTF_LONG, 0, 8, 8);               /* UINT64 */
  cts_add(cts, CT_NUM, CTF_FP, 0, 4, 4);                                /* FLOAT */
  cts_add(cts, CT_NUM, CTF_FP, 0, 8, 8);                                /* DOUBLE */
  cts_add(cts, CT_ARRAY, CTF_COMPLEX, CTID_FLOAT, 8, 4);                /* COMPLEX_FLOAT */
  cts->tab[CTID_COMPLEX_FLOAT].nelem = 2;
  cts_add(cts, CT_ARRAY, CTF_COMPLEX, CTID_DOUBLE, 16, 8);              /* COMPLEX_DOUBLE */
  cts->tab[CTID_COMPLEX_DOUBLE].nelem = 2;
  cts_add(cts, CT_PTR, 0, CTID_VOID, 8, 8);                             /* P_VOID */
  cts_add(cts, CT_PTR, 0, CTID_CVOID, 8, 8);                            /* P_CVOID */
  cts_add(cts, CT_PTR, 0, CTID_CCHAR, 8, 8);                            /* P_CCHAR */
  cts_add(cts, CT_PTR, 0, CTID_UINT8, 8, 8);                            /* P_UINT8 */
  cts_add(cts, CT_ARRAY, CTF_CONST | CTF_VLA, CTID_CCHAR, CTSIZE_INVALID, 1); /* A_CCHAR */
  cts_add(cts, CT_ENUM, 0, CTID_INT32, 4, 4);                           /* CTYPEID */
  cts_add(cts, CT_NUM, CTF_FP, 0, 16, 16);                              /* LONGDOUBLE */
  /* Register interned entries in hash. */
  for (i = 1; i < (int)cts->top; i++) {
    CType *ct = &cts->tab[i];
    if (ct->kind == CT_NUM || ct->kind == CT_PTR || ct->kind == CT_VOID || ct->kind == CT_ARRAY) {
      uint32_t h = ct_hash(ct->kind, ct->flags, ct->cid, ct->size, ct->nelem);
      ct->hnext = cts->hash[h];
      cts->hash[h] = (uint32_t)i;
    }
  }
  while (cts->top < CTID_PREDEF_MAX) cts_add(cts, CT_KW, 0, 0, 0, 1);
  for (i = 0; predef_typedefs[i][0]; i++) {
    GCstr *s = lj_str_newz(L, predef_typedefs[i][0]);
    TValue *v = lj_tab_setstr(L, cts->miscmap, s);  /* predefined typedef names */
    setnumV(v, (double)(uintptr_t)predef_typedefs[i][1]);
  }
  return cts;
}

void lj_ffi_markstate(global_State *g, void (*mark)(GCobj *))
{
  CTState *cts = (CTState *)g->ctstate;
  uint32_t i;
  if (!cts) return;
  mark((GCobj *)cts->tags);
  mark((GCobj *)cts->names);
  mark((GCobj *)cts->metatypes);
  mark((GCobj *)cts->cbfuncs);
  mark((GCobj *)cts->miscmap);
  for (i = 0; i < cts->top; i++)
    if (cts->tab[i].name) mark((GCobj *)cts->tab[i].name);
}

/* -- Type representation --------------------------------------------------- */

typedef struct RBuf {
  char *b;
  size_t n, cap;
} RBuf;

static void rb_init(RBuf *r) { r->cap = 128; r->n = 0; r->b = (char *)malloc(r->cap); r->b[0] = 0; }
static void rb_free(RBuf *r) { free(r->b); }
static void rb_append(RBuf *r, const char *s)
{
  size_t l = strlen(s);
  if (r->n + l + 1 > r->cap) { while (r->n + l + 1 > r->cap) r->cap *= 2; r->b = (char *)realloc(r->b, r->cap); }
  memcpy(r->b + r->n, s, l + 1);
  r->n += l;
}
static void rb_prepend(RBuf *r, const char *s)
{
  size_t l = strlen(s);
  if (r->n + l + 1 > r->cap) { while (r->n + l + 1 > r->cap) r->cap *= 2; r->b = (char *)realloc(r->b, r->cap); }
  memmove(r->b + l, r->b, r->n + 1);
  memcpy(r->b, s, l);
  r->n += l;
}

static void numname(CType *ct, char *buf)
{
  uint32_t f = ct->flags;
  if (f & CTF_BOOL) { strcpy(buf, "bool"); return; }
  if (f & CTF_FP) {
    if (ct->size == 4) strcpy(buf, "float");
    else if (ct->size == 8) strcpy(buf, "double");
    else strcpy(buf, "long double");
    return;
  }
  switch (ct->size) {
  case 1: strcpy(buf, (f & CTF_UNSIGNED) ? "unsigned char" : "char"); break;
  case 2: strcpy(buf, (f & CTF_UNSIGNED) ? "unsigned short" : "short"); break;
  case 4: strcpy(buf, (f & CTF_UNSIGNED) ? "unsigned int" : "int"); break;
  case 8: strcpy(buf, (f & CTF_UNSIGNED) ? "uint64_t" : "int64_t"); break;
  default: sprintf(buf, "int%u_t?", ct->size * 8); break;
  }
}

static void qualstr(uint32_t flags, char *buf)
{
  buf[0] = 0;
  if (flags & CTF_CONST) strcat(buf, "const ");
  if (flags & CTF_VOLATILE) strcat(buf, "volatile ");
}

static void repr_type(CTState *cts, CTypeID id, RBuf *r)
{
  /* r contains the inner declarator part. */
  int needspace = r->n > 0;
  for (;;) {
    CType *ct = &cts->tab[id];
    char buf[96], q[32];
    switch (ct->kind) {
    case CT_TYPEDEF:
      id = ct->cid;
      continue;
    case CT_PTR:
    case CT_REF: {
      CType *ch = lj_ctype_raw(cts, ct->cid);
      if (ct->flags & CTF_CONST) rb_prepend(r, "const");
      if (ct->flags & CTF_VOLATILE) rb_prepend(r, "volatile");
      rb_prepend(r, ct->kind == CT_PTR ? "*" : "&");
      if (ch->kind == CT_ARRAY && !(ch->flags & CTF_COMPLEX)) { rb_prepend(r, "("); rb_append(r, ")"); }
      else if (ch->kind == CT_FUNC) { rb_prepend(r, "("); rb_append(r, ")"); }
      needspace = 1;
      id = ct->cid;
      continue;
    }
    case CT_ARRAY:
      if (ct->flags & CTF_COMPLEX) {
        qualstr(ct->flags, q);
        snprintf(buf, sizeof(buf), "%s%s", q, ct->cid == CTID_FLOAT || (lj_ctype_raw(cts, ct->cid)->size == 4) ? "complex float" : "complex");
        goto base;
      }
      if (ct->flags & CTF_VLA) rb_append(r, "[?]");
      else if (ct->size == CTSIZE_INVALID) rb_append(r, "[]");
      else { snprintf(buf, sizeof(buf), "[%u]", ct->nelem); rb_append(r, buf); }
      needspace = 1;
      id = ct->cid;
      continue;
    case CT_FUNC:
      rb_append(r, "()");
      needspace = 1;
      id = ct->cid;
      continue;
    case CT_NUM:
      qualstr(ct->flags, q);
      numname(ct, buf + 64);
      snprintf(buf, sizeof(buf) - 32, "%s%s", q, buf + 64);
      goto base;
    case CT_VOID:
      qualstr(ct->flags, q);
      snprintf(buf, sizeof(buf), "%svoid", q);
      goto base;
    case CT_STRUCT:
    case CT_ENUM: {
      CTypeID oid = ctype_unqual_struct(cts, id);
      const char *kw = ct->kind == CT_ENUM ? "enum" : (ct->flags & CTF_UNION) ? "union" : "struct";
      qualstr(ct->flags, q);
      if (cts->tab[oid].name)
        snprintf(buf, sizeof(buf), "%s%s %s", q, kw, strdata(cts->tab[oid].name));
      else
        snprintf(buf, sizeof(buf), "%s%s %u", q, kw, oid);
      goto base;
    }
    default:
      snprintf(buf, sizeof(buf), "?");
      goto base;
    }
  base:
    if (needspace && r->n > 0) rb_prepend(r, " ");
    rb_prepend(r, buf);
    return;
  }
}

GCstr *lj_ctype_repr(lua_State *L, CTypeID id, GCstr *name)
{
  RBuf r;
  GCstr *s;
  CTState *cts = lj_ctype_state(L);
  rb_init(&r);
  if (name) rb_append(&r, strdata(name));
  repr_type(cts, id, &r);
  s = lj_str_new(L, r.b, r.n);
  rb_free(&r);
  return s;
}

static const char *ctype_reprz(lua_State *L, CTypeID id)
{
  return strdata(lj_ctype_repr(L, id, NULL));
}
