/* ======================================================================== */
/* -- C declaration parser --------------------------------------------- */

enum {
  CTOK_EOF = 256, CTOK_IDENT, CTOK_INTEGER, CTOK_NUMBER, CTOK_STRING,
  CTOK_OROR, CTOK_ANDAND, CTOK_EQ, CTOK_NE, CTOK_LE, CTOK_GE, CTOK_SHL,
  CTOK_SHR, CTOK_DEREF, CTOK_ELLIPSIS
};

typedef struct CPValue {
  int64_t i;
  int isunsigned;
} CPValue;

typedef struct CPState {
  CTState *cts;
  lua_State *L;
  const char *p;
  const char *e;
  int c;
  int tok;
  GCstr *str;
  CPValue val;
  char text[256];
  int linenumber;
  TValue *param;
  TValue *paramend;
  int depth;
  uint32_t packstack[16];
  int packtop;
  uint32_t pack;
} CPState;

static LJ_NORET void cp_err(CPState *cp, const char *fmt, ...)
{
  char msg[512];
  va_list argp;
  GCstr *s;
  va_start(argp, fmt);
  vsnprintf(msg, sizeof(msg), fmt, argp);
  va_end(argp);
  if (cp->linenumber > 1)
    s = lj_str_pushf(cp->L, "%s at line %d", msg, cp->linenumber);
  else
    s = lj_str_newz(cp->L, msg);
  lj_err_callermsg(cp->L, strdata(s));
}

static const char *cp_tokstr(CPState *cp)
{
  if (cp->tok == CTOK_EOF) return "<eof>";
  return cp->text;
}

static LJ_NORET void cp_err_near(CPState *cp, const char *msg)
{
  cp_err(cp, "%s near '%s'", msg, cp_tokstr(cp));
}

static LJ_NORET void cp_err_expected(CPState *cp, int tok)
{
  char buf[64];
  if (tok == CTOK_IDENT) strcpy(buf, "'<identifier>' expected");
  else if (tok == CTOK_EOF) strcpy(buf, "'<eof>' expected");
  else if (tok == CTOK_INTEGER) strcpy(buf, "'<integer>' expected");
  else snprintf(buf, sizeof(buf), "'%c' expected", tok);
  cp_err_near(cp, buf);
}

static int cp_getc(CPState *cp)
{
  return cp->p < cp->e ? (unsigned char)*cp->p : -1;
}

static void cp_next(CPState *cp);

static int cp_escape(CPState *cp)
{
  int c = cp_getc(cp);
  cp->p++;
  switch (c) {
  case 'n': return '\n';
  case 't': return '\t';
  case 'r': return '\r';
  case 'a': return '\a';
  case 'b': return '\b';
  case 'f': return '\f';
  case 'v': return '\v';
  case 'e': return 27;
  case 'x': {
    int v = 0;
    while (isxdigit(cp_getc(cp))) {
      int d = cp_getc(cp);
      v = v * 16 + (isdigit(d) ? d - '0' : (tolower(d) - 'a' + 10));
      cp->p++;
    }
    return v & 255;
  }
  default:
    if (c >= '0' && c <= '7') {
      int v = c - '0';
      int k = 1;
      while (k < 3 && cp_getc(cp) >= '0' && cp_getc(cp) <= '7') {
        v = v * 8 + (cp_getc(cp) - '0');
        cp->p++;
        k++;
      }
      return v & 255;
    }
    return c;
  }
}

static void cp_next(CPState *cp)
{
  const char *start;
  for (;;) {
    int c = cp_getc(cp);
    if (c == -1) { cp->tok = CTOK_EOF; strcpy(cp->text, "<eof>"); return; }
    if (c == '\n') { cp->linenumber++; cp->p++; continue; }
    if (isspace(c)) { cp->p++; continue; }
    if (c == '/' && cp->p + 1 < cp->e && cp->p[1] == '/') {
      while (cp->p < cp->e && *cp->p != '\n') cp->p++;
      continue;
    }
    if (c == '/' && cp->p + 1 < cp->e && cp->p[1] == '*') {
      cp->p += 2;
      while (cp->p + 1 < cp->e && !(cp->p[0] == '*' && cp->p[1] == '/')) {
        if (*cp->p == '\n') cp->linenumber++;
        cp->p++;
      }
      cp->p += 2;
      continue;
    }
    if (c == '#') {
      /* Preprocessor line: handle #pragma pack, skip others. */
      const char *ls = cp->p;
      while (cp->p < cp->e && *cp->p != '\n') cp->p++;
      {
        size_t n = (size_t)(cp->p - ls);
        char line[256];
        if (n > 255) n = 255;
        memcpy(line, ls, n);
        line[n] = 0;
        if (strstr(line, "pragma") && strstr(line, "pack")) {
          char *q = strchr(line, '(');
          if (q) {
            q++;
            while (*q == ' ') q++;
            if (*q == ')') {
              cp->pack = 0;
            } else if (strncmp(q, "push", 4) == 0) {
              if (cp->packtop < 15) cp->packstack[cp->packtop++] = cp->pack;
              q = strchr(q, ',');
              if (q) cp->pack = (uint32_t)strtoul(q + 1, NULL, 0);
            } else if (strncmp(q, "pop", 3) == 0) {
              cp->pack = cp->packtop > 0 ? cp->packstack[--cp->packtop] : 0;
            } else {
              cp->pack = (uint32_t)strtoul(q, NULL, 0);
            }
          }
        }
      }
      continue;
    }
    break;
  }
  start = cp->p;
  {
    int c = cp_getc(cp);
    if (isalpha(c) || c == '_' || c >= 0x80) {
      size_t n;
      while (cp->p < cp->e && (isalnum((unsigned char)*cp->p) || *cp->p == '_' || (unsigned char)*cp->p >= 0x80)) cp->p++;
      n = (size_t)(cp->p - start);
      cp->str = lj_str_new(cp->L, start, n);
      if (n > 250) n = 250;
      memcpy(cp->text, start, n);
      cp->text[n] = 0;
      cp->tok = CTOK_IDENT;
      return;
    }
    if (isdigit(c) || (c == '.' && cp->p + 1 < cp->e && isdigit((unsigned char)cp->p[1]))) {
      size_t n;
      int isfloat = 0;
      while (cp->p < cp->e && (isalnum((unsigned char)*cp->p) || *cp->p == '.' ||
             ((*cp->p == '+' || *cp->p == '-') && cp->p > start && (cp->p[-1] == 'e' || cp->p[-1] == 'E') && !(start[0] == '0' && (start[1] == 'x' || start[1] == 'X'))))) {
        if (*cp->p == '.' ) isfloat = 1;
        cp->p++;
      }
      n = (size_t)(cp->p - start);
      if (n > 250) n = 250;
      memcpy(cp->text, start, n);
      cp->text[n] = 0;
      if (!isfloat && !(strchr(cp->text, 'e') && !(cp->text[0] == '0' && (cp->text[1] == 'x' || cp->text[1] == 'X')))) {
        char *ep;
        unsigned long long v = strtoull(cp->text, &ep, 0);
        int u = 0;
        while (*ep) {
          if (*ep == 'u' || *ep == 'U') u = 1;
          else if (*ep != 'l' && *ep != 'L') cp_err_near(cp, "malformed number");
          ep++;
        }
        cp->val.i = (int64_t)v;
        cp->val.isunsigned = u || v > 0x7fffffffffffffffULL;
        cp->tok = CTOK_INTEGER;
      } else {
        cp->val.i = (int64_t)strtod(cp->text, NULL);
        cp->val.isunsigned = 0;
        cp->tok = CTOK_NUMBER;
      }
      return;
    }
    if (c == '\'') {
      int v;
      cp->p++;
      v = cp_getc(cp);
      cp->p++;
      if (v == '\\') v = cp_escape(cp);
      if (cp_getc(cp) == '\'') cp->p++;
      cp->val.i = (int8_t)v;
      cp->val.isunsigned = 0;
      cp->tok = CTOK_INTEGER;
      snprintf(cp->text, sizeof(cp->text), "%.*s", (int)(cp->p - start), start);
      return;
    }
    if (c == '"') {
      char buf[1024];
      size_t n = 0;
      cp->p++;
      while (cp->p < cp->e && *cp->p != '"') {
        int ch = (unsigned char)*cp->p++;
        if (ch == '\\') ch = cp_escape(cp);
        if (n < sizeof(buf)) buf[n++] = (char)ch;
      }
      cp->p++;
      cp->str = lj_str_new(cp->L, buf, n);
      snprintf(cp->text, sizeof(cp->text), "%.*s", (int)((cp->p - start) > 200 ? 200 : (cp->p - start)), start);
      cp->tok = CTOK_STRING;
      return;
    }
    cp->p++;
    cp->text[0] = (char)c;
    cp->text[1] = 0;
    cp->tok = c;
    {
      int c2 = cp_getc(cp);
      switch (c) {
      case '|': if (c2 == '|') { cp->p++; cp->tok = CTOK_OROR; strcpy(cp->text, "||"); } break;
      case '&': if (c2 == '&') { cp->p++; cp->tok = CTOK_ANDAND; strcpy(cp->text, "&&"); } break;
      case '=': if (c2 == '=') { cp->p++; cp->tok = CTOK_EQ; strcpy(cp->text, "=="); } break;
      case '!': if (c2 == '=') { cp->p++; cp->tok = CTOK_NE; strcpy(cp->text, "!="); } break;
      case '<':
        if (c2 == '=') { cp->p++; cp->tok = CTOK_LE; strcpy(cp->text, "<="); }
        else if (c2 == '<') { cp->p++; cp->tok = CTOK_SHL; strcpy(cp->text, "<<"); }
        break;
      case '>':
        if (c2 == '=') { cp->p++; cp->tok = CTOK_GE; strcpy(cp->text, ">="); }
        else if (c2 == '>') { cp->p++; cp->tok = CTOK_SHR; strcpy(cp->text, ">>"); }
        break;
      case '-': if (c2 == '>') { cp->p++; cp->tok = CTOK_DEREF; strcpy(cp->text, "->"); } break;
      case '.':
        if (c2 == '.' && cp->p + 1 < cp->e && cp->p[1] == '.') { cp->p += 2; cp->tok = CTOK_ELLIPSIS; strcpy(cp->text, "..."); }
        break;
      default: break;
      }
    }
  }
}

static int cp_opt(CPState *cp, int tok)
{
  if (cp->tok == tok) { cp_next(cp); return 1; }
  return 0;
}

static void cp_check(CPState *cp, int tok)
{
  if (cp->tok != tok) cp_err_expected(cp, tok);
  cp_next(cp);
}

static int cp_isident(CPState *cp, const char *s)
{
  return cp->tok == CTOK_IDENT && strcmp(strdata(cp->str), s) == 0;
}

/* Get a ctype id from a parameter value ($). */
static CTypeID cp_param_type(CPState *cp)
{
  TValue *o = cp->param;
  if (o && o < cp->paramend) {
    cp->param++;
    if (tviscdata(o)) {
      GCcdata *cd = cdataV(o);
      if (cd->ctypeid == CTID_CTYPEID) return *(CTypeID *)cdataptr(cd);
      return cd->ctypeid;
    }
  }
  cp_err(cp, "bad argument #%d to '?' (C type expected, got %s)", 0, o ? lj_typename(o) : "no value");
}

static int64_t cp_expr(CPState *cp, CPValue *v);
static CTypeID cp_decl_abstract(CPState *cp);
static int cp_istypename(CPState *cp);

/* -- Constant expressions -- */

static void cp_expr_unary(CPState *cp, CPValue *v);

static void cp_expr_prefix(CPState *cp, CPValue *v)
{
  if (cp->tok == CTOK_INTEGER) {
    *v = cp->val;
    cp_next(cp);
  } else if (cp->tok == CTOK_NUMBER) {
    *v = cp->val;
    cp_next(cp);
  } else if (cp->tok == '(') {
    cp_next(cp);
    if (cp_istypename(cp)) {
      CTypeID id = cp_decl_abstract(cp);
      CType *ct;
      cp_check(cp, ')');
      cp_expr_unary(cp, v);
      ct = lj_ctype_raw(cp->cts, id);
      if (ct->kind == CT_NUM && !(ct->flags & CTF_FP)) {
        if (ct->size < 8) {
          int sh = 64 - 8 * (int)ct->size;
          if (ct->flags & CTF_UNSIGNED) v->i = (int64_t)(((uint64_t)v->i << sh) >> sh);
          else v->i = (v->i << sh) >> sh;
        }
        v->isunsigned = (ct->flags & CTF_UNSIGNED) && ct->size >= 4;
      }
    } else {
      cp_expr(cp, v);
      cp_check(cp, ')');
    }
  } else if (cp->tok == CTOK_IDENT) {
    GCstr *name = cp->str;
    CTypeID id;
    if (cp_isident(cp, "sizeof") || cp_isident(cp, "__alignof__") || cp_isident(cp, "__alignof") || cp_isident(cp, "_Alignof")) {
      int isalign = !cp_isident(cp, "sizeof");
      CTypeID tid;
      cp_next(cp);
      if (cp->tok == '(') {
        const char *savep = cp->p;
        int savetok = cp->tok;
        (void)savep; (void)savetok;
        cp_next(cp);
        if (cp_istypename(cp)) {
          tid = cp_decl_abstract(cp);
          cp_check(cp, ')');
        } else {
          CPValue tmp;
          cp_expr(cp, &tmp);
          cp_check(cp, ')');
          tid = CTID_INT32;
        }
      } else {
        CPValue tmp;
        cp_expr_unary(cp, &tmp);
        tid = CTID_INT32;
      }
      {
        CType *ct = lj_ctype_raw(cp->cts, tid);
        v->i = isalign ? (int64_t)ct->align : (int64_t)lj_ctype_size(cp->cts, tid);
        v->isunsigned = 1;
      }
      return;
    }
    id = cts_get_name(cp->cts, cp->cts->names, name);
    if (id && cp->cts->tab[id].kind == CT_CONSTVAL) {
      v->i = cp->cts->tab[id].value;
      v->isunsigned = (lj_ctype_raw(cp->cts, cp->cts->tab[id].cid)->flags & CTF_UNSIGNED) != 0 &&
                      lj_ctype_raw(cp->cts, cp->cts->tab[id].cid)->size >= 4;
      cp_next(cp);
      return;
    }
    cp_err_near(cp, "unexpected symbol");
  } else if (cp->tok == '$') {
    TValue *o = cp->param;
    if (o && o < cp->paramend && tvisnum(o)) {
      v->i = (int64_t)o->u.n;
      v->isunsigned = 0;
      cp->param++;
      cp_next(cp);
      return;
    }
    cp_err_near(cp, "unexpected symbol");
  } else {
    cp_err_near(cp, "unexpected symbol");
  }
}

static void cp_expr_unary(CPState *cp, CPValue *v)
{
  if (++cp->depth > 200) cp_err(cp, "chunk has too many syntax levels");
  if (cp->tok == '-') { cp_next(cp); cp_expr_unary(cp, v); v->i = -v->i; }
  else if (cp->tok == '+') { cp_next(cp); cp_expr_unary(cp, v); }
  else if (cp->tok == '!') { cp_next(cp); cp_expr_unary(cp, v); v->i = !v->i; v->isunsigned = 0; }
  else if (cp->tok == '~') { cp_next(cp); cp_expr_unary(cp, v); v->i = ~v->i; }
  else cp_expr_prefix(cp, v);
  cp->depth--;
}

static int binprec(int tok)
{
  switch (tok) {
  case '*': case '/': case '%': return 10;
  case '+': case '-': return 9;
  case CTOK_SHL: case CTOK_SHR: return 8;
  case '<': case '>': case CTOK_LE: case CTOK_GE: return 7;
  case CTOK_EQ: case CTOK_NE: return 6;
  case '&': return 5;
  case '^': return 4;
  case '|': return 3;
  case CTOK_ANDAND: return 2;
  case CTOK_OROR: return 1;
  default: return 0;
  }
}

static void cp_expr_binop(CPState *cp, CPValue *k, int limit)
{
  int op;
  cp_expr_unary(cp, k);
  while ((op = cp->tok), binprec(op) > limit) {
    CPValue k2;
    int u;
    cp_next(cp);
    cp_expr_binop(cp, &k2, binprec(op));
    u = k->isunsigned || k2.isunsigned;
    switch (op) {
    case '*': k->i = (int64_t)((uint64_t)k->i * (uint64_t)k2.i); break;
    case '/':
      if (k2.i == 0) cp_err(cp, "division by zero");
      k->i = u ? (int64_t)((uint64_t)k->i / (uint64_t)k2.i) : k->i / k2.i; break;
    case '%':
      if (k2.i == 0) cp_err(cp, "division by zero");
      k->i = u ? (int64_t)((uint64_t)k->i % (uint64_t)k2.i) : k->i % k2.i; break;
    case '+': k->i = (int64_t)((uint64_t)k->i + (uint64_t)k2.i); break;
    case '-': k->i = (int64_t)((uint64_t)k->i - (uint64_t)k2.i); break;
    case CTOK_SHL: k->i = (int64_t)((uint64_t)k->i << (k2.i & 63)); break;
    case CTOK_SHR: k->i = k->isunsigned ? (int64_t)((uint64_t)k->i >> (k2.i & 63)) : k->i >> (k2.i & 63); break;
    case '<': k->i = u ? (uint64_t)k->i < (uint64_t)k2.i : k->i < k2.i; u = 0; break;
    case '>': k->i = u ? (uint64_t)k->i > (uint64_t)k2.i : k->i > k2.i; u = 0; break;
    case CTOK_LE: k->i = u ? (uint64_t)k->i <= (uint64_t)k2.i : k->i <= k2.i; u = 0; break;
    case CTOK_GE: k->i = u ? (uint64_t)k->i >= (uint64_t)k2.i : k->i >= k2.i; u = 0; break;
    case CTOK_EQ: k->i = k->i == k2.i; u = 0; break;
    case CTOK_NE: k->i = k->i != k2.i; u = 0; break;
    case '&': k->i &= k2.i; break;
    case '^': k->i ^= k2.i; break;
    case '|': k->i |= k2.i; break;
    case CTOK_ANDAND: k->i = k->i && k2.i; u = 0; break;
    case CTOK_OROR: k->i = k->i || k2.i; u = 0; break;
    }
    k->isunsigned = u;
  }
}

static int64_t cp_expr(CPState *cp, CPValue *k)
{
  cp_expr_binop(cp, k, 0);
  if (cp->tok == '?') {
    CPValue k1, k2;
    cp_next(cp);
    cp_expr(cp, &k1);
    cp_check(cp, ':');
    cp_expr(cp, &k2);
    *k = k->i ? k1 : k2;
  }
  return k->i;
}

static int64_t cp_expr_int(CPState *cp)
{
  CPValue v;
  cp_expr(cp, &v);
  return v.i;
}

/* -- Declaration specifiers -- */

#define CDS_TYPEDEF 1
#define CDS_EXTERN 2
#define CDS_STATIC 4

typedef struct DeclSpec {
  CTypeID base;
  uint32_t qual;
  int storage;
  uint32_t align;     /* from attribute aligned */
  int packed;
  GCstr *asmname;
} DeclSpec;

static CTypeID cp_struct(CPState *cp, int isunion, DeclSpec *ds);
static CTypeID cp_enum(CPState *cp, DeclSpec *ds);

static void cp_skip_parens(CPState *cp)
{
  int level = 0;
  do {
    if (cp->tok == '(') level++;
    else if (cp->tok == ')') level--;
    else if (cp->tok == CTOK_EOF) cp_err_expected(cp, ')');
    cp_next(cp);
  } while (level > 0);
}

static void cp_attributes(CPState *cp, DeclSpec *ds)
{
  for (;;) {
    if (cp_isident(cp, "__attribute__") || cp_isident(cp, "__attribute")) {
      cp_next(cp);
      cp_check(cp, '(');
      cp_check(cp, '(');
      while (cp->tok != ')') {
        if (cp->tok == CTOK_IDENT) {
          const char *a = strdata(cp->str);
          cp_next(cp);
          if ((strcmp(a, "aligned") == 0 || strcmp(a, "__aligned__") == 0)) {
            if (cp->tok == '(') {
              cp_next(cp);
              if (ds) ds->align = (uint32_t)cp_expr_int(cp);
              cp_check(cp, ')');
            } else if (ds) {
              ds->align = 16;
            }
          } else if (strcmp(a, "packed") == 0 || strcmp(a, "__packed__") == 0) {
            if (ds) ds->packed = 1;
          } else if (strcmp(a, "mode") == 0 || strcmp(a, "__mode__") == 0) {
            cp_check(cp, '(');
            if (cp->tok == CTOK_IDENT && ds) {
              const char *m = strdata(cp->str);
              if (strstr(m, "QI")) ds->base = CTID_INT8;
              else if (strstr(m, "HI")) ds->base = CTID_INT16;
              else if (strstr(m, "SI")) ds->base = CTID_INT32;
              else if (strstr(m, "DI")) ds->base = CTID_INT64;
              else if (strstr(m, "SF")) ds->base = CTID_FLOAT;
              else if (strstr(m, "DF")) ds->base = CTID_DOUBLE;
            }
            while (cp->tok != ')' && cp->tok != CTOK_EOF) cp_next(cp);
            cp_check(cp, ')');
          } else if (cp->tok == '(') {
            cp_skip_parens(cp);
          }
        } else {
          cp_next(cp);
        }
        if (!cp_opt(cp, ',')) break;
      }
      cp_check(cp, ')');
      cp_check(cp, ')');
    } else if (cp_isident(cp, "__declspec")) {
      cp_next(cp);
      if (cp->tok == '(') {
        cp_next(cp);
        if (cp_isident(cp, "align")) {
          cp_next(cp);
          cp_check(cp, '(');
          if (ds) ds->align = (uint32_t)cp_expr_int(cp);
          cp_check(cp, ')');
          cp_check(cp, ')');
        } else {
          int level = 1;
          while (level > 0 && cp->tok != CTOK_EOF) {
            if (cp->tok == '(') level++;
            else if (cp->tok == ')') level--;
            cp_next(cp);
          }
        }
      }
    } else if (cp_isident(cp, "__asm__") || cp_isident(cp, "__asm") || cp_isident(cp, "asm")) {
      cp_next(cp);
      cp_check(cp, '(');
      if (cp->tok == CTOK_STRING) {
        GCstr *s = cp->str;
        cp_next(cp);
        while (cp->tok == CTOK_STRING) cp_next(cp);
        if (ds) ds->asmname = s;
      }
      cp_check(cp, ')');
    } else if (cp_isident(cp, "__extension__") || cp_isident(cp, "__cdecl") || cp_isident(cp, "__stdcall") ||
               cp_isident(cp, "__fastcall") || cp_isident(cp, "__thiscall") || cp_isident(cp, "__ptr32") ||
               cp_isident(cp, "__ptr64") || cp_isident(cp, "__restrict") || cp_isident(cp, "__restrict__") ||
               cp_isident(cp, "restrict") || cp_isident(cp, "__w64") || cp_isident(cp, "__unaligned")) {
      cp_next(cp);
    } else {
      break;
    }
  }
}

/* Check whether current token starts a type. */
static int cp_istypename(CPState *cp)
{
  static const char *const kws[] = {
    "void", "char", "short", "int", "long", "signed", "unsigned", "float", "double",
    "bool", "_Bool", "complex", "_Complex", "__complex__", "struct", "union", "enum",
    "const", "volatile", "__const", "__const__", "__volatile", "__volatile__",
    "__signed__", "__signed", "__int8", "__int16", "__int32", "__int64", "__extension__",
    "__attribute__", "restrict", "__restrict", "__restrict__", NULL
  };
  int i;
  if (cp->tok == '$') return 1;
  if (cp->tok != CTOK_IDENT) return 0;
  for (i = 0; kws[i]; i++) if (strcmp(strdata(cp->str), kws[i]) == 0) return 1;
  {
    CTypeID id = cts_get_name(cp->cts, cp->cts->names, cp->str);
    if (id && cp->cts->tab[id].kind == CT_TYPEDEF) return 1;
    if (lj_tab_getstr(cp->cts->miscmap, cp->str)) return 1;
  }
  return 0;
}

enum {
  TS_VOID = 1, TS_CHAR = 2, TS_SHORT = 4, TS_INT = 8, TS_FLOAT = 16, TS_DOUBLE = 32,
  TS_BOOL = 64, TS_COMPLEX = 128, TS_SIGNED = 256, TS_UNSIGNED = 512, TS_INT8 = 1024,
  TS_INT16 = 2048, TS_INT32 = 4096, TS_INT64 = 8192
};

static int cp_decl_spec(CPState *cp, DeclSpec *ds, int must)
{
  int ts = 0, nlong = 0;
  int anyspec = 0;
  ds->base = 0;
  ds->qual = 0;
  ds->storage = 0;
  ds->align = 0;
  ds->packed = 0;
  ds->asmname = NULL;
  for (;;) {
    cp_attributes(cp, ds);
    if (cp->tok == '$') {
      if (ds->base || ts || nlong) break;
      ds->base = cp_param_type(cp);
      cp_next(cp);
      anyspec = 1;
      continue;
    }
    if (cp->tok != CTOK_IDENT) break;
    {
      const char *s = strdata(cp->str);
      int nts = 0;
      if (strcmp(s, "typedef") == 0) { ds->storage |= CDS_TYPEDEF; cp_next(cp); continue; }
      if (strcmp(s, "extern") == 0) { ds->storage |= CDS_EXTERN; cp_next(cp); continue; }
      if (strcmp(s, "static") == 0) { ds->storage |= CDS_STATIC; cp_next(cp); continue; }
      if (strcmp(s, "auto") == 0 || strcmp(s, "register") == 0 || strcmp(s, "inline") == 0 ||
          strcmp(s, "__inline") == 0 || strcmp(s, "__inline__") == 0) { cp_next(cp); continue; }
      if (strcmp(s, "const") == 0 || strcmp(s, "__const") == 0 || strcmp(s, "__const__") == 0) {
        ds->qual |= CTF_CONST; cp_next(cp); anyspec = 1; continue;
      }
      if (strcmp(s, "volatile") == 0 || strcmp(s, "__volatile") == 0 || strcmp(s, "__volatile__") == 0) {
        ds->qual |= CTF_VOLATILE; cp_next(cp); anyspec = 1; continue;
      }
      if (strcmp(s, "void") == 0) nts = TS_VOID;
      else if (strcmp(s, "char") == 0) nts = TS_CHAR;
      else if (strcmp(s, "short") == 0) nts = TS_SHORT;
      else if (strcmp(s, "int") == 0) nts = TS_INT;
      else if (strcmp(s, "float") == 0) nts = TS_FLOAT;
      else if (strcmp(s, "double") == 0) nts = TS_DOUBLE;
      else if (strcmp(s, "bool") == 0 || strcmp(s, "_Bool") == 0) nts = TS_BOOL;
      else if (strcmp(s, "complex") == 0 || strcmp(s, "_Complex") == 0 || strcmp(s, "__complex__") == 0) nts = TS_COMPLEX;
      else if (strcmp(s, "signed") == 0 || strcmp(s, "__signed__") == 0 || strcmp(s, "__signed") == 0) nts = TS_SIGNED;
      else if (strcmp(s, "unsigned") == 0) nts = TS_UNSIGNED;
      else if (strcmp(s, "__int8") == 0) nts = TS_INT8;
      else if (strcmp(s, "__int16") == 0) nts = TS_INT16;
      else if (strcmp(s, "__int32") == 0) nts = TS_INT32;
      else if (strcmp(s, "__int64") == 0) nts = TS_INT64;
      else if (strcmp(s, "long") == 0) {
        if (ds->base || nlong >= 2 || (ts & (TS_VOID | TS_CHAR | TS_SHORT | TS_FLOAT | TS_BOOL))) break;
        nlong++;
        anyspec = 1;
        cp_next(cp);
        continue;
      }
      if (nts) {
        if (ds->base) break;
        if (ts & nts) break;
        if ((nts & (TS_VOID | TS_CHAR | TS_SHORT | TS_FLOAT | TS_DOUBLE | TS_BOOL | TS_INT)) &&
            (ts & (TS_VOID | TS_CHAR | TS_SHORT | TS_FLOAT | TS_DOUBLE | TS_BOOL)) ) break;
        if ((nts & (TS_SIGNED | TS_UNSIGNED)) && (ts & (TS_SIGNED | TS_UNSIGNED))) break;
        ts |= nts;
        anyspec = 1;
        cp_next(cp);
        continue;
      }
      if (strcmp(s, "struct") == 0 || strcmp(s, "union") == 0) {
        if (ds->base || ts || nlong) break;
        cp_next(cp);
        ds->base = cp_struct(cp, s[0] == 'u', ds);
        anyspec = 1;
        continue;
      }
      if (strcmp(s, "enum") == 0) {
        if (ds->base || ts || nlong) break;
        cp_next(cp);
        ds->base = cp_enum(cp, ds);
        anyspec = 1;
        continue;
      }
      /* Typedef name? */
      if (!ds->base && !ts && !nlong) {
        CTypeID id = cts_get_name(cp->cts, cp->cts->names, cp->str);
        if (id && cp->cts->tab[id].kind == CT_TYPEDEF) {
          ds->base = id;
          anyspec = 1;
          cp_next(cp);
          continue;
        } else {
          cTValue *pv = lj_tab_getstr(cp->cts->miscmap, cp->str);
          if (pv && tvisnum(pv)) {
            ds->base = (CTypeID)pv->u.n;
            anyspec = 1;
            cp_next(cp);
            continue;
          }
        }
      }
      break;
    }
  }
  if (!ds->base) {
    if (ts & TS_VOID) ds->base = CTID_VOID;
    else if (ts & TS_BOOL) ds->base = CTID_BOOL;
    else if (ts & TS_CHAR) ds->base = (ts & TS_UNSIGNED) ? CTID_UINT8 : CTID_INT8;
    else if (ts & TS_SHORT) ds->base = (ts & TS_UNSIGNED) ? CTID_UINT16 : CTID_INT16;
    else if (ts & TS_FLOAT) ds->base = (ts & TS_COMPLEX) ? CTID_COMPLEX_FLOAT : CTID_FLOAT;
    else if (ts & TS_DOUBLE) ds->base = nlong ? CTID_LONGDOUBLE : (ts & TS_COMPLEX) ? CTID_COMPLEX_DOUBLE : CTID_DOUBLE;
    else if (ts & TS_COMPLEX) ds->base = CTID_COMPLEX_DOUBLE;
    else if (ts & TS_INT8) ds->base = (ts & TS_UNSIGNED) ? CTID_UINT8 : CTID_INT8;
    else if (ts & TS_INT16) ds->base = (ts & TS_UNSIGNED) ? CTID_UINT16 : CTID_INT16;
    else if (ts & TS_INT32) ds->base = (ts & TS_UNSIGNED) ? CTID_UINT32 : CTID_INT32;
    else if ((ts & TS_INT64) || nlong) ds->base = (ts & TS_UNSIGNED) ? CTID_UINT64 : CTID_INT64;
    else if (ts & (TS_INT | TS_SIGNED | TS_UNSIGNED)) ds->base = (ts & TS_UNSIGNED) ? CTID_UINT32 : CTID_INT32;
  }
  if (!ds->base) {
    if (must || anyspec) cp_err_near(cp, "declaration specifier expected");
    return 0;
  }
  return 1;
}

/* -- Declarators -- */

#define DOP_PTR 1
#define DOP_REF 2
#define DOP_ARRAY 3
#define DOP_FUNC 4

typedef struct DeclOp {
  int op;
  uint32_t qual;
  uint32_t nelem;
  int vla;
  int noelem;   /* [] */
  CTypeID params;  /* first param */
  int vararg;
} DeclOp;

#define MAXDOPS 32

typedef struct Decl {
  DeclOp ops[MAXDOPS];
  int nops;
  GCstr *name;
  GCstr *asmname;
  int bits;   /* bitfield width, -1 if none */
} Decl;

static void decl_push(CPState *cp, Decl *d, DeclOp *op)
{
  if (d->nops >= MAXDOPS) cp_err(cp, "chunk has too many syntax levels");
  d->ops[d->nops++] = *op;
}

static CTypeID cp_param_list(CPState *cp, int *vararg);

static int cp_declarator(CPState *cp, Decl *d, int abstract)
{
  DeclOp ptrs[MAXDOPS];
  int nptrs = 0;
  Decl inner;
  int hasinner = 0;
  DeclOp suf[MAXDOPS];
  int nsuf = 0;
  int i;
  if (++cp->depth > 100) cp_err(cp, "chunk has too many syntax levels");
  for (;;) {
    cp_attributes(cp, NULL);
    if (cp->tok == '*' || cp->tok == '&' || cp->tok == '^') {
      DeclOp op;
      memset(&op, 0, sizeof(op));
      op.op = (cp->tok == '&') ? DOP_REF : DOP_PTR;
      cp_next(cp);
      for (;;) {
        if (cp_isident(cp, "const") || cp_isident(cp, "__const") || cp_isident(cp, "__const__")) { op.qual |= CTF_CONST; cp_next(cp); }
        else if (cp_isident(cp, "volatile") || cp_isident(cp, "__volatile") || cp_isident(cp, "__volatile__")) { op.qual |= CTF_VOLATILE; cp_next(cp); }
        else if (cp_isident(cp, "restrict") || cp_isident(cp, "__restrict") || cp_isident(cp, "__restrict__") ||
                 cp_isident(cp, "__attribute__") || cp_isident(cp, "__ptr32") || cp_isident(cp, "__ptr64")) cp_attributes(cp, NULL);
        else break;
      }
      if (nptrs >= MAXDOPS) cp_err(cp, "chunk has too many syntax levels");
      ptrs[nptrs++] = op;
    } else {
      break;
    }
  }
  if (cp->tok == '(') {
    /* Nested declarator or function parameters (abstract). */
    const char *savep = cp->p;
    int saveline = cp->linenumber;
    cp_next(cp);
    if (cp->tok == '*' || cp->tok == '&' || cp->tok == '^' || cp->tok == '(' || cp->tok == '[' ||
        cp_isident(cp, "__attribute__") || cp_isident(cp, "__cdecl") || cp_isident(cp, "__stdcall") ||
        (cp->tok == CTOK_IDENT && !cp_istypename(cp)) || (cp->tok == '$' && 0)) {
      inner.nops = 0;
      inner.name = NULL;
      inner.asmname = NULL;
      inner.bits = -1;
      cp_declarator(cp, &inner, abstract);
      cp_check(cp, ')');
      hasinner = 1;
    } else {
      /* Function parameter list for abstract declarator: rewind. */
      cp->p = savep;
      cp->linenumber = saveline;
      cp->tok = '(';
      strcpy(cp->text, "(");
    }
  } else if (cp->tok == CTOK_IDENT && !cp_isident(cp, "__attribute__")) {
    d->name = cp->str;
    cp_next(cp);
  } else if (cp->tok == '$' && !abstract) {
    TValue *o = cp->param;
    if (o && o < cp->paramend && tvisstr(o)) {
      d->name = strV(o);
      cp->param++;
      cp_next(cp);
    } else {
      cp_err_near(cp, "identifier expected");
    }
  }
  for (;;) {
    if (cp->tok == '[') {
      DeclOp op;
      memset(&op, 0, sizeof(op));
      op.op = DOP_ARRAY;
      cp_next(cp);
      if (cp->tok == ']') {
        op.noelem = 1;
      } else if (cp->tok == '?') {
        op.vla = 1;
        cp_next(cp);
      } else {
        int64_t n = cp_expr_int(cp);
        if (n < 0 || n > 0x7fffffff) cp_err(cp, "size of C type is unknown or too large");
        op.nelem = (uint32_t)n;
      }
      cp_check(cp, ']');
      if (nsuf >= MAXDOPS) cp_err(cp, "chunk has too many syntax levels");
      suf[nsuf++] = op;
    } else if (cp->tok == '(') {
      DeclOp op;
      memset(&op, 0, sizeof(op));
      op.op = DOP_FUNC;
      cp_next(cp);
      op.params = cp_param_list(cp, &op.vararg);
      if (nsuf >= MAXDOPS) cp_err(cp, "chunk has too many syntax levels");
      suf[nsuf++] = op;
    } else {
      break;
    }
  }
  cp_attributes(cp, NULL);
  if (cp_isident(cp, "__asm__") || cp_isident(cp, "__asm") || cp_isident(cp, "asm")) {
    DeclSpec tmp;
    memset(&tmp, 0, sizeof(tmp));
    cp_attributes(cp, &tmp);
    d->asmname = tmp.asmname;
    cp_attributes(cp, NULL);
  }
  for (i = 0; i < nptrs; i++) decl_push(cp, d, &ptrs[i]);
  for (i = nsuf - 1; i >= 0; i--) decl_push(cp, d, &suf[i]);
  if (hasinner) {
    for (i = 0; i < inner.nops; i++) decl_push(cp, d, &inner.ops[i]);
    if (inner.name) d->name = inner.name;
    if (inner.asmname) d->asmname = inner.asmname;
  }
  cp->depth--;
  return 1;
}

static CTypeID cp_build_type(CPState *cp, CTypeID base, Decl *d)
{
  CTState *cts = cp->cts;
  int i;
  CTypeID id = base;
  for (i = 0; i < d->nops; i++) {
    DeclOp *op = &d->ops[i];
    CType *ct = lj_ctype_raw(cts, id);
    switch (op->op) {
    case DOP_PTR:
      id = lj_ctype_intern(cts, CT_PTR, op->qual, id, 8, 8, 0);
      break;
    case DOP_REF:
      id = lj_ctype_intern(cts, CT_REF, op->qual, id, 8, 8, 0);
      break;
    case DOP_ARRAY: {
      uint32_t esz = lj_ctype_size(cts, id);
      uint32_t sz;
      uint32_t flags = 0;
      if (ct->kind == CT_VOID || ct->kind == CT_FUNC) cp_err(cp, "invalid C type");
      if (op->vla) {
        flags |= CTF_VLA;
        sz = CTSIZE_INVALID;
      } else if (op->noelem) {
        sz = CTSIZE_INVALID;
        flags |= CTF_VLA | CTF_INCOMPLETE;
        flags &= ~CTF_VLA;
      } else {
        if (esz == CTSIZE_INVALID) cp_err(cp, "size of C type is unknown or too large");
        if (op->nelem && esz > 0x7fffffffu / op->nelem) cp_err(cp, "size of C type is unknown or too large");
        sz = esz * op->nelem;
      }
      id = lj_ctype_intern(cts, CT_ARRAY, flags, id, sz, ct->align ? ct->align : 1, op->nelem);
      break;
    }
    case DOP_FUNC: {
      CTypeID fid = cts_add(cts, CT_FUNC, op->vararg ? CTF_VARARG : 0, id, CTSIZE_INVALID, 1);
      cts->tab[fid].first = op->params;
      id = fid;
      break;
    }
    }
  }
  return id;
}

/* Parse parameter list after '('. Returns first param id. */
static CTypeID cp_param_list(CPState *cp, int *vararg)
{
  CTState *cts = cp->cts;
  CTypeID first = 0, last = 0;
  *vararg = 0;
  if (cp->tok == ')') {
    cp_next(cp);
    return 0;
  }
  if (cp_isident(cp, "void")) {
    const char *savep = cp->p;
    int saveline = cp->linenumber;
    cp_next(cp);
    if (cp->tok == ')') {
      cp_next(cp);
      return 0;
    }
    cp->p = savep;
    cp->linenumber = saveline;
    cp->tok = CTOK_IDENT;
    cp->str = lj_str_newlit(cp->L, "void");
    strcpy(cp->text, "void");
  }
  for (;;) {
    DeclSpec ds;
    Decl d;
    CTypeID tid, pid;
    CType *ct;
    if (cp->tok == CTOK_ELLIPSIS) {
      *vararg = 1;
      cp_next(cp);
      break;
    }
    cp_decl_spec(cp, &ds, 1);
    d.nops = 0;
    d.name = NULL;
    d.asmname = NULL;
    d.bits = -1;
    cp_declarator(cp, &d, 0);
    tid = cp_build_type(cp, ctype_qualify(cts, ds.base, ds.qual), &d);
    ct = lj_ctype_raw(cts, tid);
    if (ct->kind == CT_ARRAY && !(ct->flags & CTF_COMPLEX)) {
      tid = lj_ctype_intern(cts, CT_PTR, 0, ct->cid, 8, 8, 0);
    } else if (ct->kind == CT_FUNC) {
      tid = lj_ctype_intern(cts, CT_PTR, 0, tid, 8, 8, 0);
    }
    pid = cts_add(cts, CT_FIELD, 0, tid, 0, 1);
    cts->tab[pid].name = d.name;
    if (last) cts->tab[last].next = pid; else first = pid;
    last = pid;
    if (!cp_opt(cp, ',')) break;
  }
  cp_check(cp, ')');
  return first;
}

/* -- Struct/union/enum -- */

static uint32_t align_up(uint32_t x, uint32_t a)
{
  return (x + a - 1) & ~(a - 1);
}

static void cp_struct_layout(CPState *cp, CTypeID sid, int packed, uint32_t forcealign)
{
  CTState *cts = cp->cts;
  CType *st = &cts->tab[sid];
  int isunion = (st->flags & CTF_UNION) != 0;
  uint64_t bitpos = 0;
  uint32_t maxalign = 1;
  uint32_t maxsize = 0;
  CTypeID fid;
  uint32_t pack = cp->pack;
  for (fid = st->first; fid; fid = cts->tab[fid].next) {
    CType *f = &cts->tab[fid];
    CType *ft = lj_ctype_raw(cts, f->cid);
    uint32_t fsz = lj_ctype_size(cts, f->cid);
    uint32_t fal = ft->align ? ft->align : 1;
    if (ft->kind == CT_ARRAY && !(ft->flags & CTF_COMPLEX)) {
      /* Array alignment is element alignment. */
      fal = lj_ctype_raw(cts, ft->cid)->align;
      if (!fal) fal = 1;
    }
    if (f->value & 0x100000000LL) {
      /* explicit field alignment stored in high bits */
    }
    if (packed) fal = 1;
    if (pack && fal > pack) fal = pack;
    if (fsz == CTSIZE_INVALID) {
      if (ft->kind == CT_ARRAY && (ft->flags & (CTF_VLA | CTF_INCOMPLETE)) && !f->next) {
        fsz = 0;  /* trailing flexible array */
      } else {
        cp_err(cp, "size of C type is unknown or too large");
      }
    }
    if (f->flags & CTF_BITFIELD) {
      uint32_t w = f->bitsize;
      uint32_t ub = fsz * 8;
      if (isunion) bitpos = 0;
      if (w == 0) {
        bitpos = (bitpos + ub - 1) / ub * ub;
        continue;
      }
      {
        uint64_t unit = (bitpos / ub) * ub;
        if (packed) unit = (bitpos / 8) * 8;
        if (!packed && bitpos + w > unit + ub) {
          bitpos = unit + ub;
          unit = bitpos;
        }
        f->value = (int64_t)((bitpos / 8) & ~(uint64_t)(fsz - 1));
        if (packed) f->value = (int64_t)(bitpos / 8);
        f->bitpos = (uint32_t)(bitpos - (uint64_t)f->value * 8);
        bitpos += w;
      }
      if (fal > maxalign) maxalign = fal;
      if (isunion && fsz > maxsize) maxsize = fsz;
      continue;
    }
    if (isunion) {
      f->value = 0;
      if (fsz > maxsize) maxsize = fsz;
    } else {
      bitpos = (bitpos + 7) / 8 * 8;
      bitpos = (uint64_t)align_up((uint32_t)(bitpos / 8), fal) * 8;
      f->value = (int64_t)(bitpos / 8);
      bitpos += (uint64_t)fsz * 8;
    }
    if (fal > maxalign) maxalign = fal;
  }
  if (forcealign > maxalign) maxalign = forcealign;
  {
    uint32_t size = isunion ? maxsize : (uint32_t)((bitpos + 7) / 8);
    if (isunion && bitpos > (uint64_t)size * 8) size = (uint32_t)((bitpos + 7) / 8);
    st = &cts->tab[sid];
    st->size = align_up(size, maxalign);
    st->align = maxalign;
  }
}

static CTypeID cp_decl_single(CPState *cp, DeclSpec *ds, Decl *d)
{
  return cp_build_type(cp, ctype_qualify(cp->cts, ds->base, ds->qual), d);
}

static void cp_struct_body(CPState *cp, CTypeID sid)
{
  CTState *cts = cp->cts;
  CTypeID last = 0;
  cp_check(cp, '{');
  while (cp->tok != '}') {
    DeclSpec ds;
    if (cp->tok == ';') { cp_next(cp); continue; }
    cp_decl_spec(cp, &ds, 1);
    if (cp->tok == ';') {
      /* Anonymous (transparent) struct/union member or bare enum. */
      CType *bt = lj_ctype_raw(cts, ds.base);
      if (bt->kind == CT_STRUCT) {
        CTypeID fid = cts_add(cts, CT_FIELD, 0, ds.base, 0, 1);
        cts->tab[fid].name = NULL;
        if (last) cts->tab[last].next = fid; else cts->tab[sid].first = fid;
        last = fid;
      }
      cp_next(cp);
      continue;
    }
    if (ds.storage & CDS_STATIC) {
      /* Scoped static const. */
      Decl d;
      CTypeID tid, cid;
      d.nops = 0; d.name = NULL; d.asmname = NULL; d.bits = -1;
      cp_declarator(cp, &d, 0);
      tid = cp_decl_single(cp, &ds, &d);
      cp_check(cp, '=');
      cid = cts_add(cts, CT_CONSTVAL, 0, tid, 0, 1);
      cts->tab[cid].name = d.name;
      cts->tab[cid].value = cp_expr_int(cp);
      if (last) cts->tab[last].next = cid; else cts->tab[sid].first = cid;
      last = cid;
      cp_check(cp, ';');
      continue;
    }
    for (;;) {
      Decl d;
      CTypeID tid, fid;
      d.nops = 0; d.name = NULL; d.asmname = NULL; d.bits = -1;
      if (cp->tok != ':') cp_declarator(cp, &d, 0);
      tid = cp_decl_single(cp, &ds, &d);
      fid = cts_add(cts, CT_FIELD, 0, tid, 0, 1);
      cts->tab[fid].name = d.name;
      if (cp->tok == ':') {
        int64_t w;
        cp_next(cp);
        w = cp_expr_int(cp);
        cts->tab[fid].flags |= CTF_BITFIELD;
        cts->tab[fid].bitsize = (uint32_t)w;
      }
      if (last) cts->tab[last].next = fid; else cts->tab[sid].first = fid;
      last = fid;
      cp_attributes(cp, NULL);
      if (!cp_opt(cp, ',')) break;
    }
    cp_check(cp, ';');
  }
  cp_next(cp);
}

static CTypeID cp_struct(CPState *cp, int isunion, DeclSpec *ds)
{
  CTState *cts = cp->cts;
  CTypeID sid = 0;
  GCstr *tag = NULL;
  DeclSpec attrs;
  memset(&attrs, 0, sizeof(attrs));
  cp_attributes(cp, &attrs);
  if (cp->tok == CTOK_IDENT) {
    tag = cp->str;
    cp_next(cp);
  } else if (cp->tok == '$') {
    TValue *o = cp->param;
    if (o && o < cp->paramend && tvisstr(o)) {
      tag = strV(o);
      cp->param++;
      cp_next(cp);
    }
  }
  if (tag) {
    sid = cts_get_name(cts, cts->tags, tag);
    if (sid) {
      CType *st = &cts->tab[sid];
      if (st->kind != CT_STRUCT || ((st->flags & CTF_UNION) != 0) != isunion)
        cp_err(cp, "attempt to redefine '%s'", strdata(tag));
      if (cp->tok == '{' && !(st->flags & CTF_INCOMPLETE))
        cp_err(cp, "attempt to redefine '%s'", strdata(tag));
    } else {
      sid = cts_add(cts, CT_STRUCT, (isunion ? CTF_UNION : 0) | CTF_INCOMPLETE, 0, 0, 1);
      cts->tab[sid].name = tag;
      cts_set_name(cts, cts->tags, tag, sid);
    }
  } else {
    if (cp->tok != '{') cp_err_expected(cp, CTOK_IDENT);
    sid = cts_add(cts, CT_STRUCT, (isunion ? CTF_UNION : 0) | CTF_INCOMPLETE, 0, 0, 1);
  }
  if (cp->tok == '{') {
    cp_struct_body(cp, sid);
    cp_attributes(cp, &attrs);
    cp_struct_layout(cp, sid, attrs.packed || (ds && ds->packed), attrs.align);
    cts->tab[sid].flags &= ~CTF_INCOMPLETE;
  }
  return sid;
}

static CTypeID cp_enum(CPState *cp, DeclSpec *ds)
{
  CTState *cts = cp->cts;
  CTypeID eid = 0;
  GCstr *tag = NULL;
  (void)ds;
  cp_attributes(cp, NULL);
  if (cp->tok == CTOK_IDENT) {
    tag = cp->str;
    cp_next(cp);
  }
  if (tag) {
    eid = cts_get_name(cts, cts->tags, tag);
    if (eid && cts->tab[eid].kind != CT_ENUM)
      cp_err(cp, "attempt to redefine '%s'", strdata(tag));
    if (eid && cp->tok == '{' && !(cts->tab[eid].flags & CTF_INCOMPLETE))
      cp_err(cp, "attempt to redefine '%s'", strdata(tag));
    if (!eid) {
      eid = cts_add(cts, CT_ENUM, CTF_INCOMPLETE, CTID_UINT32, 4, 4);
      cts->tab[eid].name = tag;
      cts_set_name(cts, cts->tags, tag, eid);
    }
  } else {
    if (cp->tok != '{') cp_err_expected(cp, CTOK_IDENT);
    eid = cts_add(cts, CT_ENUM, CTF_INCOMPLETE, CTID_UINT32, 4, 4);
  }
  if (cp->tok == '{') {
    int64_t v = 0;
    CTypeID last = 0;
    int anyneg = 0;
    cp_next(cp);
    while (cp->tok != '}') {
      GCstr *name;
      CTypeID cid;
      if (cp->tok != CTOK_IDENT) cp_err_expected(cp, CTOK_IDENT);
      name = cp->str;
      cp_next(cp);
      if (cp_opt(cp, '=')) v = cp_expr_int(cp);
      if (v < 0) anyneg = 1;
      cid = cts_add(cts, CT_CONSTVAL, 0, CTID_INT32, 0, 1);
      cts->tab[cid].name = name;
      cts->tab[cid].value = (int32_t)v;
      cts_set_name(cts, cts->names, name, cid);
      if (last) cts->tab[last].next = cid; else cts->tab[eid].first = cid;
      last = cid;
      v++;
      if (!cp_opt(cp, ',')) break;
    }
    cp_check(cp, '}');
    cts->tab[eid].flags &= ~CTF_INCOMPLETE;
    cts->tab[eid].cid = anyneg ? CTID_INT32 : CTID_UINT32;
    {
      CTypeID c;
      for (c = cts->tab[eid].first; c; c = cts->tab[c].next) cts->tab[c].cid = anyneg ? CTID_INT32 : CTID_UINT32;
    }
  }
  cp_attributes(cp, NULL);
  return eid;
}

/* Abstract type: decl_spec + abstract declarator. */
static CTypeID cp_decl_abstract(CPState *cp)
{
  DeclSpec ds;
  Decl d;
  cp_decl_spec(cp, &ds, 1);
  d.nops = 0; d.name = NULL; d.asmname = NULL; d.bits = -1;
  cp_declarator(cp, &d, 1);
  return cp_decl_single(cp, &ds, &d);
}

static void cp_init(CPState *cp, lua_State *L, const char *s, size_t len, TValue *param, TValue *paramend)
{
  memset(cp, 0, sizeof(*cp));
  cp->cts = lj_ctype_state(L);
  cp->L = L;
  cp->p = s;
  cp->e = s + len;
  cp->linenumber = 1;
  cp->param = param;
  cp->paramend = paramend;
  cp_next(cp);
}

CTypeID lj_cparse_type(lua_State *L, GCstr *s, TValue *param, TValue *paramend)
{
  CPState cp;
  CTypeID id;
  cp_init(&cp, L, strdata(s), s->len, param, paramend);
  id = cp_decl_abstract(&cp);
  if (cp.tok != CTOK_EOF) cp_err_expected(&cp, CTOK_EOF);
  return id;
}

void lj_cparse_cdef(lua_State *L, GCstr *s, TValue *param, TValue *paramend)
{
  CPState cp;
  CTState *cts;
  cp_init(&cp, L, strdata(s), s->len, param, paramend);
  cts = cp.cts;
  while (cp.tok != CTOK_EOF) {
    DeclSpec ds;
    if (cp.tok == ';') { cp_next(&cp); continue; }
    cp_decl_spec(&cp, &ds, 1);
    if (cp.tok == ';') { cp_next(&cp); continue; }
    for (;;) {
      Decl d;
      CTypeID tid;
      CType *ct;
      d.nops = 0; d.name = NULL; d.asmname = ds.asmname; d.bits = -1;
      cp_declarator(&cp, &d, 0);
      tid = cp_decl_single(&cp, &ds, &d);
      ct = &cts->tab[tid];
      if (!d.name) cp_err_expected(&cp, CTOK_IDENT);
      if (ds.storage & CDS_TYPEDEF) {
        CTypeID old = cts_get_name(cts, cts->names, d.name);
        if (!(old && cts->tab[old].kind == CT_TYPEDEF)) {
          CTypeID did = cts_add(cts, CT_TYPEDEF, 0, tid, 0, 1);
          cts->tab[did].name = d.name;
          cts_set_name(cts, cts->names, d.name, did);
        }
      } else if (ct->kind == CT_FUNC) {
        ct->name = d.name;
        ct->addr = NULL;
        if (d.asmname) {
          /* Store redirected symbol name in a separate field via miscmap. */
          TValue key, *v;
          setnumV(&key, (double)tid + 0.5);
          v = lj_tab_set(L, cts->miscmap, &key);
          setstrV(v, d.asmname);
        }
        cts_set_name(cts, cts->names, d.name, tid);
      } else if ((ds.storage & CDS_STATIC) && cp.tok == '=') {
        CTypeID cid;
        cp_next(&cp);
        cid = cts_add(cts, CT_CONSTVAL, 0, tid, 0, 1);
        cts->tab[cid].name = d.name;
        cts->tab[cid].value = cp_expr_int(&cp);
        cts_set_name(cts, cts->names, d.name, cid);
      } else {
        CTypeID eid = cts_add(cts, CT_EXTERN, 0, tid, 0, 1);
        cts->tab[eid].name = d.name;
        if (d.asmname) {
          TValue key, *v;
          setnumV(&key, (double)eid + 0.5);
          v = lj_tab_set(L, cts->miscmap, &key);
          setstrV(v, d.asmname);
        }
        cts_set_name(cts, cts->names, d.name, eid);
        if (cp.tok == '=') {
          cp_next(&cp);
          cp_expr_int(&cp);
        }
      }
      if (cp.tok == '{') {
        /* Skip function body. */
        int level = 0;
        do {
          if (cp.tok == '{') level++;
          else if (cp.tok == '}') level--;
          else if (cp.tok == CTOK_EOF) break;
          cp_next(&cp);
        } while (level > 0);
        goto nextdecl;
      }
      if (!cp_opt(&cp, ',')) break;
    }
    cp_check(&cp, ';');
  nextdecl:;
  }
}
EOF
echo ok"}

