/* ======================================================================== */
/* -- cdata objects -------------------------------------------------------- */

GCcdata *lj_cdata_new(CTState *cts, CTypeID id, uint32_t size)
{
  lua_State *L = cts->L;
  uint32_t al = lj_ctype_raw(cts, id)->align;
  size_t extra = al > 8 ? al : 0;
  size_t total = offsetof(GCcdata, align) + (size ? size : 1) + extra;
  GCcdata *cd = (GCcdata *)lj_gc_newobj(L, total, LJ_TCDATA);
  uintptr_t p = (uintptr_t)cd->align;
  if (extra) p = (p + al - 1) & ~(uintptr_t)(al - 1);
  cd->cdflags = 0;
  cd->ctypeid = id;
  cd->size = size;
  cd->allocsize = (uint32_t)total;
  cd->ptr = (void *)p;
  return cd;
}

void lj_cdata_free(global_State *g, GCcdata *cd)
{
  lj_mem_free(g, cd, cd->allocsize);
}

void *lj_cdata_ptr(GCcdata *cd)
{
  return cd->ptr;
}

static GCcdata *cdata_push(CTState *cts, CTypeID id, uint32_t size)
{
  lua_State *L = cts->L;
  GCcdata *cd = lj_cdata_new(cts, id, size);
  lj_checkstack(L, 1);
  setcdataV(L->top, cd);
  L->top++;
  return cd;
}

/* Box a 64 bit integer. */
static GCcdata *box_i64(CTState *cts, CTypeID id, uint64_t v, TValue *o)
{
  GCcdata *cd = lj_cdata_new(cts, id, 8);
  *(uint64_t *)cdataptr(cd) = v;
  setcdataV(o, cd);
  return cd;
}

static CTypeID ctype_typeid_strip(CTState *cts, CTypeID id)
{
  for (;;) {
    CType *ct = &cts->tab[id];
    if (ct->kind == CT_TYPEDEF) { id = ct->cid; continue; }
    if (ct->kind == CT_REF) { id = ct->cid; continue; }
    break;
  }
  return ctype_unqual_struct(cts, id);
}

/* -- Conversions ---------------------------------------------------------- */

#define CCF_CAST   0x0001
#define CCF_INIT   0x0002
#define CCF_ARGSHIFT 8
#define CCF_ARG(n) ((n) << CCF_ARGSHIFT)

static LJ_NORET void cconv_err(CTState *cts, CTypeID did, const char *src, int flags)
{
  lua_State *L = cts->L;
  const char *dst = ctype_reprz(L, did);
  char buf[512];
  int narg = flags >> CCF_ARGSHIFT;
  snprintf(buf, sizeof(buf), "cannot convert '%s' to '%s'", src, dst);
  if (narg) lj_err_arg(L, narg, buf);
  lj_err_callermsg(L, buf);
}

static LJ_NORET void cconv_err_ct(CTState *cts, CTypeID did, CTypeID sid, int flags)
{
  cconv_err(cts, did, ctype_reprz(cts->L, sid), flags);
}

static uint64_t num2u64(double n)
{
  if (n >= 9223372036854775808.0)
    return (uint64_t)lj_num2i64(n - 9223372036854775808.0) ^ 0x8000000000000000ULL;
  return (uint64_t)lj_num2i64(n);
}

static int ct_isint(CType *ct)
{
  return ct->kind == CT_NUM && !(ct->flags & (CTF_FP | CTF_BOOL));
}

/* Read integer value from memory (sign/zero extended). */
static uint64_t ct_readint(CType *s, uint8_t *sp)
{
  switch (s->size) {
  case 1: return (s->flags & (CTF_UNSIGNED | CTF_BOOL)) ? (uint64_t)*(uint8_t *)sp : (uint64_t)(int64_t)*(int8_t *)sp;
  case 2: return (s->flags & CTF_UNSIGNED) ? (uint64_t)*(uint16_t *)sp : (uint64_t)(int64_t)*(int16_t *)sp;
  case 4: return (s->flags & CTF_UNSIGNED) ? (uint64_t)*(uint32_t *)sp : (uint64_t)(int64_t)*(int32_t *)sp;
  default: return *(uint64_t *)sp;
  }
}

static void ct_writeint(CType *d, uint8_t *dp, uint64_t v)
{
  switch (d->size) {
  case 1: *(uint8_t *)dp = (uint8_t)v; break;
  case 2: *(uint16_t *)dp = (uint16_t)v; break;
  case 4: *(uint32_t *)dp = (uint32_t)v; break;
  default: *(uint64_t *)dp = v; break;
  }
}

/* Convert a double to a numeric C type. */
static void cconv_num_double(CType *d, uint8_t *dp, double n)
{
  if (d->flags & CTF_BOOL) { *dp = (n != 0); return; }
  if (d->flags & CTF_FP) {
    if (d->size == 4) *(float *)dp = (float)n;
    else if (d->size == 8) *(double *)dp = n;
    else *(long double *)dp = (long double)n;
    return;
  }
  if (d->size == 8 && (d->flags & CTF_UNSIGNED)) *(uint64_t *)dp = num2u64(n);
  else ct_writeint(d, dp, (uint64_t)lj_num2i64(n));
}

static double ct_readdouble(CType *s, uint8_t *sp)
{
  if (s->flags & CTF_FP) {
    if (s->size == 4) return *(float *)sp;
    if (s->size == 8) return *(double *)sp;
    return (double)*(long double *)sp;
  }
  if (s->flags & CTF_BOOL) return *sp ? 1 : 0;
  if (s->size == 8 && (s->flags & CTF_UNSIGNED)) return (double)*(uint64_t *)sp;
  return (double)(int64_t)ct_readint(s, sp);
}

static int ptr_compat(CTState *cts, CTypeID d, CTypeID s)
{
  CType *dc = lj_ctype_raw(cts, d), *sc = lj_ctype_raw(cts, s);
  if (dc->kind == CT_VOID || sc->kind == CT_VOID) return 1;
  if (ctype_unqual_struct(cts, d) == ctype_unqual_struct(cts, s)) return 1;
  if (dc->kind == CT_NUM && sc->kind == CT_NUM && dc->size == sc->size &&
      ((dc->flags ^ sc->flags) & (CTF_FP | CTF_BOOL)) == 0) return 1;
  if (dc->kind == CT_ENUM && sc->kind == CT_NUM) return dc->size == sc->size;
  if (sc->kind == CT_ENUM && dc->kind == CT_NUM) return dc->size == sc->size;
  if (dc->kind == CT_PTR && sc->kind == CT_PTR) return ptr_compat(cts, dc->cid, sc->cid);
  if (dc->kind == CT_ARRAY && sc->kind == CT_ARRAY) return ptr_compat(cts, dc->cid, sc->cid);
  if (dc->kind == CT_FUNC && sc->kind == CT_FUNC) return 1;
  return 0;
}

static void cconv_ct_ct(CTState *cts, CTypeID did, CTypeID sid, uint8_t *dp, uint8_t *sp, int flags)
{
  CType *d = lj_ctype_raw(cts, did);
  CType *s = lj_ctype_raw(cts, sid);
  CType tmpd, tmps;
  if (d->kind == CT_ENUM) { tmpd = *lj_ctype_raw(cts, d->cid); d = &tmpd; }
  if (s->kind == CT_ENUM) { tmps = *lj_ctype_raw(cts, s->cid); s = &tmps; }
  switch (d->kind) {
  case CT_NUM:
    switch (s->kind) {
    case CT_NUM:
      if (s->flags & CTF_FP) cconv_num_double(d, dp, ct_readdouble(s, sp));
      else if (d->flags & CTF_BOOL) *dp = ct_readint(s, sp) != 0;
      else if (d->flags & CTF_FP) cconv_num_double(d, dp, ct_readdouble(s, sp));
      else ct_writeint(d, dp, ct_readint(s, sp));
      return;
    case CT_PTR: case CT_REF:
      if (!(flags & CCF_CAST)) break;
      if (d->flags & CTF_FP) cconv_num_double(d, dp, (double)(uintptr_t)*(void **)sp);
      else ct_writeint(d, dp, (uint64_t)(uintptr_t)*(void **)sp);
      return;
    case CT_ARRAY:
      if (s->flags & CTF_COMPLEX) {
        CType *e = lj_ctype_raw(cts, s->cid);
        cconv_num_double(d, dp, ct_readdouble(e, sp));
        return;
      }
      if (!(flags & CCF_CAST)) break;
      ct_writeint(d, dp, (uint64_t)(uintptr_t)sp);
      return;
    case CT_FUNC:
      if (!(flags & CCF_CAST)) break;
      ct_writeint(d, dp, (uint64_t)(uintptr_t)*(void **)sp);
      return;
    default:
      break;
    }
    break;
  case CT_PTR:
  case CT_REF:
    switch (s->kind) {
    case CT_PTR: case CT_REF:
      if (!(flags & CCF_CAST) && !ptr_compat(cts, d->cid, s->cid)) break;
      *(void **)dp = *(void **)sp;
      return;
    case CT_ARRAY:
      if (s->flags & CTF_COMPLEX) break;
      if (!(flags & CCF_CAST) && !ptr_compat(cts, d->cid, s->cid)) break;
      *(void **)dp = sp;
      return;
    case CT_STRUCT:
      if (!(flags & CCF_CAST) && !ptr_compat(cts, d->cid, sid)) break;
      *(void **)dp = sp;
      return;
    case CT_FUNC:
      *(void **)dp = *(void **)sp;
      return;
    case CT_NUM:
      if (!(flags & CCF_CAST)) break;
      if (s->flags & CTF_FP) *(void **)dp = (void *)(uintptr_t)num2u64(ct_readdouble(s, sp));
      else *(void **)dp = (void *)(uintptr_t)ct_readint(s, sp);
      return;
    default:
      break;
    }
    break;
  case CT_ARRAY:
    if (d->flags & CTF_COMPLEX) {
      CType *de = lj_ctype_raw(cts, d->cid);
      uint32_t esz = de->size;
      if (s->kind == CT_NUM) {
        cconv_num_double(de, dp, ct_readdouble(s, sp));
        cconv_num_double(de, dp + esz, 0);
        return;
      }
      if (s->kind == CT_ARRAY && (s->flags & CTF_COMPLEX)) {
        CType *se = lj_ctype_raw(cts, s->cid);
        cconv_num_double(de, dp, ct_readdouble(se, sp));
        cconv_num_double(de, dp + esz, ct_readdouble(se, sp + se->size));
        return;
      }
      break;
    }
    if (s->kind == CT_ARRAY && !(s->flags & CTF_COMPLEX) && ptr_compat(cts, d->cid, s->cid) &&
        d->size != CTSIZE_INVALID) {
      memcpy(dp, sp, d->size);
      return;
    }
    break;
  case CT_STRUCT:
    if (s->kind == CT_STRUCT && ctype_unqual_struct(cts, did) == ctype_unqual_struct(cts, sid)) {
      memcpy(dp, sp, d->size);
      return;
    }
    break;
  default:
    break;
  }
  cconv_err_ct(cts, did, sid, flags);
}

static int cconv_ct_tv(CTState *cts, CTypeID did, uint8_t *dp, cTValue *o, int flags);
static void cconv_tv_ct(CTState *cts, CTypeID sid, TValue *o, uint8_t *sp);
extern void *lj_ffi_callback_new(CTState *cts, CTypeID fid, cTValue *fn);

/* Get enum constant by name. */
static int enum_lookup(CTState *cts, CTypeID eid, GCstr *name, int64_t *v)
{
  CTypeID c;
  eid = ctype_unqual_struct(cts, eid);
  for (c = cts->tab[eid].first; c; c = cts->tab[c].next) {
    if (cts->tab[c].name == name) {
      *v = cts->tab[c].value;
      return 1;
    }
  }
  return 0;
}

static void cconv_tab_init(CTState *cts, CTypeID did, uint8_t *dp, GCtab *t, int flags);

static int cconv_ct_tv(CTState *cts, CTypeID did, uint8_t *dp, cTValue *o, int flags)
{
  CType *d = lj_ctype_raw(cts, did);
  switch (o->tt) {
  case LJ_TNUM: {
    double n = o->u.n;
    if (d->kind == CT_NUM) { cconv_num_double(d, dp, n); return 1; }
    if (d->kind == CT_ENUM) { cconv_num_double(lj_ctype_raw(cts, d->cid), dp, n); return 1; }
    if (d->kind == CT_ARRAY && (d->flags & CTF_COMPLEX)) {
      CType *e = lj_ctype_raw(cts, d->cid);
      cconv_num_double(e, dp, n);
      cconv_num_double(e, dp + e->size, 0);
      return 1;
    }
    if ((d->kind == CT_PTR || d->kind == CT_REF) && (flags & CCF_CAST)) {
      *(void **)dp = (void *)(uintptr_t)num2u64(n);
      return 1;
    }
    cconv_err(cts, did, "number", flags);
  }
  case LJ_TTRUE:
  case LJ_TFALSE:
    if (d->kind == CT_NUM) {
      if (d->flags & CTF_BOOL) *dp = (o->tt == LJ_TTRUE);
      else cconv_num_double(d, dp, o->tt == LJ_TTRUE ? 1 : 0);
      return 1;
    }
    if (d->kind == CT_ENUM) { cconv_num_double(lj_ctype_raw(cts, d->cid), dp, o->tt == LJ_TTRUE ? 1 : 0); return 1; }
    cconv_err(cts, did, "boolean", flags);
  case LJ_TNIL:
    if (d->kind == CT_PTR || d->kind == CT_REF) { *(void **)dp = NULL; return 1; }
    cconv_err(cts, did, "nil", flags);
  case LJ_TSTR: {
    GCstr *s = strV(o);
    if (d->kind == CT_PTR || d->kind == CT_REF) {
      CType *e = lj_ctype_raw(cts, d->cid);
      if (e->kind == CT_VOID || (e->kind == CT_NUM && e->size == 1) || (flags & CCF_CAST)) {
        *(const char **)dp = strdata(s);
        return 1;
      }
      cconv_err(cts, did, "string", flags);
    }
    if (d->kind == CT_ENUM) {
      int64_t v;
      if (enum_lookup(cts, did, s, &v)) {
        ct_writeint(lj_ctype_raw(cts, d->cid), dp, (uint64_t)v);
        return 1;
      }
      cconv_err(cts, did, "string", flags);
    }
    if (d->kind == CT_ARRAY && !(d->flags & CTF_COMPLEX)) {
      CType *e = lj_ctype_raw(cts, d->cid);
      if (e->kind == CT_NUM && e->size == 1) {
        size_t n = s->len + 1;
        if (d->size != CTSIZE_INVALID && n > d->size) n = d->size;
        memcpy(dp, strdata(s), n);
        return 1;
      }
    }
    cconv_err(cts, did, "string", flags);
  }
  case LJ_TTAB:
    if ((d->kind == CT_ARRAY && !(d->flags & CTF_COMPLEX)) || d->kind == CT_STRUCT) {
      cconv_tab_init(cts, did, dp, tabV(o), flags);
      return 1;
    }
    if (d->kind == CT_ARRAY && (d->flags & CTF_COMPLEX)) {
      cconv_tab_init(cts, did, dp, tabV(o), flags);
      return 1;
    }
    cconv_err(cts, did, "table", flags);
  case LJ_TCDATA: {
    GCcdata *cd = cdataV(o);
    CTypeID sid = cd->ctypeid;
    uint8_t *sp = (uint8_t *)cdataptr(cd);
    CType *s = &cts->tab[lj_ctype_rawid(cts, sid)];
    if (sid == CTID_CTYPEID) cconv_err(cts, did, "ctype", flags);
    if (s->kind == CT_REF) {
      sp = *(uint8_t **)sp;
      sid = s->cid;
    }
    cconv_ct_ct(cts, did, sid, dp, sp, flags);
    return 1;
  }
  case LJ_TLIGHTUD:
    if (d->kind == CT_PTR || d->kind == CT_REF) { *(void **)dp = o->u.p; return 1; }
    cconv_err(cts, did, "userdata", flags);
  case LJ_TUDATA:
    if (d->kind == CT_PTR || d->kind == CT_REF) {
      GCudata *ud = udataV(o);
      if (ud->udtype == 1) *(void **)dp = *(void **)ud->align;  /* FILE* */
      else *(void **)dp = (void *)ud->align;
      return 1;
    }
    cconv_err(cts, did, "userdata", flags);
  case LJ_TFUNC:
    if (d->kind == CT_PTR && lj_ctype_raw(cts, d->cid)->kind == CT_FUNC) {
      *(void **)dp = lj_ffi_callback_new(cts, lj_ctype_rawid(cts, d->cid), o);
      return 1;
    }
    cconv_err(cts, did, "function", flags);
  default:
    cconv_err(cts, did, lj_typename(o), flags);
  }
  return 0;
}

static void cconv_struct_field_init(CTState *cts, CTypeID fid, uint8_t *base, cTValue *o, int flags);

static void cconv_tab_init(CTState *cts, CTypeID did, uint8_t *dp, GCtab *t, int flags)
{
  lua_State *L = cts->L;
  CType *d = lj_ctype_raw(cts, did);
  cTValue *v0 = lj_tab_getint(t, 0);
  int start = (v0 && !tvisnil(v0)) ? 0 : 1;
  if (d->kind == CT_ARRAY) {
    CTypeID eid = d->cid;
    uint32_t esz = lj_ctype_size(cts, eid);
    uint32_t nelem = (d->size == CTSIZE_INVALID) ? 0xffffffffu : (esz ? d->size / esz : 0);
    uint32_t i;
    if (d->flags & CTF_COMPLEX) nelem = 2;
    for (i = 0;; i++) {
      cTValue *v = lj_tab_getint(t, (int32_t)i + start);
      if (!v || tvisnil(v)) break;
      if (i >= nelem) lj_err_callermsg(L, strdata(lj_str_pushf(L, "too many initializers for '%s'", ctype_reprz(L, did))));
      cconv_ct_tv(cts, eid, dp + i * esz, v, flags);
    }
    if (i == 1 && d->size != CTSIZE_INVALID && !(d->flags & CTF_COMPLEX)) {
      uint32_t j;
      for (j = 1; j < nelem; j++) memcpy(dp + j * esz, dp, esz);
    }
  } else {
    CTypeID sid = ctype_unqual_struct(cts, did);
    CType *st = &cts->tab[sid];
    CTypeID f;
    int isunion = (st->flags & CTF_UNION) != 0;
    cTValue *v1 = lj_tab_getint(t, 1);
    if ((v0 && !tvisnil(v0)) || (v1 && !tvisnil(v1))) {
      int i = start;
      for (f = st->first; f; f = cts->tab[f].next) {
        cTValue *v;
        if (cts->tab[f].kind != CT_FIELD) continue;
        v = lj_tab_getint(t, i);
        if (!v || tvisnil(v)) break;
        cconv_struct_field_init(cts, f, dp, v, flags);
        i++;
        if (isunion) break;
      }
    } else {
      for (f = st->first; f; f = cts->tab[f].next) {
        cTValue *v;
        if (cts->tab[f].kind != CT_FIELD || !cts->tab[f].name) continue;
        v = lj_tab_getstr(t, cts->tab[f].name);
        if (v && !tvisnil(v)) {
          cconv_struct_field_init(cts, f, dp, v, flags);
          if (isunion) break;
        }
      }
    }
  }
}

/* Write a bitfield. */
static void bitfield_write(CTState *cts, CType *f, uint8_t *base, cTValue *o, int flags)
{
  CType *ft = lj_ctype_raw(cts, f->cid);
  uint8_t *p = base + f->value;
  uint64_t v, mask, unit;
  uint8_t tmp[16];
  uint32_t usz = ft->size;
  memset(tmp, 0, sizeof(tmp));
  if (ft->kind == CT_ENUM) ft = lj_ctype_raw(cts, ft->cid);
  if (ft->flags & CTF_BOOL) {
    cconv_ct_tv(cts, CTID_BOOL, tmp, o, flags);
    v = tmp[0];
  } else {
    CType it = *ft;
    it.size = 8;
    it.flags &= ~CTF_BOOL;
    cconv_ct_tv(cts, (ft->flags & CTF_UNSIGNED) ? CTID_UINT64 : CTID_INT64, tmp, o, flags);
    v = *(uint64_t *)tmp;
  }
  mask = (f->bitsize >= 64) ? ~0ULL : ((1ULL << f->bitsize) - 1);
  unit = 0;
  memcpy(&unit, p, usz > 8 ? 8 : usz);
  unit = (unit & ~(mask << f->bitpos)) | ((v & mask) << f->bitpos);
  memcpy(p, &unit, usz > 8 ? 8 : usz);
}

static void bitfield_read(CTState *cts, CType *f, uint8_t *base, TValue *o)
{
  CType *ft = lj_ctype_raw(cts, f->cid);
  uint8_t *p = base + f->value;
  uint64_t unit = 0, v;
  uint32_t usz = ft->size;
  if (ft->kind == CT_ENUM) ft = lj_ctype_raw(cts, ft->cid);
  memcpy(&unit, p, usz > 8 ? 8 : usz);
  v = unit >> f->bitpos;
  if (f->bitsize < 64) {
    v &= (1ULL << f->bitsize) - 1;
    if (!(ft->flags & (CTF_UNSIGNED | CTF_BOOL)) && f->bitsize > 0 && (v >> (f->bitsize - 1)) & 1)
      v |= ~0ULL << f->bitsize;
  }
  if (ft->flags & CTF_BOOL) setboolV(o, v != 0);
  else if (ft->flags & CTF_UNSIGNED) setnumV(o, (double)(uint32_t)v);
  else setnumV(o, (double)(int32_t)v);
}

static void cconv_struct_field_init(CTState *cts, CTypeID fid, uint8_t *base, cTValue *o, int flags)
{
  CType *f = &cts->tab[fid];
  if (f->flags & CTF_BITFIELD) bitfield_write(cts, f, base, o, flags);
  else cconv_ct_tv(cts, f->cid, base + f->value, o, flags);
}

/* C value to Lua value. */
static void cconv_tv_ct(CTState *cts, CTypeID sid, TValue *o, uint8_t *sp)
{
  CTypeID rid = lj_ctype_rawid(cts, sid);
  CType *s = &cts->tab[rid];
  switch (s->kind) {
  case CT_NUM:
    if (s->flags & CTF_BOOL) { setboolV(o, *sp != 0); return; }
    if (s->flags & CTF_FP) {
      if (s->size == 16) {
        GCcdata *cd = lj_cdata_new(cts, rid, 16);
        memcpy(cdataptr(cd), sp, 16);
        setcdataV(o, cd);
        return;
      }
      setnumV(o, s->size == 4 ? (double)*(float *)sp : *(double *)sp);
      return;
    }
    if (s->size == 8) {
      box_i64(cts, (s->flags & CTF_UNSIGNED) ? CTID_UINT64 : CTID_INT64, *(uint64_t *)sp, o);
      return;
    }
    if (s->flags & CTF_UNSIGNED) setnumV(o, (double)(uint32_t)ct_readint(s, sp));
    else setnumV(o, (double)(int64_t)ct_readint(s, sp));
    return;
  case CT_ENUM: {
    GCcdata *cd = lj_cdata_new(cts, rid, 4);
    memcpy(cdataptr(cd), sp, 4);
    setcdataV(o, cd);
    return;
  }
  case CT_PTR: {
    GCcdata *cd = lj_cdata_new(cts, rid, 8);
    *(void **)cdataptr(cd) = *(void **)sp;
    setcdataV(o, cd);
    return;
  }
  case CT_REF: {
    GCcdata *cd = lj_cdata_new(cts, rid, 8);
    *(void **)cdataptr(cd) = *(void **)sp;
    setcdataV(o, cd);
    return;
  }
  case CT_ARRAY:
    if (s->flags & CTF_COMPLEX) {
      GCcdata *cd = lj_cdata_new(cts, rid, s->size);
      memcpy(cdataptr(cd), sp, s->size);
      setcdataV(o, cd);
      return;
    }
    /* fallthrough */
  case CT_STRUCT: {
    CTypeID refid = lj_ctype_intern(cts, CT_REF, 0, sid, 8, 8, 0);
    GCcdata *cd = lj_cdata_new(cts, refid, 8);
    *(void **)cdataptr(cd) = sp;
    setcdataV(o, cd);
    return;
  }
  case CT_FUNC: {
    CTypeID pid = lj_ctype_intern(cts, CT_PTR, 0, rid, 8, 8, 0);
    GCcdata *cd = lj_cdata_new(cts, pid, 8);
    *(void **)cdataptr(cd) = sp;
    setcdataV(o, cd);
    return;
  }
  default:
    setnilV(o);
    return;
  }
}
EOF
echo ok"}

