/* -- Initialization from argument lists ----------------------------------- */

static LJ_NORET void err_too_many_init(CTState *cts, CTypeID id)
{
  lua_State *L = cts->L;
  lj_err_callermsg(L, strdata(lj_str_pushf(L, "too many initializers for '%s'", ctype_reprz(L, id))));
}

static void cdata_init(CTState *cts, CTypeID id, uint8_t *dp, uint32_t size, TValue *o, int n)
{
  CType *d = lj_ctype_raw(cts, id);
  memset(dp, 0, size);
  if (n == 0) return;
  if (d->kind == CT_NUM || d->kind == CT_PTR || d->kind == CT_ENUM || d->kind == CT_REF) {
    if (n > 1) err_too_many_init(cts, id);
    cconv_ct_tv(cts, id, dp, o, CCF_INIT);
  } else if (d->kind == CT_ARRAY && (d->flags & CTF_COMPLEX)) {
    CType *e = lj_ctype_raw(cts, d->cid);
    if (n == 1) {
      cconv_ct_tv(cts, id, dp, o, CCF_INIT);
    } else {
      if (n > 2) err_too_many_init(cts, id);
      cconv_ct_tv(cts, d->cid, dp, o, CCF_INIT);
      cconv_ct_tv(cts, d->cid, dp + e->size, o + 1, CCF_INIT);
    }
  } else if (d->kind == CT_ARRAY) {
    CTypeID eid = d->cid;
    uint32_t esz = lj_ctype_size(cts, eid);
    uint32_t nelem = esz ? size / esz : 0;
    int i;
    if (n == 1 && (tvistab(o) || tvisstr(o) ||
        (tviscdata(o) && lj_ctype_raw(cts, ctype_typeid_strip(cts, cdataV(o)->ctypeid))->kind == CT_ARRAY))) {
      CType *e = lj_ctype_raw(cts, eid);
      if (tvisstr(o) && e->kind == CT_NUM && e->size == 1) {
        size_t l = strV(o)->len + 1;
        if (l > size) l = size;
        memcpy(dp, strdata(strV(o)), l);
        return;
      }
      if (tvistab(o)) {
        /* Use the actual (possibly VLA) size. */
        CType tmp = *d;
        CTypeID tid = id;
        (void)tmp;
        if (d->size == CTSIZE_INVALID) {
          /* VLA: init only given elements. */
          GCtab *t = tabV(o);
          cTValue *v0 = lj_tab_getint(t, 0);
          int start = (v0 && !tvisnil(v0)) ? 0 : 1;
          uint32_t k;
          for (k = 0;; k++) {
            cTValue *v = lj_tab_getint(t, (int32_t)k + start);
            if (!v || tvisnil(v)) break;
            if (k >= nelem) err_too_many_init(cts, id);
            cconv_ct_tv(cts, eid, dp + k * esz, v, CCF_INIT);
          }
          return;
        }
        cconv_ct_tv(cts, tid, dp, o, CCF_INIT);
        return;
      }
      if (tviscdata(o)) {
        cconv_ct_tv(cts, id, dp, o, CCF_INIT);
        return;
      }
    }
    if ((uint32_t)n > nelem) err_too_many_init(cts, id);
    for (i = 0; i < n; i++) cconv_ct_tv(cts, eid, dp + (uint32_t)i * esz, o + i, CCF_INIT);
    if (n == 1) {
      uint32_t j;
      for (j = 1; j < nelem; j++) memcpy(dp + j * esz, dp, esz);
    }
  } else if (d->kind == CT_STRUCT) {
    CTypeID sid = ctype_unqual_struct(cts, id);
    CType *st = &cts->tab[sid];
    if (n == 1 && (tvistab(o) || (tviscdata(o) && ctype_typeid_strip(cts, cdataV(o)->ctypeid) == sid))) {
      cconv_ct_tv(cts, id, dp, o, CCF_INIT);
    } else {
      CTypeID f;
      int i = 0;
      for (f = st->first; f && i < n; f = cts->tab[f].next) {
        if (cts->tab[f].kind != CT_FIELD) continue;
        cconv_struct_field_init(cts, f, dp, o + i, CCF_INIT);
        i++;
        if (st->flags & CTF_UNION) break;
      }
      if (i < n) err_too_many_init(cts, id);
    }
  } else {
    cconv_ct_tv(cts, id, dp, o, CCF_INIT);
  }
}

/* -- Metatypes ------------------------------------------------------------- */

static cTValue *ffi_meta(CTState *cts, CTypeID id, int mm)
{
  cTValue *tv;
  CType *ct;
  id = ctype_typeid_strip(cts, id);
  ct = &cts->tab[id];
  if (ct->kind == CT_PTR && lj_ctype_raw(cts, ct->cid)->kind == CT_FUNC) return NULL;
  tv = lj_tab_getint(cts->metatypes, (int32_t)id);
  if (tv && tvistab(tv)) {
    cTValue *mo = lj_tab_getstr(tabV(tv), G(cts->L)->mmname[mm]);
    if (mo && !tvisnil(mo)) return mo;
  }
  return NULL;
}

cTValue *lj_ffi_meta(lua_State *L, cTValue *o, int mm)
{
  CTState *cts;
  GCcdata *cd;
  if (!tviscdata(o)) return NULL;
  cts = lj_ctype_state(L);
  cd = cdataV(o);
  if (cd->ctypeid == CTID_CTYPEID) {
    return ffi_meta(cts, *(CTypeID *)cdataptr(cd), mm);
  }
  return ffi_meta(cts, cd->ctypeid, mm);
}

static void call_mm(lua_State *L, cTValue *mo, cTValue *a, cTValue *b, TValue *res, int nargs)
{
  TValue mv = *mo, av = *a, bv = b ? *b : *a;
  ptrdiff_t resoff = (res >= L->stack && res < L->stack + L->stacksize) ? savestack(L, res) : -1;
  TValue *top;
  lj_checkstack(L, 4);
  top = L->top;
  copyTV(top, &mv);
  copyTV(top + 1, &av);
  copyTV(top + 2, &bv);
  L->top = top + 1 + nargs;
  lj_vm_call(L, top, 1);
  L->top--;
  if (res) {
    if (resoff >= 0) copyTV(restorestack(L, resoff), L->top);
    else copyTV(res, L->top);
  }
}

/* -- Indexing ------------------------------------------------------------ */

static CTypeID getfield(CTState *cts, CTypeID sid, GCstr *name, uint32_t *ofs)
{
  CTypeID f;
  sid = ctype_unqual_struct(cts, sid);
  for (f = cts->tab[sid].first; f; f = cts->tab[f].next) {
    CType *fc = &cts->tab[f];
    if (fc->name == name) {
      *ofs = (fc->kind == CT_FIELD) ? (uint32_t)fc->value : 0;
      return f;
    }
    if (fc->kind == CT_FIELD && fc->name == NULL) {
      CType *sub = lj_ctype_raw(cts, fc->cid);
      if (sub->kind == CT_STRUCT) {
        uint32_t o2;
        CTypeID r = getfield(cts, fc->cid, name, &o2);
        if (r) {
          *ofs = (uint32_t)fc->value + o2;
          return r;
        }
      }
    }
  }
  return 0;
}

static int64_t cdata_key_int(CTState *cts, cTValue *k, int *ok)
{
  *ok = 1;
  if (tvisnum(k)) return lj_num2i64(k->u.n);
  if (tviscdata(k)) {
    GCcdata *cd = cdataV(k);
    CType *ct = lj_ctype_raw(cts, cd->ctypeid);
    if (ct->kind == CT_NUM && !(ct->flags & CTF_FP)) return (int64_t)ct_readint(ct, (uint8_t *)cdataptr(cd));
    if (ct->kind == CT_NUM) return lj_num2i64(ct_readdouble(ct, (uint8_t *)cdataptr(cd)));
  }
  *ok = 0;
  return 0;
}

/* Resolve address of indexed element. Returns field/element type id or 0. */
static CTypeID cdata_index(CTState *cts, GCcdata *cd, cTValue *k, uint8_t **pp, CTypeID *metaid, int *isfield, CTypeID *fieldid)
{
  CTypeID id = cd->ctypeid;
  uint8_t *p = (uint8_t *)cdataptr(cd);
  CType *ct;
  int ok;
  *isfield = 0;
  *fieldid = 0;
  id = lj_ctype_rawid(cts, id);
  ct = &cts->tab[id];
  if (ct->kind == CT_REF) {
    p = *(uint8_t **)p;
    id = lj_ctype_rawid(cts, ct->cid);
    ct = &cts->tab[id];
  }
  *metaid = id;
  if (cd->ctypeid == CTID_CTYPEID) {
    CTypeID sid = lj_ctype_rawid(cts, *(CTypeID *)cdataptr(cd));
    CType *sct = &cts->tab[sid];
    if (sct->kind == CT_PTR) { sid = lj_ctype_rawid(cts, sct->cid); sct = &cts->tab[sid]; }
    *metaid = sid;
    if (sct->kind == CT_STRUCT && tvisstr(k)) {
      uint32_t ofs;
      CTypeID f = getfield(cts, sid, strV(k), &ofs);
      if (f && cts->tab[f].kind == CT_CONSTVAL) {
        *fieldid = f;
        return f;
      }
    }
    return 0;
  }
  if (tvisstr(k)) {
    GCstr *name = strV(k);
    if (ct->kind == CT_PTR && lj_ctype_raw(cts, ct->cid)->kind == CT_STRUCT) {
      p = *(uint8_t **)p;
      id = lj_ctype_rawid(cts, ct->cid);
      ct = &cts->tab[id];
      *metaid = id;
    }
    if (ct->kind == CT_STRUCT) {
      uint32_t ofs;
      CTypeID f = getfield(cts, id, name, &ofs);
      if (f) {
        *pp = p + ofs;
        *isfield = 1;
        *fieldid = f;
        return f;
      }
    } else if (ct->kind == CT_ARRAY && (ct->flags & CTF_COMPLEX)) {
      CType *e = lj_ctype_raw(cts, ct->cid);
      if (name->len == 2 && strcmp(strdata(name), "re") == 0) { *pp = p; return ct->cid; }
      if (name->len == 2 && strcmp(strdata(name), "im") == 0) { *pp = p + e->size; return ct->cid; }
    }
    return 0;
  }
  {
    int64_t idx = cdata_key_int(cts, k, &ok);
    if (ok) {
      if (ct->kind == CT_PTR) {
        uint32_t esz = lj_ctype_size(cts, ct->cid);
        if (esz == CTSIZE_INVALID) lj_err_callermsg(cts->L, "size of C type is unknown or too large");
        *pp = *(uint8_t **)p + idx * (int64_t)esz;
        return ct->cid;
      }
      if (ct->kind == CT_ARRAY) {
        uint32_t esz = lj_ctype_size(cts, ct->cid);
        if (esz == CTSIZE_INVALID) lj_err_callermsg(cts->L, "size of C type is unknown or too large");
        if ((ct->flags & CTF_COMPLEX) && (idx < 0 || idx > 1)) idx = idx & 1;
        *pp = p + idx * (int64_t)esz;
        return ct->cid;
      }
    }
  }
  return 0;
}

static LJ_NORET void ffi_index_err(CTState *cts, CTypeID id, cTValue *k)
{
  lua_State *L = cts->L;
  const char *s = ctype_reprz(L, id);
  char buf[512];
  if (tvisstr(k)) {
    snprintf(buf, sizeof(buf), "'%s' has no member named '%s'", s, strdata(strV(k)));
  } else {
    const char *key = tviscdata(k) ? ctype_reprz(L, cdataV(k)->ctypeid) : lj_typename(k);
    snprintf(buf, sizeof(buf), "'%s' cannot be indexed with '%s'", s, key);
  }
  lj_err_msg(L, buf);
}

static int ffi_callback_method(lua_State *L, CTState *cts, GCcdata *cd, cTValue *k, TValue *res);

int lj_ffi_index(lua_State *L, cTValue *o, cTValue *k, TValue *res)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd = cdataV(o);
  uint8_t *p = NULL;
  CTypeID metaid, fid;
  int isfield;
  CTypeID eid = cdata_index(cts, cd, k, &p, &metaid, &isfield, &fid);
  if (eid) {
    CType *f = &cts->tab[eid];
    if (f->kind == CT_CONSTVAL) {
      setnumV(res, (double)f->value);
      return 1;
    }
    if (isfield) {
      if (f->flags & CTF_BITFIELD) {
        bitfield_read(cts, f, p - f->value, res);
        return 1;
      }
      eid = f->cid;
    }
    {
      TValue tmp;
      cconv_tv_ct(cts, eid, &tmp, p);
      copyTV(res, &tmp);
    }
    return 1;
  }
  if (tvisstr(k) && ffi_callback_method(L, cts, cd, k, res)) return 1;
  {
    cTValue *mo = ffi_meta(cts, metaid, MM_index);
    if (!mo) ffi_index_err(cts, metaid, k);
    if (tvisfunc(mo)) {
      call_mm(L, mo, o, k, res, 2);
      return 1;
    }
    if (tvistab(mo)) {
      TValue tv = *mo, kv = *k;
      TValue r;
      lj_vm_gettable(L, &tv, &kv, &r);
      if (tvisnil(&r)) ffi_index_err(cts, metaid, k);
      copyTV(res, &r);
      return 1;
    }
    {
      TValue tv = *mo, kv = *k;
      lj_vm_gettable(L, &tv, &kv, res);
    }
  }
  return 1;
}

int lj_ffi_newindex(lua_State *L, cTValue *o, cTValue *k, cTValue *v)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd = cdataV(o);
  uint8_t *p = NULL;
  CTypeID metaid, fid;
  int isfield;
  CTypeID eid = cdata_index(cts, cd, k, &p, &metaid, &isfield, &fid);
  if (eid) {
    CType *f = &cts->tab[eid];
    CType *et;
    if (f->kind == CT_CONSTVAL) lj_err_msg(L, "attempt to write to constant location");
    if (isfield) {
      if (f->flags & CTF_BITFIELD) {
        bitfield_write(cts, f, p - f->value, v, 0);
        return 1;
      }
      eid = f->cid;
    }
    et = lj_ctype_raw(cts, eid);
    if ((et->flags & CTF_CONST) && et->kind != CT_STRUCT)
      lj_err_msg(L, "attempt to write to constant location");
    {
      CTypeID cid = lj_ctype_rawid(cts, cd->ctypeid);
      CType *cct = &cts->tab[cid];
      if (cct->kind == CT_ARRAY && (cct->flags & CTF_COMPLEX))
        lj_err_msg(L, "attempt to write to constant location");
    }
    cconv_ct_tv(cts, eid, p, v, 0);
    return 1;
  }
  {
    cTValue *mo = ffi_meta(cts, metaid, MM_newindex);
    if (!mo) ffi_index_err(cts, metaid, k);
    if (tvisfunc(mo)) {
      TValue mv = *mo, ov = *o, kv = *k, vv = *v;
      TValue *top;
      lj_checkstack(L, 4);
      top = L->top;
      copyTV(top, &mv); copyTV(top + 1, &ov); copyTV(top + 2, &kv); copyTV(top + 3, &vv);
      L->top = top + 4;
      lj_vm_call(L, top, 0);
      return 1;
    }
    {
      TValue tv = *mo;
      lj_vm_settable(L, &tv, k, v);
    }
  }
  return 1;
}

/* -- Arithmetic --------------------------------------------------------- */

typedef struct CDArg {
  CTypeID id;     /* raw type id (0 for Lua number) */
  CType *ct;
  uint8_t *p;
  double n;
  int isnum;      /* Lua number */
  int isnil;
} CDArg;

static int carith_arg(CTState *cts, cTValue *o, CDArg *a)
{
  memset(a, 0, sizeof(*a));
  if (tvisnum(o)) { a->isnum = 1; a->n = o->u.n; return 1; }
  if (tvisnil(o)) { a->isnil = 1; return 1; }
  if (tviscdata(o)) {
    GCcdata *cd = cdataV(o);
    CTypeID id = lj_ctype_rawid(cts, cd->ctypeid);
    CType *ct = &cts->tab[id];
    uint8_t *p = (uint8_t *)cdataptr(cd);
    if (cd->ctypeid == CTID_CTYPEID) return 0;
    if (ct->kind == CT_REF) {
      p = *(uint8_t **)p;
      id = lj_ctype_rawid(cts, ct->cid);
      ct = &cts->tab[id];
    }
    if (ct->kind == CT_ARRAY && !(ct->flags & CTF_COMPLEX)) {
      /* Arrays decay to pointers. */
      a->id = id;
      a->ct = ct;
      a->p = p;
      return 1;
    }
    a->id = id;
    a->ct = ct;
    a->p = p;
    return 1;
  }
  return 0;
}

static int arg_isptr(CDArg *a)
{
  return a->ct && (a->ct->kind == CT_PTR || (a->ct->kind == CT_ARRAY && !(a->ct->flags & CTF_COMPLEX)));
}

static uint8_t *arg_ptrval(CDArg *a)
{
  if (a->ct->kind == CT_PTR) return *(uint8_t **)a->p;
  return a->p;
}

static int arg_isnum(CDArg *a)
{
  if (a->isnum) return 1;
  if (!a->ct) return 0;
  return a->ct->kind == CT_NUM || a->ct->kind == CT_ENUM;
}

static int arg_isu64(CTState *cts, CDArg *a)
{
  CType *ct = a->ct;
  if (!ct) return 0;
  if (ct->kind == CT_ENUM) ct = lj_ctype_raw(cts, ct->cid);
  return ct->kind == CT_NUM && ct->size == 8 && (ct->flags & CTF_UNSIGNED) && !(ct->flags & CTF_FP);
}

static uint64_t arg_toint(CTState *cts, CDArg *a, int u)
{
  CType *ct;
  if (a->isnum) return u ? num2u64(a->n) : (uint64_t)lj_num2i64(a->n);
  ct = a->ct;
  if (ct->kind == CT_ENUM) ct = lj_ctype_raw(cts, ct->cid);
  if (ct->flags & CTF_FP) {
    double d = ct_readdouble(ct, a->p);
    return u ? num2u64(d) : (uint64_t)lj_num2i64(d);
  }
  return ct_readint(ct, a->p);
}

static const char *arg_typename(lua_State *L, cTValue *o)
{
  if (tviscdata(o)) return ctype_reprz(L, cdataV(o)->ctypeid);
  return lj_typename(o);
}

static uint64_t powi64(uint64_t x, uint64_t k, int isu)
{
  uint64_t y;
  if (!isu && (int64_t)k < 0) {
    if ((int64_t)x == 1) return 1;
    if ((int64_t)x == -1) return (k & 1) ? (uint64_t)-1 : 1;
    if (x == 0) return 0x8000000000000000ULL;
    return 0;
  }
  if (k == 0) return 1;
  for (; (k & 1) == 0; k >>= 1) x *= x;
  y = x;
  if ((k >>= 1) != 0) {
    for (;;) {
      x *= x;
      if (k == 1) break;
      if (k & 1) y *= x;
      k >>= 1;
    }
    y *= x;
  }
  return y;
}

static void enum_string_conv(CTState *cts, CDArg *a, CDArg *b, cTValue *ob)
{
  /* enum vs string: convert string to enum constant value. */
  if (a->ct && a->ct->kind == CT_ENUM && tvisstr(ob)) {
    int64_t v;
    if (enum_lookup(cts, a->id, strV(ob), &v)) {
      memset(b, 0, sizeof(*b));
      b->isnum = 1;
      b->n = (double)v;
    }
  }
}

int lj_ffi_arith(lua_State *L, TValue *ra, cTValue *rb, cTValue *rc, int mm)
{
  CTState *cts = lj_ctype_state(L);
  CDArg a, b;
  int oka = carith_arg(cts, rb, &a);
  int okb = carith_arg(cts, rc, &b);
  if (!okb && oka && tvisstr(rc)) { enum_string_conv(cts, &a, &b, rc); okb = b.isnum; }
  if (!oka && okb && tvisstr(rb)) { enum_string_conv(cts, &b, &a, rb); oka = a.isnum; }
  if (oka && okb && !a.isnil && !b.isnil) {
    /* Pointer arithmetic. */
    if (arg_isptr(&a) && (mm == MM_add || mm == MM_sub) && arg_isnum(&b)) {
      CTypeID eid = a.ct->cid;
      uint32_t esz = lj_ctype_size(cts, eid);
      int64_t n = (int64_t)arg_toint(cts, &b, 0);
      CTypeID pid;
      GCcdata *cd;
      if (esz == CTSIZE_INVALID) lj_err_msg(L, "size of C type is unknown or too large");
      if (mm == MM_sub) n = -n;
      pid = (a.ct->kind == CT_PTR) ? a.id : lj_ctype_intern(cts, CT_PTR, 0, eid, 8, 8, 0);
      cd = lj_cdata_new(cts, pid, 8);
      *(uint8_t **)cdataptr(cd) = arg_ptrval(&a) + n * (int64_t)esz;
      setcdataV(ra, cd);
      return 1;
    }
    if (arg_isptr(&b) && mm == MM_add && arg_isnum(&a)) {
      CTypeID eid = b.ct->cid;
      uint32_t esz = lj_ctype_size(cts, eid);
      int64_t n = (int64_t)arg_toint(cts, &a, 0);
      CTypeID pid;
      GCcdata *cd;
      if (esz == CTSIZE_INVALID) lj_err_msg(L, "size of C type is unknown or too large");
      pid = (b.ct->kind == CT_PTR) ? b.id : lj_ctype_intern(cts, CT_PTR, 0, eid, 8, 8, 0);
      cd = lj_cdata_new(cts, pid, 8);
      *(uint8_t **)cdataptr(cd) = arg_ptrval(&b) + n * (int64_t)esz;
      setcdataV(ra, cd);
      return 1;
    }
    if (arg_isptr(&a) && arg_isptr(&b) && mm == MM_sub) {
      uint32_t esz = lj_ctype_size(cts, a.ct->cid);
      int64_t diff;
      if (esz == CTSIZE_INVALID || esz == 0) lj_err_msg(L, "size of C type is unknown or too large");
      diff = (int64_t)(arg_ptrval(&a) - arg_ptrval(&b)) / (int64_t)esz;
      setnumV(ra, (double)diff);
      return 1;
    }
    /* 64 bit integer arithmetic. */
    if (arg_isnum(&a) && arg_isnum(&b) && !(a.ct && a.ct->kind == CT_NUM && (a.ct->flags & CTF_FP) && a.ct->size == 16)) {
      int isu = arg_isu64(cts, &a) || arg_isu64(cts, &b);
      uint64_t x = arg_toint(cts, &a, isu), y = arg_toint(cts, &b, isu), r;
      switch (mm) {
      case MM_add: r = x + y; break;
      case MM_sub: r = x - y; break;
      case MM_mul: r = x * y; break;
      case MM_div:
        if (y == 0) r = 0x8000000000000000ULL;
        else if (isu) r = x / y;
        else if ((int64_t)x == INT64_MIN && (int64_t)y == -1) r = x;
        else r = (uint64_t)((int64_t)x / (int64_t)y);
        break;
      case MM_mod:
        if (y == 0) r = 0x8000000000000000ULL;
        else if (isu) r = x % y;
        else if ((int64_t)x == INT64_MIN && (int64_t)y == -1) r = 0;
        else {
          int64_t m = (int64_t)x % (int64_t)y;
          if (m && ((m ^ (int64_t)y) < 0)) m += (int64_t)y;
          r = (uint64_t)m;
        }
        break;
      case MM_pow: r = powi64(x, y, isu); break;
      case MM_unm: r = (uint64_t)0 - x; break;
      default: return 0;
      }
      box_i64(cts, isu ? CTID_UINT64 : CTID_INT64, r, ra);
      return 1;
    }
  }
  /* Metamethods. */
  {
    cTValue *mo = NULL;
    if (tviscdata(rb)) mo = lj_ffi_meta(L, rb, mm);
    if (!mo && tviscdata(rc)) mo = lj_ffi_meta(L, rc, mm);
    if (mo) {
      call_mm(L, mo, rb, rc, ra, 2);
      return 1;
    }
  }
  {
    char buf[512];
    if (mm == MM_unm)
      snprintf(buf, sizeof(buf), "attempt to perform arithmetic on '%s'", arg_typename(L, rb));
    else
      snprintf(buf, sizeof(buf), "attempt to perform arithmetic on '%s' and '%s'", arg_typename(L, rb), arg_typename(L, rc));
    lj_err_msg(L, buf);
  }
}

int lj_ffi_concat(lua_State *L, TValue *ra, cTValue *rb, cTValue *rc)
{
  cTValue *mo = NULL;
  char buf[512];
  if (tviscdata(rb)) mo = lj_ffi_meta(L, rb, MM_concat);
  if (!mo && tviscdata(rc)) mo = lj_ffi_meta(L, rc, MM_concat);
  if (mo) {
    call_mm(L, mo, rb, rc, ra, 2);
    return 1;
  }
  snprintf(buf, sizeof(buf), "attempt to concatenate '%s' and '%s'", arg_typename(L, rb), arg_typename(L, rc));
  lj_err_msg(L, buf);
}

int lj_ffi_len(lua_State *L, cTValue *o, TValue *res)
{
  cTValue *mo = lj_ffi_meta(L, o, MM_len);
  char buf[256];
  if (mo) {
    call_mm(L, mo, o, o, res, 1);
    return 1;
  }
  snprintf(buf, sizeof(buf), "attempt to get length of '%s'", arg_typename(L, o));
  lj_err_msg(L, buf);
}

int lj_ffi_compare(lua_State *L, cTValue *l, cTValue *r, int le, int *res)
{
  CTState *cts = lj_ctype_state(L);
  CDArg a, b;
  int oka = carith_arg(cts, l, &a);
  int okb = carith_arg(cts, r, &b);
  if (!okb && oka && tvisstr(r)) { enum_string_conv(cts, &a, &b, r); okb = b.isnum; }
  if (!oka && okb && tvisstr(l)) { enum_string_conv(cts, &b, &a, l); oka = a.isnum; }
  if (oka && okb) {
    if ((arg_isptr(&a) || a.isnil) && (arg_isptr(&b) || b.isnil) && !(a.isnil && b.isnil)) {
      uintptr_t x = a.isnil ? 0 : (uintptr_t)arg_ptrval(&a);
      uintptr_t y = b.isnil ? 0 : (uintptr_t)arg_ptrval(&b);
      *res = le ? x <= y : x < y;
      return 1;
    }
    if (arg_isnum(&a) && arg_isnum(&b)) {
      int isu = arg_isu64(cts, &a) || arg_isu64(cts, &b);
      uint64_t x = arg_toint(cts, &a, isu), y = arg_toint(cts, &b, isu);
      if (isu) *res = le ? x <= y : x < y;
      else *res = le ? (int64_t)x <= (int64_t)y : (int64_t)x < (int64_t)y;
      return 1;
    }
  }
  {
    cTValue *mo = NULL;
    int mm = le ? MM_le : MM_lt;
    if (tviscdata(l)) mo = lj_ffi_meta(L, l, mm);
    if (!mo && tviscdata(r)) mo = lj_ffi_meta(L, r, mm);
    if (mo) {
      TValue tmp;
      ptrdiff_t off;
      lj_checkstack(L, 1);
      off = savestack(L, L->top);
      setnilV(L->top); L->top++;
      call_mm(L, mo, l, r, restorestack(L, off), 2);
      *res = !tvisfalse(restorestack(L, off));
      L->top--;
      (void)tmp;
      return 1;
    }
    if (le) {
      if (tviscdata(l)) mo = lj_ffi_meta(L, l, MM_lt);
      if (!mo && tviscdata(r)) mo = lj_ffi_meta(L, r, MM_lt);
      if (mo) {
        ptrdiff_t off;
        lj_checkstack(L, 1);
        off = savestack(L, L->top);
        setnilV(L->top); L->top++;
        call_mm(L, mo, r, l, restorestack(L, off), 2);
        *res = tvisfalse(restorestack(L, off));
        L->top--;
        return 1;
      }
    }
  }
  {
    char buf[512];
    snprintf(buf, sizeof(buf), "attempt to compare '%s' with '%s'", arg_typename(L, l), arg_typename(L, r));
    lj_err_msg(L, buf);
  }
}

int lj_ffi_equal(lua_State *L, cTValue *l, cTValue *r)
{
  CTState *cts = lj_ctype_state(L);
  CDArg a, b;
  int oka = carith_arg(cts, l, &a);
  int okb = carith_arg(cts, r, &b);
  if (!okb && oka && tvisstr(r)) { enum_string_conv(cts, &a, &b, r); okb = b.isnum; }
  if (!oka && okb && tvisstr(l)) { enum_string_conv(cts, &b, &a, l); oka = a.isnum; }
  if (oka && okb) {
    if ((arg_isptr(&a) || a.isnil) && (arg_isptr(&b) || b.isnil)) {
      uintptr_t x = a.isnil ? 0 : (uintptr_t)arg_ptrval(&a);
      uintptr_t y = b.isnil ? 0 : (uintptr_t)arg_ptrval(&b);
      return x == y;
    }
    if (arg_isnum(&a) && arg_isnum(&b)) {
      CType *ac = a.ct, *bc = b.ct;
      if (ac && ac->kind == CT_ENUM) ac = lj_ctype_raw(cts, ac->cid);
      if (bc && bc->kind == CT_ENUM) bc = lj_ctype_raw(cts, bc->cid);
      if ((ac && (ac->flags & CTF_FP)) || (bc && (bc->flags & CTF_FP))) {
        /* Compare via int64 like the reference. */
      }
      {
        int isu = arg_isu64(cts, &a) || arg_isu64(cts, &b);
        return arg_toint(cts, &a, isu) == arg_toint(cts, &b, isu);
      }
    }
  }
  {
    cTValue *mo = NULL;
    if (tviscdata(l)) mo = lj_ffi_meta(L, l, MM_eq);
    if (!mo && tviscdata(r)) mo = lj_ffi_meta(L, r, MM_eq);
    if (mo) {
      ptrdiff_t off;
      int res;
      lj_checkstack(L, 1);
      off = savestack(L, L->top);
      setnilV(L->top); L->top++;
      call_mm(L, mo, l, r, restorestack(L, off), 2);
      res = !tvisfalse(restorestack(L, off));
      L->top--;
      return res;
    }
  }
  if (oka && okb && a.ct && b.ct) {
    /* Aggregates: compare base address. */
    if ((a.ct->kind == CT_STRUCT || a.ct->kind == CT_ARRAY) && (b.ct->kind == CT_STRUCT || b.ct->kind == CT_ARRAY))
      return a.p == b.p;
  }
  return l->tt == r->tt && l->u.p == r->u.p;
}

/* -- Conversions to Lua ----------------------------------------------------- */

int lj_ffi_tonumber(lua_State *L, cTValue *o, double *d)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd = cdataV(o);
  CTypeID id = lj_ctype_rawid(cts, cd->ctypeid);
  CType *ct = &cts->tab[id];
  uint8_t *p = (uint8_t *)cdataptr(cd);
  if (cd->ctypeid == CTID_CTYPEID) return 0;
  if (ct->kind == CT_REF) { p = *(uint8_t **)p; id = lj_ctype_rawid(cts, ct->cid); ct = &cts->tab[id]; }
  if (ct->kind == CT_ENUM) ct = lj_ctype_raw(cts, ct->cid);
  if (ct->kind == CT_NUM) {
    *d = ct_readdouble(ct, p);
    return 1;
  }
  if (ct->kind == CT_PTR) {
    *d = (double)(uintptr_t)*(void **)p;
    return 1;
  }
  if (ct->kind == CT_ARRAY && (ct->flags & CTF_COMPLEX)) {
    *d = ct_readdouble(lj_ctype_raw(cts, ct->cid), p);
    return 1;
  }
  return 0;
}

static void fmt_ptr(char *buf, size_t sz, void *p)
{
  if (p == NULL) snprintf(buf, sz, "NULL");
  else snprintf(buf, sz, "0x%08llx", (unsigned long long)(uintptr_t)p);
}

int lj_ffi_tostring(lua_State *L, cTValue *o, char *buf, size_t sz)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd = cdataV(o);
  CTypeID id = cd->ctypeid;
  CTypeID rid;
  CType *ct;
  uint8_t *p = (uint8_t *)cdataptr(cd);
  char pb[64];
  if (id == CTID_CTYPEID) {
    snprintf(buf, sz, "ctype<%s>", ctype_reprz(L, *(CTypeID *)p));
    return 1;
  }
  rid = lj_ctype_rawid(cts, id);
  ct = &cts->tab[rid];
  if (ct->kind == CT_NUM && ct->size == 8 && !(ct->flags & CTF_FP)) {
    if (ct->flags & CTF_UNSIGNED) snprintf(buf, sz, "%lluULL", (unsigned long long)*(uint64_t *)p);
    else snprintf(buf, sz, "%lldLL", (long long)*(int64_t *)p);
    return 1;
  }
  if (ct->kind == CT_ARRAY && (ct->flags & CTF_COMPLEX)) {
    CType *e = lj_ctype_raw(cts, ct->cid);
    double re = ct_readdouble(e, p), im = ct_readdouble(e, p + e->size);
    char b1[64], b2[64];
    lj_str_fmtnum(b1, re);
    lj_str_fmtnum(b2, im);
    if (b2[0] == '-' || (im != im)) snprintf(buf, sz, "%s%si", b1, b2);
    else snprintf(buf, sz, "%s+%si", b1, b2);
    return 1;
  }
  if (ct->kind == CT_ENUM) {
    snprintf(buf, sz, "cdata<%s>: %d", ctype_reprz(L, id), *(int32_t *)p);
    return 1;
  }
  if (ct->kind == CT_PTR || ct->kind == CT_REF)
    fmt_ptr(pb, sizeof(pb), *(void **)p);
  else if (ct->kind == CT_FUNC)
    fmt_ptr(pb, sizeof(pb), *(void **)p);
  else
    fmt_ptr(pb, sizeof(pb), p);
  snprintf(buf, sz, "cdata<%s>: %s", ctype_reprz(L, id), pb);
  return 1;
}
