/* ======================================================================== */
/* -- C function calls (x86-64 System V) ---------------------------------- */

#define CCALL_MAXSTACK 64

typedef struct CCallState {
  void *func;            /* 0 */
  uint64_t nsp;          /* 8 */
  uint64_t gpr[6];       /* 16 */
  double fpr[8];         /* 64 */
  uint64_t retgpr[2];    /* 128 */
  double retfpr[2];      /* 144 */
  uint64_t nfpr;         /* 160 */
  uint64_t stack[CCALL_MAXSTACK]; /* 168 */
} CCallState;

