  "  ret\n"
  ".size lj_ccall_do, .-lj_ccall_do\n"
);

void lj_ccall_do(CCallState *cc);

#define CLS_NONE 0
#define CLS_INT 1
#define CLS_SSE 2
#define CLS_MEM 3

static void classify_rec(CTState *cts, CTypeID id, uint32_t ofs, int *cls)
{
  CType *ct = lj_ctype_raw(cts, id);
  if (ct->kind == CT_STRUCT) {
    CTypeID f;
    for (f = cts->tab[ctype_unqual_struct(cts, id)].first; f; f = cts->tab[f].next) {
      if (cts->tab[f].kind != CT_FIELD) continue;
      classify_rec(cts, cts->tab[f].cid, ofs + (uint32_t)cts->tab[f].value, cls);
    }
  } else if (ct->kind == CT_ARRAY) {
    uint32_t esz = lj_ctype_size(cts, ct->cid), i, n = (esz && ct->size != CTSIZE_INVALID) ? ct->size / esz : 0;
    for (i = 0; i < n; i++) classify_rec(cts, ct->cid, ofs + i * esz, cls);
  } else {
    int c = (ct->kind == CT_NUM && (ct->flags & CTF_FP)) ? CLS_SSE : CLS_INT;
    int idx = (int)(ofs / 8);
    if (idx < 2) {
      if (cls[idx] == CLS_NONE) cls[idx] = c;
      else if (c == CLS_INT) cls[idx] = CLS_INT;
    }
  }
}

static void classify_struct(CTState *cts, CTypeID id, int *cls)
{
  uint32_t sz = lj_ctype_size(cts, id);
  cls[0] = cls[1] = CLS_NONE;
  if (sz > 16 || sz == 0) { cls[0] = cls[1] = CLS_MEM; return; }
  classify_rec(cts, id, 0, cls);
  if (sz <= 8) cls[1] = CLS_NONE;
  if (cls[0] == CLS_NONE) cls[0] = CLS_SSE;
  if (sz > 8 && cls[1] == CLS_NONE) cls[1] = CLS_SSE;
}

static LJ_NORET void err_wrongargs(lua_State *L)
{
  lj_err_callermsg(L, "wrong number of arguments for function call");
}

extern int lj_ffi_savederrno;
int lj_ffi_savederrno = 0;

/* Call C function. Args at L->base+1 .. L->top. Returns number of results. */
static int ccall(lua_State *L, CTState *cts, CTypeID fid, void *fptr)
{
  CType *ft = &cts->tab[fid];
  CCallState cc;
  int ngpr = 0, nfpr = 0, nsp = 0;
  int nargs = (int)(L->top - L->base) - 1;
  int i;
  CTypeID pid;
  CTypeID rid = lj_ctype_rawid(cts, ft->cid);
  CType *rt = &cts->tab[rid];
  int retcls[2] = {CLS_NONE, CLS_NONE};
  GCcdata *retcd = NULL;
  uint8_t argbuf[64];
  int nparams = 0;
  memset(&cc, 0, sizeof(cc));
  cc.func = fptr;
  for (pid = ft->first; pid; pid = cts->tab[pid].next) nparams++;
  if (nargs < nparams || (nargs > nparams && !(ft->flags & CTF_VARARG))) err_wrongargs(L);
  /* Struct return. */
  if (rt->kind == CT_STRUCT || (rt->kind == CT_ARRAY && (rt->flags & CTF_COMPLEX))) {
    if (rt->kind == CT_ARRAY) {
      retcls[0] = CLS_SSE;
      retcls[1] = rt->size > 8 ? CLS_SSE : CLS_NONE;
      if (rt->size == 8) { retcls[0] = CLS_SSE; retcls[1] = CLS_NONE; }
    } else {
      classify_struct(cts, rid, retcls);
    }
    retcd = cdata_push(cts, rid, rt->size);
    if (retcls[0] == CLS_MEM) cc.gpr[ngpr++] = (uint64_t)(uintptr_t)cdataptr(retcd);
  }
  pid = ft->first;
  for (i = 0; i < nargs; i++) {
    TValue *o = L->base + 1 + i;
    CTypeID aid;
    CType *at;
    if (pid) {
      aid = cts->tab[pid].cid;
      pid = cts->tab[pid].next;
    } else {
      /* Vararg conversion rules. */
      if (tvisnum(o)) aid = CTID_DOUBLE;
      else if (tvisstr(o)) aid = CTID_P_CCHAR;
      else if (tvisbool(o)) aid = CTID_BOOL;
      else if (tvisnil(o) || tvisudata(o) || tvislightud(o)) aid = CTID_P_VOID;
      else if (tviscdata(o)) {
        CTypeID cid = cdataV(o)->ctypeid;
        CType *cct = lj_ctype_raw(cts, cid);
        if (cct->kind == CT_REF) { cid = cct->cid; cct = lj_ctype_raw(cts, cid); }
        if (cct->kind == CT_NUM && (cct->flags & CTF_FP) && cct->size == 4) aid = CTID_DOUBLE;
        else if (cct->kind == CT_ARRAY && !(cct->flags & CTF_COMPLEX)) aid = lj_ctype_intern(cts, CT_PTR, 0, cct->cid, 8, 8, 0);
        else if (cct->kind == CT_STRUCT) aid = lj_ctype_intern(cts, CT_PTR, 0, cid, 8, 8, 0);
        else if (cct->kind == CT_FUNC) aid = lj_ctype_intern(cts, CT_PTR, 0, cid, 8, 8, 0);
        else aid = cid;
      } else {
        aid = CTID_P_VOID;
      }
    }
    at = lj_ctype_raw(cts, aid);
    if (at->kind == CT_STRUCT || (at->kind == CT_ARRAY && (at->flags & CTF_COMPLEX))) {
      uint32_t sz = at->size;
      int cls[2];
      uint8_t *buf;
      uint32_t nw = (sz + 7) / 8, k;
      GCcdata *tmp = cdata_push(cts, aid, sz);
      buf = (uint8_t *)cdataptr(tmp);
      memset(buf, 0, sz);
      cconv_ct_tv(cts, aid, buf, o, CCF_ARG(i + 1));
      if (at->kind == CT_ARRAY) { cls[0] = CLS_SSE; cls[1] = sz > 8 ? CLS_SSE : CLS_NONE; }
      else classify_struct(cts, aid, cls);
      {
        int needg = (cls[0] == CLS_INT) + (cls[1] == CLS_INT);
        int needf = (cls[0] == CLS_SSE) + (cls[1] == CLS_SSE);
        if (cls[0] != CLS_MEM && ngpr + needg <= 6 && nfpr + needf <= 8) {
          for (k = 0; k < nw; k++) {
            uint64_t w = 0;
            memcpy(&w, buf + k * 8, (sz - k * 8) >= 8 ? 8 : (sz - k * 8));
            if (cls[k] == CLS_INT) cc.gpr[ngpr++] = w;
            else memcpy(&cc.fpr[nfpr++], &w, 8);
          }
        } else {
          for (k = 0; k < nw; k++) {
            uint64_t w = 0;
            memcpy(&w, buf + k * 8, (sz - k * 8) >= 8 ? 8 : (sz - k * 8));
            if (nsp >= CCALL_MAXSTACK) lj_err_callermsg(L, "too many arguments");
            cc.stack[nsp++] = w;
          }
        }
      }
      continue;
    }
    memset(argbuf, 0, sizeof(argbuf));
    if (at->kind == CT_ARRAY) {
      aid = lj_ctype_intern(cts, CT_PTR, 0, at->cid, 8, 8, 0);
      at = lj_ctype_raw(cts, aid);
    }
    cconv_ct_tv(cts, aid, argbuf, o, CCF_ARG(i + 1));
    if (at->kind == CT_NUM && (at->flags & CTF_FP)) {
      double d;
      if (at->size == 4) {
        uint64_t w = 0;
        memcpy(&w, argbuf, 4);
        memcpy(&d, &w, 8);
      } else {
        memcpy(&d, argbuf, 8);
      }
      if (nfpr < 8) cc.fpr[nfpr++] = d;
      else { if (nsp >= CCALL_MAXSTACK) lj_err_callermsg(L, "too many arguments"); memcpy(&cc.stack[nsp++], &d, 8); }
    } else {
      uint64_t w;
      CType *it = at->kind == CT_ENUM ? lj_ctype_raw(cts, at->cid) : at;
      if (it->kind == CT_NUM) w = ct_readint(it, argbuf);
      else memcpy(&w, argbuf, 8);
      if (ngpr < 6) cc.gpr[ngpr++] = w;
      else { if (nsp >= CCALL_MAXSTACK) lj_err_callermsg(L, "too many arguments"); cc.stack[nsp++] = w; }
    }
  }
  cc.nsp = (uint64_t)nsp;
  cc.nfpr = (uint64_t)nfpr;
  errno = lj_ffi_savederrno;
  lj_ccall_do(&cc);
  lj_ffi_savederrno = errno;
  /* Convert result. */
  if (retcd) {
    uint8_t *rp = (uint8_t *)cdataptr(retcd);
    if (retcls[0] != CLS_MEM) {
      int gi = 0, fi = 0, k;
      uint32_t sz = rt->size;
      for (k = 0; k < 2 && (uint32_t)k * 8 < sz; k++) {
        uint64_t w;
        if (retcls[k] == CLS_INT) w = cc.retgpr[gi++];
        else memcpy(&w, &cc.retfpr[fi++], 8);
        memcpy(rp + k * 8, &w, (sz - k * 8) >= 8 ? 8 : (sz - k * 8));
      }
    }
    lj_checkstack(L, 1);
    setcdataV(L->top, retcd);
    L->top++;
    return 1;
  }
  if (rt->kind == CT_VOID) return 0;
  {
    uint8_t rb[16];
    TValue res;
    memset(rb, 0, sizeof(rb));
    if (rt->kind == CT_NUM && (rt->flags & CTF_FP)) {
      if (rt->size == 4) memcpy(rb, &cc.retfpr[0], 4);
      else memcpy(rb, &cc.retfpr[0], 8);
    } else {
      memcpy(rb, &cc.retgpr[0], 8);
    }
    cconv_tv_ct(cts, rid, &res, rb);
    lj_checkstack(L, 1);
    copyTV(L->top, &res);
    L->top++;
    return 1;
  }
}

/* -- Callbacks ------------------------------------------------------------- */

#define CB_MAXSLOT 1024

#define CB_SLOTS_ASM \
  ".text\n" \
  ".p2align 4\n" \
  ".globl lj_cb_slots\n" \
  "lj_cb_slots:\n" \
