extern char lj_cb_slots[];

typedef struct CBSlot {
  CTypeID fid;
  int used;
} CBSlot;

static CBSlot cb_slots[CB_MAXSLOT];
static int cb_next = 0;

void *lj_ffi_callback_new(CTState *cts, CTypeID fid, cTValue *fn)
{
  lua_State *L = cts->L;
  int slot = -1, i;
  CType *ft = &cts->tab[fid];
  for (i = 0; i < CB_MAXSLOT; i++) {
    int s = (cb_next + i) % CB_MAXSLOT;
