  return (int)(d / 16);
}

void lj_cb_handler(int slot, uint64_t *regs, uint64_t *stack)
{
  CTState *cts = g_cts;
  lua_State *L = cts->L;
  global_State *g;
  CTypeID fid = cb_slots[slot].fid;
  CType *ft;
  CTypeID pid, rid;
  CType *rt;
  int ngpr = 0, nfpr = 0, nsp = 0, nargs = 0;
  cTValue *fn;
  TValue *base;
  L = lj_ctype_state(L)->L;
  g = G(L);
  L = g->curthread;
  cts->L = L;
  ft = &cts->tab[fid];
  rid = lj_ctype_rawid(cts, ft->cid);
  rt = &cts->tab[rid];
  fn = lj_tab_getint(cts->cbfuncs, slot);
  lj_checkstack(L, 64);
  base = L->top;
  copyTV(L->top, fn ? fn : &lj_nilobj);
  L->top++;
  for (pid = ft->first; pid; pid = cts->tab[pid].next) {
    CTypeID aid = cts->tab[pid].cid;
    CType *at = lj_ctype_raw(cts, aid);
    uint8_t buf[16];
    TValue o;
    memset(buf, 0, sizeof(buf));
    if (at->kind == CT_NUM && (at->flags & CTF_FP)) {
      uint64_t w = (nfpr < 8) ? regs[6 + nfpr++] : stack[nsp++];
      memcpy(buf, &w, 8);
    } else {
      uint64_t w = (ngpr < 6) ? regs[ngpr++] : stack[nsp++];
      memcpy(buf, &w, 8);
    }
    cconv_tv_ct(cts, aid, &o, buf);
    lj_checkstack(L, 1);
    copyTV(L->top, &o);
    L->top++;
    nargs++;
  }
  {
    ptrdiff_t boff = savestack(L, base);
    lj_vm_call(L, base, rt->kind == CT_VOID ? 0 : 1);
    base = restorestack(L, boff);
  }
  regs[14] = regs[15] = 0;
  regs[16] = regs[17] = 0;
  if (rt->kind != CT_VOID) {
    uint8_t rb[16];
    memset(rb, 0, sizeof(rb));
    cts->L = L;
    cconv_ct_tv(cts, rid, rb, base, 0);
    if (rt->kind == CT_NUM && (rt->flags & CTF_FP)) {
      memcpy(&regs[16], rb, 8);
    } else {
      CType *it = rt->kind == CT_ENUM ? lj_ctype_raw(cts, rt->cid) : rt;
      uint64_t w;
      if (it->kind == CT_NUM) w = ct_readint(it, rb);
      else memcpy(&w, rb, 8);
      regs[14] = w;
    }
  }
  L->top = base;
  (void)nargs;
}

static int ffi_callback_method(lua_State *L, CTState *cts, GCcdata *cd, cTValue *k, TValue *res);

static int cb_free(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  TValue *o = L->base;
  int slot;
  if (!(o < L->top && tviscdata(o))) lj_err_argt(L, 1, LJ_TCDATA);
  slot = cb_slot_of(*(void **)cdataptr(cdataV(o)));
  if (slot < 0) lj_err_callermsg(L, "bad callback");
  cb_slots[slot].used = 0;
  {
    TValue *v = lj_tab_setint(L, cts->cbfuncs, slot);
    setnilV(v);
  }
  return 0;
}

static int cb_set(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  TValue *o = L->base;
  int slot;
  if (!(o < L->top && tviscdata(o))) lj_err_argt(L, 1, LJ_TCDATA);
  slot = cb_slot_of(*(void **)cdataptr(cdataV(o)));
  if (slot < 0) lj_err_callermsg(L, "bad callback");
  lj_lib_checkfunc(L, 2);
  {
    TValue *v = lj_tab_setint(L, cts->cbfuncs, slot);
    copyTV(v, L->base + 1);
  }
  return 0;
}

static int ffi_callback_method(lua_State *L, CTState *cts, GCcdata *cd, cTValue *k, TValue *res)
{
  CType *ct = lj_ctype_raw(cts, cd->ctypeid);
  if (ct->kind == CT_PTR && lj_ctype_raw(cts, ct->cid)->kind == CT_FUNC &&
      cb_slot_of(*(void **)cdataptr(cd)) >= 0) {
    const char *s = strdata(strV(k));
    if (strcmp(s, "free") == 0) {
      GCfunc *fn = lj_func_newC(L, 0, cb_free, L->env);
      setfuncV(res, fn);
      return 1;
    }
    if (strcmp(s, "set") == 0) {
      GCfunc *fn = lj_func_newC(L, 0, cb_set, L->env);
      setfuncV(res, fn);
      return 1;
    }
  }
  return 0;
}
