#define CCALL_MAXSTACK 64

typedef struct CCallState {
  void *func;            /* 0 */
  uint64_t nsp;          /* 8 */
  uint64_t gpr[6];       /* 16 */
  double fpr[8];         /* 64 */
  uint64_t retgpr[2];    /* 128 */
