#define CLS_NONE 0
#define CLS_INT 1
#define CLS_SSE 2
#define CLS_MEM 3

static void classify_rec(CTState *cts, CTypeID id, uint32_t ofs, int *cls)
{
  CType *ct = lj_ctype_raw(cts, id);
  if (ct->kind == CT_STRUCT) {
    CTypeID f;
    for (f = cts->tab[ctype_unqual_struct(cts, id)].first; f; f = cts->tab[f].next) {
      if (cts->tab[f].kind != CT_FIELD) continue;
      classify_rec(cts, cts->tab[f].cid, ofs + (uint32_t)cts->tab[f].value, cls);
    }
  } else if (ct->kind == CT_ARRAY) {
    uint32_t esz = lj_ctype_size(cts, ct->cid), i, n = (esz && ct->size != CTSIZE_INVALID) ? ct->size / esz : 0;
    for (i = 0; i < n; i++) classify_rec(cts, ct->cid, ofs + i * esz, cls);
  } else {
    int c = (ct->kind == CT_NUM && (ct->flags & CTF_FP)) ? CLS_SSE : CLS_INT;
    int idx = (int)(ofs / 8);
    if (idx < 2) {
      if (cls[idx] == CLS_NONE) cls[idx] = c;
      else if (c == CLS_INT) cls[idx] = CLS_INT;
    }
  }
}

static void classify_struct(CTState *cts, CTypeID id, int *cls)
{
  uint32_t sz = lj_ctype_size(cts, id);
  cls[0] = cls[1] = CLS_NONE;
  if (sz > 16 || sz == 0) { cls[0] = cls[1] = CLS_MEM; return; }
  classify_rec(cts, id, 0, cls);
  if (sz <= 8) cls[1] = CLS_NONE;
  if (cls[0] == CLS_NONE) cls[0] = CLS_SSE;
  if (sz > 8 && cls[1] == CLS_NONE) cls[1] = CLS_SSE;
}

static LJ_NORET void err_wrongargs(lua_State *L)
{
  lj_err_callermsg(L, "wrong number of arguments for function call");
}

extern int lj_ffi_savederrno;
int lj_ffi_savederrno = 0;

/* Call C function. Args at L->base+1 .. L->top. Returns number of results. */
static int ccall(lua_State *L, CTState *cts, CTypeID fid, void *fptr)
{
  CType *ft = &cts->tab[fid];
  CCallState cc;
  int ngpr = 0, nfpr = 0, nsp = 0;
  int nargs = (int)(L->top - L->base) - 1;
  int i;
  CTypeID pid;
  CTypeID rid = lj_ctype_rawid(cts, ft->cid);
  CType *rt = &cts->tab[rid];
  int retcls[2] = {CLS_NONE, CLS_NONE};
