      if (tvisnum(o)) aid = CTID_DOUBLE;
      else if (tvisstr(o)) aid = CTID_P_CCHAR;
      else if (tvisbool(o)) aid = CTID_BOOL;
      else if (tvisnil(o) || tvisudata(o) || tvislightud(o)) aid = CTID_P_VOID;
      else if (tviscdata(o)) {
