/* ======================================================================== */
/* -- Library ------------------------------------------------------------- */

CTypeID lj_cparse_type(lua_State *L, GCstr *s, TValue *param, TValue *paramend);
void lj_cparse_cdef(lua_State *L, GCstr *s, TValue *param, TValue *paramend);

/* Get ctype id from argument (string, ctype or cdata). */
static CTypeID ffi_checkctype(lua_State *L, CTState *cts, int narg, TValue *param)
{
  TValue *o = L->base + narg - 1;
  if (!(o < L->top)) {
  err_argtype:
    lj_err_argtype(L, narg, "C type");
  }
  if (tvisstr(o)) {
    GCstr *s = strV(o);
    TValue *pend = param ? L->top : NULL;
    return lj_cparse_type(L, s, param, pend);
  }
  if (tviscdata(o)) {
    GCcdata *cd = cdataV(o);
    if (cd->ctypeid == CTID_CTYPEID) return *(CTypeID *)cdataptr(cd);
    return cd->ctypeid;
  }
  goto err_argtype;
}

static GCcdata *ffi_push_ctype(lua_State *L, CTState *cts, CTypeID id)
{
  GCcdata *cd = cdata_push(cts, CTID_CTYPEID, 4);
  *(CTypeID *)cdataptr(cd) = id;
  (void)L;
  return cd;
}

static void ffi_gc_register(lua_State *L, GCcdata *cd, cTValue *fn)
{
  global_State *g = G(L);
  TValue key;
  if (!g->cdata_fin) {
    g->cdata_fin = lj_tab_new(L, 0, 4);
  }
  setcdataV(&key, cd);
  {
    TValue *v = lj_tab_set(L, g->cdata_fin, &key);
    copyTV(v, fn);
  }
}

/* Allocate a new cdata. Args after narg are initializers. */
static GCcdata *ffi_new_aux(lua_State *L, CTState *cts, CTypeID id, TValue *init, int ninit, int isvla_arg)
{
  CType *ct = lj_ctype_raw(cts, id);
  uint32_t sz;
  GCcdata *cd;
  if (ct->kind == CT_ARRAY && (ct->flags & CTF_VLA)) {
    int64_t n;
    CType *e = lj_ctype_raw(cts, ct->cid);
    uint32_t esz = lj_ctype_size(cts, ct->cid);
    (void)e;
    if (ninit < 1) lj_err_arg(L, isvla_arg, "value expected");
    {
      TValue nv;
      if (!lj_vm_tonumber(init, &nv)) {
        if (tviscdata(init)) {
          int ok;
          n = cdata_key_int(cts, init, &ok);
          if (!ok) lj_err_argt(L, isvla_arg, LJ_TNUM);
          goto haven;
        }
        lj_err_argt(L, isvla_arg, LJ_TNUM);
      }
      n = lj_num2i64(nv.u.n);
    }
  haven:
    if (n < 0 || (esz && (uint64_t)n * esz > 0x7fffff00u)) lj_err_callermsg(L, "size of C type is unknown or too large");
    sz = (uint32_t)n * esz;
    init++;
    ninit--;
    cd = cdata_push(cts, id, sz);
    {
      /* Initialize with a temporary fixed-size array type of the same element. */
      uint8_t *p = (uint8_t *)cdataptr(cd);
      memset(p, 0, sz);
      if (ninit > 0) {
        CTypeID eid = ct->cid;
        int i;
        if (ninit == 1 && tvistab(init)) {
          GCtab *t = tabV(init);
          cTValue *v0 = lj_tab_getint(t, 0);
          int start = (v0 && !tvisnil(v0)) ? 0 : 1;
          uint32_t k;
          for (k = 0;; k++) {
            cTValue *v = lj_tab_getint(t, (int32_t)k + start);
            if (!v || tvisnil(v)) break;
            if ((int64_t)k >= n) err_too_many_init(cts, id);
            cconv_ct_tv(cts, eid, p + k * esz, v, CCF_INIT);
          }
        } else if (ninit == 1 && tvisstr(init) && lj_ctype_raw(cts, eid)->kind == CT_NUM && esz == 1) {
          size_t l = strV(init)->len + 1;
          if (l > sz) l = sz;
          memcpy(p, strdata(strV(init)), l);
        } else {
          if ((int64_t)ninit > n) err_too_many_init(cts, id);
          for (i = 0; i < ninit; i++) cconv_ct_tv(cts, eid, p + (uint32_t)i * esz, init + i, CCF_INIT);
          if (ninit == 1) {
            int64_t j;
            for (j = 1; j < n; j++) memcpy(p + j * esz, p, esz);
          }
        }
      }
    }
    return cd;
  }
  if (ct->kind == CT_STRUCT) {
    CTypeID sid = ctype_unqual_struct(cts, id);
    CType *st = &cts->tab[sid];
    CTypeID f, last = 0;
    if (st->flags & CTF_INCOMPLETE) lj_err_callermsg(L, "size of C type is unknown or too large");
    for (f = st->first; f; f = cts->tab[f].next) if (cts->tab[f].kind == CT_FIELD) last = f;
    sz = st->size;
    if (last) {
      CType *lt = lj_ctype_raw(cts, cts->tab[last].cid);
      if (lt->kind == CT_ARRAY && (lt->flags & CTF_VLA)) {
        /* Variable-length struct. */
        int64_t n = 0;
        uint32_t esz = lj_ctype_size(cts, lt->cid);
        if (ninit < 1) lj_err_arg(L, isvla_arg, "value expected");
        {
          TValue nv;
          if (!lj_vm_tonumber(init, &nv)) lj_err_argt(L, isvla_arg, LJ_TNUM);
          n = lj_num2i64(nv.u.n);
        }
        init++;
        ninit--;
        sz = (uint32_t)cts->tab[last].value + (uint32_t)n * esz;
        sz = align_up(sz, st->align);
      }
    }
  } else {
    sz = lj_ctype_size(cts, id);
    if (sz == CTSIZE_INVALID || ct->kind == CT_VOID || ct->kind == CT_FUNC)
      lj_err_arg(L, 1, "size of C type is unknown or too large");
  }
  cd = cdata_push(cts, id, sz);
  cdata_init(cts, id, (uint8_t *)cdataptr(cd), sz, init, ninit);
  {
    cTValue *gcm = ffi_meta(cts, id, MM_gc);
    if (gcm) ffi_gc_register(L, cd, gcm);
  }
  return cd;
}

static int ffi_new(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = ffi_checkctype(L, cts, 1, NULL);
  int ninit = (int)(L->top - L->base) - 1;
  ffi_new_aux(L, cts, id, L->base + 1, ninit, 2);
  return 1;
}

static int ffi_cdef(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  lj_cparse_cdef(L, s, L->base + 1, L->top);
  return 0;
}

static int ffi_typeof(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = ffi_checkctype(L, cts, 1, L->base + 1);
  ffi_push_ctype(L, cts, id);
  return 1;
}

static int ffi_cast(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = ffi_checkctype(L, cts, 1, NULL);
  CType *d = lj_ctype_raw(cts, id);
  TValue *o = L->base + 1;
  GCcdata *cd;
  if (!(o < L->top)) lj_err_arg(L, 2, "value expected");
  if (!(d->kind == CT_NUM || d->kind == CT_PTR || d->kind == CT_ENUM || d->kind == CT_REF ||
        (d->kind == CT_ARRAY && (d->flags & CTF_COMPLEX))))
    lj_err_arg(L, 1, "invalid C type");
  if (tviscdata(o) && cdataV(o)->ctypeid == id) {
    lua_settop(L, 2);
    return 1;
  }
  cd = cdata_push(cts, id, d->size);
  memset(cdataptr(cd), 0, d->size);
  cconv_ct_tv(cts, id, (uint8_t *)cdataptr(cd), L->base + 1, CCF_CAST);
  return 1;
}

static int ffi_typeinfo(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  int32_t id = lj_lib_checkint(L, 1);
  if (id > 0 && (uint32_t)id < cts->top) {
    CType *ct = &cts->tab[id];
    lua_createtable(L, 0, 4);
    lua_pushinteger(L, (lua_Integer)ct->kind << 28);
    lua_setfield(L, -2, "info");
    if (ct->size != CTSIZE_INVALID) {
      lua_pushinteger(L, ct->size);
      lua_setfield(L, -2, "size");
    }
    if (ct->next) {
      lua_pushinteger(L, ct->next);
      lua_setfield(L, -2, "sib");
    }
    if (ct->name) {
      lua_pushstr(L, ct->name);
      lua_setfield(L, -2, "name");
    }
    return 1;
  }
  return 0;
}

static int ffi_istype(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id1 = ffi_checkctype(L, cts, 1, NULL);
  TValue *o = L->base + 1;
  int b = 0;
  if (o < L->top && tviscdata(o)) {
    GCcdata *cd = cdataV(o);
    CTypeID id2 = cd->ctypeid == CTID_CTYPEID ? *(CTypeID *)cdataptr(cd) : cd->ctypeid;
    CType *ct1 = lj_ctype_raw(cts, id1), *ct2 = lj_ctype_raw(cts, id2);
    if (ct2->kind == CT_REF) { id2 = ct2->cid; ct2 = lj_ctype_raw(cts, id2); }
    if (lj_ctype_rawid(cts, id1) == lj_ctype_rawid(cts, id2)) {
      b = 1;
    } else if (ct1->kind == CT_STRUCT && ct2->kind == CT_STRUCT) {
      b = ctype_unqual_struct(cts, id1) == ctype_unqual_struct(cts, id2);
    } else if (ct1->kind == CT_PTR && ct2->kind == CT_PTR) {
      b = lj_ctype_rawid(cts, ct1->cid) == lj_ctype_rawid(cts, ct2->cid);
    } else if (ct1->kind == ct2->kind && ct1->kind == CT_NUM) {
      b = ct1->size == ct2->size && ((ct1->flags ^ ct2->flags) & (CTF_FP | CTF_BOOL | CTF_UNSIGNED)) == 0;
    }
  }
  lua_pushboolean(L, b);
  return 1;
}

static int ffi_sizeof(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = ffi_checkctype(L, cts, 1, NULL);
  CType *ct = lj_ctype_raw(cts, id);
  uint32_t sz;
  TValue *o = L->base;
  if (tviscdata(o) && cdataV(o)->ctypeid != CTID_CTYPEID) {
    GCcdata *cd = cdataV(o);
    CType *cct = lj_ctype_raw(cts, cd->ctypeid);
    if (cct->kind == CT_ARRAY && (cct->flags & CTF_VLA)) {
      lua_pushinteger(L, cd->size);
      return 1;
    }
    if (cct->kind == CT_STRUCT) {
      lua_pushinteger(L, cd->size);
      return 1;
    }
  }
  if (ct->kind == CT_ARRAY && (ct->flags & CTF_VLA)) {
    int32_t n;
    uint32_t esz = lj_ctype_size(cts, ct->cid);
    if (L->base + 1 >= L->top) lj_err_arg(L, 2, "value expected");
    n = lj_lib_checkint(L, 2);
    lua_pushinteger(L, (lua_Integer)n * esz);
    return 1;
  }
  sz = lj_ctype_size(cts, id);
  if (sz == CTSIZE_INVALID || ct->kind == CT_VOID || ct->kind == CT_FUNC) {
    lua_pushnil(L);
    return 1;
  }
  lua_pushinteger(L, sz);
  return 1;
}

static int ffi_alignof(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = ffi_checkctype(L, cts, 1, NULL);
  CType *ct = lj_ctype_raw(cts, id);
  uint32_t al = ct->align;
  if (ct->kind == CT_ARRAY && !(ct->flags & CTF_COMPLEX)) al = lj_ctype_raw(cts, ct->cid)->align;
  lua_pushinteger(L, al ? al : 1);
  return 1;
}

static int ffi_offsetof(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = ffi_checkctype(L, cts, 1, NULL);
  GCstr *name = lj_lib_checkstr(L, 2);
  CType *ct = lj_ctype_raw(cts, id);
  if (ct->kind == CT_STRUCT) {
    uint32_t ofs;
    CTypeID f = getfield(cts, id, name, &ofs);
    if (f && cts->tab[f].kind == CT_FIELD) {
      lua_pushinteger(L, ofs);
      if (cts->tab[f].flags & CTF_BITFIELD) {
        lua_pushinteger(L, cts->tab[f].bitpos);
        lua_pushinteger(L, cts->tab[f].bitsize);
        return 3;
      }
      return 1;
    }
  }
  return 0;
}

static int ffi_errno(lua_State *L)
{
  int err = lj_ffi_savederrno;
  if (L->top > L->base) lj_ffi_savederrno = lj_lib_checkint(L, 1);
  lua_pushinteger(L, err);
  return 1;
}

static void *ffi_checkptr(lua_State *L, CTState *cts, int narg)
{
  TValue *o = L->base + narg - 1;
  void *p = NULL;
  if (o >= L->top) lj_err_arg(L, narg, "value expected");
  cconv_ct_tv(cts, CTID_P_CVOID, (uint8_t *)&p, o, CCF_ARG(narg));
  return p;
}

static int64_t ffi_checklen(lua_State *L, CTState *cts, int narg)
{
  TValue *o = L->base + narg - 1;
  int64_t len = 0;
  if (o >= L->top) lj_err_arg(L, narg, "value expected");
  cconv_ct_tv(cts, CTID_INT64, (uint8_t *)&len, o, CCF_ARG(narg));
  return len;
}

static int ffi_string(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  TValue *o = L->base;
  const char *p;
  size_t len;
  if (o >= L->top) lj_err_arg(L, 1, "value expected");
  p = (const char *)ffi_checkptr(L, cts, 1);
  if (L->base + 1 < L->top && !tvisnil(L->base + 1)) {
    len = (size_t)ffi_checklen(L, cts, 2);
  } else {
    if (p == NULL) lj_err_arg(L, 1, "cannot convert 'NULL' to 'string'");
    len = strlen(p);
  }
  lua_pushlstring(L, p, len);
  return 1;
}

static int ffi_copy(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  void *dp = ffi_checkptr(L, cts, 1);
  void *sp;
  TValue *o = L->base + 1;
  int64_t len;
  if (o >= L->top) lj_err_arg(L, 2, "value expected");
  sp = ffi_checkptr(L, cts, 2);
  if (L->base + 2 < L->top && !tvisnil(L->base + 2)) {
    len = ffi_checklen(L, cts, 3);
  } else if (tvisstr(o)) {
    len = (int64_t)strV(o)->len + 1;
  } else {
    lj_err_arg(L, 3, "value expected");
  }
  memcpy(dp, sp, (size_t)len);
  return 0;
}

static int ffi_fill(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  void *dp = ffi_checkptr(L, cts, 1);
  int64_t len = ffi_checklen(L, cts, 2);
  int32_t fill = lj_lib_optint(L, 3, 0);
  memset(dp, fill, (size_t)len);
  return 0;
}

static int ffi_abi(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  const char *p = strdata(s);
  int b = 0;
  if (strcmp(p, "64bit") == 0 || strcmp(p, "le") == 0 || strcmp(p, "fpu") == 0 ||
      strcmp(p, "gc64") == 0) b = 1;
  lua_pushboolean(L, b);
  return 1;
}

static int ffi_metatype(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = ffi_checkctype(L, cts, 1, NULL);
  GCtab *mt = lj_lib_checktab(L, 2);
  CTypeID sid = ctype_typeid_strip(cts, id);
  CType *ct = &cts->tab[sid];
  cTValue *old;
  if (!(ct->kind == CT_STRUCT || ct->kind == CT_ARRAY || ct->kind == CT_NUM || ct->kind == CT_ENUM || ct->kind == CT_PTR || ct->kind == CT_VOID))
    lj_err_arg(L, 1, "invalid C type");
  old = lj_tab_getint(cts->metatypes, (int32_t)sid);
  if (old && !tvisnil(old)) lj_err_callermsg(L, "cannot change a protected metatable");
  {
    TValue *v = lj_tab_setint(L, cts->metatypes, (int32_t)sid);
    settabV(v, mt);
  }
  ffi_push_ctype(L, cts, id);
  return 1;
}

static int ffi_gc(lua_State *L)
{
  TValue *o = L->base;
  global_State *g = G(L);
  if (!(o < L->top && tviscdata(o))) lj_err_argt(L, 1, LJ_TCDATA);
  if (L->base + 1 >= L->top) lj_err_arg(L, 2, "value expected");
  if (tvisnil(L->base + 1)) {
    if (g->cdata_fin) {
      TValue *v = (TValue *)lj_tab_get(L, g->cdata_fin, o);
      if (v != &lj_nilobj) setnilV(v);
    }
  } else {
    ffi_gc_register(L, cdataV(o), L->base + 1);
  }
  lua_settop(L, 1);
  return 1;
}

/* -- C library namespaces ------------------------------------------------- */

typedef struct CLibrary {
  void *handle;
  GCtab *cache;
} CLibrary;

static GCtab *clib_mt = NULL;

static void *clib_resolve(lua_State *L, CLibrary *cl, GCstr *name, GCstr *sym)
{
  void *p;
  dlerror();
  p = dlsym(cl->handle ? cl->handle : RTLD_DEFAULT, strdata(sym ? sym : name));
  if (p == NULL) {
    const char *err = dlerror();
    char buf[512];
    if (err) snprintf(buf, sizeof(buf), "%s", err);
    else snprintf(buf, sizeof(buf), "cannot resolve symbol '%s'", strdata(name));
    lj_err_msg(L, buf);
  }
  return p;
}

static GCstr *clib_asmname(CTState *cts, CTypeID id)
{
  TValue key;
  cTValue *v;
  setnumV(&key, (double)id + 0.5);
  v = lj_tab_get(cts->L, cts->miscmap, &key);
  if (v && tvisstr(v)) return strV(v);
  return NULL;
}

static CTypeID clib_lookup(lua_State *L, CTState *cts, GCstr *name)
{
  CTypeID id = cts_get_name(cts, cts->names, name);
  if (!id || cts->tab[id].kind == CT_TYPEDEF) {
    char buf[300];
    snprintf(buf, sizeof(buf), "missing declaration for symbol '%s'", strdata(name));
    lj_err_msg(L, buf);
  }
  return id;
}

static int clib_index(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CLibrary *cl = (CLibrary *)lua_touserdata(L, 1);
  GCstr *name = lj_lib_checkstr(L, 2);
  cTValue *cached = lj_tab_getstr(cl->cache, name);
  CTypeID id;
  CType *ct;
  if (cached && !tvisnil(cached)) {
    if (tvisnum(cached)) {
      /* Extern variable: read current value. */
      CTypeID eid = (CTypeID)cached->u.n;
      TValue o;
      cconv_tv_ct(cts, cts->tab[eid].cid, &o, (uint8_t *)cts->tab[eid].addr);
      lua_pushtv(L, &o);
      return 1;
    }
    lua_pushtv(L, cached);
    return 1;
  }
  id = clib_lookup(L, cts, name);
  ct = &cts->tab[id];
  if (ct->kind == CT_CONSTVAL) {
    CType *vt = lj_ctype_raw(cts, ct->cid);
    if (vt->kind == CT_NUM && (vt->flags & CTF_UNSIGNED) && vt->size >= 4)
      lua_pushnumber(L, (double)(uint32_t)ct->value);
    else
      lua_pushnumber(L, (double)ct->value);
    return 1;
  }
  if (ct->kind == CT_FUNC) {
    void *p = clib_resolve(L, cl, name, clib_asmname(cts, id));
    GCcdata *cd = cdata_push(cts, id, 8);
    *(void **)cdataptr(cd) = p;
    {
      TValue *v = lj_tab_setstr(L, cl->cache, name);
      setcdataV(v, cd);
    }
    return 1;
  }
  if (ct->kind == CT_EXTERN) {
    void *p = clib_resolve(L, cl, name, clib_asmname(cts, id));
    TValue o;
    ct->addr = p;
    {
      TValue *v = lj_tab_setstr(L, cl->cache, name);
      setnumV(v, (double)id);
    }
    cconv_tv_ct(cts, ct->cid, &o, (uint8_t *)p);
    lua_pushtv(L, &o);
    return 1;
  }
  lj_err_msg(L, strdata(lj_str_pushf(L, "missing declaration for symbol '%s'", strdata(name))));
}

static int clib_newindex(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  CLibrary *cl = (CLibrary *)lua_touserdata(L, 1);
  GCstr *name = lj_lib_checkstr(L, 2);
  CTypeID id = clib_lookup(L, cts, name);
  CType *ct = &cts->tab[id];
  if (ct->kind == CT_EXTERN) {
    void *p = ct->addr ? ct->addr : clib_resolve(L, cl, name, clib_asmname(cts, id));
    ct->addr = p;
    {
      TValue *v = lj_tab_setstr(L, cl->cache, name);
      setnumV(v, (double)id);
    }
    cconv_ct_tv(cts, ct->cid, (uint8_t *)p, L->base + 2, 0);
    return 0;
  }
  lj_err_msg(L, "attempt to write to constant location");
}

static int clib_gc(lua_State *L)
{
  CLibrary *cl = (CLibrary *)lua_touserdata(L, 1);
  if (cl && cl->handle && cl->handle != RTLD_DEFAULT) {
    dlclose(cl->handle);
    cl->handle = NULL;
  }
  return 0;
}

static void clib_push(lua_State *L, void *handle)
{
  CLibrary *cl = (CLibrary *)lua_newuserdata(L, sizeof(CLibrary));
  GCudata *ud = udataV(L->top - 1);
  ud->udtype = 2;
  ud->metatable = clib_mt;
  cl->handle = handle;
  cl->cache = lj_tab_new(L, 0, 4);
  ud->env = cl->cache;  /* keep cache alive */
}

static int ffi_load(lua_State *L)
{
  GCstr *name = lj_lib_checkstr(L, 1);
  int global = lua_toboolean(L, 2);
  const char *n = strdata(name);
  void *h;
  char buf[512];
  if (strchr(n, '/') || strstr(n, ".so")) {
    h = dlopen(n, RTLD_NOW | (global ? RTLD_GLOBAL : RTLD_LOCAL));
  } else {
    snprintf(buf, sizeof(buf), "lib%s.so", n);
    h = dlopen(buf, RTLD_NOW | (global ? RTLD_GLOBAL : RTLD_LOCAL));
    if (!h) {
      /* Try versioned names for common libraries. */
      int v;
      for (v = 9; v >= 0 && !h; v--) {
        char b2[512];
        snprintf(b2, sizeof(b2), "lib%s.so.%d", n, v);
        h = dlopen(b2, RTLD_NOW | (global ? RTLD_GLOBAL : RTLD_LOCAL));
      }
      if (!h) {
        dlerror();
        h = dlopen(buf, RTLD_NOW | (global ? RTLD_GLOBAL : RTLD_LOCAL));
      }
    }
  }
  if (!h) {
    const char *e = dlerror();
    lj_err_callermsg(L, e ? e : "cannot load library");
  }
  clib_push(L, h);
  return 1;
}

/* -- cdata call handler ------------------------------------------------------ */

static int ffi_call_handler(lua_State *L)
{
  CTState *cts = lj_ctype_state(L);
  TValue *o = L->base;
  GCcdata *cd = cdataV(o);
  CTypeID id = cd->ctypeid;
  CType *ct;
  if (id == CTID_CTYPEID) {
    CTypeID cid = *(CTypeID *)cdataptr(cd);
    cTValue *mo = ffi_meta(cts, cid, MM_new);
    if (mo) {
      /* __new(ct, ...) */
      int n = (int)(L->top - L->base);
      TValue mv = *mo;
      int i;
      lj_checkstack(L, 2);
      for (i = n; i > 0; i--) copyTV(L->base + i, L->base + i - 1);
      copyTV(L->base, &mv);
      L->top++;
      lua_call(L, n, LUA_MULTRET);
      return (int)(L->top - L->base);
    }
    ffi_new_aux(L, cts, cid, L->base + 1, (int)(L->top - L->base) - 1, 2);
    return 1;
  }
  ct = lj_ctype_raw(cts, id);
  if (ct->kind == CT_FUNC) {
    return ccall(L, cts, lj_ctype_rawid(cts, id), *(void **)cdataptr(cd));
  }
  if (ct->kind == CT_PTR && lj_ctype_raw(cts, ct->cid)->kind == CT_FUNC) {
    return ccall(L, cts, lj_ctype_rawid(cts, ct->cid), *(void **)cdataptr(cd));
  }
  {
    cTValue *mo = ffi_meta(cts, id, MM_call);
    if (mo) {
      int n = (int)(L->top - L->base);
      TValue mv = *mo;
      int i;
      lj_checkstack(L, 2);
      for (i = n; i > 0; i--) copyTV(L->base + i, L->base + i - 1);
      copyTV(L->base, &mv);
      L->top++;
      lua_call(L, n, LUA_MULTRET);
      return (int)(L->top - L->base);
    }
  }
  lj_err_callermsg(L, strdata(lj_str_pushf(L, "'%s' is not callable", ctype_reprz(L, id))));
}

static GCfunc *call_handler_fn = NULL;

int lj_ffi_call_tm(lua_State *L, TValue *func)
{
  TValue *p;
  ptrdiff_t off = savestack(L, func);
  lj_checkstack(L, 1);
  func = restorestack(L, off);
  if (!call_handler_fn) {
    call_handler_fn = lj_func_newC(L, 0, ffi_call_handler, L->env);
    /* Anchor it. */
    lj_ctype_state(L);
    {
      TValue *v = lj_tab_setstr(L, g_cts->miscmap, lj_str_newlit(L, "__callhandler"));
      setfuncV(v, call_handler_fn);
    }
  }
  for (p = L->top; p > func; p--) copyTV(p, p - 1);
  L->top++;
  setfuncV(func, call_handler_fn);
  return 1;
}

/* -- Literals from the parser ------------------------------------------- */

int lj_ffi_makeliteral(lua_State *L, TValue *o, int kind)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd;
  if (kind == STRSCAN_IMAG) {
    double im = o->u.n;
    cd = lj_cdata_new(cts, CTID_COMPLEX_DOUBLE, 16);
    ((double *)cdataptr(cd))[0] = 0;
    ((double *)cdataptr(cd))[1] = im;
  } else {
    uint64_t v = o->u.u64;
    cd = lj_cdata_new(cts, kind == STRSCAN_I64 ? CTID_INT64 : CTID_UINT64, 8);
    *(uint64_t *)cdataptr(cd) = v;
  }
  setcdataV(o, cd);
  return 1;
}

/* -- 64 bit bit operations ----------------------------------------------- */

static uint64_t bit_check64(lua_State *L, CTState *cts, int narg, CTypeID *id)
{
  TValue *o = L->base + narg - 1;
  if (o >= L->top) lj_err_argt(L, narg, LJ_TNUM);
  if (tviscdata(o)) {
    GCcdata *cd = cdataV(o);
    CTypeID sid = cd->ctypeid;
    CType *s = lj_ctype_raw(cts, sid);
    uint8_t *sp = (uint8_t *)cdataptr(cd);
    uint64_t x = 0;
    if (s->kind == CT_REF) { sp = *(uint8_t **)sp; sid = s->cid; s = lj_ctype_raw(cts, sid); }
    if (s->kind == CT_ENUM) s = lj_ctype_raw(cts, s->cid);
    if (s->kind == CT_NUM && !(s->flags & (CTF_FP | CTF_BOOL)) && (s->flags & CTF_UNSIGNED) && s->size == 8)
      *id = CTID_UINT64;
    else if (!*id)
      *id = CTID_INT64;
    cconv_ct_ct(cts, *id, sid, (uint8_t *)&x, sp, CCF_ARG(narg));
    return x;
  } else {
    TValue n;
    union { double d; uint64_t u; } u;
    if (!lj_vm_tonumber(o, &n)) lj_err_argt(L, narg, LJ_TNUM);
    u.d = n.u.n + 6755399441055744.0;
    return (uint64_t)(uint32_t)u.u;
  }
}

int lj_ffi_bitop(lua_State *L, int op)
{
  CTState *cts = lj_ctype_state(L);
  CTypeID id = 0;
  uint64_t x, y;
  int n = (int)(L->top - L->base), i;
  enum { BOP_TOBIT, BOP_BNOT, BOP_BSWAP, BOP_LSHIFT, BOP_RSHIFT, BOP_ARSHIFT, BOP_ROL, BOP_ROR, BOP_BAND, BOP_BOR, BOP_BXOR, BOP_TOHEX };
  if (op == BOP_TOBIT) {
    x = bit_check64(L, cts, 1, &id);
    lua_pushnumber(L, (double)(int32_t)(uint32_t)x);
    return 1;
  }
  if (op == BOP_BAND || op == BOP_BOR || op == BOP_BXOR) {
    for (i = 1; i <= n; i++) bit_check64(L, cts, i, &id);
    x = bit_check64(L, cts, 1, &id);
    for (i = 2; i <= n; i++) {
      y = bit_check64(L, cts, i, &id);
      if (op == BOP_BAND) x &= y; else if (op == BOP_BOR) x |= y; else x ^= y;
    }
  } else if (op == BOP_TOHEX) {
    CTypeID id2 = 0;
    int32_t nd;
    int upper = 0;
    char buf[40];
    x = bit_check64(L, cts, 1, &id);
    nd = (L->base + 1 >= L->top) ? (id ? 16 : 8) : (int32_t)bit_check64(L, cts, 2, &id2);
    if (nd < 0) { nd = -nd; upper = 1; }
    if (nd < 16) x &= (((uint64_t)1 << (4 * nd)) - 1);
    if (nd > 16) nd = 16;
    snprintf(buf, sizeof(buf), upper ? "%0*llX" : "%0*llx", nd, (unsigned long long)x);
    if (nd == 0) buf[0] = 0;
    lua_pushstring(L, buf);
    return 1;
  } else {
    TValue *o1 = L->base;
    if (!(o1 < L->top && tviscdata(o1))) return -1;
    x = bit_check64(L, cts, 1, &id);
    if (op == BOP_BNOT) {
      x = ~x;
    } else if (op == BOP_BSWAP) {
      x = __builtin_bswap64(x);
    } else {
      CTypeID id2 = 0;
      uint32_t sh = (uint32_t)bit_check64(L, cts, 2, &id2) & 63;
      switch (op) {
      case BOP_LSHIFT: x <<= sh; break;
      case BOP_RSHIFT: x >>= sh; break;
      case BOP_ARSHIFT: x = (uint64_t)((int64_t)x >> sh); break;
      case BOP_ROL: x = (x << sh) | (x >> ((64 - sh) & 63)); break;
      case BOP_ROR: x = (x >> sh) | (x << ((64 - sh) & 63)); break;
      }
    }
  }
  if (!id) {
    lua_pushnumber(L, (double)(int32_t)(uint32_t)x);
    return 1;
  }
  {
    GCcdata *cd = cdata_push(cts, id, 8);
    *(uint64_t *)cdataptr(cd) = x;
  }
  return 1;
}

GCtab *lj_ffi_getmt(lua_State *L, cTValue *o)
{
  (void)L; (void)o;
  return NULL;
}

int luaopen_ffi(lua_State *L)
{
  static const LJLibReg funcs[] = {
    {"cdef", ffi_cdef, 187},
    {"new", ffi_new, 188},
    {"cast", ffi_cast, 189},
    {"typeof", ffi_typeof, 190},
    {"typeinfo", ffi_typeinfo, 191},
    {"istype", ffi_istype, 192},
    {"sizeof", ffi_sizeof, 193},
    {"alignof", ffi_alignof, 194},
    {"offsetof", ffi_offsetof, 195},
    {"errno", ffi_errno, 196},
    {"string", ffi_string, 197},
    {"copy", ffi_copy, 198},
    {"fill", ffi_fill, 199},
    {"abi", ffi_abi, 200},
    {"metatype", ffi_metatype, 201},
    {"gc", ffi_gc, 202},
    {"load", ffi_load, 203},
    {NULL, NULL, 0}
  };
  static const LJLibReg clibmeta[] = {
    {"__index", clib_index, 204},
    {"__newindex", clib_newindex, 205},
    {"__gc", clib_gc, 206},
    {NULL, NULL, 0}
  };
  CTState *cts = lj_ctype_state(L);
  (void)cts;
  lua_newtable(L);
  clib_mt = tabV(L->top - 1);
  lj_lib_register(L, NULL, clibmeta);
  lua_pushliteral(L, "ffi");
  lua_setfield(L, -2, "__metatable");
  lua_setfield(L, LUA_REGISTRYINDEX, "_FFI_CLIBMT");
  lua_newtable(L);
  lj_lib_register(L, NULL, funcs);
  clib_push(L, NULL);
  lua_setfield(L, -2, "C");
  lua_pushliteral(L, "Linux");
  lua_setfield(L, -2, "os");
  lua_pushliteral(L, "x64");
  lua_setfield(L, -2, "arch");
  return 1;
}
