      lj_tostring_push(L, i);
      if (!tvisstr(L->top - 1)) lj_err_argtype(L, i, "string/number/__tostring");
      sb = (SBufExt *)udataV(L->base)->align;
      buf_put(L, ud, sb, strdata(strV(L->top - 1)), strV(L->top - 1)->len);
      L->top--;
    }
  }
  lua_settop(L, 1);
  return 1;
}

static int buf_method_putf(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  int n = (int)(L->top - L->base);
