static int buf_method_set(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  TValue *o = L->base + 1;
  const char *p;
  size_t len;
  if (o < L->top && tvisstr(o)) {
    p = strdata(strV(o));
    len = strV(o)->len;
