static int buf_method_reset(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  if (sb->cow) {
    buf_unref(L, buf_ud(L));
    sb->b = sb->r = sb->w = sb->e = NULL;
    sb->cow = 0;
  } else {
    sb->r = sb->w = sb->b;
  }
  lua_settop(L, 1);
  return 1;
}

static int buf_method_free(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  if (sb->cow) buf_unref(L, buf_ud(L));
  buf_free(sb);
  lua_settop(L, 1);
  return 1;
}

extern void lj_ffi_pushptr(lua_State *L, void *p);

static int buf_method_reserve(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  int32_t sz = lj_lib_checkint(L, 2);
  if (sz < 0) lj_err_arg(L, 2, "number out of range");
  if (sz > 0 || sb->cow) buf_more(L, ud, sb, (size_t)sz);
  lj_ffi_pushptr(L, sb->w);
  lua_pushinteger(L, (lua_Integer)(sb->e - sb->w));
  return 2;
}

static int buf_method_commit(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  int32_t len = lj_lib_checkint(L, 2);
  if (len < 0 || (size_t)len > (size_t)(sb->e - sb->w)) lj_err_arg(L, 2, "number out of range");
  sb->w += len;
  lua_settop(L, 1);
  return 1;
}

/* -- Readers --------------------------------------------------------------- */

static int buf_method_skip(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  int32_t n = lj_lib_checkint(L, 2);
  size_t len = (size_t)(sb->w - sb->r);
  if (n > 0) {
    if ((size_t)n > len) n = (int32_t)len;
    sb->r += n;
  }
  lua_settop(L, 1);
  return 1;
}

static int buf_method_get(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  int n = (int)(L->top - L->base) - 1;
  int i;
  if (n == 0) {
    lua_pushlstring(L, sb->r, (size_t)(sb->w - sb->r));
    sb->r = sb->w;
    return 1;
  }
  for (i = 0; i < n; i++) {
    TValue *o = L->base + 1 + i;
    size_t len = (size_t)(sb->w - sb->r);
    if (!tvisnil(o)) {
      int32_t k = lj_lib_checkint(L, 2 + i);
      if (k < 0) lj_err_arg(L, 2 + i, "number out of range");
      if ((size_t)k < len) len = (size_t)k;
    }
    lua_pushlstring(L, sb->r, len);
    sb->r += len;
  }
  return n;
}

static int buf_method_tostring(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  lua_pushlstring(L, sb->r, (size_t)(sb->w - sb->r));
  return 1;
}

static int buf_method_ref(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  lj_ffi_pushptr(L, sb->r);
  lua_pushinteger(L, (lua_Integer)(sb->w - sb->r));
  return 2;
}

static int buf_method_len(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  lua_pushinteger(L, (lua_Integer)(sb->w - sb->r));
  return 1;
}

GCstr *lj_buf_tostr(lua_State *L, GCudata *ud)
{
  SBufExt *sb = (SBufExt *)ud->align;
  return lj_str_new(L, sb->r, (size_t)(sb->w - sb->r));
}

int lj_buf_isbuffer(cTValue *o)
{
  return tvisudata(o) && udataV(o)->udtype == UDTYPE_BUFFER;
}

/* -- Serializer ---------------------------------------------------------- */

#define SER_DEPTH 100

typedef struct SerCtx {
  lua_State *L;
  GCudata *ud;
  SBufExt *sb;
  GCtab *dict_str;   /* str -> idx */
  GCtab *dict_mt;    /* mt -> idx */
  int depth;
} SerCtx;

static void ser_byte(SerCtx *c, int b)
{
  char ch = (char)b;
  buf_put(c->L, c->ud, c->sb, &ch, 1);
}

static void ser_u124(SerCtx *c, uint32_t v)
{
  char buf[5];
  if (v < 0xe0) {
    buf[0] = (char)v;
    buf_put(c->L, c->ud, c->sb, buf, 1);
  } else if (v < 0x1fe0) {
    v -= 0xe0;
    buf[0] = (char)(0xe0 | ((v >> 8) & 0x1f));
    buf[1] = (char)(v & 0xff);
    buf_put(c->L, c->ud, c->sb, buf, 2);
  } else {
    buf[0] = (char)0xff;
    memcpy(buf + 1, &v, 4);
    buf_put(c->L, c->ud, c->sb, buf, 5);
  }
}

static void ser_u64(SerCtx *c, uint64_t v)
{
  buf_put(c->L, c->ud, c->sb, (const char *)&v, 8);
}

static void ser_str(SerCtx *c, GCstr *s)
{
  ser_u124(c, 0x20 + s->len);
  buf_put(c->L, c->ud, c->sb, strdata(s), s->len);
}

extern int lj_ffi_serinfo(lua_State *L, cTValue *o, int *kind, uint64_t *v);

static void ser_put(SerCtx *c, cTValue *o)
{
  lua_State *L = c->L;
  switch (o->tt) {
  case LJ_TNIL: ser_byte(c, 0x00); return;
  case LJ_TFALSE: ser_byte(c, 0x01); return;
  case LJ_TTRUE: ser_byte(c, 0x02); return;
  case LJ_TLIGHTUD: {
    uint64_t p = (uint64_t)(uintptr_t)o->u.p;
    if (p == 0) { ser_byte(c, 0x03); return; }
    if (p <= 0xffffffffu) { uint32_t p32 = (uint32_t)p; ser_byte(c, 0x04); buf_put(L, c->ud, c->sb, (const char *)&p32, 4); return; }
    ser_byte(c, 0x05);
    ser_u64(c, p);
    return;
  }
  case LJ_TNUM:
    ser_byte(c, 0x07);
    ser_u64(c, o->u.u64);
    return;
  case LJ_TSTR:
    ser_str(c, strV(o));
    return;
  case LJ_TTAB: {
    GCtab *t = tabV(o);
    uint32_t narray = 0, nhash = 0, one = 2;
    if (c->depth <= 0) lj_err_callermsg(L, "too deep to serialize");
    c->depth--;
    if (t->asize > 0) {
      int64_t i;
      for (i = (int64_t)t->asize - 1; i >= 0; i--)
        if (!tvisnil(&t->array[i])) break;
      narray = (uint32_t)(i + 1);
      if (narray && tvisnil(&t->array[0])) one = 4;
    }
    if (t->hmask > 0) {
      uint32_t i;
      for (i = 0; i <= t->hmask; i++) nhash += !tvisnil(&t->node[i].val);
    }
    if (c->dict_mt && t->metatable) {
      TValue mk;
      cTValue *v;
      settabV(&mk, t->metatable);
      v = lj_tab_get(L, c->dict_mt, &mk);
      if (tvisnum(v)) {
        ser_byte(c, 0x0e);
        ser_u124(c, (uint32_t)v->u.n);
      }
    }
    ser_byte(c, 0x08 + (nhash ? 1 : 0) + (narray ? one : 0));
    if (narray) ser_u124(c, narray);
    if (nhash) ser_u124(c, nhash);
    if (narray) {
      uint32_t i;
      for (i = (one >> 2); i < narray; i++) ser_put(c, &t->array[i]);
    }
    if (nhash) {
      int64_t i;
      for (i = t->hmask; i >= 0; i--) {
        Node *n = &t->node[i];
        if (!tvisnil(&n->val)) {
          if (c->dict_str && tvisstr(&n->key)) {
            cTValue *v = lj_tab_get(L, c->dict_str, &n->key);
            if (tvisnum(v)) {
              ser_byte(c, 0x0f);
              ser_u124(c, (uint32_t)v->u.n);
            } else {
              ser_str(c, strV(&n->key));
            }
          } else {
            ser_put(c, &n->key);
          }
          ser_put(c, &n->val);
          if (--nhash == 0) break;
        }
      }
    }
    c->depth++;
    return;
  }
  case LJ_TCDATA: {
    int kind;
    uint64_t v[2];
    if (lj_ffi_serinfo(L, o, &kind, v)) {
      ser_byte(c, kind);
      ser_u64(c, v[0]);
      if (kind == 0x12) ser_u64(c, v[1]);
      return;
    }
    break;
  }
  default:
    break;
  }
  {
    char buf[64];
    snprintf(buf, sizeof(buf), "cannot serialize '%s'", lj_typename(o));
    lj_err_callermsg(L, buf);
  }
}

static void ser_init(SerCtx *c, lua_State *L, GCudata *ud)
{
  c->L = L;
  c->ud = ud;
  c->sb = (SBufExt *)ud->align;
  c->depth = SER_DEPTH;
  c->dict_str = NULL;
  c->dict_mt = NULL;
  if (ud->env) {
    cTValue *v = lj_tab_getint(ud->env, 4);
    if (v && tvistab(v)) c->dict_str = tabV(v);
    v = lj_tab_getint(ud->env, 5);
    if (v && tvistab(v)) c->dict_mt = tabV(v);
  }
}

/* -- Deserializer ---------------------------------------------------------- */

typedef struct DesCtx {
  lua_State *L;
  const char *r;
  const char *e;
  GCtab *dict_str;   /* array */
  GCtab *dict_mt;
  int depth;
} DesCtx;

static LJ_NORET void des_eob(DesCtx *c)
{
  lj_err_callermsg(c->L, "unexpected end of buffer");
}

static uint32_t des_u124(DesCtx *c)
{
  uint32_t v;
  if (c->r >= c->e) des_eob(c);
  v = (uint8_t)*c->r++;
  if (v >= 0xe0) {
    if (v == 0xff) {
      if (c->e - c->r < 4) des_eob(c);
      memcpy(&v, c->r, 4);
      c->r += 4;
    } else {
      if (c->r >= c->e) des_eob(c);
      v = (((v & 0x1f) << 8) | (uint8_t)*c->r++) + 0xe0;
    }
  }
  return v;
}

static uint64_t des_u64(DesCtx *c)
{
  uint64_t v;
  if (c->e - c->r < 8) des_eob(c);
  memcpy(&v, c->r, 8);
  c->r += 8;
  return v;
}

extern void lj_ffi_desnum(lua_State *L, int kind, uint64_t *v, TValue *o);

static void des_get(DesCtx *c, TValue *o)
{
  lua_State *L = c->L;
  uint32_t tp;
  GCtab *mt = NULL;
again:
  tp = des_u124(c);
  if (tp >= 0x20) {
    uint32_t len = tp - 0x20;
    if ((uint32_t)(c->e - c->r) < len) des_eob(c);
    setstrV(o, lj_str_new(L, c->r, len));
    c->r += len;
    return;
  }
  switch (tp) {
  case 0x00: setnilV(o); return;
  case 0x01: setboolV(o, 0); return;
  case 0x02: setboolV(o, 1); return;
  case 0x03: setlightudV(o, NULL); return;
  case 0x04: {
    uint32_t v;
    if (c->e - c->r < 4) des_eob(c);
    memcpy(&v, c->r, 4);
    c->r += 4;
    setlightudV(o, (void *)(uintptr_t)v);
    return;
  }
  case 0x05: setlightudV(o, (void *)(uintptr_t)des_u64(c)); return;
  case 0x06: {
    int32_t v;
    if (c->e - c->r < 4) des_eob(c);
    memcpy(&v, c->r, 4);
    c->r += 4;
    setnumV(o, (double)v);
    return;
  }
  case 0x07: {
    uint64_t v = des_u64(c);
    o->u.u64 = v;
    o->tt = LJ_TNUM;
    return;
  }
  case 0x0e: {
    uint32_t idx = des_u124(c);
    cTValue *v = c->dict_mt ? lj_tab_getint(c->dict_mt, (int32_t)idx + 1) : NULL;
    if (!v || !tvistab(v)) {
      char buf[80];
      snprintf(buf, sizeof(buf), "cannot deserialize metatable index %u", idx);
      lj_err_callermsg(L, buf);
    }
    mt = tabV(v);
    goto again;
  }
  case 0x0f: {
    uint32_t idx = des_u124(c);
    cTValue *v = c->dict_str ? lj_tab_getint(c->dict_str, (int32_t)idx + 1) : NULL;
    if (!v || !tvisstr(v)) {
      char buf[80];
      snprintf(buf, sizeof(buf), "cannot deserialize dictionary index %u", idx);
      lj_err_callermsg(L, buf);
    }
    copyTV(o, v);
    return;
  }
  case 0x08: case 0x09: case 0x0a: case 0x0b: case 0x0c: case 0x0d: {
    uint32_t narray = 0, nhash = 0;
    GCtab *t;
    if (tp >= 0x0a) narray = des_u124(c);
    if (tp & 1) nhash = des_u124(c);
    if (--c->depth < 0) lj_err_callermsg(L, "too deep to serialize");
    t = lj_tab_new(L, narray, lj_tab_hsize2hbits(nhash));
    settabV(o, t);
    lj_checkstack(L, 2);
    copyTV(L->top, o);
    L->top++;
    if (narray) {
      uint32_t i = (tp >= 0x0c) ? 1 : 0;
      for (; i < narray; i++) {
        TValue v;
        des_get(c, &v);
        copyTV(&t->array[i], &v);
      }
    }
    while (nhash--) {
      TValue k, v;
      des_get(c, &k);
      copyTV(L->top, &k); L->top++;
      des_get(c, &v);
      {
        TValue *slot = lj_tab_set(L, t, &k);
        copyTV(slot, &v);
      }
      L->top--;
    }
    if (mt) t->metatable = mt;
    L->top--;
    c->depth++;
    return;
  }
  case 0x10: case 0x11: {
    uint64_t v[2];
    v[0] = des_u64(c);
    lj_ffi_desnum(L, tp, v, o);
    return;
  }
  case 0x12: {
    uint64_t v[2];
    v[0] = des_u64(c);
    v[1] = des_u64(c);
    lj_ffi_desnum(L, tp, v, o);
    return;
  }
  default: {
    char buf[64];
    snprintf(buf, sizeof(buf), "cannot deserialize tag 0x%02x", tp);
    lj_err_callermsg(L, buf);
  }
  }
}

static void des_init(DesCtx *c, lua_State *L, GCudata *ud, const char *r, const char *e)
{
  c->L = L;
  c->r = r;
  c->e = e;
  c->depth = SER_DEPTH;
  c->dict_str = NULL;
  c->dict_mt = NULL;
  if (ud && ud->env) {
    cTValue *v = lj_tab_getint(ud->env, 2);
    if (v && tvistab(v)) c->dict_str = tabV(v);
    v = lj_tab_getint(ud->env, 3);
    if (v && tvistab(v)) c->dict_mt = tabV(v);
  }
}

static int buf_method_encode(lua_State *L)
{
  SerCtx c;
  buf_check(L, 1);
  lj_lib_checkany(L, 2);
  ser_init(&c, L, buf_ud(L));
  ser_put(&c, L->base + 1);
  lua_settop(L, 1);
  return 1;
}

static int buf_method_decode(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  DesCtx c;
  TValue o;
  des_init(&c, L, buf_ud(L), sb->r, sb->w);
  des_get(&c, &o);
  sb = (SBufExt *)udataV(L->base)->align;
  sb->r = (char *)c.r;
  lua_pushtv(L, &o);
  return 1;
}

static int lj_cf_buffer_encode(lua_State *L)
{
  SerCtx c;
  GCudata *ud;
  lj_lib_checkany(L, 1);
  ud = buf_new(L, 0);
  ser_init(&c, L, ud);
  ser_put(&c, L->base);
  {
    SBufExt *sb = (SBufExt *)ud->align;
    lua_pushlstring(L, sb->r, (size_t)(sb->w - sb->r));
    buf_free(sb);
  }
  return 1;
}

static int lj_cf_buffer_decode(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  DesCtx c;
  TValue o;
  des_init(&c, L, NULL, strdata(s), strdata(s) + s->len);
  des_get(&c, &o);
  if (c.r != c.e) lj_err_callermsg(L, "left-over data in buffer");
  lua_pushtv(L, &o);
  return 1;
}

int luaopen_string_buffer(lua_State *L)
{
  static const LJLibReg methods[] = {
    {"free", buf_method_free, 204},
    {"reset", buf_method_reset, 205},
    {"skip", buf_method_skip, 206},
    {"set", buf_method_set, 207},
    {"put", buf_method_put, 208},
    {"putf", buf_method_putf, 209},
    {"get", buf_method_get, 210},
    {"putcdata", buf_method_putcdata, 211},
    {"reserve", buf_method_reserve, 212},
    {"commit", buf_method_commit, 213},
    {"ref", buf_method_ref, 214},
    {"encode", buf_method_encode, 215},
    {"decode", buf_method_decode, 216},
    {"__gc", buf_gc, 217},
    {"__tostring", buf_method_tostring, 218},
    {"__len", buf_method_len, 219},
    {NULL, NULL, 0}
  };
  static const LJLibReg funcs[] = {
    {"new", lj_cf_buffer_new, 220},
    {"encode", lj_cf_buffer_encode, 221},
    {"decode", lj_cf_buffer_decode, 222},
    {NULL, NULL, 0}
  };
  if (!buf_mt) {
    lua_newtable(L);
    buf_mt = tabV(L->top - 1);
    lua_setfield(L, LUA_REGISTRYINDEX, "_BUFFER_MT");
  }
  lua_pushtv(L, &(TValue){ .u.gc = (GCobj *)buf_mt, .tt = LJ_TTAB });
  lj_lib_register(L, NULL, methods);
  {
    GCfunc *ts = funcV(lj_tab_getstr(buf_mt, lj_str_newlit(L, "__tostring")));
    lj_lib_pushcf(L, buf_method_tostring, 218);
    (void)ts;
    lua_setfield(L, -2, "tostring");
  }
  lua_pushvalue(L, -1);
  lua_setfield(L, -2, "__index");
  lua_pushliteral(L, "buffer");
  lua_setfield(L, -2, "__metatable");
  lua_pop(L, 1);
  lua_newtable(L);
  lj_lib_register(L, NULL, funcs);
  return 1;
}
EOF
