/* -- Helpers for the buffer library --------------------------------------- */

void *lj_ffi_toptr(lua_State *L, int narg)
{
  CTState *cts = lj_ctype_state(L);
  return ffi_checkptr(L, cts, narg);
}

void lj_ffi_pushptr(lua_State *L, void *p)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd = cdata_push(cts, CTID_P_UINT8, 8);
  *(void **)cdataptr(cd) = p;
}

int lj_ffi_serinfo(lua_State *L, cTValue *o, int *kind, uint64_t *v)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd = cdataV(o);
  CTypeID id = lj_ctype_rawid(cts, cd->ctypeid);
  CType *ct = &cts->tab[id];
  if (cd->ctypeid == CTID_CTYPEID) return 0;
  if (ct->kind == CT_NUM && ct->size == 8 && !(ct->flags & CTF_FP)) {
    *kind = (ct->flags & CTF_UNSIGNED) ? 0x11 : 0x10;
    v[0] = *(uint64_t *)cdataptr(cd);
    return 1;
  }
  if (ct->kind == CT_ARRAY && (ct->flags & CTF_COMPLEX) && ct->size == 16) {
    *kind = 0x12;
    v[0] = ((uint64_t *)cdataptr(cd))[0];
    v[1] = ((uint64_t *)cdataptr(cd))[1];
    return 1;
  }
  return 0;
}

void lj_ffi_desnum(lua_State *L, int kind, uint64_t *v, TValue *o)
{
  CTState *cts = lj_ctype_state(L);
  GCcdata *cd;
  if (kind == 0x12) {
    cd = lj_cdata_new(cts, CTID_COMPLEX_DOUBLE, 16);
    ((uint64_t *)cdataptr(cd))[0] = v[0];
    ((uint64_t *)cdataptr(cd))[1] = v[1];
  } else {
    cd = lj_cdata_new(cts, kind == 0x10 ? CTID_INT64 : CTID_UINT64, 8);
    *(uint64_t *)cdataptr(cd) = v[0];
  }
  setcdataV(o, cd);
}
