/* String buffer library with serializer. */
#include "lj.h"
#include "lj_api.h"

#define UDTYPE_BUFFER 3

typedef struct SBufExt {
  char *b;
  char *r;
  char *w;
  char *e;
  int cow;           /* data is referenced (not owned) */
  int depth;
} SBufExt;

static GCtab *buf_mt = NULL;

/* env table of the udata: [1] = cow reference, dict_str, dict_mt */

static SBufExt *buf_check(lua_State *L, int narg)
{
  TValue *o = L->base + narg - 1;
  if (!(o < L->top && tvisudata(o) && udataV(o)->udtype == UDTYPE_BUFFER))
    lj_err_argtype(L, narg, "buffer");
  return (SBufExt *)udataV(o)->align;
}

static GCudata *buf_ud(lua_State *L)
{
  return udataV(L->base);
}

static void buf_unref(lua_State *L, GCudata *ud)
{
  GCtab *env = ud->env;
  (void)L;
  if (env) {
    TValue *v = (TValue *)lj_tab_getint(env, 1);
    if (v) setnilV(v);
  }
}

/* Ensure buffer owns its data and has room for n more bytes. */
static char *buf_more(lua_State *L, GCudata *ud, SBufExt *sb, size_t n)
{
  size_t len = (size_t)(sb->w - sb->r);
  if (sb->cow) {
    size_t cap = len + n + 32;
    char *nb = (char *)malloc(cap);
    if (!nb) lj_err_throw(L, LUA_ERRMEM);
    if (len) memcpy(nb, sb->r, len);
    sb->b = nb;
    sb->r = nb;
    sb->w = nb + len;
    sb->e = nb + cap;
    sb->cow = 0;
    buf_unref(L, ud);
  }
  if ((size_t)(sb->e - sb->w) < n) {
    size_t off = (size_t)(sb->r - sb->b);
    if (off > 0 && (size_t)(sb->e - sb->b) - len >= n && off >= len) {
      memmove(sb->b, sb->r, len);
      sb->r = sb->b;
      sb->w = sb->b + len;
    } else {
      size_t cap = (size_t)(sb->e - sb->b);
      size_t need = len + n;
      char *nb;
      if (cap < 32) cap = 32;
      while (cap < need) cap *= 2;
      if (need > 0x7fffff00u) lj_err_msg(L, "buffer overflow");
      if (off > 0 && len) memmove(sb->b, sb->r, len);
      nb = (char *)realloc(sb->b, cap);
      if (!nb) lj_err_throw(L, LUA_ERRMEM);
      sb->b = nb;
      sb->r = nb;
      sb->w = nb + len;
      sb->e = nb + cap;
    }
  }
  return sb->w;
}

static void buf_put(lua_State *L, GCudata *ud, SBufExt *sb, const char *s, size_t n)
{
  char *w;
  if (n == 0) return;
  w = buf_more(L, ud, sb, n);
  memcpy(w, s, n);
  sb->w += n;
}

static void buf_free(SBufExt *sb)
{
  if (!sb->cow) free(sb->b);
  sb->b = sb->r = sb->w = sb->e = NULL;
  sb->cow = 0;
}

static int buf_gc(lua_State *L)
{
  TValue *o = L->base;
  if (o < L->top && tvisudata(o) && udataV(o)->udtype == UDTYPE_BUFFER) {
    SBufExt *sb = (SBufExt *)udataV(o)->align;
    buf_free(sb);
  }
  return 0;
}

static GCudata *buf_new(lua_State *L, size_t size)
{
  SBufExt *sb = (SBufExt *)lua_newuserdata(L, sizeof(SBufExt));
  GCudata *ud = udataV(L->top - 1);
  ud->udtype = UDTYPE_BUFFER;
  ud->metatable = buf_mt;
  ud->env = lj_tab_new(L, 4, 0);
  memset(sb, 0, sizeof(*sb));
  if (size > 0) {
    sb->b = (char *)malloc(size);
    if (!sb->b) lj_err_throw(L, LUA_ERRMEM);
    sb->r = sb->w = sb->b;
    sb->e = sb->b + size;
  }
  return ud;
}

static void buf_setdict(lua_State *L, GCudata *ud, GCtab *opts)
{
  cTValue *d = lj_tab_getstr(opts, lj_str_newlit(L, "dict"));
  cTValue *m = lj_tab_getstr(opts, lj_str_newlit(L, "metatable"));
  if (d && tvistab(d)) {
    GCtab *t = tabV(d);
    GCtab *rev = lj_tab_new(L, 0, 4);
    int32_t i;
    TValue *v = lj_tab_setint(L, ud->env, 2);
    settabV(v, t);
    v = lj_tab_setint(L, ud->env, 4);
    settabV(v, rev);
    for (i = 1;; i++) {
      cTValue *s = lj_tab_getint(t, i);
      if (!s || tvisnil(s)) break;
      if (tvisstr(s)) {
        TValue *slot = lj_tab_set(L, rev, s);
        setnumV(slot, (double)(i - 1));
      }
    }
  }
  if (m && tvistab(m)) {
    GCtab *t = tabV(m);
    GCtab *rev = lj_tab_new(L, 0, 4);
    int32_t i;
    TValue *v = lj_tab_setint(L, ud->env, 3);
    settabV(v, t);
    v = lj_tab_setint(L, ud->env, 5);
    settabV(v, rev);
    for (i = 1;; i++) {
      cTValue *s = lj_tab_getint(t, i);
      if (!s || tvisnil(s)) break;
      if (tvistab(s)) {
        TValue *slot = lj_tab_set(L, rev, s);
        setnumV(slot, (double)(i - 1));
      }
    }
  }
}

static int lj_cf_buffer_new(lua_State *L)
{
  int32_t sz = 0;
  GCtab *opts = NULL;
  TValue *o = L->base;
  if (o < L->top && !tvistab(o)) {
    sz = lj_lib_checkint(L, 1);
    if (sz < 0) sz = 0;
    o++;
  }
  if (o < L->top && tvistab(o)) opts = tabV(o);
  {
    GCudata *ud = buf_new(L, (size_t)sz);
    if (opts) buf_setdict(L, ud, opts);
  }
  return 1;
}

/* -- Writers ------------------------------------------------------------- */

static int buf_method_put(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  int n = (int)(L->top - L->base), i;
  for (i = 2; i <= n; i++) {
    TValue *o = L->base + i - 1;
    if (tvisstr(o)) {
      buf_put(L, ud, sb, strdata(strV(o)), strV(o)->len);
    } else if (tvisnum(o)) {
      char nb[64];
      size_t len = lj_str_fmtnum(nb, o->u.n);
      buf_put(L, ud, sb, nb, len);
    } else if (tvisudata(o) && udataV(o)->udtype == UDTYPE_BUFFER) {
      SBufExt *sb2 = (SBufExt *)udataV(o)->align;
      if (sb2 == sb) lj_err_arg(L, i, "cannot put buffer into itself");
      buf_put(L, ud, sb, sb2->r, (size_t)(sb2->w - sb2->r));
    } else {
      cTValue *mo = lj_meta_lookup(L, o, MM_tostring);
      if (!mo && tviscdata(o)) {
        extern cTValue *lj_ffi_meta(lua_State *L, cTValue *o, int mm);
        mo = lj_ffi_meta(L, o, MM_tostring);
      }
      if (!mo) lj_err_argtype(L, i, "string/number/__tostring");
      lj_tostring_push(L, i);
      if (!tvisstr(L->top - 1)) lj_err_argtype(L, i, "string/number/__tostring");
      sb = (SBufExt *)udataV(L->base)->align;
      buf_put(L, ud, sb, strdata(strV(L->top - 1)), strV(L->top - 1)->len);
      L->top--;
    }
  }
  lua_settop(L, 1);
  return 1;
}

static int buf_method_putf(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  int n = (int)(L->top - L->base);
  lj_lib_checkstr(L, 2);
  lua_getfield(L, LUA_REGISTRYINDEX, "_LOADED");
  lua_getfield(L, -1, "string");
  lua_getfield(L, -1, "format");
  lua_insert(L, 2);
  lua_pop(L, 2);
  lua_call(L, n - 1, 1);
  sb = (SBufExt *)udataV(L->base)->align;
  buf_put(L, ud, sb, strdata(strV(L->top - 1)), strV(L->top - 1)->len);
  lua_settop(L, 1);
  return 1;
}

extern void *lj_ffi_toptr(lua_State *L, int narg);

static int buf_method_putcdata(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  void *p = lj_ffi_toptr(L, 2);
  int32_t len = lj_lib_checkint(L, 3);
  if (len < 0) lj_err_arg(L, 3, "number out of range");
  buf_put(L, ud, sb, (const char *)p, (size_t)len);
  lua_settop(L, 1);
  return 1;
}

static int buf_method_set(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  TValue *o = L->base + 1;
  const char *p;
  size_t len;
  if (o < L->top && tvisstr(o)) {
    p = strdata(strV(o));
    len = strV(o)->len;
  } else if (o < L->top && tviscdata(o)) {
    p = (const char *)lj_ffi_toptr(L, 2);
    len = (size_t)lj_lib_checkint(L, 3);
  } else {
    lj_err_argt(L, 2, LJ_TSTR);
  }
  buf_free(sb);
  sb->b = sb->r = (char *)p;
  sb->w = sb->e = (char *)p + len;
  sb->cow = 1;
  {
    TValue *v = lj_tab_setint(L, ud->env, 1);
    copyTV(v, L->base + 1);
  }
  lua_settop(L, 1);
  return 1;
}

static int buf_method_reset(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  if (sb->cow) {
    buf_unref(L, buf_ud(L));
    sb->b = sb->r = sb->w = sb->e = NULL;
    sb->cow = 0;
  } else {
    sb->r = sb->w = sb->b;
  }
  lua_settop(L, 1);
  return 1;
}

static int buf_method_free(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  if (sb->cow) buf_unref(L, buf_ud(L));
  buf_free(sb);
  lua_settop(L, 1);
  return 1;
}

extern void lj_ffi_pushptr(lua_State *L, void *p);

static int buf_method_reserve(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  GCudata *ud = buf_ud(L);
  int32_t sz = lj_lib_checkint(L, 2);
  if (sz < 0) lj_err_arg(L, 2, "number out of range");
  if (sz > 0 || sb->cow) buf_more(L, ud, sb, (size_t)sz);
  lj_ffi_pushptr(L, sb->w);
  lua_pushinteger(L, (lua_Integer)(sb->e - sb->w));
  return 2;
}

static int buf_method_commit(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  int32_t len = lj_lib_checkint(L, 2);
  if (len < 0 || (size_t)len > (size_t)(sb->e - sb->w)) lj_err_arg(L, 2, "number out of range");
  sb->w += len;
  lua_settop(L, 1);
  return 1;
}

/* -- Readers --------------------------------------------------------------- */

static int buf_method_skip(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  int32_t n = lj_lib_checkint(L, 2);
  size_t len = (size_t)(sb->w - sb->r);
  if (n > 0) {
    if ((size_t)n > len) n = (int32_t)len;
    sb->r += n;
  }
  lua_settop(L, 1);
  return 1;
}

static int buf_method_get(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  int n = (int)(L->top - L->base) - 1;
  int i;
  if (n == 0) {
    lua_pushlstring(L, sb->r, (size_t)(sb->w - sb->r));
    sb->r = sb->w;
    return 1;
  }
  for (i = 0; i < n; i++) {
    TValue *o = L->base + 1 + i;
    size_t len = (size_t)(sb->w - sb->r);
    if (!tvisnil(o)) {
      int32_t k = lj_lib_checkint(L, 2 + i);
      if (k < 0) lj_err_arg(L, 2 + i, "number out of range");
      if ((size_t)k < len) len = (size_t)k;
    }
    lua_pushlstring(L, sb->r, len);
    sb->r += len;
  }
  return n;
}

static int buf_method_tostring(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  lua_pushlstring(L, sb->r, (size_t)(sb->w - sb->r));
  return 1;
}

static int buf_method_ref(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  lj_ffi_pushptr(L, sb->r);
  lua_pushinteger(L, (lua_Integer)(sb->w - sb->r));
  return 2;
}

static int buf_method_len(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  lua_pushinteger(L, (lua_Integer)(sb->w - sb->r));
  return 1;
}

GCstr *lj_buf_tostr(lua_State *L, GCudata *ud)
{
  SBufExt *sb = (SBufExt *)ud->align;
  return lj_str_new(L, sb->r, (size_t)(sb->w - sb->r));
}

int lj_buf_isbuffer(cTValue *o)
{
  return tvisudata(o) && udataV(o)->udtype == UDTYPE_BUFFER;
}

/* -- Serializer ---------------------------------------------------------- */

#define SER_DEPTH 100

typedef struct SerCtx {
  lua_State *L;
  GCudata *ud;
  SBufExt *sb;
  GCtab *dict_str;   /* str -> idx */
  GCtab *dict_mt;    /* mt -> idx */
  int depth;
} SerCtx;

static void ser_byte(SerCtx *c, int b)
{
  char ch = (char)b;
  buf_put(c->L, c->ud, c->sb, &ch, 1);
}

static void ser_u124(SerCtx *c, uint32_t v)
{
  char buf[5];
  if (v < 0xe0) {
    buf[0] = (char)v;
    buf_put(c->L, c->ud, c->sb, buf, 1);
  } else if (v < 0x1fe0) {
    v -= 0xe0;
    buf[0] = (char)(0xe0 | ((v >> 8) & 0x1f));
    buf[1] = (char)(v & 0xff);
    buf_put(c->L, c->ud, c->sb, buf, 2);
  } else {
    buf[0] = (char)0xff;
    memcpy(buf + 1, &v, 4);
    buf_put(c->L, c->ud, c->sb, buf, 5);
  }
}

static void ser_u64(SerCtx *c, uint64_t v)
{
  buf_put(c->L, c->ud, c->sb, (const char *)&v, 8);
}

static void ser_str(SerCtx *c, GCstr *s)
{
  ser_u124(c, 0x20 + s->len);
  buf_put(c->L, c->ud, c->sb, strdata(s), s->len);
}

extern int lj_ffi_serinfo(lua_State *L, cTValue *o, int *kind, uint64_t *v);

static void ser_put(SerCtx *c, cTValue *o)
{
  lua_State *L = c->L;
  switch (o->tt) {
  case LJ_TNIL: ser_byte(c, 0x00); return;
  case LJ_TFALSE: ser_byte(c, 0x01); return;
  case LJ_TTRUE: ser_byte(c, 0x02); return;
  case LJ_TLIGHTUD: {
    uint64_t p = (uint64_t)(uintptr_t)o->u.p;
    if (p == 0) { ser_byte(c, 0x03); return; }
    if (p <= 0xffffffffu) { uint32_t p32 = (uint32_t)p; ser_byte(c, 0x04); buf_put(L, c->ud, c->sb, (const char *)&p32, 4); return; }
    ser_byte(c, 0x05);
    ser_u64(c, p);
    return;
  }
  case LJ_TNUM:
    ser_byte(c, 0x07);
    ser_u64(c, o->u.u64);
    return;
  case LJ_TSTR:
    ser_str(c, strV(o));
    return;
  case LJ_TTAB: {
    GCtab *t = tabV(o);
    uint32_t narray = 0, nhash = 0, one = 2;
    if (c->depth <= 0) lj_err_callermsg(L, "too deep to serialize");
    c->depth--;
    if (t->asize > 0) {
      int64_t i;
      for (i = (int64_t)t->asize - 1; i >= 0; i--)
        if (!tvisnil(&t->array[i])) break;
      narray = (uint32_t)(i + 1);
      if (narray && tvisnil(&t->array[0])) one = 4;
    }
    if (t->hmask > 0) {
      uint32_t i;
      for (i = 0; i <= t->hmask; i++) nhash += !tvisnil(&t->node[i].val);
    }
    if (c->dict_mt && t->metatable) {
      TValue mk;
      cTValue *v;
      settabV(&mk, t->metatable);
      v = lj_tab_get(L, c->dict_mt, &mk);
      if (tvisnum(v)) {
        ser_byte(c, 0x0e);
        ser_u124(c, (uint32_t)v->u.n);
      }
    }
    ser_byte(c, 0x08 + (nhash ? 1 : 0) + (narray ? one : 0));
    if (narray) ser_u124(c, narray);
    if (nhash) ser_u124(c, nhash);
    if (narray) {
      uint32_t i;
      for (i = (one >> 2); i < narray; i++) ser_put(c, &t->array[i]);
    }
    if (nhash) {
      int64_t i;
      for (i = t->hmask; i >= 0; i--) {
        Node *n = &t->node[i];
        if (!tvisnil(&n->val)) {
          if (c->dict_str && tvisstr(&n->key)) {
            cTValue *v = lj_tab_get(L, c->dict_str, &n->key);
            if (tvisnum(v)) {
              ser_byte(c, 0x0f);
              ser_u124(c, (uint32_t)v->u.n);
            } else {
              ser_str(c, strV(&n->key));
            }
          } else {
            ser_put(c, &n->key);
          }
          ser_put(c, &n->val);
          if (--nhash == 0) break;
        }
      }
    }
    c->depth++;
    return;
  }
  case LJ_TCDATA: {
    int kind;
    uint64_t v[2];
    if (lj_ffi_serinfo(L, o, &kind, v)) {
      ser_byte(c, kind);
      ser_u64(c, v[0]);
      if (kind == 0x12) ser_u64(c, v[1]);
      return;
    }
    break;
  }
  default:
    break;
  }
  {
    char buf[64];
    snprintf(buf, sizeof(buf), "cannot serialize '%s'", lj_typename(o));
    lj_err_callermsg(L, buf);
  }
}

static void ser_init(SerCtx *c, lua_State *L, GCudata *ud)
{
  c->L = L;
  c->ud = ud;
  c->sb = (SBufExt *)ud->align;
  c->depth = SER_DEPTH;
  c->dict_str = NULL;
  c->dict_mt = NULL;
  if (ud->env) {
    cTValue *v = lj_tab_getint(ud->env, 4);
    if (v && tvistab(v)) c->dict_str = tabV(v);
    v = lj_tab_getint(ud->env, 5);
    if (v && tvistab(v)) c->dict_mt = tabV(v);
  }
}

/* -- Deserializer ---------------------------------------------------------- */

typedef struct DesCtx {
  lua_State *L;
  const char *r;
  const char *e;
  GCtab *dict_str;   /* array */
  GCtab *dict_mt;
  int depth;
} DesCtx;

static LJ_NORET void des_eob(DesCtx *c)
{
  lj_err_callermsg(c->L, "unexpected end of buffer");
}

static uint32_t des_u124(DesCtx *c)
{
  uint32_t v;
  if (c->r >= c->e) des_eob(c);
  v = (uint8_t)*c->r++;
  if (v >= 0xe0) {
    if (v == 0xff) {
      if (c->e - c->r < 4) des_eob(c);
      memcpy(&v, c->r, 4);
      c->r += 4;
    } else {
      if (c->r >= c->e) des_eob(c);
      v = (((v & 0x1f) << 8) | (uint8_t)*c->r++) + 0xe0;
    }
  }
  return v;
}

static uint64_t des_u64(DesCtx *c)
{
  uint64_t v;
  if (c->e - c->r < 8) des_eob(c);
  memcpy(&v, c->r, 8);
  c->r += 8;
  return v;
}

extern void lj_ffi_desnum(lua_State *L, int kind, uint64_t *v, TValue *o);

static void des_get(DesCtx *c, TValue *o)
{
  lua_State *L = c->L;
  uint32_t tp;
  GCtab *mt = NULL;
again:
  tp = des_u124(c);
  if (tp >= 0x20) {
    uint32_t len = tp - 0x20;
    if ((uint32_t)(c->e - c->r) < len) des_eob(c);
    setstrV(o, lj_str_new(L, c->r, len));
    c->r += len;
    return;
  }
  switch (tp) {
  case 0x00: setnilV(o); return;
  case 0x01: setboolV(o, 0); return;
  case 0x02: setboolV(o, 1); return;
  case 0x03: setlightudV(o, NULL); return;
  case 0x04: {
    uint32_t v;
    if (c->e - c->r < 4) des_eob(c);
    memcpy(&v, c->r, 4);
    c->r += 4;
    setlightudV(o, (void *)(uintptr_t)v);
    return;
  }
  case 0x05: setlightudV(o, (void *)(uintptr_t)des_u64(c)); return;
  case 0x06: {
    int32_t v;
    if (c->e - c->r < 4) des_eob(c);
    memcpy(&v, c->r, 4);
    c->r += 4;
    setnumV(o, (double)v);
    return;
  }
  case 0x07: {
    uint64_t v = des_u64(c);
    o->u.u64 = v;
    o->tt = LJ_TNUM;
    return;
  }
  case 0x0e: {
    uint32_t idx = des_u124(c);
    cTValue *v = c->dict_mt ? lj_tab_getint(c->dict_mt, (int32_t)idx + 1) : NULL;
    if (!v || !tvistab(v)) {
      char buf[80];
      snprintf(buf, sizeof(buf), "cannot deserialize metatable index %u", idx);
      lj_err_callermsg(L, buf);
    }
    mt = tabV(v);
    goto again;
  }
  case 0x0f: {
    uint32_t idx = des_u124(c);
    cTValue *v = c->dict_str ? lj_tab_getint(c->dict_str, (int32_t)idx + 1) : NULL;
    if (!v || !tvisstr(v)) {
      char buf[80];
      snprintf(buf, sizeof(buf), "cannot deserialize dictionary index %u", idx);
      lj_err_callermsg(L, buf);
    }
    copyTV(o, v);
    return;
  }
  case 0x08: case 0x09: case 0x0a: case 0x0b: case 0x0c: case 0x0d: {
    uint32_t narray = 0, nhash = 0;
    GCtab *t;
    if (tp >= 0x0a) narray = des_u124(c);
    if (tp & 1) nhash = des_u124(c);
    if (--c->depth < 0) lj_err_callermsg(L, "too deep to serialize");
    t = lj_tab_new(L, narray, lj_tab_hsize2hbits(nhash));
    settabV(o, t);
    lj_checkstack(L, 2);
    copyTV(L->top, o);
    L->top++;
    if (narray) {
      uint32_t i = (tp >= 0x0c) ? 1 : 0;
      for (; i < narray; i++) {
        TValue v;
        des_get(c, &v);
        copyTV(&t->array[i], &v);
      }
    }
    while (nhash--) {
      TValue k, v;
      des_get(c, &k);
      copyTV(L->top, &k); L->top++;
      des_get(c, &v);
      {
        TValue *slot = lj_tab_set(L, t, &k);
        copyTV(slot, &v);
      }
      L->top--;
    }
    if (mt) t->metatable = mt;
    L->top--;
    c->depth++;
    return;
  }
  case 0x10: case 0x11: {
    uint64_t v[2];
    v[0] = des_u64(c);
    lj_ffi_desnum(L, tp, v, o);
    return;
  }
  case 0x12: {
    uint64_t v[2];
    v[0] = des_u64(c);
    v[1] = des_u64(c);
    lj_ffi_desnum(L, tp, v, o);
    return;
  }
  default: {
    char buf[64];
    snprintf(buf, sizeof(buf), "cannot deserialize tag 0x%02x", tp);
    lj_err_callermsg(L, buf);
  }
  }
}

static void des_init(DesCtx *c, lua_State *L, GCudata *ud, const char *r, const char *e)
{
  c->L = L;
  c->r = r;
  c->e = e;
  c->depth = SER_DEPTH;
  c->dict_str = NULL;
  c->dict_mt = NULL;
  if (ud && ud->env) {
    cTValue *v = lj_tab_getint(ud->env, 2);
    if (v && tvistab(v)) c->dict_str = tabV(v);
    v = lj_tab_getint(ud->env, 3);
    if (v && tvistab(v)) c->dict_mt = tabV(v);
  }
}

static int buf_method_encode(lua_State *L)
{
  SerCtx c;
  buf_check(L, 1);
  lj_lib_checkany(L, 2);
  ser_init(&c, L, buf_ud(L));
  ser_put(&c, L->base + 1);
  lua_settop(L, 1);
  return 1;
}

static int buf_method_decode(lua_State *L)
{
  SBufExt *sb = buf_check(L, 1);
  DesCtx c;
  TValue o;
  des_init(&c, L, buf_ud(L), sb->r, sb->w);
  des_get(&c, &o);
  sb = (SBufExt *)udataV(L->base)->align;
  sb->r = (char *)c.r;
  lua_pushtv(L, &o);
  return 1;
}

static int lj_cf_buffer_encode(lua_State *L)
{
  SerCtx c;
  GCudata *ud;
  lj_lib_checkany(L, 1);
  ud = buf_new(L, 0);
  ser_init(&c, L, ud);
  ser_put(&c, L->base);
  {
    SBufExt *sb = (SBufExt *)ud->align;
    lua_pushlstring(L, sb->r, (size_t)(sb->w - sb->r));
    buf_free(sb);
  }
  return 1;
}

static int lj_cf_buffer_decode(lua_State *L)
{
  GCstr *s = lj_lib_checkstr(L, 1);
  DesCtx c;
  TValue o;
  des_init(&c, L, NULL, strdata(s), strdata(s) + s->len);
  des_get(&c, &o);
  if (c.r != c.e) lj_err_callermsg(L, "left-over data in buffer");
  lua_pushtv(L, &o);
  return 1;
}

int luaopen_string_buffer(lua_State *L)
{
  static const LJLibReg methods[] = {
    {"free", buf_method_free, 204},
    {"reset", buf_method_reset, 205},
    {"skip", buf_method_skip, 206},
    {"set", buf_method_set, 207},
    {"put", buf_method_put, 208},
    {"putf", buf_method_putf, 209},
    {"get", buf_method_get, 210},
    {"putcdata", buf_method_putcdata, 211},
    {"reserve", buf_method_reserve, 212},
    {"commit", buf_method_commit, 213},
    {"ref", buf_method_ref, 214},
    {"encode", buf_method_encode, 215},
    {"decode", buf_method_decode, 216},
    {"__gc", buf_gc, 217},
    {"__tostring", buf_method_tostring, 218},
    {"__len", buf_method_len, 219},
    {NULL, NULL, 0}
  };
  static const LJLibReg funcs[] = {
    {"new", lj_cf_buffer_new, 220},
    {"encode", lj_cf_buffer_encode, 221},
    {"decode", lj_cf_buffer_decode, 222},
    {NULL, NULL, 0}
  };
  if (!buf_mt) {
    lua_newtable(L);
    buf_mt = tabV(L->top - 1);
    lua_setfield(L, LUA_REGISTRYINDEX, "_BUFFER_MT");
  }
  lua_pushtv(L, &(TValue){ .u.gc = (GCobj *)buf_mt, .tt = LJ_TTAB });
  lj_lib_register(L, NULL, methods);
  {
    GCfunc *ts = funcV(lj_tab_getstr(buf_mt, lj_str_newlit(L, "__tostring")));
    lj_lib_pushcf(L, buf_method_tostring, 218);
    (void)ts;
    lua_setfield(L, -2, "tostring");
  }
  lua_pushvalue(L, -1);
  lua_setfield(L, -2, "__index");
  lua_pushliteral(L, "buffer");
  lua_setfield(L, -2, "__metatable");
  lua_pop(L, 1);
  lua_newtable(L);
  lj_lib_register(L, NULL, funcs);
  return 1;
}
