    uint64_t v[2];
    if (lj_ffi_serinfo(L, o, &kind, v)) {
      d_byte(d, kind == 0x10 ? 6 : kind == 0x11 ? 7 : 8);
      d_mem(d, &v[0], 8);
      if (kind == 0x12) d_mem(d, &v[1], 8);
    } else {
      d_byte(d, 0);
    }
    break;
  }
  default:
    d_byte(d, 0);
    break;
  }
}

static void d_proto(DumpState *d, lua_State *L, GCproto *pt)
{
  int i;
  d_uleb(d, pt->numparams);
  d_uleb(d, pt->is_vararg);
  d_uleb(d, pt->maxstack);
  d_uleb(d, pt->nups);
  d_uleb(d, (uint32_t)pt->sizecode);
  d_mem(d, pt->code, (size_t)pt->sizecode * sizeof(BCIns));
  if (!d->strip) {
    for (i = 0; i < pt->sizecode; i++) d_uleb(d, (uint32_t)pt->lineinfo[i]);
  }
  d_uleb(d, (uint32_t)pt->sizek);
  for (i = 0; i < pt->sizek; i++) d_const(d, L, &pt->k[i]);
  d_uleb(d, (uint32_t)pt->sizep);
  for (i = 0; i < pt->sizep; i++) d_proto(d, L, pt->p[i]);
  for (i = 0; i < pt->nups; i++) {
    d_byte(d, pt->uvinstack[i]);
    d_byte(d, pt->uvidx[i]);
  }
  if (!d->strip) {
    for (i = 0; i < pt->nups; i++) d_str(d, pt->uvnames ? pt->uvnames[i] : NULL);
    d_uleb(d, (uint32_t)pt->sizevars);
    for (i = 0; i < pt->sizevars; i++) {
      d_str(d, pt->vars[i].name);
      d_uleb(d, (uint32_t)pt->vars[i].startpc);
      d_uleb(d, (uint32_t)pt->vars[i].endpc);
    }
    d_uleb(d, (uint32_t)pt->linedefined);
    d_uleb(d, (uint32_t)pt->lastlinedefined);
  }
}

int lj_bcdump(lua_State *L, GCproto *pt, luaL_Buffer *b, int strip)
{
  DumpState d;
  d.b = b;
  d.strip = strip;
  d_mem(&d, "\033LJ\002", 4);
  d_byte(&d, strip ? BCDUMP_F_STRIP | 0x08 : 0x08);
  if (!strip) d_str(&d, pt->source);
  d_proto(&d, L, pt);
  return 0;
}

/* -- Loading ---------------------------------------------------------------- */

typedef struct LoadState {
  lua_State *L;
  const uint8_t *p, *e;
  int strip;
  GCstr *source;
  GCtab *anchor;
  const char *errname;
} LoadState;

static LJ_NORET void l_err(LoadState *ls)
{
  lua_State *L = ls->L;
  lua_pushfstring(L, "%s: cannot load incompatible bytecode", ls->errname);
  lj_err_throw(L, LUA_ERRSYNTAX);
}

static uint32_t l_uleb(LoadState *ls)
{
  uint32_t v = 0;
  int sh = 0;
  for (;;) {
    uint8_t c;
    if (ls->p >= ls->e) l_err(ls);
    c = *ls->p++;
    v |= (uint32_t)(c & 0x7f) << sh;
    if (!(c & 0x80)) break;
    sh += 7;
    if (sh > 28) l_err(ls);
  }
  return v;
}

static int l_byte(LoadState *ls)
{
  if (ls->p >= ls->e) l_err(ls);
  return *ls->p++;
}

static void l_mem(LoadState *ls, void *dst, size_t n)
{
  if ((size_t)(ls->e - ls->p) < n) l_err(ls);
  memcpy(dst, ls->p, n);
  ls->p += n;
}

static GCstr *l_str(LoadState *ls)
{
  uint32_t n = l_uleb(ls);
  GCstr *s;
  if (n == 0) return NULL;
  n--;
  if ((size_t)(ls->e - ls->p) < n) l_err(ls);
  s = lj_str_new(ls->L, (const char *)ls->p, n);
  ls->p += n;
  {
    TValue k, *v;
    setstrV(&k, s);
    v = lj_tab_set(ls->L, ls->anchor, &k);
    setboolV(v, 1);
  }
  return s;
}

extern void lj_ffi_desnum(lua_State *L, int kind, uint64_t *v, TValue *o);

static void l_const(LoadState *ls, TValue *o)
{
  lua_State *L = ls->L;
  int tag = l_byte(ls);
  switch (tag) {
  case 0: setnilV(o); break;
  case 1: setboolV(o, 0); break;
  case 2: setboolV(o, 1); break;
  case 3: o->tt = LJ_TNUM; l_mem(ls, &o->u.u64, 8); break;
  case 4: {
    GCstr *s = l_str(ls);
    if (!s) s = lj_str_newlit(L, "");
    setstrV(o, s);
    break;
  }
  case 5: {
    uint32_t asize = l_uleb(ls), i, hsize;
    GCtab *t = lj_tab_new(L, asize, 0);
    settabV(o, t);
    {
      TValue k, *v;
      settabV(&k, t);
      v = lj_tab_set(L, ls->anchor, &k);
      setboolV(v, 1);
    }
    for (i = 0; i < asize; i++) l_const(ls, &t->array[i]);
    hsize = l_uleb(ls);
    if (hsize) {
      uint32_t hbits = 0;
      while ((1u << hbits) < hsize) hbits++;
      lj_tab_resize(L, t, asize, hbits);
      for (i = 0; i < hsize; i++) {
        Node *n = &t->node[i];
        uint32_t nx;
        l_const(ls, &n->key);
        l_const(ls, &n->val);
        nx = l_uleb(ls);
        n->next = nx ? &t->node[nx - 1] : NULL;
      }
      t->freetop = &t->node[l_uleb(ls)];
    }
    break;
  }
  case 6: case 7: {
    uint64_t v[2];
    l_mem(ls, &v[0], 8);
    lj_ffi_desnum(L, tag == 6 ? 0x10 : 0x11, v, o);
    goto anchor;
  }
  case 8: {
    uint64_t v[2];
    l_mem(ls, &v[0], 8);
    l_mem(ls, &v[1], 8);
    lj_ffi_desnum(L, 0x12, v, o);
    goto anchor;
  }
  default:
    l_err(ls);
  }
  return;
anchor:
  {
    TValue *v = lj_tab_set(L, ls->anchor, o);
    setboolV(v, 1);
  }
}

static GCproto *l_proto(LoadState *ls)
{
  lua_State *L = ls->L;
  GCproto *pt = lj_func_newproto(L);
  int i;
  {
    TValue k, *v;
    setprotoV(&k, pt);
    v = lj_tab_set(L, ls->anchor, &k);
    setboolV(v, 1);
  }
  pt->source = ls->source;
  pt->numparams = (uint8_t)l_uleb(ls);
  pt->is_vararg = (uint8_t)l_uleb(ls);
  pt->maxstack = (uint8_t)l_uleb(ls);
  pt->nups = (uint8_t)l_uleb(ls);
  pt->sizecode = (int)l_uleb(ls);
  if (pt->sizecode <= 0 || pt->sizecode > 0x1000000) l_err(ls);
  pt->code = (BCIns *)lj_mem_alloc(L, (size_t)pt->sizecode * sizeof(BCIns));
  l_mem(ls, pt->code, (size_t)pt->sizecode * sizeof(BCIns));
  pt->lineinfo = (int *)lj_mem_alloc(L, (size_t)pt->sizecode * sizeof(int));
  for (i = 0; i < pt->sizecode; i++) pt->lineinfo[i] = ls->strip ? 0 : (int)l_uleb(ls);
  pt->sizek = (int)l_uleb(ls);
  pt->k = (TValue *)lj_mem_alloc(L, (size_t)(pt->sizek ? pt->sizek : 1) * sizeof(TValue));
  for (i = 0; i < pt->sizek; i++) setnilV(&pt->k[i]);
  for (i = 0; i < pt->sizek; i++) l_const(ls, &pt->k[i]);
  pt->sizep = (int)l_uleb(ls);
  pt->p = (GCproto **)lj_mem_alloc(L, (size_t)(pt->sizep ? pt->sizep : 1) * sizeof(GCproto *));
  for (i = 0; i < pt->sizep; i++) pt->p[i] = NULL;
  for (i = 0; i < pt->sizep; i++) pt->p[i] = l_proto(ls);
  if (pt->nups) {
    pt->uvinstack = (uint8_t *)lj_mem_alloc(L, pt->nups);
    pt->uvidx = (uint8_t *)lj_mem_alloc(L, pt->nups);
    pt->uvnames = (GCstr **)lj_mem_alloc(L, (size_t)pt->nups * sizeof(GCstr *));
    for (i = 0; i < pt->nups; i++) {
      pt->uvinstack[i] = (uint8_t)l_byte(ls);
      pt->uvidx[i] = (uint8_t)l_byte(ls);
      pt->uvnames[i] = NULL;
    }
  }
  if (!ls->strip) {
    for (i = 0; i < pt->nups; i++) pt->uvnames[i] = l_str(ls);
    pt->sizevars = (int)l_uleb(ls);
    pt->vars = (VarInfo *)lj_mem_alloc(L, (size_t)(pt->sizevars ? pt->sizevars : 1) * sizeof(VarInfo));
    for (i = 0; i < pt->sizevars; i++) {
      pt->vars[i].name = l_str(ls);
      if (!pt->vars[i].name) pt->vars[i].name = lj_str_newlit(L, "?");
      pt->vars[i].startpc = (int)l_uleb(ls);
      pt->vars[i].endpc = (int)l_uleb(ls);
    }
    pt->linedefined = (int)l_uleb(ls);
    pt->lastlinedefined = (int)l_uleb(ls);
  } else {
    pt->sizevars = 0;
    pt->vars = NULL;
    pt->linedefined = pt->lastlinedefined = 0;
  }
  /* Validate instructions minimally. */
  for (i = 0; i < pt->sizecode; i++) {
    int op = GET_OPCODE(pt->code[i]);
    if (op >= NUM_OPCODES) l_err(ls);
    if ((op == OP_LOADK || op == OP_GETGLOBAL || op == OP_SETGLOBAL || op == OP_TDUP || op == OP_TSETM) && GETARG_Bx(pt->code[i]) >= pt->sizek) l_err(ls);
    if (op == OP_CLOSURE && GETARG_Bx(pt->code[i]) >= pt->sizep) l_err(ls);
  }
  return pt;
}

int lj_undump_load(lua_State *L, lua_Reader reader, void *ud, const char *chunkname, const char *firstbuf, size_t firstsz)
{
  luaL_Buffer b;
  LoadState ls;
  GCproto *pt;
  GCfunc *fn;
  int flags;
  char errname[256];
  const char *src;
  luaL_buffinit(L, &b);
  luaL_addlstring(&b, firstbuf, firstsz);
  for (;;) {
    size_t sz;
    const char *p = reader(L, ud, &sz);
    if (!p || sz == 0) break;
    luaL_addlstring(&b, p, sz);
  }
  luaL_pushresult(&b);
  {
    GCstr *data = strV(L->top - 1);
    ls.L = L;
    ls.p = (const uint8_t *)strdata(data);
    ls.e = ls.p + data->len;
  }
  if (chunkname[0] == '\033') {
    strcpy(errname, "(binary)");
    src = "=?";
  } else {
    const char *n = chunkname;
    if (*n == '=' || *n == '@') n++;
    snprintf(errname, sizeof(errname), "%s", n);
    src = chunkname;
  }
  ls.errname = errname;
  ls.anchor = lj_tab_new(L, 0, 4);
  lj_checkstack(L, 1);
  settabV(L->top, ls.anchor);
  L->top++;
  if (ls.e - ls.p < 5 || memcmp(ls.p, "\033LJ\002", 4) != 0) l_err(&ls);
  ls.p += 4;
  flags = l_byte(&ls);
  if (!(flags & 0x08)) l_err(&ls);
  ls.strip = (flags & BCDUMP_F_STRIP) != 0;
  if (!ls.strip) {
    ls.source = l_str(&ls);
    if (!ls.source) ls.source = lj_str_newz(L, src);
  } else {
    ls.source = lj_str_newz(L, src);
    {
      TValue k, *v;
      setstrV(&k, ls.source);
      v = lj_tab_set(L, ls.anchor, &k);
      setboolV(v, 1);
    }
  }
  pt = l_proto(&ls);
  if (ls.p != ls.e) l_err(&ls);
  fn = lj_func_newL(L, pt, L->env);
  L->top -= 2;  /* pop anchor and data */
  setfuncV(L->top, fn);
  L->top++;
  return 0;
}
