new='''/* Small object allocator: segregated free lists in 16 byte classes. */
#define SMALL_MAX 512
#define SMALL_NCLASS (SMALL_MAX / 16)
#define CHUNK_SIZE (256 * 1024)

typedef struct FreeObj { struct FreeObj *next; } FreeObj;

static FreeObj *small_free[SMALL_NCLASS + 1];
static char *chunk_ptr = NULL;
static size_t chunk_left = 0;

static inline size_t size_class(size_t sz)
{
  return (sz + 15) >> 4;
}

static void *small_alloc(size_t cls)
{
  FreeObj *o = small_free[cls];
  if (o) {
    small_free[cls] = o->next;
    return o;
  } else {
    size_t bytes = cls << 4;
    void *p;
    if (chunk_left < bytes) {
      chunk_ptr = (char *)malloc(CHUNK_SIZE);
      if (!chunk_ptr) { chunk_left = 0; return NULL; }
      chunk_left = CHUNK_SIZE;
    }
    p = chunk_ptr;
    chunk_ptr += bytes;
    chunk_left -= bytes;
    return p;
  }
}

static inline void small_free_obj(void *p, size_t cls)
{
  FreeObj *o = (FreeObj *)p;
  o->next = small_free[cls];
  small_free[cls] = o;
}

void *lj_mem_alloc(lua_State *L, size_t sz)
{
  void *p;
  if (sz <= SMALL_MAX) {
    p = small_alloc(size_class(sz ? sz : 1));
  } else {
    p = malloc(sz);
  }
  if (!p) mem_error(L);
  G(L)->totalbytes += sz;
  return p;
}

void *lj_mem_realloc(lua_State *L, void *p, size_t osz, size_t nsz)
{
  void *np;
  if (p == NULL || osz == 0) {
    if (nsz == 0) return NULL;
    return lj_mem_alloc(L, nsz);
  }
  if (osz <= SMALL_MAX || nsz <= SMALL_MAX) {
    size_t oc = osz <= SMALL_MAX ? size_class(osz) : 0;
    size_t nc = nsz <= SMALL_MAX ? size_class(nsz ? nsz : 1) : 0;
    if (oc && nc && oc == nc) {
      G(L)->totalbytes = G(L)->totalbytes - osz + nsz;
      return p;
    }
    if (nsz == 0) {
      lj_mem_free(G(L), p, osz);
      return NULL;
    }
    np = lj_mem_alloc(L, nsz);
    memcpy(np, p, osz < nsz ? osz : nsz);
    lj_mem_free(G(L), p, osz);
    return np;
  }
  np = realloc(p, nsz ? nsz : 1);
  if (!np) mem_error(L);
  G(L)->totalbytes = G(L)->totalbytes - osz + nsz;
  return np;
}

void lj_mem_free(global_State *g, void *p, size_t sz)
{
  if (p) {
    if (sz <= SMALL_MAX) small_free_obj(p, size_class(sz ? sz : 1));
    else free(p);
    g->totalbytes -= sz;
  }
}

