static int jp_dumpstack(lua_State *L)
{
  lua_State *L1 = L;
  int arg = 1;
  const char *fmt;
  int depth, level, dir = 1, i, nlevels = 0;
  luaL_Buffer b;
  CallInfo *ci;
  if (lua_isthread(L, 1)) { L1 = lua_tothread(L, 1); arg = 2; }
  fmt = luaL_checkstring(L, arg);
  depth = luaL_optint(L, arg + 1, 1);
  if (depth < 0) { dir = -1; depth = -depth; }
  /* Count Lua-visible levels. */
  for (ci = L1->ci; ci > L1->base_ci; ci--) nlevels++;
  if (L1 == L) { nlevels--; }  /* skip dumpstack itself */
  if (depth > nlevels) depth = nlevels;
  luaL_buffinit(L, &b);
  for (i = 0; i < depth; i++) {
    int lv = dir > 0 ? i : depth - 1 - i;
    const char *f;
    int last = (i == depth - 1);
    level = lv + (L1 == L ? 1 : 0);
    if (!lj_debug_getstack(L1, level, &ci)) break;
    for (f = fmt; *f; f++) {
      if (*f == 'p' || *f == 'Z') continue;
      if (*f == 'f' || *f == 'F' || *f == 'l') {
        GCfunc *fn = funcV(ci->func);
        int fullpath = strchr(fmt, 'p') != NULL;
        if (*f != 'l') {
          const char *name = NULL;
          const char *what = lj_debug_funcname(L1, ci, &name);
          if (what && name) {
            if (*f == 'F' && !fn->isC) {
              dump_module(&b, strdata(fn->u.l.pt->source), fullpath);
              luaL_addchar(&b, ':');
            }
            luaL_addstring(&b, name);
            continue;
          }
        }
        if (fn->isC) {
          char pb[40];
          snprintf(pb, sizeof(pb), "[builtin#%d]", fn->ffid);
          luaL_addstring(&b, fn->ffid ? pb : "?");
        } else {
          char lb[32];
          dump_module(&b, strdata(fn->u.l.pt->source), fullpath);
          snprintf(lb, sizeof(lb), ":%d", *f == 'l' ? lj_debug_currentline(L1, ci) : fn->u.l.pt->linedefined);
          luaL_addstring(&b, lb);
        }
      } else {
        const char *z = strchr(fmt, 'Z');
        if (last && z && f > z) break;
        luaL_addchar(&b, *f);
      }
    }
  }
  luaL_pushresult(&b);
  return 1;
}

