#define CO_STACKS_PER_CHUNK 256

typedef struct FreeStack { struct FreeStack *next; } FreeStack;
static FreeStack *free_stacks = NULL;
static char *chunk_cur = NULL;
static int chunk_left = 0;

static void *stack_alloc(global_State *g, size_t sz)
{
  void *p;
  (void)g;
  if (free_stacks) {
    p = free_stacks;
    free_stacks = free_stacks->next;
    return p;
  }
  if (chunk_left == 0) {
    void *c = mmap(NULL, sz * CO_STACKS_PER_CHUNK, PROT_READ | PROT_WRITE,
